LL sum[N],a[N];
int cmp(LL a,LL b){
	return a > b;
}
int solve(int L,int R,LL k,int from){
	int l = L,r = R,res = -1;
	while (l <= r){
		int m = (l + r) / 2;
		if (sum[m] - sum[from - 1] >= k){
			res = m;
			r = m - 1;
		}
		else l = m + 1;
	}
	return res;
}
int main(){
	int n;
	LL k;
	scanf("%d%I64d",&n,&k);
	FOR(i,1,n) scanf("%I64d",&a[i]);
	sort(a + 1,a + n + 1,cmp);
	FOR(i,1,n) sum[i] = sum[i - 1] + a[i];
	int ans = 0;
	FOR(i,1,n) if (a[i] >= k) ans ++;
	else{
		LL mi = 0x7fffffffffffffff;
		//cout << mi << endl;
		FOR(j,1,i){
			int p = solve(i,n,k,j);
			if (p != -1 && sum[p] - sum[j - 1] < mi) mi = sum[p] - sum[j - 1];
		}
		if (mi - a[i] < k) ans ++;
	}
	printf("%d\n",n - ans);
}

