	BT now = y;
	rip(i,5001,0){
		if(x[i]) ret |= now;
		now <<= 1;
	}
}

bool check(BT &x, int c){
	x <<= 5001 - k;
	x >>= 5001 - c;
	//cout << x << endl;
	return x.any();
}

