bool isNotNeed(int n, int k, V& as, int i){
    int a = as[i];
    if(a >= k){
	return false;
    }

    Mb dp(n + 1, Vb());
    fillTrueFrom(dp, 0, 0);

    for(int x = 1; x < dp.size(); x++){
	int b = as[x - 1];
	if(b >= k){
	    break;
	}
	if(x - 1 == i){
	    continue;
	}
	for(int y = b; y < k; y++){
	    if(dp[x - 1][y - b]){
		fillTrueFrom(dp, x, y);
	    }
	}
    }

    // for(auto d : dp){
