            dp[elm_num+1][k] = dp[elm_num][k] || (a <= k and dp[elm_num][k-a]);
        elm_num++;
    }

    for (ll k = max(K-A[i], 0); k < K; k++)
        if (dp[N-1][k]) return true;
    return false;
}

int no_need() {
    int l = -1, r = N;
    while (l + 1 < r) {
        int m = (l + r) / 2;

        if (need(m)) r = m;
        else l = m;
    }
    return l + 1;
}

