void solve(int N, int K, vi a) {
  SORT(a);
  N = lower_bound(all(a), K) - a.begin();
  int l = -1, r = N;
  while(r - l > 1) {
    int m = (l + r) / 2;
    vb dp(K);
    dp[0] = true;
    rep(i, N)if(i - m)rrep(j, a[i], K)if(dp[j - a[i]])dp[j] = true;
    bool need = false;
    rep(i, K - a[m], K)if(dp[i]){
      need = true;
      break;
    }
    (need ? r : l) = m;
  }
  COUT(r);
}


