int main() {
	int N, K;
	cin >> N >> K;
	vl A(N);
	for (i = 0; i < N; i++) cin >> A[i];
	vector<vector<int>> dp(N+1, vector<int>(K+1,0));
	dp[0][0] = 1;
	for (i = 0; i < N; i++) {
		for (j = 0; j <= K; j++) {
			dp[i + 1][j] += dp[i][j];
			if (j + A[i] <= K) dp[i + 1][j + A[i]] += dp[i][j];
		}
	}
	vector<vector<int>> sum(K,vector<int>(K,0));
	for (i = 0; i < K; i++) {
		for (j = 1; j < K; j++) {
			if (i - j >= 0) sum[i][j] = -sum[i-j][j] + dp[N][i];
			else sum[i][j] = dp[N][i];
		}
	}
	for (i = 0; i < N; i++) {
		ll valid = 0;
		if (K <= A[i]) valid = 1;
		else {
			for (j = K - A[i]; j < K; j++) {
				if (sum[j][A[i]] >= 1) {
					valid = 1;
					break;
				}
			}
		}
		if (!valid) ans++;
	}
	co(ans);
}

