				dp[i+1][j]=1;
				if(i!=m&&j+a[i]<k)dp[i+1][j+a[i]]=1;
			}
		}
	}
	for(int i=max(0,k-a[m]);i<k;i++)if(dp[n][i])return true;
	return false;
}
