int main() {
    int N;
    ll K;
    cin >> N >> K;
    for (int i = 1; i <= N; i++) cin >> a[i];
    if (N > 400 || K > 400) return 0;
    int ans = 0;
    for (int i = 1; i <= N; i++) {
        // i番目のカードが不要かどうかを確かめる
        vector<int> other_a;
        other_a.push_back(0);
        for (int j = 1; j <= N; j++) {
            if (i == j) continue;
            other_a.push_back(a[j]);
        }
        for (int j = 0; j < N; j++) {
            for (int k = 1; k < K; k++) dp[j][k] = 0;
        }
        for (int j = 0; j < N; j++) dp[j][0] = 1;
        for (int j = 1; j < N; j++) {
            for (int k = 0; k < K; k++) {
                dp[j][k] += dp[j - 1][k];
                if (k - other_a[j] >= 0) dp[j][k] += dp[j - 1][k - other_a[j]];
            }
        }
        bool is_needed = false;
        for (int j = 1; j < K; j++) {
            if (dp[N - 1][j] > 0 && j + a[i] >= K) {
                is_needed = true;
            }
        }
        if (!is_needed) ans++;
    }
    cout << ans << endl;
    return 0;
}

