int main() {
	int n, k;
	cin >> n >> k;
	ll a[n];
	ll sum = 0;
	bool used[n];
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		sum += a[i];
		used[i] = false;
	}

	sort(a, a + n, greater<ll>());
	if (sum < k) {
		cout << n << endl;
		return 0;
	}
	int index = 0;
	for(int i = 0; i < n; i++) {
		if(a[i] < k) {
			index = i;
			break;
		} else {
			used[i] = true;
		}
	}

	for (int i = index; i < n - 1; i++) {
		for (int j = i + 1; j < n; j++) {
			if (a[i] + a[j] >= k) {
				used[i] = used[j] = true;
			}
		}
	}

	bool ok = false;
	for (int i = index; i < n; i++) {
		if (ok) {
			break;
		}
		ll subSum = a[i];
		ll diff = k - subSum;
		int pos = i + 1;
		stack<ll> s;
		s.push(i);
		while (true) {
			for (int j = pos; j < n; j++) {
				if (subSum + a[j] < k) {
					subSum += a[j];
					s.push(j);
					pos = j + 1;
					break;
				} else if (!used[j] && subSum + a[j] >= k) {
					s.push(j);
					break;
				}
			}
			if (subSum >= k) {
				while (!s.empty()) {
					used[s.top()] = true;
					s.pop();
				}
				break;
			}
			if (pos == n) {
				ok = true;
				break;
			}
		}
	}

	ll ans = 0;
	for (int i = index; i < n; i++) {
		if (!used[i]) {
			ans++;
		}
	}
	cout << ans << endl;


	return 0;
}

