const int mod = 61559;
int n, k, arr[5005];
unsigned short Forward[5005][5005], backward[5005][5005][2], DP[5005][5005];
bitset <5005> vis[5005];
int fun(int ind, int rem)
{
	if (ind == n && rem == 0) return 1;
	if (ind == n) return 0;
	if (vis[ind][rem]) return DP[ind][rem];

	// I go
	vis[ind][rem] = 1;
	int res = 0;
	backward[ind][rem][1] = fun(ind+1, max(0, rem-arr[ind]));
	res += backward[ind][rem][1];
	res %= mod;

	// I dont go

	backward[ind][rem][0] = fun(ind+1, rem);
	res += backward[ind][rem][0];
	res %= mod;

	return DP[ind][rem] = res;
}
bool upper = true;
int fun2(int ind, int rem)
{
	if (rem < 0)
	{
		if (! upper) return 0;
		rem = 0;
	}
	if (ind == n && rem == 0) return 1;
	if (ind == n) return 0;
	if (vis[ind][rem]) return DP[ind][rem];
	vis[ind][rem] = 1;
	// I go
	int res = 0;
	int temp = fun2(ind+1,rem-arr[ind]);
	res += temp;
	res %= mod;

	// I dont go

	Forward[ind][rem] = fun2(ind+1, rem);
	res += Forward[ind][rem];
	res %= mod;

	return DP[ind][rem] = res;
}

inline int mul(int A, int B){return (((int) A)*B) % mod;}
void solve()
{

	cin >> n >> k;
	rep(i,0,n) cin >> arr[i];

	memset(vis, 0, sizeof vis);


	rep(i,0,k+1)fun(0, i);

	reverse(arr, arr+n);


	memset(vis, 0, sizeof vis);

	fun2(0, k);
	upper = false;

	memset(vis, 0, sizeof vis);
	rep(i,0,k)fun2(0, i);

	reverse(arr, arr+n);

	int ans = 0;

	rep(i,0,n)
	{
		ll num_with_me = 0, num_without_me = 0;

		rep(j,0,k+1)
		{
				num_with_me += ( Forward[n-i-1][j] * backward[i][k-j][1]);
				num_without_me += ( Forward[n-i-1][j] * backward[i][k-j][0]);

		}
		if (num_without_me == num_with_me) ans++;
	}
	cout << ans << "\n";
}
signed main()
{
	ios_base::sync_with_stdio(false);cin.tie(NULL);

 	#ifdef local
