	std::sort(a, a + n, std::greater<long long>());
	int left{-1}, right{n};
	while (left + 1 < right)
	{
		int mid{(left + right) / 2};
		if (need(k - a[mid], k, n - 1, mid)) left = mid;
		else right = mid;
	}
	printf("%d\n", n - left - 1);

	delete[] a;
