/* -----  2019/03/21  Problem: ABC 056 D / Link: http://abc056.contest.atcoder.jp/tasks/abc056_d  ----- */

struct Cumusum {
	vector<LL>csum;
	Cumusum(vector<LL>&a) {
		csum.assign((int)a.size() + 1, 0);
		for (int i = 0; i < (int)a.size(); i++) {
			csum[i + 1] = csum[i] + a[i];
		}
	}
	LL query(int l, int r) {
		return csum[r] - csum[l];
	}
};

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	LL N, K; cin >> N >> K;
	vector<LL> a(N);
	for (int i = 0; i < N; ++i) {
		cin >> a[i];
	}

	// prebuild back dp
	VVL dpB(N + 1, VL(K + 1, 0));
	dpB[N][0] = 1;
	FORR(i, N, 0) {
		int A = a[i - 1];
		FOR(k, 0, K + 1 - A) {
			dpB[i - 1][k + A] |= dpB[i][k];
		}
		FOR(k, 0, K + 1) {
			dpB[i - 1][k] |= dpB[i][k];
		}
	}


	VL dp(K + 1, 0);
	dp[0] = 1;
	LL ans = N;
	FOR(i, 0, N) {

		// build back dp cumsum
		Cumusum asum(dpB[i+1]);


		// query [K-a[i]-s,K-s) is exist
		bool exist = 0;
		FOR(s, 0, K+1) {
			if (dp[s]) {
				int L = max(0LL, K - s - a[i]);
				int R = max(0LL, K - s);
				exist |= asum.query(L, R) > 0;
			}
		}
		// if(exist)need.
		ans -= exist;

		// front dp
		FORR(k, K - a[i], 0 - 1) {
			dp[a[i] + k] |= dp[k];
		}
	}

	cout << (ans) << "\n";

	return 0;
}

