const int N=5e3 + 5,M=5e5+5, MOD=1e9 + 7;
int memo[N][N];
int n,arr[N],k,bad;
map<int,int> ind;
vector<int> vec;
int dp(int i,int sum){
    if(sum>=k)return 0;
    if(i>=n)return sum;
    int &res=memo[i][sum];
    if(res!=-1)return res;
    if(i==bad){
        return dp(i+1,sum);
    }
    return max(dp(i+1,sum+arr[i]),dp(i+1,sum));
}
bool valid(int i){
    int x=vec[i];
    memset(memo,-1, sizeof(memo));
    bad=ind[x];
    return dp(0,0)>=k-x;
}
