bool need(int x);
int solve();

int main() {
  cin >> n >> k;
  for(int i = 0; i < n; ++i) {
    int x;
    cin >> x;
    a.push_back(x);
  }
  sort(a.begin(), a.end());
  cout << solve() << endl;
  return 0;
}

int solve() {
  int l = 0, r = n - 1, now;
  while(l <= r) {
    if(r - l < 2) {
      if(need(l))
        return l;
      else if(need(r))
        return r;
      else
        return r + 1;
    }
    now = (l + r) / 2;
    if(need(now))
      r = now;
    else
      l = now;
  }
  return -1;
}

bool need(int x) {
  if(a[x] >= k) return 1;
  bool memo[2][10005] = {0};
  memo[1][0] = 1;
  for(int i = 0; i < n; ++i)
    for(int j = 0; j <= 10000; ++j)
      if(memo[1 - i % 2][j] && j + a[i] <= 10000)
        memo[i % 2][j + a[i]] = 1;
  for(int i = k; i < k + a[x]; ++i)
    if(memo[(n - 1) % 2][i]) return 1;
  return 0;
}

