#include <algorithm>
#include <array>
#include <cstdio>
#include <cmath>

using namespace std;

array<int, 5000> need;

int K = 0;
int tmp = 0;
int mid = 0;

bool BisectionMethod()
{
    if (tmp + need[mid] < K) return true;
    else return false;
}

int main()
{
    int N;
    if (scanf("%d%d", &N, &K) < 2) return 0;

    int num = N;
    int ans = 0;

    for (int i = 0; i< N; i++)
    {
        if (scanf("%d", &tmp) < 1) return 0;

        // greater than or equal to K
        // no need
        if (tmp >= K) num--;
        else
        {
            // candidate
            need[ans] = tmp;
            ans++;
        }
    }

    // ascending
    sort(need.begin(), need.begin() + ans);

    tmp = 0;
    while (num >= 2)
    {
        // add in from the bigger one
        tmp += need[num - 1];

        if (need[num - 2] + tmp < K)
        {
            num--;
            continue;
        }

        // need all
        if (need[0] + tmp >= K)
        {
            ans = 0;
            break;
        }

        // find unnecessary numbers
        // bisection method
        int under = 0;
        int upper = num - 2;

        while (under + 1 < upper)
        {
            // Bisection Method
            // [under, upper]
            // to narrow the range
            mid = (under + upper) / 2;

            bool flg = BisectionMethod();

            if (flg) under = mid;
            else upper = mid;
        }

        ans = ans - (num - upper);
        num = upper;
    }
    printf("%d\n", ans);
    return 0;
}

