vi Manacher(string s){
  vi R(s.size());
  int i = 0, j = 0;
  while(i < s.size()){
    while(i-j >= 0 && i+j < s.size() && s[i-j] == s[i+j]) ++j;
    R[i] = j;
    int k = 1;
    while(i-k >= 0 && i+k < s.size() && k+R[i-k] < j) R[i+k] = R[i-k], k++;
    i += k; j -= k;
  }
  return R;
}

vi Z_algorithm(string &s){
  vi Z(s.size());
  Z[0] = s.size();
  int i = 1, j = 0;
  while(i < s.size()){
    while(i+j < s.size() && s[j] == s[i+j]) j++;
    Z[i] = j;
    if(j == 0){++i; continue;}
    int k = 1;
    while(i+k < s.size() && k+Z[k] < j) Z[i+k] = Z[k], ++k;
    i += k; j -= k;
  }
  return Z;
}

const int MAX = 1e6+1;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(ll n, ll k){
  if(n >= MAX){
    ll tmp = 1;
    rep(i,k){
      tmp *= (n-i);
      tmp %= MOD;
    }
    return tmp*finv[k]%MOD;
  }

  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll POW(ll x, ll n){
  ll ret = 1;
  if(n < 0){// n < 0 にも対応
    n *= -1;
    x = inv[x];
  }
  while(0 < n){
    if(n%2 == 0){
      x = x*x%MOD;
      n /= 2;
    }
    else{
      ret = ret*x%MOD;
      n--;
    }
  }
  return ret;
}

int main(){
  // O(K N^2) 部分点解法
  int n, K; cin >> n >> K;
  vi a(n); rep(i,n) cin >> a[i];
  int dp1[n+1][K+1], s1[K+1];
  int ans = n;
  rep(i,n) {
    // i を抜く
    if(a[i] >= K){
      ans--;
      continue;
    }
    memset(dp1, 0, sizeof(dp1));
    memset(s1, 0, sizeof(s1));
    dp1[0][0] = true;
    rep(j,n) rep(k,K+1) {
      if(!dp1[j][k]) continue;
      // j を使用しない
      dp1[j+1][k] = true;
      // j を使用する
      if(i == j) continue;
      dp1[j+1][min(K, k+a[j])] = true;
    }
    /*
    // [K-a[i], K-1] が true かどうか判定 -> ここも累積和で高速化したい
    bool need = false;
    for(int x = K-a[i]; x < K && !need; x++) {
      if(dp1[n][x]) need = true;
    }
    if(need) ans--;
    */
    rep(k,K) s1[k+1] = s1[k] + dp1[n][k];
    if(s1[K] - s1[K-a[i]]) ans--;
  }

  cout << ans << endl;

}

