LL sum[N],a[N];
int cmp(LL a,LL b){
	return a > b;
}
int solve(int L,int R,LL k,int from){
	int l = L,r = R,res = -1;
	while (l <= r){
		int m = (l + r) / 2;
		if (sum[m] - sum[from - 1] >= k){
			res = m;
			r = m - 1;
		}
		else l = m + 1;
	}
	return res;
}
