// クラスカル法
// 連結グラフの最小全域木を求める
class Kruskal {
private:
  Graph graph;
  vector<Edge> MinimumSpanningTree;
  ll minimumCost;
  void searchMinimumSpanningTree() {
    UnionFindTree uf(graph.nodes);
    sort(all(graph.edges));
    itrep(edge, graph.edges) {
      if (!uf.same(edge->from, edge->to)) {
        uf.unite(edge->from, edge->to);
        MinimumSpanningTree.push_back(*edge);
      }
    }
  }

public:
  Kruskal(Graph graph) { this->graph = graph; }
  ll getMinimumSpanningTreeCost() {
    searchMinimumSpanningTree();
    ll cost = 0;
    itrep(it, MinimumSpanningTree) { cost += it->cost; }
    return cost;
  }
};

// ダイクストラ法 O((E+V)logV)
// 最小経路問題を解くためのアルゴリズム。辺の重みに負数を含む場合は利用不可
// 無向グラフ
class Dijkstra {
private:
  Graph graph;
  map<ll, vector<Edge>> fromPaths;
  vl distances;
  vl srcs;

public:
  Dijkstra(Graph graph) {
    this->graph = graph;
    itrep(edge, graph.edges) {
      fromPaths[edge->from].push_back(*edge);
      fromPaths[edge->to].push_back(Edge(edge->to, edge->from, edge->cost));
    }
  }
  void searchMinimumPathFrom(ll src) {
    // 複数回呼ばれる度に計算する
    this->distances = vl(graph.nodes + 1, INF);
    this->srcs = vl(graph.nodes + 1, INF);

    priority_queue<ll> pq;
    distances[src] = 0;
    srcs[src] = -1;

    pq.push(src);
    while (!pq.empty()) {
      int u = pq.top();
      pq.pop();

      itrep(edge, fromPaths[u]) {
        int v = edge->to;
        int w = edge->cost;
        if (distances[v] > distances[u] + w) {
          distances[v] = distances[u] + w;
          srcs[v] = u;
          pq.push(v);
        }
      }
    }
  };
  ll getDistance(ll n) { return this->distances[n]; }
  ll getFrom(ll n) { return this->srcs[n]; }
};

// ベルマンフォード O(|V||E|)
// 負コストが含まれていても最短経路問題を解くためのアルゴリズム。閉路の検出も可能
// 有向グラフ
class BellmanFord {
private:
  Graph graph;
  // 閉路が含まれるかは個々のノードごとに管理する必要あり
  vector<bool> hasNegativeCycles;
  vector<ll> distances;

public:
  BellmanFord(Graph graph) {
    this->graph = graph;
    this->distances = vector<ll>(this->graph.nodes + 1, INF);
    this->hasNegativeCycles = vector<bool>(this->graph.nodes + 1, false);
  }
  void searchMinimumPathFrom(ll src) {
    this->distances[src] = 0;

    for (ll i = 0; i < graph.nodes - 1; i++) {
      itrep(edge, graph.edges) {
        ll u = edge->from;
        ll v = edge->to;
        ll w = edge->cost;
        if (this->distances[u] != INF) {
          chmin(this->distances[v], this->distances[u] + w);
        }
      }
    }

    itrep(edge, graph.edges) {
      ll u = edge->from;
      ll v = edge->to;
      ll w = edge->cost;
      if (this->distances[u] == INF) {
        continue;
      }
      if (this->distances[u] + w < this->distances[v]) {
        this->hasNegativeCycles[v] = true;
      }
    }

    for (ll i = 0; i < graph.nodes; i++) {
      itrep(edge, graph.edges) {
        ll u = edge->from;
        ll v = edge->to;
        ll w = edge->cost;
        if (this->distances[u] == INF) {
          continue;
        }
        chmin(this->distances[v], this->distances[u] + w);
        if (this->hasNegativeCycles[u] == true) {
          this->hasNegativeCycles[v] = true;
        }
      }
    }
  }
  ll getDistance(ll n) { return this->distances[n]; }
  bool hasNegativeCycle(ll n) { return this->hasNegativeCycles[n]; }
};

void solve(long long N, long long K, std::vector<long long> a) {
  //左からi番目までで総和kを作れるか
  vector<vector<bool>> dp1(N, vector<bool>(K));
  //右からi番目までで総和kを作れるか
  vector<vector<bool>> dp2(N, vector<bool>(K));

  dp1[0][0] = true;
  dp1[0][a[0]] = true;
  dp2[N - 1][0] = true;
  dp2[N - 1][a[N - 1]] = true;
  rep(i, 1, N) {
    rep(k, 0, K) {
      dp1[i][k] = dp1[i][k] | dp1[i - 1][k];
      if (a[i] + k < K) {
        dp1[i][a[i] + k] = dp1[i][a[i] + k] | dp1[i - 1][k];
      }
    }
  }
  rrep(i, 0, N - 1) {
    rep(k, 0, K) {
      dp2[i][k] = dp2[i][k] | dp2[i + 1][k];
      if (a[i] + k < K) {
        dp2[i][a[i] + k] = dp2[i][a[i] + k] | dp2[i + 1][k];
      }
    }
  }

  vector<vector<int>> cum1(N, vector<int>(K + 1));
  vector<vector<int>> cum2(N, vector<int>(K + 1));
  rep(i, 0, N) {
    rep(k, 1, K + 1) {
      cum1[i][k] = cum1[i][k - 1] + dp1[i][k - 1];
      cum2[i][k] = cum2[i][k - 1] + dp2[i][k - 1];
    }
  }

  ll ans = 0;
  rep(i, 0, N) {
    ll start = max(K - a[i], 0ll);
    bool need = false;
    rep(s, start, K) {
      if (i == 0) {
        if (cum2[i + 1][s + 1] - cum2[i + 1][s] > 0) {
          need = true;
          break;
        }
      } else if (i == N - 1) {
        if (cum1[i - 1][s + 1] - cum1[i - 1][s] > 0) {
          need = true;
          break;
        }
      } else {
        if (dp1[i - 1][s]) {
          int mi = (int)(max(0ll, K - a[i] - 1 - s));
          if (cum2[i + 1][K - s] - cum2[i + 1][mi] > 0) {
            need = true;
            break;
          }
        }
        if (dp2[i + 1][s]) {
          int mi = (int)(max(0ll, K - a[i] - 1 - s));
          if (cum1[i - 1][K - s] - cum1[i - 1][mi] > 0) {
            need = true;
            break;
          }
        }
      }
    }
    if (!need) {
      ans++;
    }
  }

  print(ans);
}

int main() {
  long long N;
  scanf("%lld", &N);
  long long K;
  scanf("%lld", &K);
  std::vector<long long> a(N);
  for (int i = 0; i < N; i++) {
    scanf("%lld", &a[i]);
  }
  solve(N, K, std::move(a));
  return 0;
}

