vec A;
vec dp;
vec dpNew;

bool judge(ll piv)
{
  ll target = A[piv];

  REP(i, 5001)
  {
    dp[i] = 0;
    dpNew[i] = 0;
  }
  dp[0] = 1;

  REP(i, piv)
  {

    REP(j, 5001)
    {
      ll x = A[i];
      if (j - x >= 0)
        dpNew[j] = dp[j - x];
    }
    REP(j, 5001)
    {
      dp[j] |= dpNew[j];
      dpNew[j] = 0;
    }
  }
  bool f = false;

  REP(i, k)
  {
    OUT2(i, dp[i]);
  }

  for (ll i = k - target; i < k; i++)
  {
    if (k - target < 0)
      continue;
    if (dp[i] == 1)
    {
      f = true;
      break;
    }
  }
  return f;
}

int main(void)
{

  cin >> n >> k;
  A.resize(n);
  input(A);

  sort(begin(A), end(A));
  ll sum = 0;
  REP(i, n)
  {
    sum += A[i];
  }

  auto itr = lower_bound(begin(A), end(A), k);
  ll l = 0;
  ll r = (itr - begin(A)) - 1;

  dp.resize(5001, 0);
  dpNew.resize(5001, 0);

  if (sum < k)
  {
    cout << n << endl;
    return 0;
  }

  while (r - l > 1)
  {
    ll piv = l + (r - l) / 2;
    OUT3(l, r, piv);

    bool f = judge(piv);
    OUT2("f", f);
    if (f)
    {
      r = piv;
    }
    else
    {
      l = piv;
    }
  }
  OUT2("l", "r");
  OUT2(l, r);

  auto f1 = judge(l);
  auto f2 = judge(r);
  OUT2(f1, f2);

  if (!f2)
  {
    cout << r << endl;
  }
  else
  {
    cout << l << endl;
  }

  return 0;
}

