bool check_needed(vector<int> v, int i, int n, int k) {
  bool dp[n][k] = {};
  dp[0][0] = true;
  int ai = v[i];
  v.erase(v.begin() + i);
  REP(j,n) {
    REP(l,k) {
      if(dp[j][l]) {
        dp[j+1][l] = true;
      }
      if(l-v[j] >= 0 && dp[j][l-v[j]]) {
        dp[j+1][l] = true;
      }
    }
  }
  bool answer = false;
  for(int j=k-ai;j<k;j++) { if(dp[n-1][j]) answer = true; }
  return answer;
}

