  vector<bool> dp(2*k+1,false);
  dp[a[cn]] = true;
  rep(i,a.size()){
    if(i==cn) continue;
    vector<bool> ndp(2*k+1);
    rep(j,2*k+1) ndp[j] = dp[j];
    rep(j,2*k+1){
      if(j-a[i]>=0){
	ndp[j] = (dp[j-a[i]] || ndp[j]);
      }
    }
    rep(j,2*k+1) dp[j] = ndp[j];
  }
  for(int i=k;i<k+a[cn];i++){
    if(dp[i]) return true;   
  }
  return false;
}




