bool can_make[MAX_N][MAX_N];

bool check(const int id) {
    if (K <= a[id]) {
        return true;
    }

    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= K; j++) {
            can_make[i][j] = false;
        }
    }

    can_make[0][0] = true;

    for (int i = 1; i <= N; i++) {
        for (int j = 0; j <= K; j++) {
            if (can_make[i-1][j]) {
                can_make[i][j] = true;
            }
            if (i != id && j + a[i] <= K && can_make[i-1][j]) {
                can_make[i][j + a[i]] = true;
                //std::cout << i << " " << j + a[i] << std::endl;
            }
        }
    }

    for (int k = K - a[id]; k < K; k++) {
        if (can_make[N][k]) {
            return true;
        }
    }

    return false;
}


