    if (x < K) arr.push_back(x);
  }

  sort(rall(arr));

  boolGraph dp(arr.size()+1, vb(K, false));
  rep(i,dp.size()) dp[i][0] = true;
  rep(i,arr.size()) {
    rep(j,K-arr[i]) {
      dp[i+1][j+arr[i]] = dp[i][j] || dp[i][j+arr[i]];
    }
  }

