{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n,k; cin>>n>>k;
    vll a(n);
    rep(i,n) cin>>a[i];
    vector<vi> dp(n+1,vi(k,0));
    vector<vi> dp2(n+1,vi(k,0));
    dp[0][0] = 1;
    rep(i,n)rep(j,k){
        if ((ll)j>=a[i])
            dp[i+1][j] = max(dp[i][j-a[i]],dp[i][j]);
        else
            dp[i+1][j] = dp[i][j];
    }
    dp2[n][0] = 1;
    rep(i,n)rep(j,k){
        if ((ll)j>=a[n-i-1])
            dp2[n-i-1][j] = max(dp2[n-i][j-a[n-i-1]],dp2[n-i][j]);
        else
            dp2[n-i-1][j] = dp2[n-i][j];
    }
    int ans=0;
    rep(i,n){
        vi A = dp[i];
        vi B = dp2[i+1];
        auto C = FastFourierTransform::multiply(A,B);
        bool need=false;
        rep(j,k)if(C[j]>0 && a[i]+j>=k){
            need=true;
            break;
        }
        if (!need) ans++;
    }
    cout<<ans<<endl;
    return 0;
