bool isNoNeed(int index){
  //i枚目まで使った時にjにできるか
  //trueできる，falseできない
  bool dp[N+1][K];
  rep(i,N+1) rep(j,K) dp[i][j] = false;
  dp[0][0] = true;
  rep(i,N){
    rep(j,K){
      dp[i+1][j] = dp[i][j];
