int main(void){
	int n, k; cin >> n >> k;
	vector<int> a(n);
	rep(i, n) scanf("%d", &a[i]);
	sort(a.begin(), a.end());
	int m = lower_bound(a.begin(), a.end(), k) - a.begin();
	if(m == 0){
		cout << 0 << endl;
		return 0;
	}
	int ans = 0;

	vector<bool> dpb(k, false); dpb[0] = true;
	vector<vector<bool>> dp(m+2, dpb);
	vector<vector<bool>> rdp(m+2, dpb);

	reg(i, 1, m) irep(j, k) if(dp[i-1][j]){
		dp[i][j] = true;
		if(a[i-1]+j<k) dp[i][a[i-1]+j] = true;
	}
	ireg(i, 1, m) irep(j, k) if(rdp[i+1][j]){
		rdp[i][j] = true;
		if(a[i-1]+j<k) rdp[i][a[i-1]+j] = true;
	}

	reg(i, 1, m){
		bool f = true;
		if(i == 1){
			reg(j, 1, a[i-1]) if(rdp[2][k-j]){
				f = false;
				break;
			}
		}else if(i == m){
			reg(j, 1, a[i-1]) if(dp[m-1][k-j]){
				f = false;
				break;
			}
		}else{
			int l = k-1;
			reg(j, 0, k) if(dp[i-1][j]){
				if(k-j <= l) l = k-j-1;
				if(l<0) break;
				while(k-a[i-1]-j <= l){
					if(rdp[i+1][l]){
						f = false;
						break;
					}
					l--;
					if(l<0) break;
				}
				if(!f) break;
			}
		}
		if(f) ans++;
	}

	cout << ans << endl;

	return 0;
}

