                        gsets.push_back(tmp);
                    }else{
                        sets_next[tmp]++;
                    }
                }
            }

            for(long long k=0; k<MAX_K; k++ ){
                if( sets_next[k] > sets[k] ){
                    sets[k]= sets_next[k];
                }
            }

        }

        bool flag;
        flag=true;
        for(auto v: gsets){
            if( v-a[ii] < K ){
                //cout << "ii v " << ii << " " << v << endl;
                flag=false;
            }
        }
        if(flag){
            //cout << "ans++ ii a[ii]= " << ii << " " << a[ii] << endl; 
            ans++;
        }

    }

    cout << ans << endl;

    return 0;
}

