int main(){
	scanf("%d%lld", &n, &k);
	LL sum = 0;
	for(int i = 0; i < n; ++i)
		scanf("%lld", num + i), sum += num[i];
	if(sum < k){
		printf("%d\n", n);
		return 0;
	}
	sort(num, num + n, greater<int>());
	int res = 0;
	for(int i = 0; i < n; ++i){
		if(num[i] >= k){
			res++;
			continue;
		}
		int c = 0;
		for(int j = 0; j < n; ++j)
			if(j != i)	dp[c++] = num[j];
		bool flag = true;
		LL x = 0;
		LL p = k - num[i];
		for(int j = 0; j < c; ++j){
			x += dp[j];
			if(x >= p){
				if(x >= p && x < k)	flag = false;
				x -= dp[j];
			}
		}
		if(!flag)	res++;
	}
	printf("%d\n", n - res);
	return 0;
}

