    rep(i, n) {
        if (i == x) {
            continue;
        }
        if (a[i] >= k) {
            continue;
        }
        bitset<5050> next = bs << a[i];
        bs |= next;
    }
    repp(i, max(0ll, k - a[x]), k) {
        if (bs[i]) {
            return true;
        }
    }
    return false;
}

