        scanf("%lld", &A[i]);
    }

    int dp[N][K];

    for (int i = 0; i < N; ++i) {

        for (int k = 0; k < N; ++k) {
            for (int l = 0; l < K; ++l) {
                dp[k][l] = 0;
            }
        }
        dp[0][0] = 1;

        int count = 0;
        bool flag = false;
        for (int j = 0; j < N; ++j) {
            if(i==j) continue;

