                    if (now >= K - A[i] && now < K){
                        flag = true;
                        break;
                    }else if (now < K - A[j]) {
                        dp[count][now] = 1;
                    }
                }
            }

            if(flag){
                break;
            }
        }

        if(!flag) ans++;
    }

    printf("%d\n", ans);
}

