  ll sum[n + 1];
  for (ll i = 0; i <= n; i++) {
    sum[i] = 0;
    if (i != 0) {
      sum[i] = a[i - 1] + sum[i - 1];  
    }  
  }
  ll good_num = 0;
  for (ll size = 1; size <= n; size++) {
    if (size == 1) {
      for (ll j = 0; j < n; j++) {
        if (a[j] >= k) {
          good_num++;    
        }  
      }  
    }    
    else {
      if (good_num + size - 1 > n) {
        continue;  
      }
      // a[good_num]からスタートする
      ll now = sum[good_num + size - 1] - sum[good_num + size - 2];
      ll sub = 0;
      for (ll j = good_num + size - 1; j < n; j++) {
        if (a[j] + now >= k) {
          sub++;  
        }  
      }  
      if (sub > 0) {
        good_num += sub + size - 1;  
      }
    }
  } 
  cout << n - good_num << endl;
