void gns(int &a, int mod) {
	a %= mod;
	if(a < 0) a += mod;
}

vector<int> tvi(int a) {
	vector<int> v;
	for(int i = 0; i < vod.size(); ++i) {
		v.push_back(a);
		gns(v[i], vod[i]);
	}
	return v;
}

struct vint {
	vector<int> vum;

	vint() {
		vum.resize(vod.size(), 0);
	}

	void add(vint v) {
		for(int i = 0; i < vum.size(); ++i) {
			vum[i] += v.vum[i];
			gns(vum[i], vod[i]);
		}
	}

	void sub(vint v) {
		for(int i = 0; i < vum.size(); ++i) {
			vum[i] -= v.vum[i];
			gns(vum[i], vod[i]);
		}
	}

	bool is0() {
		for(int i = 0; i < vum.size(); ++i) {
			if(vum[i]) return 0;
		}
		return 1;
	}

	void set(int a) {
		vum = tvi(a);
	}
};

