void add(ll x, ll a) {
	x++;
	for (ll i = x; i <= 5100; i += i & -i) dat[i] += a;
}

ll sum(ll x) {
	if (x < 0)return 0;
	x++;
	ll res = 0;
	for (int i = x; i > 0; i -= i & -i) res += dat[i];
	return res;
}


bool dp[5100][5100]; //上限5001
int main() {
	cin >> n >> k;
	REP(i, n)cin >> s[i];
	dp[0][0] = 1;
	add(0, 1);
	REP(i, n) {
		REP(j, k + 1) {
			if (dp[i][j]) {
				dp[i + 1][j] = true;
				dp[i + 1][min((ll)5001, j + s[i])] = true;
			}
		}
	}
	REPR(i, n - 1) {
		bool ok = true;
		REP(j, k) {
			if (dp[i][j]) {
				if (sum(max(0ll, k - 1 - j)) - sum(k - s[i] - 1 - j) > 0) {
					ok = false;
				}
			}
		}
		if (ok)ans++;
		REPR(j, 5001) {
			if (sum(j) - sum(j - 1) > 0)add(min((ll)5001, j + s[i]), 1);
		}
	}
	cout << ans << endl;
}

