bool need(int index, const VL& a_list, int k){ // 0index
    fill_n((bool*)dp, 5010 * 5010, false);
    dp[0][0] = true;
    FOR(i, 1, a_list.size()){
        FOR(j, 0, k){
            if(j - a_list[i - 1] >= 0 && i - 1 != index)
                dp[i][j] = dp[i - 1][j] | dp[i - 1][j - a_list[i - 1]];
            else
                dp[i][j] = dp[i - 1][j];
        }
    }

    FOR(i, max(k - (int)a_list[index], 0), k - 1)
        if(dp[a_list.size()][i]) return true;

    return false;
}


