  //   cerr << endl;
  // }

  ll ans = 0;
  ll tmp = dp3[1][k - 1];
  if (k - a[0] - 1 >= 0) {
    tmp -= dp3[1][k - a[0] - 1];
  }
  if (a[0] < k && tmp == 0) ans++;
  // cerr << ans << endl;
  if (a[n - 1] <= k - 1) {
    ll cnt = 0;
    // cerr << dp1[n - 2][k - a[n - 1]] << endl;
    REP(v, max(0LL, k - a[n - 1]), k) {
      if (dp1[n - 2][v]) {
        cnt++;
        break;
      }
    }
    if (a[n - 1] < k && cnt == 0) {
      ans++;
    }
  }
  // cerr << ans << endl;
  REP(i, 1, n - 1) {
    if (a[i] >= k) continue;
    ll cnt = 0;
    rep(v, k) {
      if (dp1[i - 1][v] || v == 0) {
        ll tmp = dp3[i + 1][k - 1 - v];
        if (k - v - a[i] - 1 >= 0) {
          tmp -= dp3[i + 1][k - a[i] - v - 1];
        } else if (v > 0 && k - a[i] >= v) {
          cnt++;
          continue;
        }
        if (tmp > 0) {
          cnt++;
        }
      }
