using lint = long long;

int main() {
    int N; lint K;
    cin >> N >> K;
    vector<lint> a(N);
    for (int i = 0; i < N; i++) {
        cin >> a[i];
    }

    sort(a.begin(), a.end());

    int ans = 0;
    int lb = 0, ub = N;
    while (ub - lb > 0) {
        int mid = (lb + ub)/2;

        lint Kp_min = max(lint(0), K - a[mid]);
        lint Kp_max = K;

        vector<lint> ap = a;
        ap.erase(ap.begin() + mid);

        vector<vector<bool>> can(N, vector<bool>(K + 1, false));
        can[0][0] = true;
        for (int j = 1; j <= N - 1; j++) {
            for (int k = 0; k <= K; k++) {
                if (can[j - 1][k] == true) {
                    can[j][k] = true;
                }
                if (k - ap[j - 1] >= 0 and can[j - 1][k - ap[j - 1]] == true) {
                    can[j][k] = true;
                }
            }
        }

        bool need = false;
        for (int j = Kp_min; j < Kp_max; j++) {
            if (can[N - 1][j] == true) {
                need = true;
                break;
            }
        }

        if (need == true) {
            ub = mid;
        } else {
            lb = mid + 1;
        }
    }

    cout << lb << endl;
    return 0;
}

