		LL a = a_list[i];
		for (int j = dp.size() - 1; j >= 0; --j) {
			if (dp[j] == 1 && j + a < dp.size()) {
				dp[j + a] = 1;
			}
		}
	}

	FOR(i, 0, dp.size()) {
		if (i < K && dp[i] == 1) {
			if (a_list[idx] + i >= K) {
				return true;
			}
		}
	}

	return false;
}

int main(int argc, char *argv[]) {
	int N, K;
	cin >> N >> K;
	vector<LL> a_list(N);
	FOR(i, 0, N) {
		cin >> a_list[i];
	}
	sort(ALL(a_list));

	int low = -1, high = N, ans = 0;
	while (high - low > 1) {
		int middle = (low + high) / 2;
		if (is_necessary(middle, a_list, K)) {
			ans = N - middle;
			high = middle;
		}
		else {
			low = middle;
		}
	}
	cout << N - ans << endl;

	return 0;
}

