    for (int i = 0; i < N; ++i) {
        scanf("%d", &A[i]);
    }

    int dp[N][K];

    for (int j = 0; j < N; ++j) {

        for (int k = 0; k < N; ++k) {
            for (int l = 0; l < K; ++l) {
                dp[k][l] = 0;
            }
        }
        dp[0][0] = 1;

        int count = 0;
        bool flag = false;
        for (int i = 0; i < N; ++i) {
            if(i==j) continue;

            count++;
            for (int k = 0; k < K; ++k) {
                if (dp[count - 1][k] == 1){
                    now = k + A[i];

                    if (now >= K - A[j] && now < K){
                        flag = true;
                        break;
                    }

                    if (now < K - A[j]) {
                        dp[count][now] = 1;
                    }
                }
            }

