//                for (int l = 0; l < K; ++l) {
//                    printf("%d", dp[k][l]);
//                }
//                puts("");
//            }

            if(flag){
                break;
            }
        }

        if(!flag) ans++;
    }

    printf("%d\n", ans);
}

