		for(int val = 0; val < MAX_K; ++val) {
			if(suff[i][val]) {
				int val2 = std::min(MAX_K - 1, val + a[n - 1 - i]);

				suff[i + 1][val] = 1;
				suff[i + 1][val2] = 1;
			}
		}
	}

	int answ = 0;

	for(int i = 0; i < n; ++i) {
		int r = 0;
		int j = n - 1 - i;
		int need = 0;

		for(int l = MAX_K - 1; l >= 0; --l) {
