int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    rep(i, 0, n) cin >> a[i];
    vector<vector<int>> b(n + 2), c(n + 2);
    b[0].emplace_back(0);
    c[n + 1].emplace_back(0);

    rep(i, 0, n) {
        b[i + 1] = b[i];
        for (auto s : b[i]) {
            if (k > s + a[i]) b[i + 1].emplace_back(s + a[i]);
        }
        sort(b[i + 1].begin(), b[i + 1].end());
        b[i + 1].erase(unique(b[i + 1].begin(), b[i + 1].end()), b[i + 1].end());
    }
    for (int i = n - 1; i >= 0; i--) {
        c[i + 1] = c[i + 2];
        for (auto s : c[i + 2]) {
            if (k > s + a[i]) c[i + 1].emplace_back(s + a[i]);
        }
        c[i + 1].emplace_back(-1e5);
        c[i + 1].emplace_back(k);
        sort(c[i + 1].begin(), c[i + 1].end());
        c[i + 1].erase(unique(c[i + 1].begin(), c[i + 1].end()), c[i + 1].end());
    }
    int ans = n;
    rep(i, 0, n) {
        if (a[i] >= k) {
            ans--;
            continue;
        }
        int sum = 0;
        for (auto s : b[i]) {
            int t = *(lower_bound(c[i + 2].begin(), c[i + 2].end(), k - s) - 1);
            if (0 <= s + t && s + t < k)
                sum = max(s + t, sum);
        }
        if (sum + a[i] >= k) {
            ans--;
        }
    }
    cout << ans << endl;
    return 0;
}

