    mid=(r+l)/2;
    for(int i=0;i<n;i++){
      for(int j=0;j<=k;j++){
        if(dp[i][j]){
          dp[i+1][j]=1;
          if(i!=mid&&j+a[i]<=k)
            dp[i+1][j+a[i]]=1;
        }
      }
