int main() {
  int n, k;
  cin>>n>>k;
  vector<int> as;
  for (int i=0; i<n; i++) {
    int x;
    cin>>x;
    if (x < k) {
      as.push_back(x);
    }
  }
  int len = 2*k+1;
  int dp[len], prev_dp[as.size()][len];

  dp[0] = 1;
  for (int i=1; i<len; i++) {
    dp[i] = 0;
  }
  for (int i=0; i<as.size(); i++) {
    for (int j=0; j<len; j++) prev_dp[i][j] = j;
  }
  for (int j=0; j<as.size(); j++) {
    int a = as[j];
    for (int i=len-1; i>=a; i--) {
      if (dp[i-a] > 0) {
        prev_dp[j][i] = i-a;
        ++dp[i];
      }
    }
  }
  int cnt = 0;
  for (int j=0; j<as.size(); j++) {
    int a = as[j];
    bool ok = false;
    for (int i=k; i<k+a; i++) {
      int prev = i;
      for (int l=as.size()-1; l>j; l--) {
        prev = prev_dp[l][prev];
      }
      if (prev_dp[j][prev] != prev) {
        ok = true;
        break;
      }
    }
    if (!ok) {
      ++cnt;
    }
  }
  cout<<cnt<<endl;
}

