	}
	for (int c = 0; c < n; c++) {
		for (int i = 1; i <= n; i++) {
			if (c == (i-1)) {
				for (int j = 0; j < k; j++) {
					dp[c][i][j] = dp[c][i-1][j];
				}
				continue;
			}
			for (int j = 0; j + a[i-1] < k; j++) {
				dp[c][i][j] = (dp[c][i-1][j] or dp[c][i][j]);
