	sort(ALL(a));
	corner(a[N - 1] < K, N);
	int ok = N - 1, ng = 0, md;
	while(ok-ng>1){
		md = (ok + ng) / 2;

		if(a[md]>=K){
			ok = md;
			continue;
		}

		V<ll> b(N,0);
		int idx = 1;
