  a.push_back(0);
  for (int i=0;i<N;++i){
    int a_;cin>>a_;a.push_back(a_);
  }
  a.push_back(0);

  int left[N+2][K+1], right[N+2][K+1];
  memset(left, -1, sizeof(left));
  memset(right, -1, sizeof(right));

  left[0][0]=1;
  right[N+1][0]=1;

  for (int i=0;i<N+1;++i){
    for (int j=0;j<K+1;++j){
      if(left[i][j]==1||(j>=a[i+1]&&left[i][j-a[i+1]]==1)) left[i+1][j]=1;
    }
  }

  for (int i=N+1;i>=1;--i){
    for (int j=0;j<K+1;++j){
      if(left[i][j]==1||(j>=a[i-1]&&left[i][j-a[i-1]]==1)) left[i-1][j]=1;
    }
  }

  vi l_sum[N+2], r_sum[N+2];
  int ans=0;

  for (int i=0;i<N+2;++i){
    for (int j=0;j<K+1;++j){
      if(left[i][j]==1)l_sum[i].push_back(j);
      if(right[i][j]==1)r_sum[i].push_back(j);
    }
  }

  for (int i=1;i<N+1;++i){
    int L=l_sum[i-1].size();
