		dp[2][0] = 1; dp[2][a[2]] = 1;
		for (int i = 3; i <= n; ++i) 
			for (int j = 0; j <= k; ++j) {
				dp[i][j] = dp[i - 1][j];
				if(j >= a[i]) dp[i][j] |= dp[i - 1][j - a[i]]; 
			}
	}
	else {
		dp[1][0] = dp[1][a[1]] = 1;
		for (int i = 2; i <= n; ++i) {
			if(x == i) {
				for (int j = 0; j <= k; ++j) dp[i][j] = dp[i - 1][j]; continue;
			}
			for (int j = 0; j <= k; ++j) {
				dp[i][j] = dp[i - 1][j];
				if(j >= a[i]) dp[i][j] |= dp[i - 1][j - a[i]];
			}
		}
	}
	for (int i = k - a[x]; i < k; ++i) if(dp[n][i]) return 1;
