bool disposable(int k, int discarded, VEC<int> a) {
  int n = a.size();
  bool dp[n + 1][k + 1];
  REPC(i,0,n){REPC(j,0,k){dp[i][j]=0;}}

  dp[0][0] = 1;
  REPC(i, 1, n) {
    REPC(j, 0, k) {
      int item = a[i-1];
      if (j - item >= 0)
        dp[i][j] = dp[i - 1][j] | dp[i - 1][j - item];
      else
        dp[i][j] = dp[i - 1][j];
    }
  }
  // cerr<<endl;
  // REPC(i, 0, n) {
  //   REPC(j, 0, k) { cerr << dp[i][j] << " "; }
  //   cerr << endl;
  // }
  //   cerr << endl;
  REP(i, max(0,k - discarded), k) if (dp[n][i]) { return 0; }
  return 1;
}

