  VEC<int> a(n);
  REP(i, 0, n) cin >> a[i];
  sort(ALL(a));
  // DUMP(a);
  int deletable = 0, necessary = n;
  VEC<int> b(n - 1);
  int mid;
  while (abs(necessary - deletable) > 1) {
    mid = (deletable + necessary) / 2;
    int cnt = 0;
    REP(i, 0, n) {
      if (i != mid) {
        b[cnt] = a[i];
        ++cnt;
      }
    }
    // DUMP(deletable, mid, necessary, ":", a[mid], b);
    if (disposable(k, a[mid], b)) {
      // DUMP(a[mid],"is deletable");
      deletable = mid;
    } else
      necessary = mid;
  }
  cout << necessary << endl;
  return 0;
}

