bool knapsack(vector<ll> &cards, int i, ll k) {
    ll a = cards[i];
    int n = cards.size();
    vector<vector<bool>> dp(n + 1, vector<bool>(k + 1, false));
    dp[0][0] = true;

    auto set = [&](int y, ll x) -> bool {
        if (y > n) return false;
        if (x > k) return false;


        dp[y][x] = true;
        if (k - a <= x && x < k) return true;
        return false;
    };

    rep(y, n) {
        if (y == i) {
            dp[y + 1] = dp[y];
            continue;
        }
        rep(x, k) {
            if (!dp[y][x]) continue;
            // y を使わない
            bool b1 = set(y + 1, x);
            // yを使う
            bool b2 = set(y + 1, cards[y] + x);
            if (b1 || b2) return true;
        }
    }

    return false;

}


