int compare (const void * a, const void * b)
{
                        return ( *(long long*)b - *(long long*)a);
}

int main()
{
  long long N;
  long long K;
  long long a[5010];
  long long i;
  long long j;
  long long maxsum=0;
  long long sets[5010];
  long long sum;
  long long temp;
  long long necessary[5010];
  long long necessarycount=0;
  long long unnecessary=0;
  scanf("%lld %lld",&N,&K);
  for(i=0; i<N;i++) 
  {
          scanf("%lld",&a[i]);
          maxsum+=a[i];
  }
  if(maxsum<K){  
          // all cards are unnecessary since cannot get full sum
          printf("%lld\n",N);
  }else{
          if(maxsum==K){
                  // all cards are necessary since need them to get full sum
                  printf("0\n");
          }else{
                  // find possible subsets of cards
                  qsort(a, N, sizeof(long long), compare);
                  for(i=0; i<N; i++) necessary[i]=0;
                  for(i=0; i<N; i++){
                          sum=maxsum;
                          for(j=0; j<N; j++){
                                  temp = sum - a[(i+j)%N];
                                  if(temp>=K)
                                  {
                                          sum=temp;
                                          sets[j]=0;
                                  }else sets[j]=a[(i+j)%N];
                          }
                          for(j=0;j<N;j++){
                                  if(necessary[(i+j)%N]<sets[j])
                                  {
                                          necessary[(i+j)%N]=sets[j];
                                          necessarycount++;
                                  }
                          }
                  }
                  unnecessary=N-necessarycount;
                  printf("%lld\n",unnecessary);
          }
  }
return 0;
}

