    int ans = 0;
    bitset<5005> dp;
    for(int i=0; i < N; ++i) {
        if(K < a[i]) continue;
        dp[0] = true;
        for(int j=0; j < N; ++j) {
            for(int k=K; k >= a[j]; --k) {
                if(i == j) continue;
                dp[k] = dp[k] | dp[k - a[j]];
            }
        }

        bool need = false;
        for(int k = K - a[i]; k < K; ++k) need |= dp[k];
        if(!need) ++ans;

        dp >>= 5005;
    }
    cout << ans << '\n';
    return 0;
}

