	FOR(i,1,n) sum[i] = sum[i - 1] + a[i];
	int ans = 0;
	FOR(i,1,n){
		LL mi = 0x7fffffffffffffff;
		//cout << mi << endl;
		FOR(j,1,i){
			int p = solve(i,n,k,j);
			if (p != -1 && sum[p] - sum[j - 1] < mi) mi = sum[p] - sum[j - 1];
		}
		if (mi - a[i] >= k) ans ++;
	}
	printf("%d\n",ans);
}

