		cout << N << endl;
		return;
	}
	sort( A.begin(), A.end() );
	int NG = -1;
	int OK;
	vector<bool> dp(K,false);//[0,K-1]まで保持する
	dp[0] = true;
	bool flag = false;
if( A[N-1] < K ){
	for(int i=0;i<N;++i){
		if( i == N-1) continue;
		for(LL var=K-1;var>=0;--var){
			if( dp[var] == false ) continue;
			LL res = var + A[i];
			if( res >= K ) continue;
			dp[ res ] = true;

			if( K-A[N-1] <= res ){
				flag = true;//作れる
				break;
			}
		}
		if( flag ) break;
	}
}else{
	flag = true;
}
	if( flag ){
		OK = N-1;
	}else{
		cout << N << endl;
		return;
	}
	int mid;
	while(OK-NG>1){
		mid = (NG+OK)/2;
		dp.assign(K,false);//[0,K-1]
		dp[0] = true;
		bool flag = false;
		if( A[mid] < K ){
			for(int i=0;i<N;++i){
				if( i == mid ) continue;
				for(LL var = K-1;var>=0;--var){
					if( dp[var] == false ) continue;
					LL res = var + A[i];
					if( res >= K ) continue;
					dp[ res ] = true;
					if( K-A[mid] <= res ){
						flag = true;
						break;
					}
				}
				if( flag ) break;
			}
		}else{
			flag = true;
		}
		if( flag ){
			OK = mid;
		}else{
			NG = mid;
		}
	}
	cout << OK << endl;
}

