using namespace std;

//cardsのうちK - num以上K - 1以下の和をもつ部分集合Sが作れるか//
//を全探索で判定する関数//
bool search_set(vector<int> cards, int K, int num){

        //もしK - num <= 0 <= K - 1ならこれ以上何も選ばず条件を満たす// 
        if(K - num <= 0 && K - 1 >= 0)
                return true;

        //すでにmax < 0なら条件を満たさない//
        else if(K - 1 < 0)
                return false;

        //cardsの要素1ならそれをSの元に選んで条件を満たすか検討//
        else if(cards.size() == 1){
                if(cards[0] >= K - num && cards[0] <= K - 1)
                        return true;
                else
                        return false;
        }

        else{
                //cardsの全探索で条件を満たす集合が存在するか調べる//
                //新たなvectorを作る//
                vector<int> n_cards;
                copy(cards.begin(), cards.end(), back_inserter(n_cards));
                //vectorの先頭を削除//
                n_cards.erase(n_cards.begin());
                //先頭の要素を使うか使わないか両方調べ、どちらかがtrueならtrueを返す//
                if(search_set(n_cards, K, num) || search_set(n_cards, K - cards[0], num))
                        return true;
                else
                        return false;
        }
}

int main(){
        //カードの枚数N, 目標とする和K//
        int N, K;

        cin >> N >> K;

        //改行文字が入らないように1文字飛ばす//
        cin.ignore();
        //N個のカードの数字が格納されたvector cards//
        string str;
        vector<int> cards;
        if(N > 1){
                for(int i = 0; i < N - 1; i++){
                        getline(cin, str, ' ');
                        cards.push_back(stoi(str));
                }
        }
        getline(cin, str);
        cards.push_back(stoi(str));

        //cardsをソートする//
        sort(cards.begin(), cards.end());

        //カードaの数字Naとすると、S < K && S + Na >= Kなる集合が見つかれば//
        //aは必要で、なければ不必要//
        //大きい方から見て初めて不要なカードが出た時点でそれ以下の数のカードはすべて不要//
        int i;
        bool all = false;
        vector<int> n_cards;
        for(i = N - 1; i >= 0; i--){
                //n_cardsにcardsをコピー//
                copy(cards.begin(), cards.end(), back_inserter(n_cards));
                //集合からcards[i]を消去//
                n_cards.erase(n_cards.begin() + i);
                //search_setはcardsのうちK - cards[i] <= S <= K - 1//
                //を満たす部分集合Sが存在するか確かめる関数//
                //Sが見つかったら同じ大きさの数のカードは飛ばしてループ続行//
                if(search_set(n_cards, K, cards[i])){
                        while(i >= 1){
                                if(cards[i] == cards[i - 1])
                                        i--;
                                else
                                        break;
                        }
                        if(i == 0)
                                all = true;
                }

                //falseならばその場でbreak//
                else
                        break;
        }

        //全部ダメならNを出力//
        if(all)
                cout << 0 << endl;
        else
                cout << i + 1 << endl;

        return 0;
}

