    if(~ret)    return ret;

    return ret = solve(i + 1, min(k, sum + a[i])) | solve(i + 1, sum);
}


int main(){
    init();

    cin >> n >> k;
    for(int i = 0;i < n;i++)    cin >> a[i];

    sort(a, a + n);
    while(n - 1 >= 0 && a[n - 1] >= k)  n--;

    int l = 0, r = n - 1, p = 0;
    while(l <= r){
        int i = (l + r) >> 1;

        temp = a[i];    a[i] = 0;
        memset(dp, -1, sizeof dp);
        int ok = !(solve(0, 0));
        a[i] = temp;


        if(ok == 1)
            l = i + 1;
        else
            r = i - 1;
    }

    cout << l;

}

