    for(int i = 0; i < N; i++)
    {
        for(int j = 0; j <= K * 2; j++)
        {
            if(dp[0][j] != 0)
            {
                dp[1][j] += dp[0][j];
                if(j + V[i] <= K * 2)dp[1][j + V[i]] += dp[0][j];
            }
        }
        for(int j = 0; j <= K * 2; j++)
        {
            dp[0][j] = dp[1][j];
            dp[1][j] = 0;
        }
    }
    for(int i = 0; i < N; i++)
    {
        int now = V[i];
        long long mem[5010] = {0};
        for(int j = 0; j <= K; j++)
        {
            if(j == K)ans++;
            if(dp[0][j] - mem[j] > 0 && dp[0][j + now] > 0)
            {
                mem[j + now] += dp[0][j] - mem[j];
                mem[j] += dp[0][j] - mem[j];
                if(j >= K - now)
                {
                    break;
                }
            }
        }
