    return b[s/64]>>s%64&1;
  }
  void slo(const size_t s)__attribute__((noinline)){
    if(s%64==0){
      for(int i=NE-1;i>=s/64;i--){
	b[i]|=b[i-s/64];
      }
    }else{
      unsigned long long p=b[NE-1-s/64];
      for(int i=NE-1;i>=1+s/64;i--){
