	unsigned long long n=p;
	p=b[i-s/64-1];
	b[i]|=sr(n,p,64-s%64);
      }
      b[s/64]|=b[0]<<s%64;
    }
  }
  unsigned long long sr(unsigned long long h,unsigned long long l,unsigned char c){
    unsigned long long r;
    asm (
	 "shrd\t%%cl, %2, %0"
	 :"=r"(r)
	 :"c"(c),"r"(h),"0"(l)
	 );
