    for(int obj = 1; obj <= N; ++obj) {
        for(int actual = K - V[obj]; actual >= 0; --actual) {
            if(is[actual]) {
                is[actual + V[obj]] = 1;

                for(int cop = 1; cop <= N; ++cop) {
                    appears[actual + V[obj]][cop] |= appears[actual][cop];
                }

                appears[actual + V[obj]][obj] = 1;
            }
        }
    }

