        int flag = 1;

        if(is[K] && appears[K][obj]) {
            flag = 0;
        }

        if(flag) {
            for(int actual = K - 1; flag && actual >= K - V[obj]; actual--) {
                if(is[actual] && appears[actual][obj] == 0) {
                    flag = 0;
                }
            }

            ans += flag;
        }
    }

    cout << ans << '\n';

