        scanf("%d",a+i);
    if (n==1){
        printf("%d\n",int(a[0]>=k));
        return 0;
    }
    a[n]=0,n++;
    sort(a,a+n);
    n=lower_bound(a,a+n,k)-a;
    ll=0,rr=n;
    while (ll<rr){
        int mid=(ll+rr+1)>>1;
        int necessary=0;
        bs.reset();
        bs.set(0);
        for (int i=0;i<n;i++)
            if (i!=mid)
                bs=bs|(bs<<a[i]);
        bs>>=(k-a[mid]);
        for (int i=0;i<a[mid];i++){
            if (bs.test(i)){
                necessary=1;
                break;
            }
        }
        if (necessary)
            rr=mid;
        else
            ll=mid+1;
    }
    return rr;
}

