int n, k;
int a[5500];
int b[5500];
int dp1[5500][5500];
int dp2[5500][5500];

void solve()
{
	cin >> n >> k;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		b[n - 1 - i] = a[i];
	}

	dp1[0][0] = 1;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j <= k; j++) {
			dp1[i + 1][j] = dp1[i][j];
			if (j - a[i] >= 0) dp1[i + 1][j] |= dp1[i][j - a[i]];
		}
	}

	dp2[0][0] = 1;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j <= k; j++) {
			dp2[i + 1][j] = dp2[i][j];
			if (j - b[i] >= 0) dp2[i + 1][j] |= dp2[i][j - b[i]];
		}
	}

	int ans = 0;

	for (int i = 0; i < n; i++) {
		if (i == 0) {
			for (int j = k - a[0]; j < k; j++) {
				if (dp2[n-1][j]) {
					ans++;
					break;
				}
			}
			continue;
		}
		if (i == n-1) {
			for (int j = k - a[n-1]; j < k; j++) {
				if (dp1[n - 1][j]) {
					ans++;
					break;
				}
			}
			continue;
		}

		int flag = 0;
		for (int j = k - a[i]; j < k; j++) {
			if (dp1[i-1][j] || dp2[n - 1 - i][j]) {
				ans++;
				flag = 1;
				break;
			}
		}
		if (flag) continue;

		vector<int> v(k + 1, 0);
		for (int j = 1; j <= k; j++) {
			v[i] = v[i - 1] + dp2[n - 1 - i][j];
		}

		for (int j = 1; j <= k; j++) {
			if (dp1[i][j]) {
				int l = k - a[i] - j;
				int r = k - 1 - j;
				if (v[r] - v[l] > 0) {
					ans++;
					break;
				}
			}
		}
	}

	cout << n - ans << endl;
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0); cout << fixed << setprecision(13);
	solve();
	return 0;
}

