int main(void){
    cin>>n>>k;
    vector<ll> vec(n);
    for(int i=0;i<n;i++){cin>>vec[i];}
    sort(vec.begin(),vec.end());
    int l=0,r=vec.size();
    while(l!=r-1){
        int i=(l+r)/2;
        for(int j=0;j<5001;j++)dp[j]=0;
        for(int j=0;j<5001;j++)dpcopy[j]=0;
        dp[vec[i]]=1;
        for(int k=0;k<n;k++){
            if(i==k)continue;
            for(int j=vec[i];j<5001;j++){
                if(dp[j]){
                    dpcopy[j+vec[k]]=1;
                }
            }
            for(int j=0;j<5001;j++)if(dpcopy[j])dp[j]=1;
        }
        for(int j=k;j<5001;j++){
            if(dp[j]){
                sum=j;
                break;
            }
        }
        if(sum-vec[i]>=k)l=i;
        else r=i;
    }
    sum=0;
    for(int i=0;i<n;i++){sum+=vec[i];}
    if(sum<=k){cout<<n<<endl;return 0;}
