int judge(int j,int* a,int k,int n){
  int dp[k+1];
  dp[0]=1;for(int i=1;i<=k;i++)dp[i]=0;
  if(df){
    for(int x:dp)printf("%d",x);
    printf("\n");
  }
  for(int i=0;i<n;i++){
    if(i==j)continue;
    for(int t=k-a[i];t>=0;t--){
      dp[t+a[i]]|=dp[t];
    }
    if(df){
      for(int x:dp)printf("%d",x);
      printf("\n");

    }
  }
  for(int i=k-a[j];i<k;i++){
    if(dp[i])return 1;
  }
  return 0;
}

