bool dp1[5001][5001];
bool dp2[5001][5001];

signed main() {
    int n, k;
    cin >> n >> k;
    vi p(n);
    rep(i, n) cin >> p[i];
    dp1[0][0] = 1;
    dp2[n][0] = 1;
    rep(i, n) rep(j, k + 1) {
        if(j >= p[i]) {
            dp1[i + 1][j] = dp1[i][j - p[i]] | dp1[i][j];
        } else {
            dp1[i + 1][j] = dp1[i][j];
        }
    }
    for(int i = n; i > 0; i--) {
        rep(j, k) {
            if(j >= p[i - 1]) {
                dp2[i - 1][j] = dp2[i][j - p[i - 1]] | dp2[i][j];
            } else {
                dp2[i - 1][j] = dp2[i][j];
            }
        }
    }
    int ans = n;
    rep(i, n) {
        vi a, b;
        rep(j, k + 1) {
            if(dp1[i][j])
                a.push_back(j);
            if(dp2[i + 1][j])
                b.push_back(j);
        }
        for(int x : a) {
            if(x >= k)
                break;
            int y = *(lower_bound(all(b), k - x) - 1);
            if(x + y >= k - p[i]) {
                ans--;
                break;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

