bool bs(int mid, int n, int k, const vector<ll> &a) {
  vector<ll> b;
  for(int i=0;i<n;++i) {
    if(i != mid) b.push_back(a[i]);
  }
  vector<vector<bool>> dp(n+1, vector<bool>(k+1, false));
  dp[0][0] = true;
  for(int i=0;i<n;++i) {
    for(int j=0;j<k+1;++j) {
      if(!dp[i][j]) continue;
      dp[i+1][j] = dp[i][j];
      if(i != mid && j + a[i] <= k) dp[i+1][j+a[i]] = dp[i][j];
    }
  }
  bool need = false;
  for(int i=k-a[mid];i<k;++i) {
    need |= dp[n][i];
  }
  return !need;
}
