const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, k;
ll as[5005];
bool dp[2][5005][5005];

void solve(){
    rep(i, n) in1(as[i]);

    rep(i, n + 1) dp[0][i][0] = dp[1][i][0] = true;
    For(i1, 1, n + 1) rep(i2, k + 1){
        ll l = as[i1 - 1], r = as[n - i1];

        dp[0][i1][i2] = dp[0][i1 - 1][i2];
        if (i2 - l >= 0) dp[0][i1][i2] |= dp[0][i1 - 1][i2 - l];

        dp[1][i1][i2] = dp[1][i1 - 1][i2];
        if (i2 - r >= 0) dp[1][i1][i2] |= dp[1][i1 - 1][i2 - r];
    }

    answer = n;
    For(i1, 1, n + 1) {
        ll ai = as[i1 - 1]; okay = false;
        if (ai >= k) {answer--; continue;}
        rep(i2, k){
            if (!dp[0][i1 - 1][i2]) continue;
            else if (okay) break;
            For(i3, k - ai - i2, k - i2){
                if (okay) break;
                if (dp[1][n - i1][i3]){
                    answer--; okay = true; break;
                }
            }
        }
    }
    prl(answer);
}

int main(void){
