const int N = 5010;

int dp[2][N][N], a[N], pre[N][N];
int n, k;

int main(){
	scanf("%d%d", &n, &k);
	for (int i = 1; i <= n; ++ i){
		scanf("%d", &a[i]);
	}
	dp[0][0][0] = 1;
	for (int i = 1; i <= k; ++ i){
		pre[0][i] = 1;
	}
	for (int i = 1; i <= n; ++ i){
		for (int j = 0; j < k; ++ j){
			dp[0][i][j] = std::max(dp[0][i][j], dp[0][i - 1][j]);
			if (!dp[0][i - 1][j] || j + a[i] >= k){
				continue;
			}
			dp[0][i][j + a[i]] = 1;
		}
		for (int j = 0; j < k; ++ j){
			pre[i][j + 1] = pre[i][j] + dp[0][i][j];
		}
	}
	dp[1][n + 1][0] = 1;
	for (int i = n; i >= 1; -- i){
		for (int j = 0; j < k; ++ j){
			dp[1][i][j] = std::max(dp[1][i][j], dp[1][i + 1][j]);
			if (!dp[1][i + 1][j] || j + a[i] >= k){
				continue;
			}
			dp[1][i][j + a[i]] = 1;
		}
	}
	int ans = 0;
	for (int i = 1; i <= n; ++ i){
		if (a[i] >= k){
			++ ans;
			continue;
		}
		for (int j = 0; j < k; ++ j){
			if (!dp[1][i + 1][j]){
				continue;
			}
			int left = std::max(0, k - a[i] - j), right = k - j;
			if (pre[i - 1][right] - pre[i - 1][left]){
				++ ans;
				break;
			}
		}
	}
	return printf("%d\n", n - ans), 0;
}

