int main(){
  int N, K;cin>>N>>K;
  vi a;
  for (int i=0;i<N;++i){
    int a_;cin>>a_;a.push_back(a_);
  }

  int left[N][K], right[N][K];
  memset(left, -1, sizeof(left));
  memset(right, -1, sizeof(right));

  left[0][0]=1;left[0][a[0]]=1;
  right[N-1][0]=1;right[N-1][a[N-1]]=1;

  for (int i=0;i<N;++i){
    for (int j=0;j<K;++j){
      if(left[i][j]==1||(j>=a[i+1]&&left[i][j-a[i+1]]==1)) left[i+1][k]=1;
    }
  }

  for (int i=N-1;i>=1;--i){
    for (int j=0;j<K;++j){
      if(left[i][j]==1||(j>=a[i-1]&&left[i][j-a[i-1]]==1)) left[i-1][k]=1;
    }
  }

  vi l_sum[N], r_sum[N];
  int ans=0;

  for (int i=0;i<N;++i){
    for (int j=0;j<K;++j){
      if(left[i][j]==1)l_sum[i].push_back(j);
      if(right[i][j]==1)r_sum[i].push_back(j);
    }
  }

  int x=lower_bound(l_sum[N-2].begin(), l_sum[N-2].end(), K-a[N-1])-l_sum[N-2].begin();
  if(l_sum[x]>=K) ans++;

  x=lower_bound(r_sum[1].begin(), r_sum[1].end(), K-a[0])-r_sum[1].begin();
  if(r_sum[x]>=K) ans++;

  for (int i=1;i<N-1;++i){
    int L=l_sum[i-1].size();
    for (int l=0;l<L;++l){
      x=lower_bound(r_sum[i+1].begin(), r_sum[i+1].end(), K-l_sum[i-1][l]-a[i])-l_sum[i-1].begin();
      if(r_sum[x]+l_sum[i-1][l]>=K) ans++;
    }
  }

  cout << ans << endl;
  return 0;
}

