typedef long long ll;

const int MAXN = 5010;
ll N, K;
int a[MAXN+1];

bool isneed(int p){
  if(K < a[p]){
    return true;
  }
  vector<ll> b;
  for(int i=1;i<=N;i++){
    if(i == p) continue;
    b.push_back(a[i]);
  }
  // i枚目まで使って総和をjにできるか
  bool dp[N][K+1];
  for(int i=0;i<=N-1;i++){
    for(int j=0;j<=K;j++){
      dp[i][j] = false;
    }
  }
  for(int i=0;i<=N-1;i++){
    dp[i][0] = true;
  }
  for(int i=1;i<=N-1;i++){
    for(int j=0;j<=K;j++){
      if(j - b[i-1] < 0) dp[i][j] = dp[i-1][j];
      else dp[i][j] = (dp[i-1][j] || dp[i-1][j - b[i-1]]);
    }
  }
  /*
  cout << p << endl;
  for(int i=1;i<=N-1;i++){
    for(int j=0;j<=K;j++){
      cout << dp[i][j] << " ";
    }
    cout << endl;
  }
  cout << endl;
  */
  for(int i=K-a[p];i<K;i++){
    if(dp[N-1][i]) return true;
  }
  return false;
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  cin >> N >> K;
  for(int i=1;i<=N;i++) cin >> a[i];
  if(N == 1){
    if(a[1] < K){
      cout << 1 << endl;
      return 0;
    }else{
      cout << 0 << endl;
      return 0;
    }
  }
  // binary_search
  ll left = 0, right = N;
  // (left, right]
  while(right - left > 1){
    ll mid = (left + right)/2;
    if(isneed(mid)){
      right = mid;
    }else{
      left = mid;
    }
  }
  if(right == N && !isneed(N)) cout << N << endl;
  else cout << right - 1 << endl;
}

