aiを含む任意の総和K以上の部分集合がK+ai以上であるということ

逆に言えば、K-K+ai間ギャップにaiを含む部分集合が存在しないこと

全体和から大きい順に除いていってK以上のぎりぎりにしたとき、
値がギャップにあれば必要、ギャップ以上かそもK未満なら不必要
->最も器用な構成の仕方でギャップにあるかどうか判定することで、
これでギャップに入れられないならその他の構成の仕方では
なおさらギャップに入らないので不必要であろうと考えられる


^-editorialでは
必要である条件に注目していた
必要<-> K-ai~K間の総和をiを使わずに実現できることと捉える
こうすると、考えればよい値域がK以下になるため、値域を含めて
dpを実施できる
dp[i][j] i枚目まで使ったときに総和をjにできるかどうか
*/

//必要ならtrue 不必要ならfalse
bool f(ll x, vector<ll> &a, ll K) {
    if (x >= a.size() || K - a[x] <= 0) return true;
    ll ub = K, lb = K - a[x];
    ll N = a.size();
    vector<ll> b = a; b.erase(b.begin()+x);
    vector<bool> dp(K+1,false);
    dp[0] = true;
    //for (int i = 0; i < N-1; i++) cout << b[i] << " "; cout << endl;
    for (int i = 0; i < N-1; i++) {
        for (int j = K; j >= 0; j--) {
            if (j-b[i] >= 0) dp[j] = dp[j] || dp[j-b[i]];
        } 
    }

    for (ll k = lb; k < ub; k++) {
        if (dp[k]) return true;
    }
    return false;
}

