void solve()
{
    sort(A, A+N);

    S[0] = A[0];
    FOR(i, 1, N) {
        S[i] = S[i-1] + A[i];
    }

    bool need[5000] = {};
    for(int i = N-1; i >= 0; --i) {
        if(A[i] >= K) {
            need[i] = true;
            continue;
        }

        for(int j = i-1; j >= 0; --j) {
            ll s = A[i] + S[j];
            if(s >= K) {
                need[i] = true;
                for(int k = j; k >= 0; --k) {
                    if(s - A[k] < K) {
                        need[k] = true;
                    }
                    else {
                        break;
                    }
