const int MAX_N = 5010;
int dp[MAX_N][MAX_N];
set<int> tabooo;
int src;
int memo(int pos, int val){
  if (val >= K - A[src] and val < K){
    return 1;
  }

  if (pos == N){
    return 0;
  }
  int &res = dp[pos][val];
  if (res >= 0){
    return res;
  }
  res = 0;
  res |= memo(pos + 1, val);
  if (tabooo.count(pos) == 0){
    res |= memo(pos + 1, min((ll)K, val + A[pos]));
  }

  return res;
}


int main() {
  cin >> N >> K;

  A.resize(N);
  for (auto &val : A){
    cin >> val;
  }
  sort(A.begin(), A.end());
  int left,right;
  left = -1;
  right = N;
  while (right - left > 1){
    int med = (right + left) / 2;
    if (med >= N){
      right--;
      continue;
    }else if(med < 0){
      left++;
      continue;
    }
    src = med;
    memset(dp, -1, sizeof(dp));
    tabooo.emplace(med);

    int res = memo(0, 0);
    tabooo.erase(med);
    if (res > 0){//necessary
      right = med;
    }else{//unnecessary
      left = med;
      int tmp = *tabooo.rbegin();
      for (int i = tmp; i <= med; i++){
        tabooo.emplace(i);
      }
    }
  }
  cout << tabooo.size() << endl;

  return 0;
}

