    return b[s/64]>>s%64&1;
  }
  void slo(size_t s){
    if(s%64==0){
      for(int i=NE-1;i>=s/64;i--){
	b[i]|=b[i-s/64];
      }
    }else{
      for(int i=NE-1;i>=1+s/64;i--){
      	b[i]|=b[i-s/64]<<s%64|b[i-s/64-1]>>64-s%64;
      }
      b[s/64]|=b[0]<<s%64;
    }
  }
};

