		REP(j, k) {
			if((k - 1 - j) - a[i] >= 0) dp[(k - 1 - j)] += dp[(k - 1 - j) - a[i]];
		}
	}
	ll cnt = 0;
	REP(i, n) {
		if(a[i] >= k) {
			++cnt;
