    for(int y=0; y < K; y++){
      if(A[0]==y)
	dp[0][y] = true;
      else
        dp[0][y] = false;
    }
    for(int x=0; x < N; x++){
      dp[x][0] = true;
    }
    for(int x=1; x < N; x++){
      for(int y=1; y < K; y++){
	dp[x][y] = false;
	if(dp[x-1][y]) dp[x][y] = dp[x-1][y];
	if(y-A[x] >= 0 && A[x] > 0 && dp[x][y] != true)
	  dp[x][y] = dp[x-1][y-A[x]];
      }
    }
    bool need = false;
    int s;
    if(K < ai) s = 0;
    else s = K-ai;
    for(int a=s; a < K; a++){
      if(dp[N-1][a]){
        need = true;
        break;
      }
    }
    if(need == false) ans++;
    A[i] = ai;
  }
  cout << ans << endl;
  return 0;
}

