bool dp[5010][5010];

int main() {
    int n, k; cin >> n >> k;
    vector<int> a(n); rep(i, n) cin >> a[i];
    sort(a.begin(), a.end());

    // 単調性が成り立つことを示す。
    // k - a[i] <= S < k となるSが存在するとすると、
    // a[j] > a[i] を満たす任意のa[j]について、k - a[j] <= S' < k が成り立つようなS'が存在することが示せる。
    // (Sに a[j]が含まれる場合と、a[j]が含まれる場合に分けると示せた。)

    int left = -1;
    int right = n;
    int mid;
    while (right - left > 1) {
        mid = (left + right) / 2;
        memset(dp, false, sizeof(dp));
        dp[0][0] = true;

        rep(i, n) {
            rep(j, k+1) {
                if (i == mid) {
                    dp[i+1][j] |= dp[i][j];
                } else {
                    dp[i+1][j] |= dp[i][j];
                    if (j + a[i] <= k) {
                        dp[i+1][j+a[i]] |= dp[i][j];
                    } else {
                        dp[i+1][k] |= dp[i][j];
                    }
                }
            }
        }

        bool flag = 0;
        for (int j = max(0, k - a[mid]); j < k; j++) {
            flag |= dp[n][j];
        }
        if (flag) right = mid;
        else left = mid;
    }

    cout << left + 1 << endl;

    return 0;
}

