bool isUnnecessary(int cur) {
    // dp[x][y] = x枚目まで使った時総和をyにできるか？
    vector<vector<bool> > dp(N+1, vector<bool>(K+1, false));
    dp[0][0] = 1;
    REP(i, N) REP(j, K+1) {
        if (i == cur) {
            dp[i+1][j] = dp[i][j];
        } else {
            if(dp[i][j]) {
                if (j + a[i] <= K) {
                    dp[i+1][j+a[i]] = 1;
                }
                dp[i+1][j] = 1;
            }
        }
    }
    bool ret = false;
    FOR(i, max(0, K-a[cur]), K) {
        ret |= dp[N][i];
    }

    return !ret;
}

