int main() {
  int n, k;
  cin >> n >> k;
  vector<int> a;
  for (int i = 0; i < n; i++) {
    int t;
    cin >> t;
    if (t < k) {
      a.push_back(t);
    }
  }
  n = a.size();
  sort(a.begin(), a.end());
  int l = -1, r = n;
  while (r - l > 1) {
    int m = (r + l + 1) / 2;
    bool need = false;
    vector<bool> dp(k);
    dp.at(0) = true;
    for (int i = 0; i < n; i++) {
      if (i == m) continue;
      for (int j = k - 1; j >= a.at(i); j--) {
        dp.at(j) = dp.at(j) or dp.at(j - a.at(i));
        if (dp.at(j) and j >= k - a.at(m)) {
          need = true;
          break;
        }
      }
      if (need) break;
    }
    if (need) {
      r = m;
    } else {
      l = m;
    }
  }
  cout << r << endl;
}

