//cardsのうちK - num以上K - 1以下の和をもつ部分集合Sが作れるか//
//を全探索で判定する関数//
bool search_set(vector<int> cards, int K, int num){

        //もしK - num <= 0 <= K - 1ならこれ以上何も選ばず条件を満たす// 
        if(K - num <= 0 && K - 1 >= 0)
                return true;

        //すでにmax < 0なら条件を満たさない//
        else if(K - 1 < 0)
                return false;

        //cardsの要素1ならそれをSの元に選んで条件を満たすか検討//
        else if(cards.size() == 1){
                if(cards[0] >= K - num && cards[0] <= K - 1)
                        return true;
                else
                        return false;
        }

        else if(cards.size() == 0)
                return false;

        else{
                //cardsの全探索で条件を満たす集合が存在するか調べる//
                //cardsのコピーn_cardsを作る//  
                vector<int> n_cards;
                copy(cards.begin(), cards.end(), back_inserter(n_cards));
                //n_cardsの先頭を同じ数の重複も含めて削除//
                unsigned int i;
                for(i = 0; i < cards.size() - 1; i++){
                        if(cards[i] != cards[i + 1])
                                break;
                }
                n_cards.erase(n_cards.begin(), n_cards.begin() + i + 1);

                //先頭の要素を使うか使わないか両方調べ、trueが出たらtrueを返す//
                //重複がない場合は1枚のカードを使うか使わないか決めるだけ(j = 0, 1)//
                //n枚重複があるなら0~n枚使うのを全部調べる(j = 0,...,n)//
                bool ok = false; 
                for(unsigned int j = 0; j <= i + 1; j++){
                        if(search_set(n_cards, K - cards[0] * j, num))
                                ok = true;
                }

                return ok;
        }
}


int main(){
        //カードの枚数N, 目標とする和K//
        int N, K, i;

        cin >> N >> K;

        //改行文字が入らないように1文字飛ばす//
        cin.ignore();
        //N個のカードの数字が格納されたvector cards//
        string str;
        vector<int> cards;
        if(N > 1){
                for(i = 0; i < N - 1; i++){
                        getline(cin, str, ' ');
                        cards.push_back(stoi(str));
                }
        }
        getline(cin, str);
        cards.push_back(stoi(str));

        //cardsをソートする//
        sort(cards.begin(), cards.end());

        //K以下の数字を持つカードの和sumをとる//
        long int sum = 0;
        for(i = 0; i < N; i++){
                if(cards[i] < K)
                        sum += cards[i];
                else
                        break;
        }

        //K以上の数のカードはそれ1枚の集合で必要となり//
        //他のカードと組んでギリギリの集合を作らないので消去//
        cards.erase(cards.begin() + i, cards.end());
        //もしsumがKより小さいならK以下のカードはすべて不要//
        if(sum < K)
                cout << i << endl;

        //sumがKに等しいかすべてのカードがK以上ならばどれが抜けてもダメなので全て必要//
        else if(sum == K || i == 0)
                cout << 0 << endl;

        //それ以外は大きい方から1枚ずつ必要か判断//
        else{

                //カードaの数字Naとすると、S < K && S + Na >= Kなる集合が見つかれば//
                //aは必要で、なければ不必要//
                //大きい方から見て初めて不要なカードが出た時点でそれ以下の数のカードはすべて不要//
                vector<int> n_cards;
                for(i = cards.size() - 1; i >= 0; i--){
                        //n_cardsにcardsをコピー//
                        copy(cards.begin(), cards.end(), back_inserter(n_cards));
                        //集合からcards[i]を消去//
                        n_cards.erase(n_cards.begin() + i);
                        //search_setはcardsのうちK - cards[i] <= S <= K - 1//
                        //を満たす部分集合Sが存在するか確かめる関数//
                        //Sが見つかったら同じ大きさの数のカードは飛ばしてループ続行//
                        if(search_set(n_cards, K, cards[i])){
                                while(i >= 1){
                                        if(cards[i] == cards[i - 1])
                                                i--;
                                        else
                                                break;
                                }
                        }

                        //falseならばその場でbreak//
                        else
                                break;
                        n_cards.clear();
                }

                //iは不要なカードのindexで止まっているので+1する//
                cout << i + 1 << endl;
        }

        return 0;
}

