bool disposable(int k, int discarded, VEC<int> a) {
  int n = a.size();
  bool dp[n + 1][k + 1];
  REPC(i,0,n){REPC(j,0,k){dp[i][j]=0;}}

  dp[0][0] = 1;
  REPC(i, 1, n) {
    REPC(j, 0, k) {
      int item = a[i-1];
      if (j - item >= 0)
        dp[i][j] = dp[i - 1][j] | dp[i - 1][j - item];
      else
        dp[i][j] = dp[i - 1][j];
    }
  }
  // cerr<<endl;
  // REPC(i, 0, n) {
  //   REPC(j, 0, k) { cerr << dp[i][j] << " "; }
  //   cerr << endl;
  // }
  //   cerr << endl;
  REP(i, k - discarded, k) if (dp[n][i]) { return 0; }
  return 1;
}

int main() {
  int n, k;
  cin >> n >> k;
  VEC<int> a(n);
  REP(i, 0, n) cin >> a[i];
  sort(ALL(a));
  // DUMP(a);
  int deletable = 0, necessary = n;
  VEC<int> b(n - 1);
  int mid;
  while (abs(necessary - deletable) > 1) {
    mid = (deletable + necessary) / 2;
    int cnt = 0;
    REP(i, 0, n) {
      if (i != mid) {
        b[cnt] = a[i];
        ++cnt;
      }
    }
    // DUMP(deletable, mid, necessary, ":", a[mid], b);
    if (disposable(k, a[mid], b)) {
      // DUMP(a[mid],"is deletable");
      deletable = mid;
    } else
      necessary = mid;
  }
  cout << necessary << endl;
  return 0;
}

