            if (dp2[i+1][j]) s2.insert(j);
        }
        int low = max(k-a[i], 0LL);
        for (ll e1: s1) {
            auto it = s2.lower_bound(low-e1);
            if (it==s2.end()) continue;
            ll e2 = *it;
            if (e1+e2<k) {
                ok = true;
                break;
            }
        }
        if (!ok) ans++;
    }

    cout << ans << endl;
    return 0;
}

