      if (x == N) return false;
      if (ix(as, x) >= K) return false;
      bitset<5001> ok = 1;
      for (auto i = 0; i < N; i++)
        if (i != x) ok |= ok << ix(as, i);
      bool unnecessary = true;
      dump(bitset<64>(ok.to_ulong()));
      for (auto i = 1; i <= ix(as, x); i++)
        unnecessary &= !ok[K - i];
      dump(unnecessary);
      return unnecessary;
    },
    -1, N);
  cout << (res + 1) << endl;
}

