int main(void){
    int n, k; scanf("%d%d", &n, &k);
    Vint A(n); REP(i, n) scanf("%d", &A[i]);
    // カード j が 不要か
    //          => k - A_i ≤ ∑_{i ∈ S} A_i < k となる S が取れるか
    // DP[i][S] = i枚目　まで使用して, 和を S にできるか
    // DP[i][S] ~> [0, i), rDP[i] ~> [0, i)^c
    // rDP ; 逆
    Wbool DP(n + 1, Vbool(k, false)),
         rDP(n + 1, Vbool(k, false));
    DP[0][0] = true; rDP[n][0] = true;
    for(int i = 0; i < n; ++i){
        const int nextI = i + 1;
        int j;
        for(j = 0; j < k - A[i]; ++j){
            if(DP[i][j]){
                DP[nextI][j] = true;
                DP[nextI][j + A[i]] = true;
            }
        }
        for(; j < k; ++j) if(DP[i][j]) DP[nextI][j] = DP[i][j];
    }
    for(int i = n - 1; i >= 0; --i){
        const int preI = i + 1;
        int j;
        for(j = 0; j < k - A[i]; ++j){
            if(rDP[preI][j]){
                rDP[i][j] = true;
                rDP[i][j + A[i]] = true;
            }
        }
        for(; j < k; ++j) if(rDP[preI][j]) rDP[i][j] = rDP[preI][j];
    }
    int cnt = n; Vint counter(k);
    for(int i = 0; i < n; ++i){
        // 0で初期化
        for(int j = 0; j < k; ++j) counter.at(j) = 0;
        for(int j = 0; j < k; ++j){
            if(DP[i][j]){
                // k - A[i] - j ~ k - A[i] に + 1
                //printf("+ : %d, - : %d \n", max(k - A[i] - j, 0), k - j);
                counter.at(max(k - A[i] - j, 0))++;
                if(j != 0) counter.at(k - j)--;
            }
        }
        for(int j = 1; j < k; ++j) counter.at(j) += counter.at(j-1);
        //printf("%d : ", i); for(int j = 0; j < k; ++j) printf("%d ", counter.at(j)); putchar('\n');
        for(int j = 0; j < k; ++j) if(rDP[i+1][j] and counter[j] > 0){
            //printf("bad = %d\n", i);
            cnt--;
            break;
        }
    }
    printf("%d\n", cnt);
    return 0;
}

