            rep(i, N + 1) dp[i].assign(2 * K, 0);
            dp[0][0] = 1;

            rep(i, 0, N) {
                if (A[i] >= K || i == mid) {
                    rep(j, 0, 2 * K) {
                        dp[i + 1][j] = dp[i][j];
                    }
                }
                else {
                    rep(j, 0, K + 1) {
                        dp[i + 1][j] += dp[i][j];
                        dp[i + 1][j + A[i]] += dp[i][j];
                    }
                    rep(j, K + 1, 2 * K) {
                        dp[i + 1][j] += dp[i][j];
                    }
                }
            }

            bool b = false;
            rep(i, K - A[mid], K) {
                if (dp[N][i] > 0) b = true;
            }

            if (b) ok = mid;
            else ng = mid;
        }
    }

    write(ok);
}

