        cin >> a[i];
    }

    sort(a,a+n);

    int my_left = 0,my_right = n;

    while(my_left + 1 != my_right){

        int middle = (my_left + my_right)/2;

        for(int r=0; r<=n; r++){
            for(int w=0; w<=k; w++){
                dp[r][w] = false;
