set<int> tabooo;
int src;
int memo(int pos, int val){
  if (val >= K - A[src] and val < K){
    return 1;
  }

  if (pos == N){
    return 0;
  }
  int &res = dp[pos][val];
  if (res >= 0){
    return res;
  }
  res = 0;
  res |= memo(pos + 1, val);
  if (tabooo.count(pos) == 0){
    res |= memo(pos + 1, min((ll)K, val + A[pos]));
  }

  return res;
}


