            break;
        }
    }
    return ans;
}

// hitsuyou (dp=1) ;hitsuyoudenai (dp=0)   max unnecessary
int binarysearch(int p,int q){
    int lo=p,hi=q;
    int med=lo+hi;
    med>>=1;
    if(hi!=lo+1){
        ll y=k-a[med];
        if(y>=0){
            if(dpxy(y,med)==0){  // unnecessary
                binarysearch(med,hi);
            }
            else{
                binarysearch(lo,med);
            }
        }
        else{
            if(dpxy(lo,med)==0){
                binarysearch(lo,med);
            }
        }
    }
    else{
        ll y=k-a[lo];
        if(y>=0){
            if(dpxy(y,med)==0){  // unnecessary
                return med;
            }
            else{
                return med-1;
            }
        }
        else{
            return med;
        }
    }
}

