vi Manacher(string s){
  vi R(s.size());
  int i = 0, j = 0;
  while(i < s.size()){
    while(i-j >= 0 && i+j < s.size() && s[i-j] == s[i+j]) ++j;
    R[i] = j;
    int k = 1;
    while(i-k >= 0 && i+k < s.size() && k+R[i-k] < j) R[i+k] = R[i-k], k++;
    i += k; j -= k;
  }
  return R;
}

vi Z_algorithm(string &s){
  vi Z(s.size());
  Z[0] = s.size();
  int i = 1, j = 0;
  while(i < s.size()){
    while(i+j < s.size() && s[j] == s[i+j]) j++;
    Z[i] = j;
    if(j == 0){++i; continue;}
    int k = 1;
    while(i+k < s.size() && k+Z[k] < j) Z[i+k] = Z[k], ++k;
    i += k; j -= k;
  }
  return Z;
}

const int MAX = 1e6+1;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(ll n, ll k){
  if(n >= MAX){
    ll tmp = 1;
    rep(i,k){
      tmp *= (n-i);
      tmp %= MOD;
    }
    return tmp*finv[k]%MOD;
  }

  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll POW(ll x, ll n){
  ll ret = 1;
  if(n < 0){// n < 0 にも対応
    n *= -1;
    x = inv[x];
  }
  while(0 < n){
    if(n%2 == 0){
      x = x*x%MOD;
      n /= 2;
    }
    else{
      ret = ret*x%MOD;
      n--;
    }
  }
  return ret;
}

int s1[5005][5005], s2[5005][5005];
bitset<5005> dp1, dp2;

int main(){
  int n, K; cin >> n >> K;
  vi a(n); rep(i,n) cin >> a[i];

  dp1[0] = 1; s1[0][0] = 1;
  rep(i,n){
    // bitset を使えば更新が楽
    dp1 |= (dp1 << a[i]);
    rep(k,K){
      s1[i+1][k+1] = s1[i+1][k] + dp1[k];
    }
  }

  dp2[0] = 1; s2[n][0] = 1;
  rrep(i,n){
    dp2 |= (dp2 << a[i]);
    rep(k,K) {
      s2[i][k+1] = s2[i][k] + dp2[k];
    }
  }

  int ans = n;
  rep(i,n) {
    if(a[i] >= K){
      ans--;
      continue;
    }
    // 和を [K-a[i], K) にできるかどうかを判定
    rep(x,K) {
      if(!(s1[i][x+1]-s1[i][x])) continue;
      // [K-a[i]-x, K-x) に dp2[i+1] が true となることがあるかどうかを判定
      if(s2[i+1][K-x] - s2[i+1][max(K-a[i]-x,0)]){
        ans--;
        break;
      }
    }
  }
  cout << ans << endl;
}

