bool is_need(vector<int>& A, int ix, int N ,int K)
{
  vector<bool> dp(K + 5, false);
  dp[0] = true;
  for (int i = 0; i < N; ++i) {
    if (i == ix) { continue; }
    for (int j = K; j >= 0; --j) {
      if (j >= A[i] and dp[j - A[i]]) {
        dp[j] = true;
      }
    }
  }
