{
  int ix = num - 1;
  int n = A.size();
  vector<vector<int>> dp(n + 5, vector<int>(K + 5, 0));
  dp[0][0] = 1;
  for (int i = 0; i < n; ++i) {
    for (int sum = 0; sum <= K; ++sum) {
      dp[i + 1][sum] = dp[i][sum];
      if (i != ix and sum >= A[i]) {
        dp[i + 1][sum] |= dp[i][sum - A[i]];
      }
    }
  }
  for (int sum = max(0, K - A[ix]); sum < K; ++sum) {
    if (dp[n][sum]) { return false; }
  }
  return true;
}

