void solve(){
    ll tot = 0;
    rep(i, n){
        ll b; in1(b);
        tot += b;
        if (b < k) a.pb(b);
    }

    if (tot < k){prl(n); return;}
    n = a.size();
    dp[0][0][0] = dp[1][0][0] = true;

    For(i, 1, n + 1){
        dp[0][i][0] = true;
        For(v, 1, k + 1){
            ll val = a[i - 1];
            dp[0][i][v] = dp[0][i - 1][v];
            if (v - val >= 0 && dp[0][i - 1][v - val]) dp[0][i][v] = true;
        }
    }

    For(i, 1, n + 1){
        dp[1][i][0] = true;
        For(v, 1, k + 1){
            ll val = a[n - i];
            dp[1][i][v] = dp[1][i - 1][v];
