//v[index]を使わずにk-v[index]<= Sum < kとなる挿話が作れるならfalse
bool isNoNeed(int index){
  if(v[index]>=K) return false;
  set<int> st;
  st.insert(0);
  rep(i,N){
    vector<int> add(st.size());
    int num = 0;
    if(i==index)continue;
    if(v[i] >= K) break;
    for(auto it = st.begin(),st_end = st.end(); it != st_end; ++it){
      int s = *it;
      int ns = s+v[i];
      if(ns>=K-v[index] && ns < K) return false;
      if(ns<K){
        add[num] = ns;
        ++num;
      } else st.erase(s);
    }
    rep(j,num) st.insert(add[j]);
  }
  return true;
}

