    ios::sync_with_stdio(false);
    int n,k; cin>>n>>k;
    vll a(n);
    rep(i,n) cin>>a[i];
    vector<bitset<5000> > dp(n+1);
    vector<bitset<5000> > dp2(n+1);
    dp[0][0] = true;
    rep(i,n)rep(j,k){
        if (j>=a[i])
            dp[i+1][j] = dp[i][j-a[i]]|dp[i][j];
        else
            dp[i+1][j] = dp[i][j];
    }
    dp2[n][0] = true;
    rep(i,n)rep(j,k){
        if (j>=a[n-i-1])
            dp2[n-i-1][j] = dp2[n-i][j-a[n-i-1]]|dp2[n-i][j];
        else
            dp2[n-i-1][j] = dp2[n-i][j];
    }
    int ans=0;
    rep(i,n){
