        rep(j,k){
            A[j] = dp[i][j];
            B[j] = dp2[i+1][j];
        }
        auto C = FastFourierTransform::multiply(A,B);
        bool need=false;
        rep(j,k)if(C[j] && a[i]+j>=k){
            need=true;
            break;
        }
