bool isNeeded(int i)
{
    int s;
    if (i != 0) {
        if (A[0] < K) {
            dp[0][A[0]] = 1;
            s = 1;
        } else {
            return true;
        }
    } else {
        if (A[1] < K) {
            dp[1][A[1]] = 1;
            s = 2;
        } else {
            if (A[0] >= K) {
                return true;
            } else {
                return false;
            }
        }
    }
    for (int j = s; j < N; j++) {
        for (int k = 0; k < K; k++) {
            if (i == j) {
                dp[j][k] = dp[j - 1][k];
            } else {
                if (k >= A[j]) {
                    dp[j][k] = dp[j - 1][k] + dp[j - 1][k - A[j]];
                } else {
                    dp[j][k] = dp[j - 1][k];
                }
            }
        }
    }
    int ans = 0;
    for (int k = max(0LL, K - A[i]); k < K; k++) {
        ans += dp[N - 1][k];
    }
    memset(dp, 0, sizeof(dp));
    return ans != 0;
}

