      dp |= (dp << B[j]);
    }
    bool ok=false;
    for(int j=K-B[i];j<=K-1;j++){
      if(dp[j]) ok=true;
    }
    if(ok) cnt++;
  }

  cout<<N-cnt<<endl;
  //cout<<M<<endl;
  }
}

