// 下記のリンクを実装(kitamasa法のモンゴメリ乗算を使わない版)
// http://q.c.titech.ac.jp/docs/progs/polynomial_division.html
// k項間漸化式のa_Nを求める O(k log k log N)
// N ... 求めたい項　(0-indexed)
// Q ... 漸化式 (1 - \sum_i c_i x^i)の形
// a ... 初期解 (a_0 , a_1 , ... , a_k-1)
// x^N を fでわった剰余を求め、aと内積を取る
modint kitamasa(ll N, FPS &Q, FPS &a){
  int k = Q.size() - 1;
  assert( (int)a.size() == k );
  FPS P = a * Q; P.resize(k);
  while(N){
    auto Q2 = Q;
    for(int i = 1; i < (int)Q2.size(); i += 2) Q2[i].x = MOD - Q2[i].x;
    auto S = P * Q2;
    auto T = Q * Q2;
    if(N & 1){
      for(int i = 1 ; i < (int)S.size() ; i += 2) P[i>>1].x = S[i].x;
      for(int i = 0 ; i < (int)T.size() ; i += 2) Q[i>>1].x = T[i].x;
    }
    else{
      for(int i = 0 ; i < (int)S.size() ; i += 2) P[i>>1].x = S[i].x;
      for(int i = 0 ; i < (int)T.size() ; i += 2) Q[i>>1].x = T[i].x;
    }
    N >>= 1;
  }
  return P[0];
}

void solve(){
  ini(N , K);
  vi a(N); in(a);
  {
    vi b;
    each(x , a) if(x < K) b.pb(x);
    swap(a , b);
    N = sz(a);
  }
  if(N == 0) die(0);

  trc(a);
  FPS f(K + 1);
  f[0] = 1;
  rep(i,N)
    mul_simple(f , 1 , a[i] , 1);

  trc(f);
  int ans = 0;
  rep(i , N){
    div_simple(f , 1 , a[i] , 1);
    trc(f);
    int flg = 1;
    for(int j = max(0,K-a[i]); j<K; j++){
      if(f[j].x != 0) flg = 0;
    }
    ans += flg;
    mul_simple(f , 1 , a[i] , 1);
    trc(f);
  }
  out(ans);

}

