  while(right-left>1){
    ll mid=left+(right-left)/2;
    bool flag = false;

    if(a[mid]>=k){
      flag=true;
    }else{
      std::vector<std::vector<bool>> dp(n,std::vector<bool>(k,false));
      dp[0][0]=true;
      rep(i,0,n-1){
        ll temp=i;
        if(temp>=mid)temp++;
        rep(j,0,k){
          dp[i+1][j]=dp[i][j]|dp[i][(j-a[temp]>=0)?j-a[temp]:j];
        }
      }
      rep(i,k-a[mid],k)flag=(flag|dp[n-1][i]);
    }
    if(flag)right=mid;
    else left=mid;
  }

  std::cout<<left+1;
  return 0;
}

