bool isneed(int p){
  if(K < a[p]){
    return true;
  }
  vector<ll> b;
  for(int i=1;i<=N;i++){
    if(i == p) continue;
    b.push_back(a[i]);
  }
  // i枚目まで使って総和をjにできるか
  bool dp[N][K+1];
  for(int i=0;i<=N-1;i++){
    for(int j=0;j<=K;j++){
      dp[i][j] = false;
    }
  }
  for(int i=0;i<=N-1;i++){
    dp[i][0] = true;
  }
  for(int i=1;i<=N-1;i++){
    for(int j=0;j<=K;j++){
      if(j - b[i-1] < 0) dp[i][j] = dp[i-1][j];
      else dp[i][j] = (dp[i-1][j] || dp[i-1][j - b[i-1]]);
    }
  }
  /*
  cout << p << endl;
  for(int i=1;i<=N-1;i++){
    for(int j=0;j<=K;j++){
      cout << dp[i][j] << " ";
    }
    cout << endl;
  }
  cout << endl;
  */
  for(int i=K-a[p];i<K;i++){
    if(dp[N-1][i]) return true;
  }
  return false;
}

