      return 0;
    }else{
      cout << 0 << endl;
      return 0;
    }
  }
  // binary_search
  ll left = 1, right = N+1;
  // [left, right)
  while(right - left > 1){
    ll mid = (left + right)/2;
    if(isneed(mid)){
      // midが条件を満たせば、解の存在範囲は[left, mid)
      right = mid;
    }else{
      // 解の存在範囲は[mid, right)
      left = mid;
    }
  }
  cout << right-1 << endl;
}

