bool can_delete(int idx, const vector<LL> &A, int K) {
    vector<bool> dp(K + 1, false);
    dp[0] = true;

    FOR(i, 0, A.size()) {
        if (i == idx) {
            continue;
        }

        for (int j = int(dp.size()) - 1; j >= 0; --j) {
            if (dp[j] and j + A[i] < dp.size()) {
                dp[j + A[i]] = true;
            }
        }
    }

    bool ok = true;
    FOR(i, 0, K) {
        if (dp[i] and i + A[idx] >= K) {
            ok = false;
        }
    }
    return ok;
}

