void solve(long long N, long long K, std::vector<long long> a) {
  sort(a.begin(), a.end());
  set<int> need;
  ll r = 0;
  ll currSum = 0;
  for (ll l = 0; l < N; l++) {
    ll origL = l;
    while (currSum < K and r < a.size()) {
      currSum += a[r];
      r++;
    }
    if (currSum - K < a[l] and currSum >= K) {
      for (int i = l; i < r; i++) {
        need.insert(i);
      }
    }
    currSum -= a[origL];
  }
  cout << N - need.size() << endl;
}

