                else if(upper_bound(all(dpR[i+1]), j-a[i])-lower_bound(all(dpR[i+1]), j-a[i])){
                    dpR[i].pb(j);
                }
            }
        }
    }

    int ans = 0;
    rep(i, N){
        if(i == 0){
            if(lower_bound(all(dpR[1]), K)-lower_bound(all(dpR[1]), K-a[0]) == 0){
                ans++;
            }
        }
        else if(i == N-1){
            if(lower_bound(all(dpL[N-2]), K)-lower_bound(all(dpL[N-2]), K-a[N-1]) == 0){
                ans++;
            }
        }
        else{
            bool need = false;
            rep(j, dpL[i-1].size()){
                if(lower_bound(all(dpR[i+1]), K-dpL[i-1][j])-lower_bound(all(dpR[i+1]), K-dpL[i-1][j]-a[i]) > 0) need = true;
            }
            if(!need) ans++;
        }
    }
    cout << ans << endl;
}

