signed main(void){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int N, K; cin >> N >> K;
  vector<vector<bool>> dp(N, vector<bool>(K+1, 0));
  vector<int> a(N);
  REP(i, N) cin >> a[i];
  sort(ALL(a));

  int left = -1, right = N;
  while(right-left > 1){
    int mid = (left+right) / 2;
    vector<int> b = a;
    b.erase(b.begin()+mid);

    REP(i, N) REP(j, K+1){
      if(j == 0) dp[i][j] = 1;
      else dp[i][j] = 0;
    }
    REP(i, N-1) REP(j, K){
      if(j - b[i] >= 0){
        dp[i+1][j] = (dp[i+1][j] or dp[i][j]) or dp[i][j-b[i]];
      } else {
        dp[i+1][j] = dp[i+1][j] or dp[i][j];
      }
    }
    bool need = 0;
    for(int i = K-a[mid]; i < K; i++){
      if(dp[N-1][i]) need = 1;
    }
    if(need) right = mid;
    else left = mid;
  }
  cout << left+1 << endl;

  return 0;
}

