bool check(int x) {
    if (a[x] >= k) return true;
    memset(dp, 0, sizeof dp);
    dp[0] = true;
    for (int i = 0; i < n; ++i) {
        if (i == x) continue;
        for (int j = k - 1; j > 0; --j) {
            if (j >= a[i] && dp[j - a[i]]) {
                dp[j] = true;
            }
        }
    }
    for (int i = k - x; i < k; ++i) {
        if (dp[i]) {
