void solve() {
  int N, K; cin >> N >> K;
  vi32 a(N); cin >> a;
  sort(all(a));

  auto check = [&](int md) {
    if (a[md] >= K) return true;

    vector<bool> dp(K + 1);
    dp[0] = true;

    rep(i, N) rrep(j, K) {
      if (i == md) continue;
      if (!dp[j]) continue;
      dp[min(K, j + a[i])] = true;
    }

    for (int i = K - a[md]; i < K; i++) {
      if (dp[i]) return true;
    }
    return false;
  };

  int ok = N, ng = -1;
  while (ok - ng > 1) {
    int md = (ok + ng) / 2;
    if (check(md)) ok = md; else ng = md;
  }
  cout << ok << '\n';
}

