    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < k; ++j)
        {
            dpl[i + 1][j] = dpl[i][j];
            if (j >= a[i])
                dpl[i + 1][j] |= dpl[i][j - a[i]];
        }
    }
    dpr[n][0] = 1;
    for (int i = n - 1; i >= 0; --i)
    {
        for (int j = 0; j < k; ++j)
        {
            dpr[i][j] = dpr[i + 1][j];
            if (j >= a[i])
                dpr[i][j] |= dpr[i + 1][j - a[i]];
        }
    }
    for (int i = 0; i <= n + 1; ++i)
    {
        for (int j = 0; j < k; ++j)
        {
            smr[i][j + 1] = smr[i][j] + dpr[i][j];
        }
    }
    int ans = n;
    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < k; ++j)
        {
            if (dpl[i][j] && smr[i + 1][k - j] - smr[i + 1][max(k - j - a[i], 0)])
            {
                --ans;
                break;
            }
        }
    }
    cout << ans << "\n";
    return 0;
}

