using namespace std;

int search(vector<int>& a,vector<int>& b,int K,int i,int sum){
	sum += a[i];
	if (sum >= K){
		b[i] = 1;
		return 1;
	}
	int flag=0;
	for (int j = i - 1; j >=0; j--){
		int f = search(a, b, K, j, sum);
		if (f){
			b[i] = 1;
			flag = 1;
		}
	}
	return flag;
}

