      right--;
      continue;
    }else if(med < 0){
      left++;
      continue;
    }

    src = med;
    memset(dp, -1, sizeof(dp));
    tabooo[med] = true;
    int res = memo(left, 0);
    tabooo[med] = false;
    if (res > 0){//necessary
      right = med;
