int main(int argc, char const* argv[])
{
	int n,k;
	cin >> n >> k;
	VL a(n);
	cin >> a;
	auto dp = make_v<bool>(n+1, k);
	int ans = n;
	auto init = [&](){
		for (auto&& var : dp) {
			for (auto&& var2 : var) {
				var2 = false;
			}
		}
		dp[0][0] = true;
	};
	init();
	for (int c = 0; c < n; c++) {
		for (int i = 1; i <= n; i++) {
			if (c == (i-1)) {
				for (int j = 0; j < k; j++) {
					dp[i][j] = dp[i-1][j];
				}
				continue;
			}
			for (int j = 0; j + a[i-1] < k; j++) {
				dp[i][j] = (dp[i-1][j] or dp[i][j]);
				if (dp[i-1][j]) {
					dp[i][j+a[i-1]] = true;
				}
			}
		}
		int h = 0;
		for (int i = 1; i <= n; i++) {
			if (c == (i-1)) {
				continue;
			}
			for (int j = k-1; j >= 0; j--) {
				if (dp[i][j] and j + a[c] >= k) {
					h = 1;
				}
			}
		}
		ans -= h;
		init();
	}
	cout << ans << endl;
	return 0;
}

