	for(int i=0;i<ch_n;i++)if(t[i]<K)dp[i][t[i]]=true;
	for(int i=1;i<ch_n;i++)
	{
		for(int j=0;j+t[i]<K;j++)
		{
			dp[i][j+t[i]]|=dp[i-1][j];
		}
	}
	if(K<=A[rp])return 1;
	for(int i=0;i<N-1;i++)
		for(int j=K-A[rp];j<K;j++)
