bool deep(vector<int> a,int r){
	vector<int> b;
	int l;
	for(int i = 0;i < a.size();i++){
		if(i == r){
			l = a[r];
		}
		else{
			b.push_back(a[i]);
		}
	}
	bool bp[5000] = {};
	bp[0] = true;
	for(int i = 1;i < 5000;i++){
		bp[i] = false;
	}
	for(int i = 0;i < b.size();i++){
		for(int j = 0;j < 5000;j++){
			if(bp[j] && j+b[i] < 5000)bp[j+b[i]] = true;
		}
	}
	for(int i = k-l;i < k;i++){
		if(bp[i]) return true;
	}
	return false;
}

