	auto init = [&](){
		for (auto&& var : dp) {
			for (auto&& var2 : var) {
				var2 = false;
			}
		}
		dp[0][0] = true;
	};
	init();
	for (int c = 0; c < n; c++) {
		for (int i = 1; i <= n; i++) {
			if (c == (i-1)) {
				for (int j = 0; j < k; j++) {
					dp[i][j] = dp[i-1][j];
				}
				continue;
			}
			for (int j = 0; j + a[i-1] < k; j++) {
				if (dp[i-1][j]) {
					dp[i][j+a[i-1]] = true;
				}
			}
