		int h = 0;
		for (int i = 1; i <= n; i++) {
			if (c == (i-1)) {
				continue;
			}
			for (int j = k-1; j >= 0; j--) {
				if (dp[i][j] and j + a[c] >= k) {
					h = 1;
				}
			}
		}
		ans -= h;
		init();
	}
	cout << ans << endl;
