int n, k;

void DODP(vector<bitset<5001>> &dp, const vector<int> &a) {
    dp[0][0] = true;
    for(int i = 0; i < n; i++) {
        for(int j = 0; j <= k; j++) {
            if(!dp[i][j])continue;
            dp[i + 1][j] = true;
            dp[i + 1][min(k, j + a[i])] = true;
        }
    }
}



bool marge(bitset<5001> f, bitset<5001> b, int a) {
    if(a >= k)return false;
    bitset<5001> dp;
    for(int i = 0; i <= k; i++) {
        for(int j = 0; j <= k; j++) {
            if(i+j<=k&&f[i]&&b[j])dp[i+j]=true;
        }
    }
    for(int i = k - 1; i >= k - a; i--)if(dp[i])return false;
    return true;
}


