#include <functional>

using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(i, n) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ')

const int N_MAX = 5000;
const int K_MAX = 5000;

int N, K;
int a[N_MAX];

bool dp[K_MAX];

bool C(int k) {
  if (k < 0) return false;
  if (k >= N) return true;
  if (a[k] >= K) return true;
  fill(dp, dp + K, false);
  dp[0] = true;
  REP(i, N) {
    if (i == k) continue;
    for (int j = K - 1; j >= a[i]; j--) {
      dp[j] |= dp[j - a[i]];
    }
  }
  FOR(j, K - a[k], K - 1) {
    if (dp[j]) return true;
  }
  return false;
}

void solve() {
  sort(a, a + N);
  int lo = -1;
  int hi = N;
  while (hi - lo > 1) {
    int mi = (lo + hi) / 2;
    if (C(mi)) hi = mi;
    else lo = mi;
  }
  printf("%d\n", hi);
}

void input() {
  scanf("%d%d", &N, &K);
  REP(i, N) scanf("%d", a + i);
}

int main() {
  input();
  solve();
  return 0;
}

