    rep(i,n) cin>>a[i];
    vector<vi> dp(n+1,vi(k,0));
    vector<vi> dp2(n+1,vi(k,0));
    dp[0][0] = 1;
    rep(i,n)rep(j,k){
        if ((ll)j>=a[i])
            dp[i+1][j] = max(dp[i][j-a[i]],dp[i][j]);
        else
            dp[i+1][j] = dp[i][j];
    }
    dp2[n][0] = 1;
    rep(i,n)rep(j,k){
        if ((ll)j>=a[n-i-1])
            dp2[n-i-1][j] = max(dp2[n-i][j-a[n-i-1]],dp2[n-i][j]);
        else
            dp2[n-i-1][j] = dp2[n-i][j];
    }
    int ans=0;
    rep(i,n){
        int idx=0;
        int maxi=0;
        set<int> A,B;
        rep(j,k){
            if (dp[i][j]) A.ins(j);
            if (dp2[i+1][j]) B.ins(j);
        }
        for(auto e:A){
            auto itr = B.lower_bound(k-e); itr--;
            chmax(maxi, *itr+e);
        }
        if(a[i]+maxi<k){
            ans++;
        }
    }
    cout<<ans<<endl;
    return 0;
}

