const int MAX_N = 5005;
const int MAX_K = 5005;

int N, K;
vector<int> a;
bool dp[MAX_N][MAX_K]; // dp[x][y] := x 枚目をみたとき、総和を y にできるか？

bool solve(int x){

	memset(dp, false, sizeof(dp));
	dp[0][0] = true;
	rep (j, N){
		rep (k, K){
			if (dp[j][k]){
				dp[j+1][k] |= true;
				if (x != j && k + a[j] < K) dp[j + 1][k + a[j]] |= true;
			} // end if
		} // end rep
	} // end rep

	bool need = false;
	rep(k, K){
		if (dp[N][k] && k + a[x] >= K){
			need |= true;
		} // end if
	} // end for

	return !need;
}

int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cin >> N >> K;
	a.clear(); a.resize(N, 0);
	rep (i, N){
		cin >> a[i];
	} // end rep

	sort(ALL(a));

	int ulimit = lower_bound(ALL(a),K) - a.begin();
	N = ulimit;
	int ok = 0;
	int ng = ulimit;
	while(abs(ok - ng) > 1){
		int mid = (ok + ng) / 2;
		if (solve(mid)){
			ok = mid;
		}else{
			ng = mid;
		} // end if
	} // end while

	cout << ok + 1 << endl;

	return 0;
}

