    REP(i,N){
        REP(j,5010){
            if(a[i]>=K) continue;
            if(j-a[i]>=0){
                L[i+1][j]=L[i][j-a[i]]|L[i][j];
            }else{
                L[i+1][j]=L[i][j];
            }
        }
    }

    REP(i,N){
        REP(j,5010){
            if(a[i]>=K) continue;
            if(j-a[i]>=0){
                R[i][j]=R[i+1][j-a[i]]|R[i+1][j];
