  for (int64_t i = 1; i < n; i++) {
    l[i] = l[i - 1];
    if (k <= a[i - 1]) {
      continue;
    }
    for (const auto j : l[i - 1]) {
      if (a[i - 1] + j < k && !tmp[a[i - 1] + j]) {
