  tmp[0] = true;

  for (int64_t i = n - 2; 0 <= i; i--) {
    r[i] = r[i + 1];
    if (k <= a[i + 1]) {
      continue;
    }
    for (const auto j : r[i + 1]) {
      if (a[i + 1] + j < k && !tmp[a[i + 1] + j]) {
        tmp[a[i + 1] + j] = true;
        r[i].insert(a[i + 1] + j);
