        dp[0]           = 1;
        for (int i = 0; i < n; ++i) {
            if (i == mid)
                continue;
            if (a[i] <= 5000)
                dp |= dp << a[i];
        }
        bool ok = true;
        for (int i = max(0LL, k - a[mid]); i < k; ++i) {
            if (dp[i] == 1) {
                ok = false;
                break;
            }
        }
        return ok;
    };
    ll ok = 0;
    ll ng = n - 1;
    while (abs(ok - ng) != 1) {
        ll mid = (ng + ok) / 2;
        if (check(mid))
            ok = mid;
        else
            ng = mid;
    }
    cout << ok + 1 << "\n";
    return 0;
}

