// i 枚目が必要かどうか
bool is_needed(vll& a, ll i, int K) {
    swap(a.back(), a.at(i));

    vector<vector<bool>> s(a.size(), vector<bool>(K, false));
    s[0][0] = true;
    rep(i, a.size() - 1) {
        for(ll j = 0; j < a[i]; j++)
            s[i + 1][j] = s[i][j];
        for(ll j = a[i]; j < K; j++)
            s[i + 1][j] = s[i][j - a[i]] || s[i][j];
    }

    bool ret = false;
    rep(i, a.size()) {
        bool tmp = false;
        for (ll j = max(K - a.back(), 0LL); j < K - 1; j++)
            if (s[a.size()-1][j]) tmp = true;
        ret = ret || tmp;
    }

    swap(a.back(), a.at(i));

    return ret;
}

void solve() {
    ini(N, K);
    vll a(N);
    rep(i, N) cin >> a[i];
    sort(a.begin(), a.end());

    if (is_needed(a, 0, K))
        out(0);
    else if (!is_needed(a, a.size() - 1, K))
        out(a.size());
    else {
        ll left = 0, right = a.size() - 1;
        while (left + 1 != right) {
            ll mid = (left + right) / 2;
            if (is_needed(a, mid, K))
                right = mid;
            else
                left = mid;
        }
        out(right);
    }
}

