int binary_search(int lower, int upper){
  //cout << lower << "," << upper << endl;
  if(lower == upper) return lower;
  if(lower+1 == upper){
    bool l = judge(lower), u = judge(upper);
    if(l && u) return lower;
    if((!l) && (!u)) return N;
    return upper;
  }
  int mid = (lower+upper)/2;

  if(judge(mid))
    binary_search(lower, mid);
  else
    binary_search(mid, upper);
}

