vector<int> a;

bool check(int p) {
  vector<vector<bool>> dp(N + 1, vector<bool>(K + 1, false));
  dp[0][0] = true;
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < K + 1; j++) {
      dp[i + 1][j] = (i != p && j >= a[i]) ? dp[i][j] | dp[i][j - a[i]] : dp[i][j];
    }
  }
  bool res = false;
  for (int i = max(0, K - a[p]); i < K; i++) {
    res |= dp[N][i];
  }
  return res;
}

main() {
  cin >> N >> K;
  a.resize(N);
  for (int i = 0; i < N; i++) cin >> a[i];
  sort(a.begin(), a.end());

  int ng = -1, ok = N, mid;
  while (ok - ng > 1) {
    mid = (ok + ng) / 2;
    if (check(mid)) {
      ok = mid;
    } else {
      ng = mid;
    }
  }
  cout << ok << endl;
}

