bool judge(int idx){
	bitset<5001> bts;
	bts.set(0);
	int i = 0;
	while(i < n && a[i] < k) if(idx != i) bts |= bts << a[i++]; else ++i;
	repU(j,max(0,k - a[idx]),k - 1) if(bts[j]) return 0;
	return 1;
} 

int srch(){
	int l = 0,u = n;
	while(u - l > 1){
		int m = (u + l) / 2;
		if(judge(m)) l = m;
		else u = m;
	}
	if(l) return l;
	return judge(0) - 1;
}

