bool check(int a, int b){

  bool ret;

  if(a == l){
    a++;
  }

  if(logc[l]){
    ret = loga[l];

  }else if( (K - number[l]) <= b && b < K ){
    //lは必要
    //終了処理
    ret = true;

  }else if( K <= b ){
    //終了処理
    ret = false;

  }else if(a >= N){
    //終了処理
    ret = false;

  }else if( check(a+1, b+number[a]) ){
    ret = true;
  }else if( check(a+1, b) ){
    ret = true;
  }else{
    ret = false;
  }

  return ret;

}

int nibutan(bool flag, int f, int e, int m){

  int mem = -1;

  if(f == m || e == m){
    l = m+1;
    if(check(0, 0)){
      mem = m;
    }else{
      mem = l;
    }



  }else{
    if(flag){
      //printf("H%d E%d L%d\n", f, l, (f+m)/2);
      l = (f+m)/2;
      mem = nibutan( check(0, 0), f, m, l );
    }else{
      //printf("H%d E%d L%d\n", m, e, (m+e)/2);
      l = (m+e)/2;
      mem = nibutan( check(0, 0), m, e, l );
    }
  }

  return mem;

}

