/* ------------- Functions -------------- */

bool judge(ll itr) {
    if (a[itr] > K) return true;

    bitset<10010> dp;
    dp.set(0);

    REP(i, N) {
        if (i == itr) continue;
        dp = dp | (dp << a[i]);
    }

    bool ret = false;
    NREP(i, a[itr]) {
        ret |= dp[K - i];
    }

    return ret;
}

