int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> K;

    a.resize(N);
    REP(i, N) {
        cin >> a[i];
    }
    SORT(a);

    ll ok = N, ng = -1;
    while (ok - ng > 1) {
        ll mid = (ok + ng) / 2;
        if (judge(mid)) {
            ok = mid;
        } else {
            ng = mid;
        }
    }

    cout << ok << endl;
    return 0;
}

