signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> n >> k;
	rep(i, n)cin >> a[i];
	dp1[0][0] = true;
	rep(i, n - 1) {
		rep(j, k) {
			if (dp1[i][j])dp1[i + 1][j] = true;
			if (dp1[i][j] && j + a[i] <= k) {
				dp1[i + 1][j + a[i]] = true;
			}
		}
	}
	dp2[n - 1][0] = true;
	for (int i = n - 1; i > 0; i--) {
		rep(j, k) {
			if (dp2[i][j])dp2[i - 1][j] = true;
			if (dp2[i][j] && j + a[i] <= k) {
				dp2[i - 1][j + a[i]] = true;
			}
		}
	}
	int ans = 0;
	rep(i, n) {
		vector<int>ans1, ans2;
		rep(j, k + 1) {
			if (dp1[i][j])ans1.push_back(j);
			if (dp2[i][j])ans2.push_back(j);
		}
		bool b = false;
		for (int p : ans1) {
			if (upper_bound(all(ans2), k - p - 1) - lower_bound(all(ans2), k - p - a[i])) {
				b = true;
			}
		}
		if (!b)ans++;
	}
	cout << ans << endl;
}

