    dp1[0][0] = 1;

    for (int j = 1; j < N; j++) {
        for (int k = 0; k < K; k++) {
            if (k >= A[j]) {
                dp1[j][k] = dp1[j - 1][k] + dp1[j - 1][k - A[j]];
            } else {
                dp1[j][k] = dp1[j - 1][k];
            }
        }
    }
    dp2[N - 1][A[N - 1]] = 1;
    dp2[N - 1][0] = 1;

    for (int j = N - 2; j >= 0; j--) {
        for (int k = 0; k < K; k++) {
            if (k >= A[j]) {
                dp2[j][k] = dp2[j + 1][k] + dp2[j + 1][k - A[j]];
            } else {
                dp2[j][k] = dp2[j + 1][k];
            }
        }
    }

    /*
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < K; j++) {
            cout << "i = " << i << ", j = " << j << ",dp1 = " << dp1[i][j] << "\n";
        }
    }
    for (int i = 0; i < N; i++) {
