    for (int i = 0; i < N; i++) {
        cout << "A[i] = " << A[i] << ", isNeeded = " << isNeeded(i) << "\n";
    }
    */

    int ans = 0;
    int lmax, lmin;
    if (isNeeded(0)) {
        ans = 0;
    } else if (!isNeeded(N - 1)) {
        ans = N;
    } else {
        lmax = N - 1;
        lmin = 0;
        while (true) {
            int lmid = (lmin + lmax) / 2;
            //cout << "lmin = " << lmin << ", lmax = " << lmax << ", lmid = " << lmid << ", isNeeded = " << isNeeded(lmid) << "\n";
            if (lmid == lmin || lmid == lmax) {
                ans = lmin + 1;
                break;
            }
            if (isNeeded(lmid)) {
                lmax = lmid;
            } else {
                lmin = lmid;
            }
        }
    }

    cout << ans << "\n";

    return 0;
}

bool isNeeded(int i)
{
    if (i != 0 && i != N - 1) {
        for (int s = max(0, K - A[i]); s < K; s++) {
            for (int t = 0; t <= s; t++) {
                //cout << "s = " << s << ", t = " << t << ",dp1 = " << dp1[i - 1][t] << ", dp2 = " << dp2[i + 1][s - t] << "\n";
                if (dp1[i - 1][t] != 0 && dp2[i + 1][s - t] != 0) {
                    return true;
                }
            }
        }
        return false;
    } else if (i == 0) {
        for (int s = max(0, K - A[0]); s < K; s++) {
            if (dp2[1][s] != 0) {
                return true;
            }
        }
        return false;
    } else {
        for (int s = max(0, K - A[N - 1]); s < K; s++) {
            if (dp1[N - 2][s] != 0) {
                return true;
            }
        }
        return false;
    }
}

