	int N, K;
	cin >> N >> K;

	vector<int> A(N);
	FOR(i, 0, N) {
	    cin >> A[i];
	}

	LL low = -1, high = A.size();
	while (high - low > 1) {
	    auto idx = (low + high) / 2;
	    if (can_delete(idx, A, K)) {
	        low = idx;
	    }
	    else {
	        high = idx;
	    }
	}

	print(low + 1);
	return 0;
}

