        dp[0][0] = true;

        for(int j=1; j<=n; j++){
            for(int t=0; t<k; t++){
                if(dp[j-1][t]){
                    dp[j][t] = true;
                }
                else if(i+1 != j && a[j-1] < k && t-a[j-1] >= 0 && dp[j-1][t-a[j-1]]){
                    dp[j][t] = true;
                }
            }
        }


        for(int j = k-a[i]; j<k; j++){
            if(dp[n][j]){
                need++;
                break;
            }
        }
    }

    cout << n-need << endl;

    return 0;
}

