            break;
        *(buf++)=(char)ch;
    }
    *(buf)='\0';

    return nBuf;
}

int InputIntAry(int *a,int nBuf,int N,int K){
    int ret=0;
    int64_t tmp;
    char *buf,*ptr;

    buf=(char*)malloc(nBuf*sizeof(char));
    my_gets(buf,nBuf,stdin);

    ptr=strtok(buf," ");
    while(ptr!=NULL && N-->0){
        tmp=atoll(ptr);
        if(tmp < K){    //Kより大きなカードは必要に決まっているし, 他のカードの判定に関係しない
            a[ret++] = (int)tmp;
            //printf("%d\n",a[ret-1]);
        }
        ptr=strtok(NULL," ");
    }
    free(buf);

    return ret;
}

