  sort(A.begin(), A.end());
  int result = 0;
  for (int i = 0; i < N; i++){
    memset(dp, -1, sizeof(dp));
    tabooo = i;
    int res = memo(0, 0);
    if (res > 0){
      result++;
    }
  }
  cout << N - result << endl;

  return 0;
}

