void DODP(vector<vector<bool>> &dp, const vector<int> &a) {
    dp[0][0] = 1;
    for(int i = 0; i < n; i++) {
        for(int j = 0; j <= k; j++) {
            if(!dp[i][j])continue;
            dp[i + 1][j] = true;
            dp[i + 1][min(k, j + a[i])] = true;
        }
    }
