bool marge(vector<bool> dp1, vector<bool> dp2, int a) {
    if(a >= k)return false;
    bitset<5001> dp, f, b;
    for(int i = 0; i <= k; i++) {
        if(dp1[i])f[i] = true;
        if(dp2[i])b[i] = true;
    }
    for(int i = 0; i <= k; i++) {
        for(int j = 0; j <= k; j++) {
            if(i+j<=k&&f[i]&&b[j])dp[i+j]=true;
        }
    }
    // cout << "----" << a << endl;
    // cout << f << endl;
    // cout << b << endl;
    // cout << dp << endl;
    for(int i = k - 1; i >= k - a; i--)if(dp[i])return false;
    return true;
}


