using namespace std;

int N, K, A[5005];

bool dp[5005][5005];

bool need(int t)
{
    CLR(dp);
    dp[0][0] = true;
    REPS(i, N)
    {
        int a = A[i - 1];
        FOR(j, 0, K)
        {
            if (i == t)
            {
                dp[i][j] = dp[i - 1][j];
                continue;
            }
            if (j - a < 0)
            {
                dp[i][j] = dp[i - 1][j];
                continue;
            }
            dp[i][j] = dp[i - 1][j - a] || dp[i - 1][j];
        }
    }
    FOR(i, K - A[t - 1], K - 1)
    {
        if (dp[N][i])
            return true;
    }
    return false;
}

signed main()
{
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    cin >> N >> K;
    REP(i, N)
    {
        cin >> A[i];
    }
    sort(A, A + N);

    if (!need(N))
    {
        cout << N << endl;
        return 0;
    }

    int left = 0;
    int right = N;
    while (right - left > 1)
    {
        int mid = (left + right) / 2;
        if (need(mid))
        {
            right = mid;
        }
        else
        {
            left = mid;
        }
    }
    cout << left << endl;

    return 0;
}

