    }
  }

  for (int i=N-1;i>=1;--i){
    for (int j=0;j<K+1;++j){
      if(left[i][j]==1||(j>=a[i-1]&&left[i][j-a[i-1]]==1)) left[i-1][j]=1;
    }
  }

