int n, k;
vector<int> a;

bool check(int x) { // 不必要

    if (a[x] >= k) return 0;

    int dp[n + 1][k + 1];
    fill_n(*dp, (n + 1) * (k + 1), 0);


    rep(j, n) {
        if (x == j) {
            rep(l, k + 1) dp[j + 1][l] = dp[j][l];
            continue;
        }

        rep(l, k + 1) {
            if (l == 0) {
                if (a[j] >= k - a[x] && a[j] < k) return 0;
                dp[j + 1][(a[j] > k ? k : a[j])] = 1;
            } else if (dp[j][l] == 0) continue;
            else {
                if (a[j] + l >= k - a[x] && a[j] + l < k) return 0; // 1にしてたorz
                dp[j + 1][(a[j] + l > k ? k : a[j] + l)] = 1;
            }

        }
    }

    return 1;
}

template<typename T>
void binary_search(T ok, T ng) {
    while (abs(ng - ok) > 1) {
        T mid = (ng + ok) / 2;
        // cout << mid << endl;
        (check(mid) ? ok : ng) = mid;
        // cout << ok << " " << ng << endl;
    }
    cout << ok + 1 << endl;
}






