bool Solve(int pos) {
    for( int i = 0; i < n; ++i ) {
        for( int j = 0; j <= k; ++j ) {
            dp[i][j] = false;

        }
    }

    for( int i = 0; i < n; ++i ) {
        dp[i][0] = true;
        if( i == 0 && i == pos ) continue;

        for( int j = 1; j < k; ++j ) {
            if( i == pos ) {
                dp[i][j] = dp[i - 1][j];
                continue;

            }

            if( i == 0 ) {
                if( v[i] == j ) {
                    dp[i][j] = true;

                }
            } else {
                if( v[i] <= j ) {
                    dp[i][j] |= dp[i - 1][j - v[i]];

                }
                dp[i][j] |= dp[i - 1][j];
            }
        }
    }

    for( int j = max(k - v[pos], 0); j < k; ++j ) {
        if( dp[n - 1][j] ) {
            return true;

        }
    }
    return false;
}

