    int m = fr.size();
    for(int i = 0; i < m; i++) {
        auto les = lower_bound(bc.begin(), bc.end(), k - a - fr[i]);
        auto gre = lower_bound(bc.begin(), bc.end(), k - fr[i]);
        if(les != gre)return false;
    }
    return true;
}


