    while (right - left > 1) {
        int mid = (right + left) / 2;
        // i番目のカードが不要かどうかを確かめる
        vector<ll> other_a;
        for (int j = 1; j <= N; j++) {
            if (mid == j) continue;
            other_a.push_back(a[j]);
