        for (int j = 0; j <= N; j++) {
            for (int k = 1; k < K; k++) dp[j][k] = 0;
        }
        for (int j = 0; j <= N; j++) dp[j][0] = 1;
        for (int j = 1; j <= other_a.size(); j++) {
            for (ll k = 0; k < K; k++) {
                dp[j][k] += dp[j - 1][k];
                if (k - other_a[j - 1] >= 0) dp[j][k] += dp[j - 1][k - other_a[j - 1]];
            }
        }
        bool is_needed = false;
        for (ll j = 0; j < K; j++) {
            if (dp[N - 1][j] > 0 && j + a[mid] >= K) {
                is_needed = true;
            }
        }
