using bs = bitset<5000>;

bs dp[2][5010];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, K;
    cin >> N >> K;
    Vl A(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    for (int i = 0; i < 2; i++) {
        for (int j = 0; j <= 5000; j++) {
            dp[i][j].flip();
        }
    }

    dp[0][0] = 0;
    for (int i = 0; i < N; i++) {
        for (int x = 0; x <= 5000; x++) {
            ll x_next = min(x + A[i], 5000LL);
            bs u = dp[i & 1][x];
            u.set(i);
            dp[(i + 1) & 1][x_next] &= u;
            dp[(i + 1) & 1][x] &= dp[i & 1][x];
        }
    }

    int cnt = 0;
    for (int i = 0; i < N; i++) {
        bool ok = false;
        for (int x = max(0LL, K - A[i]); x < K; x++) {
            if (dp[N & 1][x].test(i) == 0) {
                ok = true;
                break;
            }
        }
        if (ok) ++cnt;
    }

    cout << N - cnt << endl;

    return 0;
}

