int main() {
  int N, K;
  cin >> N >> K;

  long a[N];
  for (int n = 0; n < N; n++) {
    cin >> a[n];
  }

  int dp[N][K];
  int count = 0;  // nums of essential cards


  // need a[i]?
  for (int i = 0; i < N; i++) {
    // clear dp array
    for (int n = 0; n < N; n++) {
      for (int k = 0; k < K; k++) {
        dp[n][k] = -1;
      }
    }

    // do dp
    for (int x = 1; x < N; x++) {
      for (long y = K - a[i]; y >= 0 && y < K; y++) {
        dp[0][a[0]] = 1;

        if (y - a[x] >= 0 && x != i) {
          dp[x][y] = max(dp[x - 1][y], dp[x - 1][y - a[x]]);
        } else {
          dp[x][y] = dp[x - 1][y];
        }
      }
    }

    for (long y = K - a[i]; y >= 0 && y < K; y++) {
      if (dp[N - 1][y] == 1) {
        count++;
        break;
      }
    }
  }

  cout << N - count << endl;

  return 0;
