	sort(ALL(v));
	sort(RALL(v1));
	REP(i, n)
	{
		w += v[i];
		if (w >= k)
		{
			h = i;
			break;
		}
	}
	REP(i, h)
	{
		if (k <= w - v[i])
		{
			ans++;
		}
	}

	if (w < k)
	{
		cout << n << endl;
	}
	else
	{
		cout << ans << endl;
	}
}

