bool need(int a_i, long long expressed_num, int ignore)
{
	// expressed_numがneedの条件を満たすか
	if (expressed_num < k && expressed_num >= k - a[ignore]) return true;
	// expressed_numがこれ以前のa_iについて判定済みなら無視
	if (expressed_num >= k || dp[expressed_num] <= a_i) return false;
	if (expressed_num >= k - a[ignore]) return true;
	if (a_i == n) return false;

	if (ignore != a_i && need(a_i + 1, expressed_num + a[a_i], ignore)) return true;
	if (need(a_i + 1, expressed_num, ignore)) return true;
	dp[expressed_num] = a_i;
	return false;
}

