bool isneed(int p){
  if(p == 0) return false;
  if(K < a[p]){
    return true;
  }
  // i枚目まで使って総和をjにできるか
  bool dp[N+1][K+1];
  for(int i=0;i<=N;i++){
    for(int j=0;j<=K;j++){
      dp[i][j] = false;
    }
  }
  for(int i=0;i<=N;i++){
    dp[i][0] = true;
  }
  for(int i=1;i<=N;i++){
    if(i == p){
      for(int j=0;j<=K;j++) dp[i][j] = dp[i-1][j];
    }else{
      for(int j=0;j<=K;j++){
        if(j - a[i] < 0) dp[i][j] = dp[i-1][j];
        else dp[i][j] = (dp[i-1][j] || dp[i-1][j - a[i]]);
      }
    }
  }
  /*
  cout << p << endl;
  for(int i=1;i<=N-1;i++){
    for(int j=0;j<=K;j++){
      cout << dp[i][j] << " ";
    }
    cout << endl;
  }
  cout << endl;
  */
  for(int i=K-a[p];i<K;i++){
    if(dp[N][i]) return true;
  }
  return false;
}

