bool f(int pos, int k, vector<int> card)
{
	const int prev = card[pos];
	card[pos] = 0;

	const int size = card.size();
	vector<vector<bool>> table(size+1, vector<bool>(k+1, false));
	table[0][0] = true;

	for(int i=0; i<size; i++)
	{
		for(int j=0; j<k+1; j++)
		{
			if(table[i][j] == false)
				continue;

			table[i+1][j] = table[i][j];

			int n = j + card[i];
			if(n > k)
				continue;

			table[i+1][n] = true;
		}
	}

	bool flag = false;
	for(int i=max(0, k-prev); i<k; i++)
		if(table[size][i] == true)
			flag = true;

	return flag;
}

