  using Bitset = bitset<5000>;
  vector<Bitset> dpl(n+1);
  dpl[0][0] = 1;
  for (int i = 1; i <= n; i++) {
    auto a = A[i-1];
    dpl[i] = dpl[i-1] | dpl[i-1] << a;
  }
  vector<vector<int>> cdpl(n+1, vector<int>(k));
  for (int i = 0; i <= n; i++) {
    cdpl[i][0] = dpl[i][0];
    for (int j = 1; j < k; j++) {
      cdpl[i][j] += cdpl[i][j-1] + dpl[i][j];
    }
  }
  vector<Bitset> dpr(n+1);
  dpr[n][0] = 1;
  for (int i = n-1; i >= 0; i--) {
    auto a = A[i];
    dpr[i] = dpr[i+1] | dpr[i+1] << a;
  }

  int ans = n;
  for (int i = 0; i < n; i++) {
