int main() {
	long n, k;
	scanf("%ld %ld",&n, &k);
	long arr[n];
	for (int i=0; i<n; i++) {
		scanf("%ld",&arr[i]);
	}
	sort(arr, arr+n);
	long DP[n];
	long temp = -1;
	DP[0] = arr[0];
	for (int i=1; i<n; i++) {
		DP[i] = DP[i-1] + arr[i];
		if (DP[i] >= k && temp==-1) {
			temp = i;
		}
	}
	if (temp==-1) {
		cout << n << endl;
	}
	else {
		int minimum_hit = 1000000;
		for (int x=temp; x<n; x++) {
			int max_hit = 0;
			long comparator = DP[x];

			for (int y=0; y<=x-1; y++) {
				if (comparator < k) {
					break;
				}	
				else {
					int i = y;
					int hit = 0;
					while (i<=x-1) {
						if (comparator - arr[i] >= k) {
							hit++;
						}
						i++;
					}
					if (hit>max_hit) {
						max_hit = hit;
					}
					comparator -= arr[y];
				}
			}

			if (max_hit < minimum_hit) {
				minimum_hit = max_hit;
			}
		}
		cout << minimum_hit << endl;
	}
}

