int solve(int i, int sum){
    if(i == n)  return (sum >= k - temp && sum < k);

    int &ret = dp[i][sum];
    if(~ret)    return ret;

    ret = solve(i + 1, sum);
    if(ret) return ret;

    return ret = solve(i + 1, min(k, sum + a[i]));
}


