    REP(i,n){
        REP(j,k+1){
            if(dp[i][j].first==0) continue;
            dp[i+1][j].first++;//何もしない
            if(j<k){
                if(j+a[i]<k) dp[i+1][j+a[i]].first++;
                else dp[i+1][k]={1,j};
            }
        }
    }

    REP2(i,n){
        REP(j,k+1){
            if(use[j]==false) continue;
            if(j-a[i]>=0 and dp[i][j-a[i]].first!=0){
                need[i]=true;
                use[j-a[i]]=true;
