        int mid = (right + left) / 2;
        // i番目のカードが不要かどうかを確かめる
        vector<ll> other_a;
        other_a.push_back(0);
        for (int j = 1; j <= N; j++) {
            if (mid == j) continue;
            other_a.push_back(a[j]);
        }
        for (int j = 0; j <= N; j++) {
            for (int k = 1; k < K; k++) dp[j][k] = 0;
        }
        for (int j = 0; j <= N; j++) dp[j][0] = 1;
        for (int j = 1; j < N; j++) {
            for (ll k = 0; k < K; k++) {
                dp[j][k] += dp[j - 1][k];
                if (k - other_a[j] >= 0) dp[j][k] += dp[j - 1][k - other_a[j]];
            }
