ll solve(){
    ll res = 0;
    cin >> N >> K;
    a.resize(N); for(auto &in:a) cin >> in;
    sort(a.begin(),a.end()); reverse(a.begin(),a.end());
    ll ans = -1;
    for(int i = 0; i < N;i++){
        ll sum = 0;
        for(ll j = i; j < N;j++){
            if(sum + a[j] < K){ sum += a[j]; continue; }
            ans = max(ans,j);
        }
    }
    return res = N - ans - 1;
}
