struct BS{
  static const size_t NE=(5001+63)/64;
  unsigned long long b[NE];
  bool operator[](size_t s)const{
    return b[s/64]>>s%64&1;
  }
  void slo(const size_t s){
    if(s%64==0){
      for(int i=NE-1;i>=s/64;i--){
	b[i]|=b[i-s/64];
      }
    }else{
      for(int i=NE-1;i>=1+s/64;i--){
	//	b[i]|=b[i-s/64]<<s%64|b[i-s/64-1]>>64-s%64;
	//	b[i]|=(((unsigned __int128)b[i-s/64])<<64|b[i-s/64-1])>>64-s%64;
	unsigned long long r;
	asm (
	     "shrd\t%%cl, %2, %0"
	     :"=r"(r)
	     :"c"(64-s%64),"r"(b[i-s/64]),"0"(b[i-s/64-1])
	     );
	b[i]|=r;
      }
      b[s/64]|=b[0]<<s%64;
    }
  }
};

