int binary_DP()
{
	int left=-1;
	int right=n;
	int mid;
	bool dp[5001];
	bool flag=false;
	while(right-left>1)
	{
		mid=(left+right)/2;
		cerr<<mid<<endl;
		flag=false;
		for(int i=0;i<5001;i++)
		{
			dp[i]=false;
		}
		dp[0]=true;
		//DP
		for(int i=0;i<n;i++)
		{
			if(i==mid)
			{
				continue;
			}
			for(int j=5000;j>=0;j--)
			{
				if(dp[j]==true && j+a[i]<=5000)
				{
					dp[j+a[i]]=true;
				}
			}
		}
		//ここまでDP
		for(int i=0;i<k;i++)
		{
			if(dp[i]==true&&i+a[mid]>=k)
			{
				flag=true;
				break;
			}
		}
		if(flag==true)
		{
			right=mid;
		}else{
			left=mid;
		}
	}
	return right;
}

