bool need(int m) {
	for (int i = 0; i <= N; i++) {
		for (int j = 0; j <= K; j++) dp[i][j] = false;
	}

	dp[0][0] = true;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < K; j++) {

			if (dp[i][j]) {
				dp[i + 1][j] = true;
				// a[m]は使ってはいけない
				if (i+1 != m && j + a[i + 1] < K) dp[i + 1][j + a[i + 1]] = true;
			}
		}
	}

	// dp[N][K-a[n]]～dp[N][K-1]がすべてfalseなら不要
	bool flag = false;
	for (int i = max(0,K - a[m]); i < K && !flag; i++) {
		if (dp[N][i]) flag = true;
	}

	return flag;
}

