void solve() {
    ll n, k;
    cin >> n >> k;
    vll a;
    rep(i, n) {
        ll _a;
        cin >> _a;
        if(_a >= k) continue;
        a.push_back(_a);
    }
    n = a.size();
    vvb saf(n + 1, vb(k + 1)), sab(n + 1, vb(k + 1));
    saf[0][0] = true;
    for(ll i = 0; i < n; i++) {
        for(ll j = 0; j <= k; j++) {
            if(saf[i][j]) {
                saf[i + 1][j] = true;
                if(j + a[i] <= k) saf[i + 1][j + a[i]] = true;
            }
        }
    }
    sab[n][0] = true;
    for(ll i = n - 1; i >= 0; i--) {
        for(ll j = 0; j <= k; j++) {
            if(sab[i + 1][j]) {
                sab[i][j] = true;
                if(j + a[i] <= k) sab[i][j + a[i]] = true;
            }
        }
    }
    vvll saf2(n + 1), sab2(n + 1);
    rep(i, n + 1) rep(j, k + 1) if(saf[i][j]) saf2[i].push_back(j);
    rep(i, n + 1) rep(j, k + 1) if(sab[i][j]) sab2[i].push_back(j);

    ll ans = 0;
    for(ll i = 0; i < n; i++) {
        vll& v1 = saf2[i];
        vll& v2 = sab2[i + 1];
        // v1+v2がk-a[i]~k-1となるのを探す
        bool ok = false;
        for(auto& j : v1) {
            ll l = lower_bound(v2.begin(), v2.end(), k - a[i] - j) - v2.begin();
            ll r = upper_bound(v2.begin(), v2.end(), k - 1 - j) - v2.begin();
            if(r - l > 0) ok = true;
            if(ok) break;
        }
        if(!ok) ++ans;
    }
    cout << ans << endl;
    return;
}

