				//二分探索で指定した値より大きい数を探してを足す
				vec.erase(it);
				//二分探索で使った値を消す
				c2++;
			}
			else {//大きい数がなかったらitよい小さい数の大きい数から足していく。
				while (sum < k && vec.size() != 0) {
					sum += vec[vec.size() - 1];
					vec.pop_back();
					c2++;
				}
			}
		}
		if (sum >= k) {
			c++;  sum = 0;
		}
		if (vec.size() == 0) {
			ans = c2;
			break;
		}
	}

	cout << ans << endl;
}

