int N, K;

bool necessary(int idx, const vector<ll>& a) {
    if (a[idx] >= K) {
        return true;
    }

    vector<vector<bool>> dp(N+1);
    for (int i = 0; i < N+1; ++i) {
        dp[i].resize(K+1, false);
    }
    dp[0][0] = true;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j <= K; ++j) {
            if (i == idx || j < a[i]) {
                dp[i+1][j] = dp[i][j];
            } else {
                dp[i+1][j] = dp[i][j] || dp[i][j-a[i]];
            }
        }
    }

    bool ret = false;
    for (int j = K-a[idx]; j < K; ++j) {
        ret |= dp[N][j];
    }
    return ret;
}

