	}
	int sum = 0;
	for (int i = 0; i < n; ++i) {
		if (A[i] >= k) continue;
		for (int j = 0; j < k; ++j) {
			DP[j] = -1;
		}
		for (int j = 0; j < n; ++j) {
			if (i == j) continue;
			if ((A[j] < k) && (DP[A[j]] == -1)) {
