/*
     x1: 0000 0001 0010 0101 0110 0111 0111
     x2: xxxx 0001 0011 0100 0101 1000 0110
x1 & x2: 0000 0001 0010 0100 0100 0000 0110

      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S & (1 << i) -> if true, i in S
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}
__builtin_popcountl(i) -> the number of 1 in binary

#Conditional Operator
condition ? true : false;

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
str s, t, u;
ll n, m, h, w, k, Q;
ll a, b, c, d, idx, cnt;
vl as, bs, cs, ds;
vb2 block;
vb visited;
Graph graph;

void solve(){
    in2(n, k);
    read_vector(n, as);

    vb3 dp(2, vb2(n + 1, vb(k, false)));
    rep(i, n + 1) dp[0][i][0] = dp[1][i][0] = true;
    For(i, 1, n + 1) For(v, 1, k){
        ll v0 = as[i - 1], v1 = as[n - i];
        dp[0][i][v] = dp[0][i - 1][v];
        dp[1][i][v] = dp[1][i - 1][v];

        if (v - v0 >= 0 && !dp[0][i][v])
            dp[0][i][v] = dp[0][i - 1][v - v0];
        if (v - v1 >= 0 && !dp[1][i][v])
            dp[1][i][v] = dp[1][i - 1][v - v1];
    }

    answer = n;
    rep(i, n){
        ll m = k - as[i], M = k - 1;
        vl v0, v1;
        rep(v, k) if (dp[0][i][v]) v0.pb(v);
        rep(v, k) if (dp[1][n - 1 - i][v]) v1.pb(v);

        okay = false;
        for (ll v: v0){
            // m - v <= v1 <= k - 1 - v
            if (k - 1 - v < 0) break;
            auto it = lower_bound(all(v1), m - v);
            if (it != v1.end() && *it <= k - 1 - v){
                okay = true; break;
            }
        }
        if (okay) answer--;
    }

    prl(answer);
}

