// no need to have a[mid] ?
bool solve(ll n, ll k, const vector<ll>& a, ll mid) {
    const ll w = a[mid];
    vector<ll> b(a);
    b[mid] = INF;

    vector<ll> dp(k + 1);
    vector<ll> dp_next(k + 1);

    // no card, no sum
    fill(dp.begin(), dp.end(), 0);

    for (ll i = 0; i < n; i++) {
        for (ll j = 1; j <= k; j++) {
            dp_next[j] = dp[j];
            if (j - b[i] > 0) {
                dp_next[j] = max(dp_next[j], b[i] + dp[j - b[i]]);
            }
        }
        dp = dp_next;
    }

    return dp[k] + w < k;
}

