signed main() {
	cin >> n >> k;
	rep(i, n)cin >> a[i];
	if (n == 1) {
		if (a[0] >= k)cout << 0 << endl;
		else cout << 1 << endl;
		return 0;
	}
	rep(i, n) {
		if (!i) {
			dp[0][i][0] = 1;
			if (a[i] < k)dp[0][i][a[i]] = 1;
			continue;
		}
		rep(j, k) {
			if (j - a[i] >= 0)dp[0][i][j] |= (bool)dp[0][i - 1][j - a[i]];
			dp[0][i][j] |= (bool)dp[0][i - 1][j];
		}
	}
	rep(i, n) {
		rep(j, k) {
			if (j)dp[0][i][j] += dp[0][i][j - 1];
		}
	}
	for (int i = n - 1; i >= 0; i--) {
		if (i == n - 1) {
			dp[1][i][0] = 1;
			if (a[i] < k)dp[1][i][a[i]] = 1;
			continue;
		}
		rep(j, k) {
			if (j - a[i] >= 0)dp[1][i][j] |= (bool)dp[1][i + 1][j - a[i]];
			dp[1][i][j] |= (bool)dp[1][i + 1][j];
		}
	}
	rep(i, n) {
		rep(j, k) {
			if (j)dp[1][i][j] += dp[1][i][j - 1];
		}
	}
	int ans = 0;
	if (dp[1][1][k - 1] == dp[1][1][max((int)0, k - a[0] - 1)] && a[0] < k)ans++;
	for (int i = 1; i < n - 1; i++) {
		bool f = false;
		for (int j = 1; j < k; j++) {
			if (k - j - a[i] - 1 >= 0 && dp[0][i - 1][j - 1] != dp[0][i - 1][j] && dp[1][i + 1][max((int)0, k - j - a[i] - 1)] != dp[1][i + 1][k - j - 1])f = true;
			if (k - j - a[i] - 1 < 0 && dp[0][i - 1][j - 1] != dp[0][i - 1][j] && 0 != dp[1][i + 1][k - j - 1])f = true;
		}
		if (!f && a[i] < k)ans++;
	}
	if (dp[0][n - 2][k - 1] == dp[0][n - 2][max((int)0, k - a[n - 1] - 1)] && a[n - 1] < k)ans++;
	cout << ans << endl;
	return 0;
}

