int N, K, A[5005];

bool dp[5005][5005];

bool need(int t)
{
    CLR(dp);
    dp[0][0] = true;
    REPS(i, N)
    {
        int a = A[i - 1];
        FOR(j, 0, K)
        {
            if (i == t)
            {
                dp[i][j] = dp[i - 1][j];
            }
            else if (j - a < 0)
            {
                dp[i][j] = dp[i - 1][j];
                continue;
            }
            else
            {
                dp[i][j] = dp[i - 1][j - a] || dp[i - 1][j];
            }
            if (dp[i][j] && j >= K - A[t - 1] && j < K)
                return true;
        }
    }
    return false;
}

