    }
    sort(A, A + N);

    if (!need(N))
    {
        cout << N << endl;
        return 0;
    }

    int left = 0;
    int right = N;
    while (right - left > 1)
    {
        int mid = (left + right) / 2;
        if (need(mid))
        {
            right = mid;
        }
        else
        {
            left = mid;
        }
    }
    cout << left << endl;

    return 0;
}

