int main() {
	int n, k;
	std::cin >> n >> k;
	std::vector<int> a(n);
	for (int i = 0; i < n; i++) {
		std::cin >> a[i];
	}

	std::vector<std::vector<bool>> dpl(MAX_N, std::vector<bool>(MAX_K, false));
	std::vector<std::vector<bool>> dpr(MAX_N, std::vector<bool>(MAX_K, false));
	dpl[0][0] = true;
	dpr[n][0] = true;

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < MAX_K; j++) {
			if (dpl[i][j]) dpl[i + 1][j] = true;
			if (j + a[i] < MAX_K and dpl[i][j]) {
				dpl[i + 1][j + a[i]] = true;
			}
			if (dpr[n - i][j]) dpr[n - i - 1][j] = true;
			if (j + a[n - 1 - i] < MAX_K and dpr[n - i][j]) {
				dpr[n - i - 1][j + a[n - 1 - i]] = true;
			}
		}
	}

	std::vector<std::vector<int>> sl(MAX_N, std::vector<int>(MAX_K, 0));
	std::vector<std::vector<int>> sr(MAX_N, std::vector<int>(MAX_K, 0));
	for (int i = 0; i < MAX_N; i++) {
		for (int j = 0; j + 1 < MAX_K; j++) {
			sl[i][j + 1] = sl[i][j] + (dpl[i][j] == true);
			sr[i][j + 1] = sr[i][j] + (dpr[i][j] == true);
		}
	}

	int ans = n;
	for (int i = 0; i < n; i++) {
		bool need = false;
		for (int j = 0; j < k; j++) {
			int vl = std::max(0, k - a[i] - j), vr = k - j;
			if (dpl[i][j]) need |= (sr[i + 1][vr] - sr[i + 1][vl] > 0);
			if (dpr[i + 1][j]) need |= (sl[i][vr] - sl[i][vl] > 0);
		}
		if (need) ans--;
	}

	std::cout << ans << '\n';

	return 0;
}

