void sol(int l,int r,int now){
    if(l==r){
        int i;
        for(i=max(0,k-num[l]);i<k;i++)if(dp[now][i])break;
        if(i<k)ans++;
        return;
    }
    int i,j,mid=((l+r)>>1);
    for(i=0;i<k;i++)dp[now+1][i]=dp[now][i];
    for(j=l;j<=mid;j++){
        for(i=k-1; i>=num[j]; i--)dp[now+1][i]|=dp[now+1][i-num[j]];
    }
    sol(mid+1,r,now+1);
    for(i=0;i<k;i++) dp[now+1][i]=dp[now][i];
