    for (int i = 0; i < n; i++)
    {
        bitset<10001> m = pref[i];
        for (int u = 0; u < 2 * k; u++) if (suff[i + 1][u]) m |= m << u;
        if ((m & mask).count()) ans++;
    }
    cout << ans;
}

