void pre() {
  DP[0][0] = true;
  DQ[0][0] = true;
  for (int i = 0; i < n; ++i) {
    DP[i + 1] = DP[i] | (DP[i] << a[i]);
    DQ[i + 1] = DQ[i] | (DQ[i] << a[n - 1 - i]);
  }
}

bool no_need(int i) {
  bitset<5001> x = DP[i];
  bitset<5001> y = DQ[n - 1 - i];

  const int lo = max(0, k - a[i]);
  const int hi = k;

