				dp[i+1][j+v[i]] = true;
			}
		}
	}

	int res = 0;
	for(int i=0;i<n;i++)
	{
		bool ok = true;
		if(dp[n][k]==false)
		{
			res++;
		}
		else
		{
			for(int j=k;j<=2*k;j++)
			{
				if(dp[n][j]==true)
				{
					if(j-v[i]>=0 && dp[n][j-v[i]]==false)
					{
						ok = false;
						break;
					}
				}
			}
			if(ok)
			{
				res++;
			}
		}
	}

	cout << res << '\n';

	return 0;
}

