  cin.tie(0);
  ios_base::sync_with_stdio(false);
  cin >> N >> K;
  for(int i=1;i<=N;i++) cin >> a[i];
  if(N == 1){
    if(a[1] < K){
      cout << 1 << endl;
      return 0;
    }else{
      cout << 0 << endl;
      return 0;
    }
  }
  // binary_search
  ll left = 0, right = N;
  while(right - left > 1){
    ll mid = (left + right)/2;
    if(isneed(mid)){
      // midが条件を満たせば、解の存在範囲は(left, mid]
      right = mid;
    }else{
      // 解の存在範囲は(mid, right]
      left = mid;
    }
  }
  cout << right - 1 << endl;
}

