using ll  = long long;
using ull = unsigned long long;

int N, K;
ll A[5001];

bool dp[5001][5001]; // i枚目まで使ったとき総和をjにできるか

void solve()
{
    int cnt = 0;

    FOR(i, 0, N+1) {
        dp[i][0] = true;
    }
    FOR(j, 1, K+1) {
        dp[0][j] = false;
    }
    FOR(k, 1, N+1) {
        if(A[k] >= K) continue; // 集合 {k} が存在するためkは必要

        // 一時的にカードkを取り除く
        ll tmp = A[k];
        A[k] = 0;

        // DP
        FOR(i, 1, N+1) {
            FOR(j, 1, K) {
                // i枚目を使うか使わないかの2択
                // 使う場合、dp[i-1][j-A[i]]
                // 使わない場合、dp[i-1][j]
                // ただし j-A[i] < 0 ならば使えない
                if(j-A[i] < 0) {
                    dp[i][j] = dp[i-1][j];
                }
                else {
                    dp[i][j] = dp[i-1][j-A[i]] || dp[i-1][j];
                }
            }
        }
        // N枚目まで使って総和を [K-tmp, K-1] にできるならkは必要
        bool need = false;
        FOR(j, K-tmp, K) {
            if(dp[N][j]) need = true;
        }
        if(!need) ++cnt;

        // カードkを戻す
        A[k] = tmp;
    }

    cout << cnt << "\n";
}

int main()
{
    cin >> N >> K;
    FOR(i, 1, N+1) {
        cin >> A[i];
    }

    solve();

    return 0;
}

