int n, k, a[5050], check[5050], isin[5050];

void calc(int start, int i, int sum){
    if(i >= n) return;
    sum += a[i];
    if(sum >= k){
        for(int p=start;p<=i;++p){
            if(isin[p]) continue;
            if(sum - a[p] < k) {
                check[p] = 1;
            }
        }
    }
    isin[i] = 0;
    calc(start, i+1, sum);
    isin[i] = 1;
    calc(start, i+1, sum-a[i]);
}

