				for (int j = k - 1; j >= ar[i - 1]; j--) 
				{
					for (int kk = 0; kk < MDSZ; kk++)
					{
						dp[j][kk] += dp[j - ar[i - 1]][kk];
						dp[j][kk] %= MD[kk];
					}
				}
			}
		}
