      nxt = crr;
      for (int x = 0; x + a.at(i) <= k; x++) {
        nxt.at(x + a.at(i)) |= crr.at(x);
      }
    }
    return left;
  };
  auto left  = make_left(a);
  auto right = [&]{
    auto b = a;
    std::reverse(b.begin(), b.end());
    auto ret = make_left(b);
    std::reverse(ret.begin(), ret.end());
