bool check(int mid)
{
	if(arr[mid] >= k)
		return 0 ;
	memset(dp , -1 , sizeof(dp)) ;
	bitset<MAX>bit[1] ;
	bit[0][0] = 1 ;
	for(int i = 0 ; i < n ; ++i)
	{
		if(i == mid || arr[i] >= k)
			continue ;
		bit[0] |= (bit[0] << arr[i]) ;
	}
	for(int i = k-arr[mid] ; i < k ; ++i)
		if(bit[0][i])
			return 0 ;
	return 1 ;
}

