int N, K;
int a[MAX];

bool dfs(int cur_v, int cur_id, int target_id) {
    if (cur_id == N) {
        if (cur_v < K && cur_v + a[target_id] >= K) return true;
        else return false;  
    }
    if (cur_id == target_id) return dfs(cur_v, cur_id + 1, target_id);
    if (dfs(cur_v            , cur_id + 1, target_id)) return true;
    if (dfs(cur_v + a[cur_id], cur_id + 1, target_id)) return true;
    return false;
}

