int N,K;

bool ok(int mid,vector<ll> &a) {
  if(mid==N) return true;
  if(mid==-1) return false;
  vector<vector<bool>> dp(N+1,vector<bool>(K,false));
  dp[0][0] = true;
  rep(i,N) {
    rep(j,K) {
      if(i==mid) {
	dp[i+1][j] = dp[i][j];
	continue;
      }
      if(dp[i][j]) {
	dp[i+1][j] = true;
	if(j+a[i] < K) dp[i+1][j+a[i]] = true;
      }
    }
  }
  for(int i =max(0,(int)(K - a[mid])); i < K; i++) {
    if(dp[N][i]) return true;
  }
  return false;
}

