      REP(j,k) if (head[j] && sum(k-1-j) != sum(k-1-j-a[i])) {
        needed = true;
      }
      if (!needed) {
        // cout << "no-needs " << i << ' ' << a[i] << endl; 
        ++result;
      }
    }
