      if(i != mid && j + a[i] < k) dp[i+1][j+a[i]] = dp[i][j];
    }
  }
  bool need = false;
  for(ll i=max(0ll, k-a[mid]);i<k;++i) {
    need |= dp[n][i];
  }
  return !need;
}
