bool C(long i) {
    dp >>= 5005;
    dp[0] = true;

    for(int j = 0; j < N; ++j) {
        if(i == j) continue;
        for(int k = K; k >= a[j]; --k) {
            dp[k] = dp[k] | dp[k - a[j]];
        }
    }

    bool need = false;
    for(int k = K - a[i]; k < K; ++k) need |= dp[k];
    return need;
}

