		right(N + 10, cum_sum_lessmemory(K + 10));

	dpl = 1, dpr = 1;
	left[0].setup(dpl), right[0].setup(dpr);

	for (int i = 0; i < N; i++) {
		if (a[i] < K) {
			dpl |= (dpl << a[i]);
		}
		left[i + 1].setup(dpl);
	}
	for (int i = N; i > 0; i--) {
		dpr |= (dpr << a[i - 1]);
		right[i - 1].setup(dpr);
	}

	int ans = 0;
	for (int i = 0; i < N; i++) {
		//i番目を除外する
