        vector<bool> dp[2] = {vector<bool>(K, false), vector<bool>(K, false)};
        dp[0][0] = true;
        for (i64 i = 0; i < N; i++) {
            int b = i & 1;
            for (i64 s = 0; s < K; s++) {
                if(i != x && s - a[i] >= 0) {
                    dp[!b][s] = dp[b][s] | dp[b][s - a[i]];
                } else {
                    dp[!b][s] = dp[b][s];
                }
            }
        }
        bool retval = false;
        for(i64 s = max<i64>(0, K - a[x]); s < K; s++) {
            retval |= dp[N & 1][s];
        }
        return !retval;
    };
    int ans = BinSearch<int>(-1, a.size(), f, false);
    cout << ans + 1 << endl;
    return 0;
}

