const int MAX = 5010 ;

int dp[MAX][MAX] ;
int arr[MAX] ;
int n , k;
int idx2 ;

int solve(int idx , int sum)
{
	if(sum >= k)
		return 0 ;
	if(idx == n)
		return (sum < k && sum >= (k - arr[idx2])) ;
	int &ret = dp[idx][sum] ;
	if(ret != -1)
		return ret ;
	ret = 0 ;
	ret |= solve(idx+1 , sum) ;
	if(idx != idx2)
		ret |= solve(idx+1 , sum + arr[idx]) ;
	return ret ;
}

bool check(int mid)
{
	memset(dp , -1 , sizeof(dp)) ;
	idx2 = mid ;
	return (!solve(0 , 0)) ;
}

