    int cnt = 0;
    ll sum = 0;
    for(int i = 0; i < n; i++){
        if(!flag && a[i] < k){
            now = i;
            flag = true;
        }
        if(flag && a[i] + a[now] < k){
            sum += a[i];
            cnt++;
        }
    }
    if(!flag){
        cout << n << endl;
    }else{
        if(sum > k){
            cout << 0 << endl;
        }else{
            cout << cnt << endl;
        }
    }
    return 0;
}

