        tmp = a[i];
        if (s - tmp < k) {
          g[i] = g[i] || s >= k;
        } else {
          a[i] = 0;
          rec(a, k, s - tmp, g);
          a[i] = tmp;
        }
      }
    }
  }

  void solve(std::istream &in, std::ostream &out) {
    int n, k, res, sum = 0;
