int main()
{
	ll N, K;
	cin >> N >> K;
	vector<ll> a(N);
	REP(i, N) cin >> a[i];

	ll idx = 0;
	ll sum = 0;
	vector<pair<ll, ll>> area;
	REP(i, N) {
		sum += a[i];
		while (K <= sum) {
			area.emplace_back(make_pair(i, sum));
			sum -= a[idx];
			idx++;
		}
	}

	ll stPos = 0;
	ll ans = 0;
	for (ll i = 0; i < area.size(); i++) {
		auto &areaOne = area[i];
		for (; stPos <= areaOne.first; stPos++) {
			bool isOk = true;
			for (ll chkIdx = i; chkIdx <= stPos; chkIdx++) {
				ll diffSumOne = area[chkIdx].second - a[stPos];
				if (diffSumOne < K) {
					isOk = false;
					break;
				}
			}
			if (isOk) {
				ans++;
			}
		}
	}
	ans += (N - stPos);

	cout << ans << endl; 
	return 0;
}

