const int MAXN = 5010;
ll N, K;
int a[MAXN+1];

bool isneed(int p){
  if(p == 0) return false;
  if(K < a[p]){
    return true;
  }
  // i枚目まで使って総和をjにできるか
  bool dp[N+1][K+1];
  for(int i=0;i<=N;i++){
    for(int j=0;j<=K;j++){
      dp[i][j] = false;
    }
  }
  for(int i=0;i<=N;i++){
    dp[i][0] = true;
  }
  for(int i=1;i<=N;i++){
    if(i == p){
      for(int j=0;j<=K;j++) dp[i][j] = dp[i-1][j];
    }else{
      for(int j=0;j<=K;j++){
        if(j - a[i] < 0) dp[i][j] = dp[i-1][j];
        else dp[i][j] = (dp[i-1][j] || dp[i-1][j - a[i]]);
      }
    }
  }
  /*
  cout << p << endl;
  for(int i=1;i<=N-1;i++){
    for(int j=0;j<=K;j++){
      cout << dp[i][j] << " ";
    }
    cout << endl;
  }
  cout << endl;
  */
  for(int i=K-a[p];i<K;i++){
    if(dp[N][i]) return true;
  }
  return false;
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  cin >> N >> K;
  a[0] = 2000000000;
  for(int i=1;i<=N;i++) cin >> a[i];
  if(N == 1){
    if(a[1] < K){
      cout << 1 << endl;
      return 0;
    }else{
      cout << 0 << endl;
      return 0;
    }
  }
  sort(a, a+(N+1));
  // binary_search
  ll left = 0, right = N;
  while(right - left > 1){
    ll mid = (left + right)/2;
    if(isneed(mid)){
      // midが条件を満たせば、解の存在範囲は(left, mid]
      right = mid;
    }else{
      // 解の存在範囲は(mid, right]
      left = mid;
    }
  }
  cout << right-1 << endl;
}

