void fillTrueFrom(Mb& dp, int x, int y){
    for(int i = x; i < dp.size(); i++){
	dp[i][y] = true;
    }
}

bool isNotNeed(int n, int k, V& as, int i){
    V bs = as;
    bs.erase(bs.begin() + i);
    // cout << "bs:" << "\n";
    // for(auto b : bs)
    //     cout << b << " ";
    // cout << "\n\n";

    Mb dp(n, Vb());
    fillTrueFrom(dp, 0, 0);

    for(int x = 1; x < dp.size(); x++){
	int b = bs[x - 1];
	for(int y = b; y < k; y++){
	    if(dp[x - 1][y - b]){
		fillTrueFrom(dp, x, y);
	    }
	}
    }

    int a = as[i];
    bool need = false;
    for(int y = max(k - a, 0); y < k; y++){
	need |= dp[dp.size() - 1][y];
    }

    // for(auto d : dp){
    //     for(int i = 0; i < k; i++)
    // 	    cout << d[i] << " ";
    //     cout << "\n";
    // }
    // debug(need);
    // cout << "\n";

    return !need;

}

int solve(int n, int k, V& as){
    V is(n);
    iota(is.begin(), is.end(), 0);
    transform(is.begin(), is.end(), is.begin(), [&](int i){return isNotNeed(n, k, as, i);});
    return accumulate(is.begin(), is.end(), 0);
}

