  for(int i=1;i<=N-1;i++){
    for(int j=0;j<=K;j++){
      cout << dp[i][j] << " ";
    }
    cout << endl;
  }
  cout << endl;
  */
  for(int i=K-a[p];i<K;i++){
    if(dp[N][i]) return true;
  }
  return false;
}

