      return 0;
    }else{
      cout << 0 << endl;
      return 0;
    }
  }
  // binary_search
  ll left = 1, right = N;
  while(right - left > 1){
    ll mid = (left + right)/2;
    if(isneed(mid)){
      // midが条件を満たせば、解の存在範囲は(left, mid]
      right = mid;
