bool isNotNeed(int n, int k, V& as, int i){
    V bs = as;
    bs.erase(bs.begin() + i);
    // cout << "bs:" << "\n";
    // for(auto b : bs)
    //     cout << b << " ";
    // cout << "\n\n";

    Mb dp(n, Vb(k, false));
