	int b = bs[x - 1];
	for(int y = b; y < dp[x].size(); y++){
	    if(dp[x - 1][y - b]){
		fillTrueFrom(dp, x, y);
	    }
	}
    }

    int a = as[i];
    bool need = false;
    for(int y = max(k - a, 0); y < dp[dp.size() - 1].size(); y++){
	need |= dp[dp.size() - 1][y];
    }

