int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n,k;
  cin >> n >> k;

  vector <int>card(n);
  int sum = 0;
  REP(i,n){
    cin >> card[i];
    sum += card[i];
  }

  if(sum < k){
    cout << n << endl;
    return 0;
  }

  sort(card.begin(),card.end());

  //card[i]を除くk-card[i]以上の部分和の最小値がk以上のとき，card[i]は不要
  //DPを用いたO(n^3)解
  int ans = 0;
  REP(i,n){
    int dp[k+1] = {};
    bool flag = true;
    dp[0] = 1;
    RREP(j,n){
      if(j != i){
        for(int l = k+1; l >= 0; l--){
          if(dp[l] != 0 && l+card[j] <= k){
            dp[l+card[j]]++;
          }
        }
      }
    }
    int check = k - card[i];

 //   REP(i,k+1) cout << dp[i];
 //   cout << endl;
    while(flag && check < k){
      if(dp[check] > 0) flag = false;
      check++;
    }
    if(flag) ans++;
  }

  cout << ans << endl;

  return 0;
}

