using namespace std;

int main(){
  long long n,k;
  cin >> n >> k;
  vector<long long> a(n);
  for(int i = 0; i < n; i++){
    cin >> a[i];
  }
  sort(a.begin(), a.end(), greater<long long>());

  vector<bool> need(n, false);

  vector<long long> rev_sum(n, 0);
  rev_sum[n-1] = a[n-1];

  for(int i = n-2; i >= 0; i--){
    rev_sum[i] += a[i] + rev_sum[i+1];
  }

  bool fin = false;
  for(int p = 0; p < n; p++){
    if(rev_sum[p] < k) break;
    if(a[p] >= k){
      need[p] = true;
      continue;
    }
    long long sum = 0;
    for(int i = p; i < a.size(); i++){
      if(sum + rev_sum[i] < k){
        fin = true;
        break;
      }
      sum += a[i];
      if(sum >= k){
        sum -= a[i];
        while(i+1 < a.size() && a[i+1] == a[i]){
          i++;
        }
        for(int j = 0; j <= i; j++){
          need[j] = true;
        }
        // for(int j = 0; j < a.size(); j++){
        //   cout << a[j] << ",";
        // }
        // cout << endl;
      }
    }
    if(fin){
      break;
    }
  }

  int ans = 0;
  for(int i = 0; i < n; i++){
    if(!need[i]) ans++;
  }
  cout << ans << endl;
}

