#include <bits/stdc++.h>
using namespace std;

const int DIM = 5e3 + 5;

int arr[DIM], dp1[DIM][DIM], dp2[DIM][DIM];

int main( void ) {

    int n, k;
    cin >> n >> k;

    for( int i = 1; i <= n; i ++ )
        cin >> arr[i];

    dp1[0][0] = 1;
    for( int i = 1; i <= n; i ++ ) {
        for( int j = 0; j <= k; j ++ ) {
            dp1[i][j] = dp1[i - 1][j];

            if( j >= arr[i] )
                dp1[i][j] |= dp1[i - 1][j - arr[i]];
        }
    }

    dp2[n + 1][0] = 1;
    for( int i = n; i >= 1; i -- ) {
        for( int j = 0; j <= k; j ++ ) {
            dp2[i][j] = dp2[i + 1][j];

            if( j >= arr[i] )
                dp2[i][j] |= dp2[i + 1][j - arr[i]];
        }
    }

    int ans = n;
    for( int i = 1; i <= n; i ++ ) {
        for( int j = 1; j <= k; j ++ )
            dp2[i + 1][j] += dp2[i + 1][j - 1];

        for( int j = 0; j < k; j ++ ) {
            if( dp1[i - 1][j] == 0 )
                continue;

            int cnt = dp2[i + 1][k - j - 1];
            if( k - j - arr[i] >= 1 )
                cnt -= dp2[i + 1][k - j - arr[i] - 1];

            if( cnt != 0 ) {
                ans --;
                break;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

