vector<int> v,nes;
vector<vector<int>> dp;
void dfs(int cur, int mn){
    for(auto i: dp[cur]){
        if(i > mn)nes[i] = true;
        dfs(cur-i,mn);
    }
    dp[cur].resize(0);
}
signed main(){
    int n, k;
    cin >> n >> k;
    dp.resize(2*k+1);
    nes.resize(k);
    dp[0].pb(0);
    for(int i = 0; i < n; i++){
        int x;
        cin >> x;
        v.pb(x);
    }
    sort(all(v));
    for(auto x: v){
        if(x >= k)break;
        for(int i = k; i >= 0; i--){
            if(dp[i].size() && !(dp[i+x].size() && dp[i+x].back()==x))dp[i+x].pb(x);
        }
    }
    dp[0].resize(0);
    for(int i = 0; i <= k; i++)dfs(i+k,i);
    int ans = n;
    for(auto x: v){
        if(x >= k || nes[x])ans--;
    }
    cout << ans << endl;
}

