using namespace std;

int main()
{
  int N,K;
  cin >> N >> K;
  vector<long long int>A(N);
  for(int i=0; i < N; i++)
    cin >> A[i];
  vector<vector<bool> >dp(N,vector<bool>(K));
  int ans = 0;
  for(int i=0; i < N; i++){

    long long int ai = A[i];
    A[i] = 0;

    for(int y=0; y < K; y++){
      if(A[0]==y)
	dp[0][y] = true;
      else
        dp[0][y] = false;
    }
    for(int x=0; x < N; x++){
      dp[x][0] = true;
    }

    for(int x=1; x < N; x++){
      for(int y=1; y < K; y++){
	if(y-A[x] >= 0 && y-A[x] < K){
	  if(dp[x-1][y-A[x]] == true) dp[x][y] = true;
	  else dp[x][y] = false;
	}else if(y < A[x]){
	  if(dp[x-1][y] == true) dp[x][y] = true;
	  else dp[x][y] = false;
	}else if(y-A[x] >= K){
	  dp[x][y] = false;
	}
      }
    }
    bool need = false;
    for(int a=K-ai; a < K; a++){
      if(a >= 0 && a < K){
        if(dp[N-1][a] == true){
          need = true;
          break;
        }
      }
    }
    if(need == false) ans++;
    A[i] = ai;
   }
  cout << ans << endl;

  return 0;
}

