void solve(long long N, long long K, std::vector<long long> a)
{
  vector<lli> b;
  rep(i, N) if (a[i] < K) b.push_back(a[i]);
  sort(b.begin(), b.end());
  lli up = b.size(), low = -1;
  // up is need, low is no need
  N = b.size();
  while (up - low > 1)
  {
    lli mid = (up + low) / 2;
    rep(i, N + 1) dp[i]
        .assign(K, 0);
    dp[0][0] = true;
    rep(i, N)
    {
      rep(j, K)
      {
        dp[i + 1][j] |= dp[i][j];
        if (mid != i && j + b[i] < K)
        {
          dp[i + 1][j + b[i]] |= dp[i][j];
        }
      }
    }
    bool ok = false;
    rrep(i, K)
    {
      if (dp[N][i])
      {
        if (i + b[mid] >= K)
          ok = true;
        break;
      }
    }
    (ok ? up : low) = mid;
  }
  cout << low + 1 << endl;
}

