int main(){
	scanf("%d%d", &n, &k);
	int tot = 0;
	sum = 0;
	for(int i = 1; i <= n; i++) scanf("%d", &a[i]);
	sort(a + 1, a + n + 1);
	for(int i = 1; i <= n; i++){
		if(sum < k){
			sum += a[i];
		}
		if(sum >= k){
			tot = i;
			break;
		}
	}
	if(tot == 1){
		printf("0\n");
		return 0;
	}
	else if(tot == 0){
		printf("%d\n", n);
		return 0;
	}
	else{
		for(int i = 1; i <= tot; i++){
			ans++;
			sum -= a[i];
			if(sum < k) break;
		}
		ans--;
		for(int i = ans - 1; i <= n; i++){
			int ant = a[i];
			int pp;
			for(int j = 1; j < ans - 1; j++){
				ant += a[j];
				if(ant >= k){
					pp = j;
					for(int k = 1; k <= ans - 1; k++){
						ant -= a[i];
						if(ant < k) ans = min(ans, k - 1);
					}
				}
			}
		}
		printf("%d\n", ans);
		return 0;
	}
}

