bool dp[5001];

void solve() {
  i64 N, K; cin >> N >> K;
  vi64 A(N); cin >> A;
  sort(all(A));
  int ok = N, ng = -1;
  while (ok - ng > 1) {
    int i = (ng + ok) / 2;
    if (K <= A[i]) { ok = i; continue; }
    rep(k, K) dp[k] = false;
    dp[0] = true;
    rep(j, N) {
      if (i == j) continue;
      rrep(k, K) {
        if (dp[k]) {
          if (k + A[j] < K) dp[k + A[j]] = true;
        }
      }
    }
    bool f = false;
    for (int j = K - A[i]; j < K; j++) if (dp[j]) f = true;
    if (f) ok = i; else ng = i;
  }
  cout << ok << '\n';
}

