int main() {
  int64_t n, k;
  std::cin >> n >> k;
  std::vector<int64_t> a(n);
  std::cin >> a;
  std::sort(a.begin(), a.end());

  int64_t m = 0;

  for (auto itr = a.cbegin(); itr != a.cend(); itr++) {
    if (k <= *itr) {
      break;
    }
    std::set<int64_t> num;
    num.insert(0);
    bool flag = false;
    std::vector<bool> cache(k, false);
    for (auto j = a.cbegin(); j != a.cend() && !flag; j++) {
      if (k <= *j) {
        break;
      } else if (j != itr) {
        std::set<int64_t> tmp;
        for (const auto i : num) {
          if (i + *j < k) {
            if (k <= i + *j + *itr) {
              flag = true;
              break;
            }
          if (!cache[i + *j]) {
              cache[i + *j] = true;
              tmp.insert(i + *j);
          }
          } else {
            break;
          }
        }
        if (!flag) {
          num.insert(tmp.begin(), tmp.end());
        }
      }
    }
    if (!flag) {
      m++;
    }
  }

  std::cout << m << std::endl;
  return 0;
}

