    ios::sync_with_stdio(false);

    int N, K; cin >> N >> K;
    vector<int> a(1, 0);
    rep(i, N){
        int v; cin >> v;
        if(v < K) a.push_back(v);
    }
    N = a.size() - 1;
    sort(a.begin(), a.end());

    vector<vector<bool>> dpl(N+5, vector<bool>(K+5, false));
    vector<vector<bool>> dpr(N+5, vector<bool>(K+5, false));

    dpl[0][0] = true;
    repr(i, 1, N+1) rep(j, K+1) {
        // not use
        dpl[i][j] = (dpl[i][j] || dpl[i-1][j]);
        // use
        if(j-a[i]>=0) dpl[i][j] = (dpl[i][j] || dpl[i-1][j-a[i]]);
    }

    dpr[N+1][0] = true;
    reprrev(i, 1, N+1) rep(j, K+1) {
        // not use
        dpr[i][j] = (dpr[i][j] || dpr[i+1][j]);
        // use
        if(j-a[i]>=0) dpr[i][j] = (dpr[i][j] || dpr[i+1][j-a[i]]);
    }

    int ans = 0;
    repr(i, 1, N+1) {
        vector<int> L, R;
        rep(j, K){
            if(dpl[i-1][j]) L.push_back(j);
            if(dpr[i+1][j]) R.push_back(j);
        }
        bool noNeed = true;
        // l <= q < r を満たす q があるかだとどちらも lower_bound でできるので変形してから
        for(auto p : L) if(lower_bound(R.begin(), R.end(), K-p+1) - lower_bound(R.begin(), R.end(), K-a[i]-p+1) > 0) {
            noNeed = false;
            break;
        }
        if(noNeed) ++ans;
    }
    cout << ans << endl;


    return 0;
}

