bool check(int target, int k, const vector<int> &a) {
    int n = a.size();

    fill((int *)dp, (int *)(dp + n + 1), 0);

    dp[0][0] = 1;
    for (int i : rep(0, n)) {
        for (int j : rep(0, k + 1)) {
            dp[i + 1][j] |= dp[i][j];
            if (i != target && j + a[i] <= k) {
                dp[i + 1][j + a[i]] |= dp[i][j];
            }
        }
    }

    bool f = false;

    for (int i : rep(k - a[target], k)) {
        f |= dp[n][i];
    }

    return f;
}

