void fillTrueFrom(Mb& dp, int x, int y){
    for(int i = x; i < dp.size(); i++){
	dp[i][y] = true;
    }
}

bool isNotNeed(int n, int k, V& as, int i){
    int a = as[i];
    if(a >= k){
	return false;
    }

    Mb dp(n + 1, Vb());
    fillTrueFrom(dp, 0, 0);

    for(int x = 1; x < dp.size(); x++){
	int b = as[x - 1];
	if(b >= k){
	    break;
	}
	if(x - 1 == i){
	    continue;
	}
	for(int y = b; y < k; y++){
	    if(dp[x - 1][y - b]){
		fillTrueFrom(dp, x, y);
	    }
	}
    }

    // for(auto d : dp){
    //     for(int i = 0; i < k; i++)
    // 	    cout << d[i] << " ";
    //     cout << "\n";
    // }
    // debug(dp[dp.size() - 1].none());
    // cout << "\n";

    for(int y = max(k - a, 0); y < k; y++){
    	if(dp[dp.size() - 1][y]){
	    return false;
	}
    }
    return true;
}

int solve(int n, int k, V& as){
    sort(begin(as), end(as));
    int l = 0, u = n;
    while(l != u){
	int c = (l + u) / 2;
	if(isNotNeed(n, k, as, c)){
	    l = c + 1;
	}else{
	    u = c;
	}
    }
    return l;
