const int MAX_N = 5010;
int dp[MAX_N][MAX_N];
set<int> tabooo;
int src;
int memo(int pos, int val){
  if (val >= K - A[src] and val < K){
    return 1;
  }

  if (pos == N){
    return 0;
  }
  int &res = dp[pos][val];
  if (res >= 0){
    return res;
  }
  res = 0;
  res |= memo(pos + 1, val);
  if (tabooo.count(pos) == 0){
    res |= memo(pos + 1, min(K, val + A[pos]));

  }

  return res;
}


int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> N >> K;

  A.resize(N);
  for (auto &val : A){
    cin >> val;
