    }

    src = med;
    memset(dp, -1, sizeof(dp));
    tabooo[med] = true;
    int res = memo(max(0, left), 0);
    tabooo[med] = false;
    if (res > 0){//necessary
      right = med;
    }else{//unnecessary
      left = med;
