int main() {    
	int n, k;
	cin >> n >> k;
	vector<int> a(n, 0);
	for(int i=0; i<n; i++) {
		cin >> a[i];
	}

	int l = 0, r = n;
	while(l < r) {
		int removed = (l + r) / 2;
		vector<vector<int>> dp(n+1, vector<int>(k+1, false));
		dp[0][0] = true;
		for(int i=0; i<n; i++) {
			int ca = a[i];
			for(int j=0; j<=k; j++) {
				dp[i+1][j] = dp[i+1][j] || dp[i][j];
				if(i != removed) {
					dp[i+1][min(k, j+ca)] = dp[i+1][min(k, j+ca)] || dp[i][j];
				}
			}
		}
		bool is_needed = false;
		for(int i=max(0, k-a[removed]); i<k; i++) {
			if(dp[n][i]) {
				is_needed = true;
			}
		}
		if(!is_needed) {
			l = removed + 1;
		} else {
			r = removed;
		}
	}
	cout << l << endl;
	return 0;    
}    

