    // [lb, ub)
    ll ub = a.size();
    ll lb = 0;
    while (ub - lb > 1) {
        ll mid = lb + (ub - lb) / 2;
        if (solve(a.size(), k, a, mid)) {
            lb = mid;
        } else {
            ub = mid;
        }
    }

    cout << (lb + 1) << endl;

    return 0;
}

