    sort(card.rbegin(), card.rend());

    int needMax = 0;
    for (int start = 0; start < card.size(); ++start) {
        ll sum = 0;
        int len = start;
        for (int j = start; j < card.size(); ++j) {
            sum += card[j];
            len++;
            if (sum >= K) {
                needMax = max(needMax, len);
                sum -= card[j];
            }
        }
    }

    cout << N - needMax << endl;

    return 0;
}

