bool solve(int x){

	memset(dp, false, sizeof(dp));
	dp[0][0] = true;
	rep (j, N){
		rep (k, K){
			if (dp[j][k]){
				dp[j+1][k] |= true;
				if (x != j && k + a[j] < K) dp[j + 1][k + a[j]] |= true;
			} // end if
		} // end rep
	} // end rep

	rep (k, K){
		if (dp[N][k] && k + a[x] >= K){	
			return true;
		} // end if
	} // end for

	return false;
}

