int main() {

    cin >> n >> k;

    for(int i=0; i<n; i++){
        cin >> a[i];
    }

    sort(a,a+n);

    int left = 0,right = n;

    while(left + 1 != right){

        int middle = (left + right)/2;

        for(int r=0; r<=n; r++){
            for(int w=0; w<=k; w++){
                dp[r][w] = false;
            }
        }

        dp[0][0] = true;

        for(int j=1; j<=n; j++){
            for(int t=0; t<k; t++){
                if(dp[j-1][t]){
                    dp[j][t] = true;
                }
                else if(middle+1 != j && a[j-1] < k && t-a[j-1] >= 0){
                    if(dp[j-1][t-a[j-1]]) {
                        dp[j][t] = true;
                    }
                }
            }
        }

        bool need = false;

        if(k>a[middle]) {
            for (int j = k - a[middle]; j < k; j++) {
                if (dp[n][j]) {
                    need = true;
                    break;
                }
            }
        }
        else{
            need = true;
        }

        if(need){
            right = middle;
        }
        else{
            left = middle;
        }
    }

    cout << right << endl;

    return 0;
}

