vb2 block;

void solve(){
    read_vector(n, as);

    vb3 dp(2, vb2(n + 1, vb(k, false)));
    rep(i1, n + 1) dp[0][i1][0] = dp[1][i1][0] = true;

    For(i1, 1, n + 1){
        ll v0 = as[i1 - 1], v1 = as[n - i1];
        For(i2, 1, k){
            dp[0][i1][i2] = dp[0][i1 - 1][i2];
            dp[1][i1][i2] = dp[1][i1 - 1][i2];

            if (i2 - v0 >= 0 && !dp[0][i1][i2])
                dp[0][i1][i2] = dp[0][i1 - 1][i2 - v0];
            if (i2 - v1 >= 0 && !dp[1][i1][i2])
                dp[1][i1][i2] = dp[1][i1 - 1][i2 - v1];
            // prl4(i1, i2, dp[0][i1][i2], dp[1][i1][i2]);
        }
    }

    For(i1, 1, n + 1){
        ll v = as[i1 - 1];
        okay = false;
        if (v >= k) continue;
        For(i2, k - v, k){
            if (okay) break;
            rep(i3, i2 + 1){
                if (dp[0][i1 - 1][i3] && dp[1][n - i1][i2 - i3])
                    okay = true;
            }
        }
        if (!okay) answer++;
    }

    prl(answer);
}

