static constexpr int P = 988'244'353;
void solve(std::istream &in, std::ostream &out) {
  int n, k;
  in >> n >> k;
  vector<int> a(n);
  for (int &i : a) {
    in >> i;
  }
  int count = 0;
  vector<vector<int>> can_suff(n+1, vector<int>(k+1,0));
  vector<vector<int>> sum_suff(n+1, vector<int>(k+2,0));
  sum_suff[n] = vector<int>(k+2,1);
  can_suff[n][0] = 1;
  for (int i = n - 1; i >= 0; --i) {
    can_suff[i] = can_suff[i + 1];
    if (a[i] < k) {
      for (int w = k; w >= 0; --w) {
        can_suff[i][min(k, w + a[i])] |= can_suff[i][w];
      }
    }
    for (int w = 0; w <= k; ++w) {
      sum_suff[i][w + 1] = sum_suff[i][w] + can_suff[i][w];
    }
  }
  vector<int> can(k + 1, 0);
  can[0] = 1;
  for (int i = 0; i < n; ++i) {
    if (a[i] >= k) continue;
    bool found = false;
    int L = k - a[i], R = k; // [L, R)
    for (int j = L; j < R && !found; ++j) {
      if (can[j]) {
        found = true;
      }
    }
    for (int sum = 0; sum < L && !found; ++sum) {
      if (!can[sum]) continue;
      int ll = L - sum, rr = R - sum;
      if (sum_suff[i + 1][rr] - sum_suff[i + 1][ll] > 0) {
        found = true;
      }
    }
    for (int w = k; w >= 0; --w) {
      can[min(k, w + a[i])] |= can[w];
    }
    count += !found;
  }
  out << count;
}

