  for (int i = 1; i <= N; ++i)
  {
    for (int j = 0; j < K; ++j)
    {
      if (!dp[i-1][j]) continue;

      dp[i][j] = true;
      if(i != x) dp[i][min(j + A[i], K)] = true;

      if (j >= K - A[x]
      || (j + A[i] >= K - A[x] && j + A[i] < K))
        return true;
    }
    DUMPV(dp[i], K);
  }
  return false;
}

