    dp[0][0] = true;
    for(int i=1;i<=n;i++){
        for(int j=0;j<=k;j++){
            dp[i][j] = dp[i-1][j];
            if(i!=x && j-a[i] >= 0) dp[i][j] = dp[i][j] | dp[i-1][j-a[i]];
        }
    }
    int lef = max(k-a[x],0);
    for(int i=lef;i<k;i++) if(dp[n][i]) return true;
    return false;

}
int bins(){
    int l = 0;
    int r = n+1;
    int res = n+1;
    while(l<=r){
        int mid = (l+r)>>1;
        if(necessary(mid)) {res=mid; r = mid-1;}
        else l = mid+1;
    }
    return res-1;
}
