	ll N, K; cin >> N >> K;
	V<ll> a(N); REP(i, N) cin >> a[i];
	sort(ALL(a));
	int ok = N, ng = 0, md;
	while(ok-ng>1){
		md = (ok + ng) / 2;

		if(a[md]>=K){
			ok = md;
			continue;
		}

		V<ll> b(N,0);
		int idx = 1;
		REP(i, N) if (i != md) b[idx++] = a[i];

		V<V<int>> dp(N, V<int>(K + 1, 0));
		dp[0][0] = 1;
		FOR(i,1,N){
			REP(j,K+1){
				dp[i][j] = max(dp[i][j], dp[i - 1][j]);
				dp[i][min(j+b[i],K)] = max(dp[i][min(j + b[i], K)], dp[i - 1][j]);
			}
		}
		bool flg = false;
		FOR(j, K - a[md], K) if (dp[N-1][j]) flg = true;
		((flg) ? ok : ng) = md;
	}
	cout << ok << endl;
	cin >> N;

	return 0;
}

