#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)

const int N_MAX = 5000;

int N, K;
int a[N_MAX];

void solve() {
  sort(a, a + N, greater<int>());
  int ans = N;
  int sum = 0;
  int need = 0;
  int skip = 0;
  REP(i, N) {
    if (a[i] == skip) {
      ans--;
      continue;
    }
    sum += a[i];
    need++;
    if (sum >= K) {
      ans -= need;
      sum = 0;
      need = 0;
      skip = a[i];
    }
  }
  printf("%d\n", ans);
}

void input() {
  scanf("%d%d", &N, &K);
  REP(i, N) scanf("%d", a + i);
}

int main() {
  input();
  solve();
  return 0;
}

