struct cum_sum {
	vector<ll> ar;
	vector<ll> sum;
	int N;
	cum_sum() = default;
	cum_sum(int _N) {
		N = _N;
		ar.resize(N), sum.resize(N + 1);
	}
	cum_sum(vector<ll>& _ar) {
		ar = _ar;
	}

	ll& operator[](int _idx) {
		return ar[_idx];
	}

	void setup() {
		for (int i = 0; i < N; i++) {
			sum[i + 1] = sum[i] + ar[i];
		}
	}
	ll getval(int l, int r) {
		//[l, r)
		ll ret = sum[r] - sum[l];
		return ret;
	}
};

int N, K;
vector<ll> a;
bitset<5000 + 10> dpl, dpr;//0-idx

int main() {
	cin >> N >> K;
	a.resize(N);
	for (int i = 0; i < N; i++)cin >> a[i];

	vector<cum_sum> left(N + 10, cum_sum(K + 10)), right(N + 10, cum_sum(K + 10));

	dpl = 1, dpr = 1;
	left[0][0] = 1, right[N][0] = 1;
	left[0].setup(), right[0].setup();

	for (int i = 0; i < N; i++) {
		dpl |= (dpl << a[i]);
		for (int j = 0; j < K; j++) left[i + 1][j] = dpl[j];
		left[i + 1].setup();
	}
	for (int i = N; i > 0; i--) {
		dpr |= (dpr << a[i - 1]);
		for (int j = 0; j <= K; j++) right[i - 1][j] = dpr[j];
		right[i - 1].setup();
	}

	int ans = 0;
	for (int i = 0; i < N; i++) {
		//i番目を除外する
		if (a[i] >= K)continue;
		bool f = true;
		for (int j = 0; j < K; j++) {
			if (left[i].getval(j, j + 1) == 0)continue;
			if (j >= K - a[i]) {
				f = false;
				break;
			}
			if (right[N - i].getval(K - a[i] - j, K - j)) {
				f = false;
				break;
			}
		}
		if (f)ans++;
	}
	cout << ans << endl;
	return 0;
}

