bool is_needed(int ind, int K, int N){
    //cout << ind << endl;
    if(K <= a[ind]){
        return true;
    }
    for(int i = 0; i < N; i++){
        for(int j = 0; j <= K; j++){
            dp[i][j] = false;
        }
    }
    if(ind != 0){
        dp[0][0] = true;
        dp[0][a[0]] = true;
    } else {
        dp[1][0] = true;
        dp[1][a[1]] = true;
    }
    for(int i = 1; i < N; i++){
        if(i == ind){
            for(int j = 0; j <= K; j++){
                dp[i][j] = dp[i - 1][j];
            }
            continue;
        }
        for(int j = 0; j <= K; j++){
            dp[i][j] |= dp[i - 1][j];
            if(j + a[i] < K){
                dp[i][j + a[i]] |= dp[i - 1][j];
            } else {
                dp[i][K] |= dp[i - 1][j];
            }
        }
    }
    /*
    for(int i = 0; i < N; i++){
        for(int j = 0; j <= K; j++){
            cout << dp[i][j] << " ";
        }
        cout << endl;
    }
    */
    for(int i = K - a[ind]; i < K; i++){
        if(dp[N - 1][i]){
            return true;
        }
    }
    return false;
}

