int search(vector<int>& a,vector<int>& b,int K,int i,int sum){
	sum += a[i];
	if (sum >= K){
		b[i] = 1;
		return sum;
	}
	int max = 0;
	for (int j = i - 1; j >=0; j--){
		int sum2=search(a, b, K, j, sum);
		if (sum2 >= K){
			b[i] = 1;
		}
		if (sum2 > max){
			max = sum2;
		}
	}
	return max;
}

