					if ((DPL[l] >= 0) && (DPL[l] < j) && (l + A[idx] <= k)) {
						DPL[l + A[idx]] = j;
					}
				}
			}
			// Right
			idx = i + j;
			if (idx < n) {
				for (int l = 0; l <= k; ++l) {
					if ((DPL[l] >= 0) && (DPL[l] < j) && (l + A[idx] <= k)) {
						DPR[l + A[idx]] = j;
					}
				}
			}
		}
		bool flag = false;
		for (int v = k - A[i]; v < k; ++v) {
			for (int l = 0; l <= v; ++l) {
				if ((DPL[l] >= 0) && (DPR[v - l] >= 0)) {
					flag = true;
					break;
				}
			}
		}
		if (flag == false) {
			++count;
		}
	}
	printf("%d", count);
	return 0;
}

