bool isNotNeed(int n, int k, V& as, int i){
    V bs = as;
    bs.erase(bs.begin() + i);
    // cout << "bs:" << "\n";
    // for(auto b : bs)
    //     cout << b << " ";
    // cout << "\n\n";

    Mb dp(n, Vb());
    fillTrueFrom(dp, 0, 0);

    for(int x = 1; x < dp.size(); x++){
	int b = bs[x - 1];
	for(int y = b; y < k; y++){
	    if(dp[x - 1][y - b]){
		fillTrueFrom(dp, x, y);
	    }
	}
    }

    // for(auto d : dp){
    //     for(int i = 0; i < k; i++)
    // 	    cout << d[i] << " ";
    //     cout << "\n";
    // }
    // debug(dp[dp.size() - 1].none());
    // cout << "\n";

    int a = as[i];
    for(int y = max(k - a, 0); y < k; y++){
    	if(dp[dp.size() - 1][y]){
	    return false;
	}
    }
    return true;
}

int solve(int n, int k, V& as){
    V is(n);
    iota(begin(is), end(is), 0);
    transform(begin(is), end(is), begin(is), [&](int i){return isNotNeed(n, k, as, i);});
    return accumulate(begin(is), end(is), 0);
}

