        lint Kp_min = K - a[mid];
        lint Kp_max = K;

        vector<lint> ap = a;
        ap.erase(ap.begin() + mid);

        vector<vector<bool>> can(N, vector<bool>(K + 1, false));
        can[0][0] = true;
        for (int j = 1; j <= N - 1; j++) {
            for (int k = 0; k <= K; k++) {
                if (can[j - 1][k] == true) {
                    can[j][k] = true;
                }
                if (k - ap[j - 1] >= 0 and can[j - 1][k - ap[j - 1]] == true) {
                    can[j][k] = true;
                }
            }
        }

        bool need = false;
        for (int j = Kp_min; j < Kp_max; j++) {
            if (can[N - 1][j] == true) {
                need = true;
                break;
            }
        }

        if (need == true) {
            ub = mid;
        } else {
            lb = mid;
        }
    }

    cout << lb + 1 << endl;
    return 0;
}

