  for (int i = 0; i < n; ++i) {
    for (int j = 0; j <= k; ++j) {
      if (dp1[i][j]) dp1[i + 1][j] = 1;
      if (j + a[i] > 5010) continue;
      dp1[i + 1][j + a[i]] |= dp1[i][j];
    }
  }

  dp2[0][0] = 1;

  for (int i = 0; i < n; ++i) {
    for (int j = 0; j <= k; ++j) {
      if(dp2[i][j]) dp2[i + 1][j] = 1;
      if (j + a[n - 1 - i] > 5010) continue;
      dp2[i + 1][j + a[n - 1 - i]] |= dp2[i][j];
    }
  }
