inline T read()
{
	T x = 0, w = 1; char c = getchar();
	while(c < '0' || c > '9') { if(c == '-') w = -1; c = getchar(); }
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x * w; 
}

bool check(int mid)
{
	if(a[mid] >= k) return 0; 
	sum.reset(), sum[0] = 1;
	for(int i = 1; i <= n; i++) if(i != mid && a[i] < k) sum |= sum << a[i];
