struct mint {
  ll x;  // typedef long long ll;
  mint(ll x = 0) : x((x % mod + mod) % mod) {}
  mint operator-() const { return mint(-x); }
  mint &operator+=(const mint a) {
    if ((x += a.x) >= mod) x -= mod;
    return *this;
  }
  mint &operator-=(const mint a) {
    if ((x += mod - a.x) >= mod) x -= mod;
    return *this;
  }
  mint &operator*=(const mint a) {
    (x *= a.x) %= mod;
    return *this;
  }
  mint operator+(const mint a) const { return mint(*this) += a; }
  mint operator-(const mint a) const { return mint(*this) -= a; }
  mint operator*(const mint a) const { return mint(*this) *= a; }
  mint pow(ll t) const {
    if (!t) return 1;
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const { return pow(mod - 2); }
  mint &operator/=(const mint a) { return *this *= a.inv(); }
  mint operator/(const mint a) const { return mint(*this) /= a; }
};
istream &operator>>(istream &is, mint &a) { return is >> a.x; }
ostream &operator<<(ostream &os, const mint &a) { return os << a.x; }

class modutils {
  vector<mint> fact, invfact;

 public:
  modutils(int n = 200005) : fact(n + 1), invfact(n + 1) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
    invfact[n] = fact[n].inv();
    for (int i = n; i >= 1; i--) invfact[i - 1] = invfact[i] * i;
  }
  mint pow(mint x, ll n) { return x.pow(n); }
  mint comb(ll n, ll k) {
    if (n < 0 || k < 0 || n < k) return 0;
    return fact[n] * invfact[k] * invfact[n - k];
  }
  mint perm(ll n, ll k) {
    if (n < 0 || k < 0 || n < k) return 0;
    return fact[n] * invfact[n - k];
  }
  mint fac(ll n) { return fact[n]; }
};

int dp[5001][5001];
int rdp[5001][5001];

int main() {
  //ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
  cout << fixed << setprecision(15);

  ll n, k;
  cin >> n >> k;

  vll as(n);
  rep(i, n) cin >> as[i];

  if(n == 1){
    cout << (as[0] >= k) << endl;
    return 0;
  }

  rep(i, n){
    dp[0][0] = 1;
    rdp[0][0] = 1;
    rep(j, 5001) {
      dp[i+1][j] += dp[i][j];
      dp[i+1][min(5000LL, j + as[i])] += dp[i][j];
      rdp[i+1][j] += rdp[i][j];
      rdp[i+1][min(5000LL, j + as[n-1-i])] += rdp[i][j];
    }
  }

  ll ans = 0;
  rep(i, n){
    vll csum(5002, 0);
    rep(j, 5001) csum[j+1] += csum[j] + rdp[n-1-i][j];
    rep(j, 4999) {
      if(dp[i][j] < k && dp[i][j] + as[i] >= k) {
        ans++;
        break;
      }
      int key = dp[i][j] + as[i];
      if((csum[k+1] - csum[k - key]) > 0){
        ans++;
        break;
      }
    }
  }

  cout << n - ans << endl;

  return 0;
}

