int n, k, a[N], dp[N][N], temp;

int solve(int i, int sum){
    if(i == n)  return (sum >= k - temp);

    int &ret = dp[i][sum];
    if(~ret)    return ret;

    ret = 0;
    if(sum + a[i] < k)  ret = solve(i + 1, sum + a[i]);
    return ret |= solve(i + 1, sum);
}

