    for (int i = 0; i < n; i++)
        pref[i + 1] = pref[i] | (pref[i] << a[i]);
    suff[n][0] = 1;
    for (int i = n - 1; i >= 0; i--)
        suff[i] = suff[i + 1] | (suff[i + 1] << a[i]);
