#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define DUMP(a, n) REP(i, n) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ')

const int N_MAX = 5000;
const int K_MAX = 5000;

int N, K;
int a[N_MAX];

bool dp[K_MAX];

void solve() {
  int ans = N;
  // sort(a, a + N, greater<int>());
  REP(k, N) {
    if (a[k] >= K) {
      ans--;
      continue;
    }
    fill(dp, dp + K, false);
    dp[0] = true;
    REP(i, N) {
      if (i == k) continue;
      for (int j = K - 1; j >= a[i]; j--) {
        dp[j] |= dp[j - a[i]];
      }
    }
    FOR(j, K - a[k], K - 1) {
      if (dp[j]) {
        ans --;
        break;
      }
    }
  }
  printf("%d\n", ans);
}

