        for (auto num : ms) {
            if (num == a[i] && flg) {
                flg = false;
                continue;
            }
            bs = bs | (bs << num);
            bs[num] = 1;
            auto brk = false;
            for (auto l = k - a[i]; l < k; l++) {
                if (bs[l]) {
                    ret--;
                    m[a[i]] = false;
                    brk = true;
                    break;
                }
            }
            if (brk) break;
        }       
    }

    std::cout << ret << std::endl;

    return 0;
}

