  nex[0] = 1;
  rep(i,n){
    rep(k,K+1) {
      if(!dp1[k]) continue;
      // i を使用する
      nex[min(K, k+a[i])] = 1;
    }
    rep(k,K){
      dp1[k] = nex[k];
      s1[i+1][k+1] = s1[i+1][k] + dp1[k];
    }
  }

  dp2[0] = 1; s2[n][0] = 1;
  nex2[0] = 1;
  rrep(i,n){
    rep(k,K+1) {
      if(!dp2[k]) continue;
