        for (int j = 0; j <= K; j++) {
            if (!dp1[i-1][j]) continue;
            auto it = s.lower_bound(K-j-a[i]);
            if (it != s.end() && (*it) < K-j) {
                check = false;
                break;
            }
        }
        if (check) ans++;
        vector<int> nxt;
        auto it2 = s.begin();
        while (it2 != s.end()){
            nxt.push_back(min(K, (*it2)+a[i]));
            it2++;
        }
        for (int n : nxt) s.insert(n);
    }
    cout << ans << endl;
    return 0;
}

