    for (auto i = 0; i < N; i++) {
        if (i == m) continue;
        for (auto j = K-a[i]-1; j >= 0; j--) {
            if (!dp[j]) continue;
            if (K-a[m] <= j+a[i]) {
                return true;
            }
            dp[j+a[i]] = true;
        }
    }
    return false;
}

