bool judge(ll piv)
{
  ll target = A[piv];

  REP(i, 5001)
  {
    dp[i] = 0;
    dpNew[i] = 0;
  }
  dp[0] = 1;

  REP(i, piv)
  {

    REP(j, 5001)
    {
      ll x = A[i];
      if (j - x >= 0)
        dpNew[j] = dp[j - x];
    }
    REP(j, 5001)
    {
      dp[j] |= dpNew[j];
      dpNew[j] = 0;
    }
  }
  bool f = false;

  REP(i, k)
  {
    OUT2(i, dp[i]);
  }

  for (ll i = k - target; i < k; i++)
  {
    if (dp[i] == 1)
    {
      f = true;
      break;
    }
  }
  return f;
}

