ll noNeed(ll n, ll k, vll v_sorted){
	ll left_sum = accumulate(v_sorted.begin(), v_sorted.end(), 0);
	for (ll i = n - 1; i >= 0; i--){
		if (left_sum < k){
			return i+1;
		}
		left_sum -= v_sorted[i];
		if (v_sorted[i] < k){
			vll v_sub;
			copy(v_sorted.begin(), v_sorted.begin() + i, back_inserter(v_sub));
			return noNeed(i, k - v_sorted[i], v_sub);
		}
		else{
			continue;
		}
	}
}

