		}
	}
	vector<vector<int>> sum(K,vector<int>(K,0));
	for (i = 0; i < K; i++) {
		for (j = 1; j < K; j++) {
			if (i - j >= 0) sum[i][j] = -sum[i-j][j] + dp[N][i];
			else sum[i][j] = dp[N][i];
		}
	}
	if (S >= K) {
		for (i = 0; i < N; i++) {
			ll valid = 0;
			if (K <= A[i]) valid = 1;
			else {
				for (j = K - A[i]; j < K; j++) {
					if (sum[j][A[i]] >= 1) {
						valid = 1;
						break;
					}
				}
			}
			if (!valid) ans++;
		}
	}
	else ans = N;
	co(ans);
}

