            nums.push_back(num);
        }
    }

    sort(nums.begin(), nums.end());

    auto index = -1;
    auto power = (1 << 14);

    while (power > 0) {
        auto next_index = index + power;
        power >>= 1;

        if (next_index < (int)nums.size() && IsUseless(nums, k, next_index)) {
            index = next_index;
        }
    }

