template<typename T>
struct CumulativeSum{
private:
    vector<T> s;
public:
    void init(vector<T>& v){
        s.push_back(0);
        for(int i=0; i<v.size(); i++){
            s.push_back(s.back() + v[i]);
        }
    }
    T sum(int l, int r){
        l = (l < 0 ? 0 : l);
        r = (r >= s.size() ? s.size()-1 : r);
        return s[r] - s[l];
    }
};

int N, K;
int a[5000];

bool dpL[5000][5000] ={}, dpR[5000][5000] ={};
CumulativeSum<int> sumR[5000];

signed main(){
    scanf("%d%d", &N, &K);
    rep(i, N){
        scanf("%d", a+i);
        a[i] = min(a[i], K);
