    rep(i, N){
        if(i == 0){
            dpL[0][0] = true;
            if(a[i] < K) dpL[0][a[i]] = true;;
        }
        else{
            rep(j, K){
                dpL[i][j] = dpL[i-1][j];
                if(j-a[i] >= 0) dpL[i][j] |= dpL[i-1][j-a[i]];
            }
        }
    }

    for(int i=N-1; i>=0; i--){
        if(i == N-1){
            dpR[N-1][0] = true;
            if(a[i] < K) dpR[N-1][a[i]] = true;
        }
        else{
            rep(j, K){
                dpR[i][j] = dpR[i+1][j];
                if(j-a[i] >= 0) dpR[i][j] |= dpR[i+1][j-a[i]];
            }
        }
    }
    rep(i, N){
        vector<int> tmp(K, 0);
        rep(j, K) tmp[j] = dpR[i][j];
        sumR[i].init(tmp);
    }

    int ans = 0;
    rep(i, N){
        if(a[i] >= K) continue;
        if(i == 0){
            bool needed = false;
            for(int j=max(0, K-a[0]); j<K; j++){
                needed |= dpR[1][j];
            }
            if(!needed) ans++;
        }
        else if(i == N-1){
            bool needed = false;
            for(int j=max(0,K-a[N-1]); j<K; j++){
                needed |= dpL[N-2][j];
            }
            if(!needed) ans++;
        }
        else{
            bool needed = false;
            rep(j, K){
                if(!dpL[i-1][j]) continue;
                needed |= (sumR[i+1].sum(K-j-a[i], K-j) > 0);
            }
            if(!needed) ans++;
        }
    }
    printf("%d\n", ans);
}

