bool useless(vector<int> &b, int val){

    memo[0][b[0]] = 1;

    for(auto i = 1; i<N-1; i++){
        for(auto j = 0; j<=K; j++){
            memo[i][j] = memo[i-1][j];
            if (j-b[i]>=0){
                memo[i][j] = memo[i-1][j-b[i]];
            }

            if (b[i] <=K) memo[i][b[i]] = 1;
        }
    }

    bool flag = true;

    for(auto i = K-val; i<K; i++){

        if (memo[N-2][i] != 0) flag =false;

    }

    return flag;
}

