using namespace std ;

const int MAX = 410 ;

int dp[MAX][MAX] ;
int arr[MAX] ;
int n , k;
int idx2 ;

int solve(int idx , int sum)
{
	if(sum >= k)
		return 0 ;
	if(idx == n)
		return (sum < k && sum >= (k - arr[idx2])) ;
	int &ret = dp[idx][sum] ;
	if(ret != -1)
		return ret ;
	ret = 0 ;
	ret |= solve(idx+1 , sum) ;
	if(idx != idx2)
		ret |= solve(idx+1 , sum + arr[idx]) ;
	return ret ;
}

int main()
{
	ios_base::sync_with_stdio(0) ;
	cin.tie(0) ;
	cin>>n>>k ;
	for(int i = 0 ; i < n ; ++i)
		cin>>arr[i] ;
	int ans = 0 ;
	for(int i = 0 ; i < n ; ++i)
	{
		memset(dp , -1 , sizeof(dp)) ;
		idx2 = i ;
		ans += (!solve(0 , 0)) ;
	}
	return cout<<ans<<"\n" , 0 ;
}

