    while(r-l>1){
        int i = l + (r - l) / 2;
        if (solve(i)) r=i;
        else l=i;
    }
    sum=0;
    for(int i=0;i<n;i++){sum+=vec[i];}
    if(sum<=k){cout<<n<<endl;return 0;}
    cout<<r<<endl;
    return 0;
}

