using ll = long long;

ll n, k;
vector<ll> a, sum;

bool Check(ll idx) {
    for (int l = 0; l <= idx; ++l) {
        for (int r = idx; r < n; ++r) {
            ll tmp = sum[r + 1] - sum[l];
            if (k <= tmp && tmp - a[idx] < k) return true;
        }
    }
    return false;
}

ll Solve() {
    cin >> n >> k;
    a.resize(n);
    sum.resize(n + 1);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        sum[i + 1] = sum[i] + a[i];
    }
    sort(a.begin(), a.end(), greater<ll>());

    if (accumulate(a.begin(), a.end(), 0ll) < k) return n;

    // 必要な要素の集合を見つける
    ll lb = -1, ub = n;
    while (1 < ub - lb) {
        ll mid = (lb + ub) >> 1;
        if (Check(mid)) lb = mid;
        else ub = mid;
    }

    return n - lb - 1;
}

