    vector<vector<char> > dp(n+1, vector<char>(K+1));
    dp[0][0] = 1;
    repi(i, n+1) {
        rep(j, K+1) {
            if (j-a[i-1] >= 0) {
                dp[i][j] = max(dp[i][j], dp[i-1][j-a[i-1]]); //use
            }
            dp[i][j] = max(dp[i][j], dp[i-1][j]); //unuse
        }
    }

    vector<vector<char> > dpi(n+2, vector<char>(K+1));
    dpi[n+1][0] = 1;
    for (int i = n; i >= 0; i--) {
        rep(j, K+1) {
            if (j-a[i-1] >= 0) {
                dpi[i][j] = max(dpi[i][j], dpi[i+1][j-a[i-1]]); //use
            }
            dpi[i][j] = max(dpi[i][j], dpi[i+1][j]); //unuse
        }
    }


    ll res = 0;
    vector<ll> S(K+2);
    rep(i, n) {
        repi(j, K+2) {
            S[j] = S[j-1] + dpi[i+2][j-1];
        }
        bool necessary = false;
        rep(j, K+1) {
            if (0 == dp[i][j]) {
                continue;
            }
            ll sum = i - 1 >= 0 ? j + a[i] : a[i];
            if (sum > K) {
                necessary = true;
                break;
            }
            ll v1 = K - sum;
            ll v2 = K + a[i] - 1 - sum;
            ll cnt = S[v2+1] - S[v1];
            if (cnt > 0) {
                necessary = true;
                break;
            }
        }
        if (!necessary) {
            res++;
        }
    }
    put(res);
}
