	{
		for (int i = 0; i < N; ++i) {
			for (int j = 0; j <= K; ++j) {
				if (dp[i][j]) {
					dp[i+1][j] = 1;
					if (j + A[i] <= K) {
						dp[i + 1][j + A[i]] = 1;
					}
				}
			}
		}
	}
	dpR[0][0] = 1;
	{
		for (int i = 0; i < N; ++i) {
			for (int j = 0; j <= K; ++j) {
				if (dpR[i][j]) {
					dpR[i+1][j] = 1;
					if (j + A[N - 1 - i] <= K) {
						dpR[i + 1][j + A[N - 1 - i]] = 1;
					}
				}
			}
		}
	} 
	{
		for (int i = 0; i <= N; ++i) {
			for (int j = 0; j <= K; ++j) {
				dpSumR[i][j + 1] = dpR[i][j];
				if (0!=j) {
					dpSumR[i][j + 1] += dpSumR[i][j];
				}
			}
		}
	}
	int ans = 0;
	for (int i = 0; i < N; ++i) {
		for (int j = 0;j<K;++j) {
			if (dp[i][j]) {
				if (dpSumR[N-i-1][K-j] > dpSumR[N-i-1][max(0, K - A[i]-j)]) {
					ans++;
					break;
				}
			}
		}
	}
	cout << N - ans <<  endl;
	return 0;
}

