int test(vector<pair<int64_t,int>>& a, int64_t pos, int64_t sum) {
    int ret = 0;
    int before;
//    cout << a[pos].first << " ";


    if((a[pos].first + sum) >= K) {
//        cout << "\n";
//printf("sum:%ld a[%ld].first:%ld %c %ld\n", sum, pos, a[pos].first, (((a[pos].first+sum) )>K ? '>': '<'), K);
        if (sum < K){
            // 最初に必要となった場合、そのカードは必要で確定
            return OK;
        } else {
            return NG;
        }
    }

    for(int64_t i=pos-1;i>=0;i--) {
        before = a[i].second;
        a[i].second = 1;
        ret = test(a, i, sum+ a[pos].first);
        if(ret != OK) {
            a[i].second = before;
        } else {
            return OK;
        }
    }

    return NG;
}

