int n, k;

bool check(int mid, vector<int> &a){
    vector<bool> dp(k, false);
    dp[0] = true;
    for (int i = 0; i < n; i++){
        if (a[i] > k) break;
        if (i == mid) continue;
        vector<bool> dp2 = dp;
        for (int j = 0; j < k; j++){
            if (dp[j] && j + a[i] < k) dp2[j + a[i]] = true;
        }
        dp = dp2;
    }
    bool flag = false;
    for (int i = k - a[mid]; i < k; i++) if (dp[i]) flag = true;
    return flag;
}

int main(){
    cin >> n >> k;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a.begin(), a.end());
    int border = n;
    for (int i = 0; i < n; i++){
        if (a[i] >= k){
            border = i;
            break;
        }
    }
    int ok = border;
    int ng = - 1;
    while (abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;
        if (check(mid, a)) ok = mid;
        else ng = mid;
    }
    cout << ok << endl;
}

#include <bits/stdc++.h>
using namespace std;
long long MOD = 1000000007;
int main(){
  int N, K;
  cin >> N >> K;
  vector<int> a(N);
  for (int i = 0; i < N; i++){
    cin >> a[i];
    a[i] = min(a[i], K);
  }
  vector<vector<long long>> dp(N + 1, vector<long long>(K + 1, 0));
  dp[0][0] = 1;
  for (int i = 0; i < N; i++){
    for (int j = 0; j <= K; j++){
      int next = min(j + a[i], K);
      dp[i + 1][j] += dp[i][j];
      dp[i + 1][j] %= MOD;
      dp[i + 1][next] += dp[i][j];
      dp[i + 1][next] %= MOD;
    }
  }
  vector<vector<long long>> dp2(N + 1, vector<long long>(K + 1, 0));
  dp2[N][0] = 1;
  for (int i = N - 1; i >= 0; i--){
    for (int j = 0; j <= K; j++){
      int next = min(j + a[i], K);
      dp2[i][j] += dp2[i + 1][j];
      dp2[i][j] %= MOD;
      dp2[i][next] += dp2[i + 1][j];
      dp2[i][next] %= MOD;
    }
  }
  for (int i = 0; i <= N; i++){
    for (int j = K - 1; j >= 0; j--){
      dp2[i][j] += dp2[i][j + 1];
      dp2[i][j] %= MOD;
    }
  }
  int ans = 0;
  for (int i = 0; i < N; i++){
    long long cnt = 0;
    for (int j = 0; j <= K; j++){
      cnt += dp[i][j] * dp2[i + 1][K - j] % MOD;
    }
    cnt %= MOD;
    if (cnt * 2 % MOD == dp[N][K]){
      ans++;
    }
  }
  cout << ans << endl;
}

