	if (b[0] < K) {
		cout << N << endl;
	}
	else {
		for (int i = 0; i < N; i++) {
			int flag = 0;
			if (a[i] >= K) {
				ans--;
			}
			else if (b[i] == K) {
				ans = 0;
				break;
			}else{
				int j = i+1;
