	static const int MAX_N = 1000010;
public:
	BIT2() { memset(bit, 0, sizeof(bit)); }
	ll bit[MAX_N + 1], n;
	ll gmax(int i) {
		ll s = 0;
		while (i > 0)
		{
			s = max(bit[i],s);
			i -= i & -i;
		}
		return s;
	}

	void add(int i, ll x) {
		while (i <= n)
		{
			bit[i] = max(bit[i], x);
			i += i & -i;
		}
	}
	void clear() {
		memset(bit, 0, sizeof(bit));
	}

};
