int solve(int *a,int index,int n,int k){

	int dp[n+1][k];
	for(int i=0;i<=n;i++){
		for(int j=0;j<k;j++){
			if(j==0){
				dp[i][j]=1;
			}else{
				dp[i][j]=0;
			}
		}
	}

	for(int i=0;i<n;i++){
		for(int j=0;j<k;j++){
			if(dp[i][j]==1){
				if(j+a[i]<k && i!=index){
					dp[i+1][j+a[i]]=1;
				}
				dp[i+1][j]=1;
			}
		}
		if(DEBUG)cout<<"index="<<index<<endl;
		if(DEBUG)cout<<"i="<<i<<endl;
		if(DEBUG)show(dp[i+1],k);
	}

	for(int i=k-a[index];i<k;i++){
		if(dp[n][i]==1){
			return 1;
		}
	}

	return 0;

}

