const int K = 5001;

bool needed(const vint &a, int n, int k, int t) {
  static bool dp[N][K];
  REP(i,n+1) REP(j,k+1) dp[i][j] = false;
  dp[0][0] = true;
  REP(i,n) REP(j,k) {
    if (i != t && j + a[i] < k) dp[i+1][j+a[i]] = dp[i+1][j+a[i]] || dp[i][j];
    dp[i+1][j] = dp[i+1][j] || dp[i][j];
  }
  FOR(j,max(0,k-a[t]),k) if (dp[n][j]) return true;
  return false;
}

typedef int int_nk[N][K];
typedef bool bool_nk[N][K];

void DP(const vint &a, int n, int k, bool_nk dp, int_nk sum) {
  REP(i,n+1) REP(j,k+1) dp[i][j] = false;
  dp[0][0] = true;
  REP(i,n) REP(j,k) {
    if (j + a[i] < k) dp[i+1][j+a[i]] = dp[i+1][j+a[i]] || dp[i][j];
    dp[i+1][j] = dp[i+1][j] || dp[i][j];
  }
  REP(i,n+1) REP(j,k+1) {
    sum[i][j] = dp[i][j];
    if (j) sum[i][j] += sum[i][j-1];
  }
}

int main() {
  int n, k;
  while (cin >> n >> k) {
    vint a(n);
    REP(i,n) cin >> a[i];

    static bool_nk dp1, dp2;
    static int_nk sum1, sum2;
    DP(a, n, k, dp1, sum1);
    reverse(ALL(a));
    DP(a, n, k, dp2, sum2);
    reverse(ALL(a));
    int result = 0;
    REP(i,n) {
      bool *head = &dp1[i][0];
      int *tail = &sum2[n-i-1][0];
      bool needed = false;
      REP(j,k) if (head[j] && tail[max(0, k-1-j)] != tail[max(0, k-1-j-a[i])]) {
        needed = true;
      }
      if (!needed) {
        // cout << "no-needs " << i << ' ' << a[i] << endl; 
        ++result;
      }
    }
    cout << result << endl;
  }
}

