vector<long long> A;
int N,K;
int dp[5000] = {0};

bool solve( int a ) {

    fill( dp, dp+5000, 0 );

    dp[0] = 1;

    for ( int i = 0; i < N; i++ ) {
        if ( i == a ) { continue; }
        for ( int j = K-1; j >= 0; j-- ) {
            if ( dp[j] && j+A[i] < K ) {
                dp[ j+A[i] ] = 1;
            }
        }
    }

    bool ret = false;
    for ( int i = max( 0LL, K-A[a] ); i < K; i++ ) {
        if ( dp[i] ) { ret = true; break; }
    }

    return ret;
}

int main() {


