    int l = -1;
    int r = N;

    while ( l != r ) {
        int mid = (l+r+1)/2;
        if ( solve(mid) ) {
            l = mid;
        }
        else {
            r = mid-1;
        }
    }

    cout << N-( l+1 ) << endl;


    return 0;
}

