bool search_set(vector<int> cards, int K, int num){
        //exist[i][j]はcardsのi枚目まで使って合計jとなる部分集合を作れるかどうか//
        bool exist[cards.size()][K];

        unsigned int i, j;

        //初期化//
        for(i = 1; i < K; i++){
                if(cards[0] == i)
                        exist[0][i] = true;
                else
                        exist[0][i] = false;
        }

        //条件を満たす集合が見つかったかのフラグ//
        bool find = false;

        //サイズが1の場合は別に処理//
        if(cards.size() == 1){
                for(int k = K - num; k < K; k++){
                        if(exist[0][k] = true){
                                find = true;
                                break;
                        }
                }

                return true;
        }

        //それ以外はDPmatrixを埋めていく//
        //exist[i][j](K - num <= j <= K - 1)がtrueになるまでループ//
        for(i = 1; i < cards.size(); i++){
                //K - num <= j <= K - 1がtrueになったかどうかのフラグ//
                bool ok;
                for(j = 1; j < K; j++){
                        if(exist[i - 1][j] == true){
                                exist[i][j] = true;
                                if(j + cards[i] < K)
                                        exist[i][j + cards[i]] = true;
                        }
                        if(cards[i] == j)
                                exist[i][j] = true;

                        if(j >= K - num && j <= K - 1 && exist[i][j] = true){
                                ok = true;
                                break;
                        }
                }

                //okがtrueなら見つかったので終了//
                if(ok){
                        find = true;
                        break;
                }
        }

