    REP(i,N){
        L[i+1] = L[i];
        for(auto t : L[i])if(t + a[i] <= K)L[i+1].EB(t + a[i]);
    }
    FOR(i,N,0){
        R[i] = R[i+1];
        for(auto t : R[i+1])if(t + a[i] <= K)R[i].EB(t + a[i]);
    }
