bool is_need(vector<int>& A, int ix, int N ,int K)
{
  vector<vector<bool>> dp(N + 5, vector<bool>(K + 5, false));
  dp[0][0] = true;
  for (int i = 0; i < N; ++i) {
    for (int j = 0; j <= K; ++j) {
      dp[i + 1][j] = dp[i][j];
      if (i != ix and j - A[i] >= 0) {
        dp[i + 1][j] = dp[i + 1][j] or dp[i][j - A[i]];
      }
    }
  }
  for (int i = max(0, K - A[ix]); i < K; ++i) {
    if (dp[N][i]) { return true; }
  }
  return false;
}

