  int high = N, low = -1;
  while (high - low > 1) {
    int mid = (high + low) / 2;
    if (is_need(A, mid, N, K)) {
      low = mid;
    }
    else {
      high = mid;
    }
  }

  int ans = N - low - 1;
  printf("%d\n", ans);
  return 0;
}

