template< typename Monoid >
struct SegmentTree {
  using F = function< Monoid(Monoid, Monoid) >;

  int sz;
  vector< Monoid > seg;

  const F f;
  const Monoid M1;

  SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
    sz = 1;
    while(sz < n) sz <<= 1;
    seg.assign(2 * sz, M1);
  }

  void set(int k, const Monoid &x) {
    seg[k + sz] = x;
  }

  void build() {
    for(int k = sz - 1; k > 0; k--) {
      seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
    }
  }

  void update(int k, const Monoid &x) {
    k += sz;
    seg[k] = x;
    while(k >>= 1) {
      seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
    }
  }

  Monoid query(int a, int b) {
    Monoid L = M1, R = M1;
    for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
      if(a & 1) L = f(L, seg[a++]);
      if(b & 1) R = f(seg[--b], R);
    }
    return f(L, R);
  }

  Monoid operator[](const int &k) const {
    return seg[k + sz];
  }
};
int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int n, k; cin >> n >> k;
  vector<ll> A(n); rep(i, n) cin >> A[i];
  vector<vector<bool>> dpl(n+1, vector<bool>(k+1)), dpr(n+1, vector<bool>(k+1));
  dpl[0][0] = true;
  dpr[n][0] = true;
  rep(i, n) {
    rep(j, k+1) {
      dpl[i+1][j] = dpl[i][j] || dpl[i+1][j];
      dpl[i+1][min(j+A[i], (ll)k)] = dpl[i][j] || dpl[i+1][min(j+A[i], (ll)k)];
    }
  }
  rrep(i, n) {
    rep(j, k+1) {
      dpr[i][j] = dpr[i+1][j] || dpr[i][j];
      dpr[i][min(j+A[i], (ll)k)] = dpr[i+1][j] || dpr[i][min(j+A[i], (ll)k)];
    }
  }
  int ans = n;
  SegmentTree<bool> seg(k+1, [](bool a, bool b) { return a || b; }, false);
  rep(i, n) {
    bool ok = false;
    if(A[i] >= k) {
      ans--;
      continue;
    }
    rep(j, k+1) seg.update(j, dpr[i+1][j]);
    rep(j, k) {
      if(dpl[i][j] && seg.query(max(k-A[i]-j, 0LL), k-j)) ok = true;
    }
    if(ok) ans--;
  }
  cout << ans << endk;
  return 0;
}

