int N, K;
bool dp[MAX][MAX];
vector <int> v;

bool check(int x) {
    int n = (int)v.size();
    memset(dp, false, sizeof(dp));
    dp[0][0] = true;
    rep(n, i) rep(K, j) {
        dp[i+1][j] = dp[i][j] || dp[i+1][j];
        if (j+v[i] < K && dp[i][j] && x != i) dp[i+1][j+v[i]] = true;
    }
    rep(K, j) if (dp[n][j] && j + v[x] >= K) return true;
    return false;
}

