                L[i][j] = true;
                if(j + a[i] < K) L[i][j + a[i]] = true;
            }

    REP(i, N) REP(j, K) R[i][j] = false;
    R[N-1][0] = true;
    if(a[N-1] < K) R[N-1][a[N-1]] = true;
    for(int i = N-2; i >= 0; --i) 
        for(int j = 0; j < K; ++j)
            if(R[i+1][j]) {
                R[i][j] = true;
                if(j + a[i] < K) R[i][j + a[i]] = true;
            }

    REP(i, N) {
        REP(j, K) if(R[i][j]) Rsum[i][j] = 1;
        for(int j = 1; j < K; ++j) Rsum[i][j] += Rsum[i][j-1];
    }

    int cnt = 0;
    REP(i, N) {
        if(i == 0) {
            int lw = max(0, K - a[i]);
            for(int j = lw; j < K; ++j) if(R[i+1][j]) { ++cnt; break; }
            continue;
        }
        if(i == N-1) {
            int lw = max(0, K - a[i]);
            for(int j = lw; j < K; ++j) if(L[i-1][j]) { ++cnt; break; }
            continue;
        }

        bool flg = false;
        for(int j = 0; j < K; ++j) if(L[i-1][j]) {
            int lw = K - j - a[i] - 1;
            int up = K - j;

            if(lw >= 0){
                if(Rsum[i+1][up - 1] - Rsum[i+1][lw] > 0) { flg = true; break; }
            }
            else {
                if(Rsum[i+1][up-1] > 0) { flg = true; break; }
            }
        }
        if(flg) ++cnt;
    }

    printf("%d\n", N - cnt);
    return 0;
}

