#include <bits/stdc++.h>

using namespace std ;

const int MAX = 5005 ;
int arr[MAX] , pref[MAX][MAX] , suff[MAX][MAX];
bitset<MAX>b1,b2;

int main()
{
	ios_base::sync_with_stdio(0) ;
	cin.tie(0) ;
	int n , k ;
	cin>>n>>k ;
	for(int i = 1 ; i <= n ; ++i)
		cin>>arr[i] ;
	b1[0] = 1 ;
	pref[0][0] = 1 ;
	for(int j = 1 ; j <= k ; ++j)
		pref[0][j] = pref[0][j-1] + b1[j] ;
	for(int i = 1 ; i <= n ; ++i)
	{
		if(arr[i] >= k)
			continue ;
		b1 |= (b1 << arr[i]) ;
		pref[i][0] = 1 ;
		for(int j = 1 ; j <= k ; ++j)
			pref[i][j] = pref[i][j-1] + b1[j] ;
	}
	b2[0] = 1 ;
	suff[n+1][0] = 1 ;
	for(int j = 1 ; j <= k ; ++j)
		suff[n+1][j] = suff[n+1][j-1] + b2[j] ;
	for(int i = n ; i >= 1 ; --i)
	{
		if(arr[i] >= k)
			continue ;
		b2 |= (b2 << arr[i]) ;
		suff[i][0] = 1 ;
		for(int j = 1 ; j <= k ; ++j)
			suff[i][j] = suff[i][j-1] + b2[j] ;
	}
	int ans = 0 ;
	for(int i = 1 ; i <= n ; ++i)
	{
		if(arr[i] >= k)
			continue ;
		bool flag = false; 
		for(int j = 0 ; j < k ; ++j)
		{
			int x ;
			if(j == 0)
				x = pref[i-1][j] ;
			else
				x = pref[i-1][j] - pref[i-1][j-1] ;
			if(x == 0)
				continue ;
			if(j >= k - arr[i])
			{
				flag = true ;
				break ;
			}
			//debugging
			if(k-j-1 <= k-arr[i]-1)
				while(1) ;
			if(suff[i+1][k-j-1] - suff[i+1][k-arr[i]-1] > 0)
			{
				flag = true ;
				break ;
			}
		}
		if(flag == false)
			ans++ ;
	}
	return cout<<ans<<"\n" , 0 ;
}

