            if(dp[i][j].first==0) continue;
            dp[i+1][j].first++;//何もしない
            if(j<k){
                if(j+a[i]<k) dp[i+1][j+a[i]].first++;
                else dp[i+1][k]={1,j};
            }
        }
    }

    vec<bool> need(n,false);
