int N, K; 
int A[5010] = {}; 
bool dp[5010][5010] = {}; // dp[i番目まで][和がちょうどj] = 可能？
bool necessary(int m){ // m番目を除いて[K-A[m], K)の値を作れるか？
	for(int i = 0; i <= N; i++){
		for(int j = 0; j <= K; j++){
			dp[i][j] = false; 
		}
	}
	dp[0][0] = true; 
	for(int i = 1; i <= N; i++){
		if(i == m){
			for(int j = 0; j < K; j++){
				dp[i][j] = dp[i-1][j]; 
			}
		}
		else{
			for(int j = 0; j < K; j++){
				if(dp[i-1][j]) {
					dp[i][j] = true; 
					dp[i][min(j+A[i], K)] = true; 
                }
			}
		}
	}
	bool ans = false; 
	for(int a = max(K - A[m], 0); a < K; a++){
		if(dp[N][a]){ans = true;}
	}
	return ans; 
}
int main() {
	cin >> N >> K; 
	for(int i = 1; i <= N; i++){
		cin >> A[i]; 
	}
	sort(A, A+N+1); 
	// a<bでaが必要かつbが不必要とすると矛盾．
	// aが属し，K<=(Sの元の和)<K+aなるSを1つとる．bがSの元のときはSそのものが，
	// bがSの元でないときはSからaを除きbを加えたものが反例．
	if(necessary(1)){cout << 0 << endl;}
	else if(!necessary(N)){cout << N << endl;}
	else{
		int L = 1, R = N; 
		while(R - L > 1){
			int M = (L + R) / 2; 
			if(necessary(M)){R = M;}
			else{L = M;}
		}
		cout << L << endl;
	}
}

