bool judge(int x) {
    rep(i, N) rep(j, K) dp[i][j] = false;
    dp[0][0] = true;
    rep(i, N-1) {
        int v = a[i+(i>=x ? 1:0)];
        rep(j, K) {
            dp[i+1][j] |= dp[i][j];
            if (j+v<K) dp[i+1][j+v] |= dp[i][j];
        }
    }
    for (int i=max(0ll, K-a[x]); i<K; i++) if (dp[N-1][i]) return false;
    return true;
}

