int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cout << fixed << setprecision(16);
  i32 N, K;
  cin >> N >> K;
  vi32 A(N);
  rep(i, N) cin >> A[i];
  vi32 b(N, false);
  sort(all(A), greater<i32>());
  for(int i = 0; i < N; i++) {
    i32 idx = i;
    i64 sum = 0;
    while (idx < N && sum < K) {
      sum += A[idx++];
    }
    if (sum < K) break;
    sum -= A[--idx];
    i32 ok = idx, ng = N;
    while (ng - ok > 1) {
      i32 md = (ok + ng) / 2;
      if (sum + A[md] >= K) {
        ok = md;
      } else {
        ng = md;
      }
    }
    for (int j = i; j < idx; j++) {
      b[j] = true;
    }
    for (int j = idx; j <= ok; j++) {
      b[j] = true;
    }
  }
  int ans = 0;
  rep(i, N) if (!b[i]) ans++;
  cout << ans << endl;
  return 0;
}

