constexpr int MAX_BIT = 5001;
std::vector<int> A;
std::vector<std::bitset<MAX_BIT>> S, T;


int main(void){
    // 入力部
    int n, k; scanf("%d%d", &n, &k);
    A.resize(n); REP(i, n) scanf("%d", &A[i]);

    // 実行部
    S.resize(n), T.resize(n);
    REP(i, n){S[i].reset(); T[i].reset();}

    S[0][0] = true; T[0][0] = true;
    REP(i, n){
        for(int x = 0; x < k; ++x){
            if(S[i][x]){
                S[i+1][x] = true;
                if(x + A[i] <= k) S[i+1][x+A[i]] = true;
            }
            if(T[i][x]){
                T[i+1][x] = true;
                if(x + A[n-i-1] <= k) T[i+1][x+A[n-i-1]] = true;
            }
        }
    }

    // 確認 + 出力
    int noNeed = 0;

    // X[i] := i 未満の数
    std::vector<int> X(k+1);
    REP(i, n){
        // k - ai ≤ m + X < k <==> k - ai - m < X < k - m
        X[0] = 0;
        for(int x = 1; x <= k; ++x){
            X[x] = X[x-1] + (T[i][x] ? 1 : 0);
        }
        bool flag = false;
        for(int x = 0; x < k; ++x) if(S[i][x]){
            int cnt = X[k-x] - X[std::max(k-x-A[i], 0)];
            if(cnt > 0){
                flag = true;
                break;
            }
        }
        if(not flag) noNeed++;
    }

    printf("%d\n", noNeed);



    return 0;
}

