class subsequence 
{
private:
    int Left, Right;
    long long S;
    int N;
    long long LRsum;
    std::vector<long long> sequence;
public:
    virtual void move_left_pointer();
    virtual void move_right_pointer();
    virtual bool is_cond();
    virtual bool is_right_end();
    virtual std::pair<int, int> no_next();
    virtual std::pair<int, int> get_LR();


    void set_S(long long S);
    subsequence(std::vector<long long>& sequence, int N, int start);
};

subsequence::subsequence(std::vector<long long>& sequence, int N, int start) :
    sequence(sequence),
    N(N),
    Left(start),
    Right(start),
    S(0),
    LRsum(0)
{
}

void subsequence::set_S(long long S) {
    this->S = S;
}

void subsequence::move_left_pointer() {
    LRsum -= sequence[Left];
    Left++;
}

void subsequence::move_right_pointer() {
    if (Right < N) {
        LRsum += sequence[Right];
        Right++;
    }
}

bool subsequence::is_cond() {
    if (LRsum >= S)
        return true;
    return false;
}

bool subsequence::is_right_end() {
    if (Right >= N)
        return true;
    return false;
}

std::pair<int, int> subsequence::no_next() {
    return std::make_pair(-1, -1);
}

std::pair<int, int> subsequence::get_LR() {
    return std::make_pair(Left, Right);
}

int main() {

    std::vector<long long> sequence;
    int N, K;
    std::cin >> N >> K;
    for (int i = 0; i < N; i++) {
        long long a;
        std::cin >> a;
        sequence.push_back(a);
    }
    std::sort(sequence.begin(), sequence.end());

    subsequence seq(sequence, sequence.size(), 0);
    seq.set_S(K);
    int count = 0;
    int left_pointer_move_count = 0;
    while (1) {
        bool is_break = false;
        while (seq.is_cond() == false && seq.is_right_end() == false) {
            if (left_pointer_move_count > 0) {
                count += (left_pointer_move_count - 1);
                is_break = true;
            }
            left_pointer_move_count = 0;
            seq.move_right_pointer();
        }
        if (is_break == true)
            break;
        if (seq.is_cond() == false) {
            if (left_pointer_move_count > 0)
                count += (left_pointer_move_count - 1);
            break;
        }
        seq.move_left_pointer();
        left_pointer_move_count++;
    }

    std::cout << count << endl;
    return 0;
}

