void solve() {
    ll n, k;
    cin >> n >> k;
    vll a;
    rep(i, n) {
        ll _a;
        cin >> _a;
        if(_a >= k) continue;
        a.push_back(_a);
    }
    n = a.size();

    vvb sa(n + 1, vb(k + 1));
    vvi saf(n + 1);
    sa[0][0] = true;
    for(ll i = 0; i < n; i++) {
        for(ll j = 0; j <= k; j++) {
            if(sa[i][j]) {
                sa[i + 1][j] = true;
                if(j + a[i] <= k) sa[i + 1][j + a[i]] = true;
            }
        }
    }
    rep(i, n + 1) rep(j, k + 1) if(sa[i][j]) saf[i].push_back(j);

    sa.assign(n + 1, vb(k + 1, false));
    vvi sab(n + 1);
    sa[n][0] = true;
    for(ll i = n - 1; i >= 0; i--) {
        for(ll j = 0; j <= k; j++) {
            if(sa[i + 1][j]) {
                sa[i][j] = true;
                if(j + a[i] <= k) sa[i][j + a[i]] = true;
            }
        }
    }
    rep(i, n + 1) rep(j, k + 1) if(sa[i][j]) sab[i].push_back(j);

    ll ans = 0;
    for(ll i = 0; i < n; i++) {
        vi& v1 = saf[i];
        vi& v2 = sab[i + 1];
        // v1+v2がk-a[i]~k-1となるのを探す
        bool ok = false;
        for(auto& j : v1) {
            ll l = lower_bound(v2.begin(), v2.end(), k - a[i] - j) - v2.begin();
            ll r = upper_bound(v2.begin(), v2.end(), k - 1 - j) - v2.begin();
            if(r - l > 0) ok = true;
            if(ok) break;
        }
        if(!ok) ++ans;
    }
    cout << ans << endl;
    return;
}

