using vll = vector<ll>;

int N, K, A[5001];
bool dp[5001][5001];

vector<vi> f() {
    MEM(dp, 0);
    dp[0][0] = 1;
    rep(i, N) rep(j, K) if(dp[i][j]){
        if (j + A[i] < K)dp[i + 1][j + A[i]] = 1;
        dp[i + 1][j] = 1;
    }
    vector<vi> res(N + 2);
    res[N + 1].push_back(0);
    rep(i, N + 1)rep(j, K)if (dp[i][j])res[i].push_back(j);
    RT res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    cin >> N >> K;
    rep(i, N)cin >> A[i];

    auto S = f();
    reverse(all(S));
    reverse(A, A + N);
    auto T = f();
    int ans = 0;
    for (int i = 1; i <= N; ++i) {
        int a = A[i - 1];
        if (a >= K)continue;
        int need = 0;

        each(x, T[i - 1]) {
            int lb = K - a - x, ub = K - x;
            auto it = lower_bound(all(S[i + 1]), lb);
            if (it != S[i + 1].end() && *it < ub) {
                assert(*it >= lb);
                need = 1;
                break;
            }
        }
        if (!need)ans++;
        cout << need << endl << endl;
    }
    cout << ans << endl;
}

