void solve() {
    cin>>n>>k;
    rep(i,n) cin>>a[i];
    vii dp[5010];
    vii dp2[5010];
    cnt[0][0]=1;
    for(int i=0;i<n;i++){
        // dp[i+1]=dp[i];
        for(int j=0;j<=k;j++){
            if(cnt[i][j]==0) continue;
            cnt[i+1][j]=1;
            if(j + a[i] > k) continue;
            cnt[i+1][j+a[i]]=1;
        }
    }
    cnt2[n][0]=1;
    for(int i=n-1;i>=0;i--){
        for(int j=0;j<=k;j++){
            if(cnt2[i+1][j]==0) continue;
            cnt2[i][j]=1;
            if(j + a[i] > k) continue;
            cnt2[i][j+a[i]]=1;
        }
    }

    rep(i,n+1){
        for(int j=0;j<=k;j++){
            if(cnt[i][j]>0){
                dp[i].pb(j);
            }
        }
    }
    for(int i=0;i<n+1;i++){
        for(int j=0;j<=k;j++){
            if(cnt2[i][j]==1){
                dp2[i].pb(j);
            }
        }
    }

    // rep(i,n+1){
    //     for(ll j : dp[i]) cout<<j<<" ";
    //     cout<<endl;
    // }
    // rep(i,n+1){
    //     for(ll j : dp2[i]) cout<<j<<" ";
    //     cout<<endl;
    // }

    int ans=0;
    for(int i=0;i<n;i++){
        int x = max(0, k-a[i]);
        bool ok = true;
        for(int j=0;j<=k;j++) {
            if(cnt[i][j]==0) continue;
            // cout<<"x-j:"<<x-j<<" ";
            auto index = lower_bound(dp2[i+1].begin(), dp2[i+1].end(), x - j);
            if(index== dp2[i+1].end()){
                // cout<<endl;
                continue;
            }
            int y = *index;
            // cout<<i<<" "<<j<<" "<<y<<" "<<endl;
            if(j + y >= k) continue;
            ok = false;
            if(!ok) break;
        }
        if(ok) ans++;
    }
    cout<<ans<<endl;
}


