bool f(int pos, int k, vector<int> card)
{
	const int prev = card[pos];
	card[pos] = 0;

	const int size = card.size();
	vector<vector<bool>> table(size+1, vector<bool>(k+1, false));
	table[0][0] = true;

	for(int i=0; i<size; i++)
	{
		for(int j=0; j<k+1; j++)
		{
			if(table[i][j] == false)
				continue;

			table[i+1][j] = table[i][j];

			int n = j + card[i];
			if(n > k)
				continue;

			table[i+1][n] = true;
		}
	}

	bool flag = false;
	for(int i=max(0, k-prev); i<k; i++)
		if(table[size][i] == true)
			flag = true;

	return flag;
}

int main(void)
{
	int N, K;
	cin >> N >> K;

	vector<int> a(N);
	for(int i=0; i<N; i++)
		cin >> a[i];

	sort(a.begin(), a.end());

	if(f(N-1, K, a) != true)
	{
		cout << N << endl;
		return 0;
	}

	int left, right;
	left = 0;
	right = N-1;
	while(right-left>1)
	{
		int mid = (left + right)/2;

		if(f(mid, K, a) == true)
			right = mid;
		else
			left = mid;
	}

	cout << left + 1 << endl;

	return 0;
}

