#include<bits/stdc++.h>
using namespace std;
using ll = long long;

#define REP(i, n) for(int i = 0; i < (n); ++i)

int main() {
    int N; ll K;
    scanf("%d %lld", &N, &K);
    ll a[N];
    for(int i = 0; i < N; ++i) scanf("%lld", &a[i]);

    bool L[N][K], R[N][K];

    REP(i, N) REP(j, K) L[i][j] = false;
    L[0][0] = true;
    if(a[0] < K) L[0][a[0]] = true;
    for(int i = 1; i < N; ++i) 
        for(ll j = 0; j < K; ++j) 
            if(L[i-1][j]) {
                L[i][j] = true;
                if(j + a[i] < K) L[i][j + a[i]] = true;
            }

    REP(i, N) REP(j, K) R[i][j] = false;
    R[N-1][0] = true;
    if(a[N-1] < K) R[N-1][a[N-1]] = true;
    for(int i = N-2; i >= 0; --i) 
        for(ll j = 0; j < K; ++j)
            if(R[i+1][j]) {
                R[i][j] = true;
                if(j + a[i] < K) R[i][j + a[i]] = true;
            }

    int Rsum[N][K]; //累積和
    REP(i, N) {
        REP(j, K) if(R[i][j]) Rsum[i][j] = 1;
        for(int j = 1; j < K; ++j) Rsum[i][j] += Rsum[i][j-1];
    }

    int cnt = 0;
    REP(i, N) {
        if(i == 0) {
            ll lw = K - a[i] - 1;
            if(lw >= 0){
                if(Rsum[1][K-1] - Rsum[1][lw] > 0) ++cnt;
            }
            else ++cnt;
            continue;
        }
        if(i == N-1) {
            ll lw = max(0LL, K - a[i]);
            for(ll j = lw; j < K; ++j) if(L[i-1][j]) { ++cnt; break; }
            continue;
        }

        for(ll j = 0; j < K; ++j) if(L[i-1][j]) {
            ll lw = K - j - a[i] - 1;
            ll up = K - j;
            if(lw >= 0){
                if(Rsum[i+1][up - 1] - Rsum[i+1][lw] > 0) { ++cnt; break; }
            }
            else {
                if(Rsum[i+1][up-1] > 0) { ++cnt; break; }
            }
        }
    }

    printf("%d\n", N - cnt);
    return 0;
}

