// 二分探索（改）
// judge を満たすような下限を求める
// left:[X] 定義域の下限
// right:[X] 定義域の上限
// judge:[X -> bool] X を評価する関数
// lower:[bool] falseにすると代わりに上限を求める
// eps:[X] 終了距離

template <typename X>
X BinSearch(X left, X right, function<bool(X)> judge, bool lower = true, X eps = 1) {
    while (right - left > eps) {
        X mid = (right + left) / 2;
        if (judge(mid) == lower) {
            right = mid;
        } else {
            left = mid;
        }
    }
    return lower ? right : left;
}

int main() {
    int N, K;
    cin >> N >> K;
    vector<int> a(N);
    sort(WHOLE(a));
    for(auto &x : a) cin >> x;
    auto f = [&](int x) -> bool {
        vector<bool> dp[2] = {vector<bool>(K, false), vector<bool>(K, false)};
        dp[0][0] = true;
        for(int i = 0; i < N; i++) {
            int b = i & 1;
            for(int s = 0; s < K; s++) {
                if(i != x && s - a[i] >= 0) {
                    dp[!b][s] = dp[b][s] | dp[b][s - a[i]];
                } else {
                    dp[!b][s] = dp[b][s];
                }
            }
        }
        bool retval = false;
        for(int s = max(0, K - a[x]); s < K; s++) {
            retval |= dp[N & 1][s];
        }
        return !retval;
    };
    int ans = BinSearch<int>(-1, a.size(), f, false);
    cout << ans + 1 << endl;
    return 0;
}

