  rep(i,arr.size()) {
    rep(j,K-arr[i]) {
      if (dp2[i][j]) {
        dp2[i+1][j+arr[i]] = true;
      }
    }
  }

  int ans = arr.size();

  rep(i,arr.size()) {
    vi tmp(K+1);
    rep(j,K) tmp[j+1] = tmp[j] + (dp2[i][j] ? 1 : 0);

    int h = arr.size()-1 - i;

    rep(j,K) {
      if (!dp[h][j]) continue;

      if (j < K-arr[i] && tmp[K-j] == tmp[K-arr[i]-j]) continue;

      --ans;
      break;
    }
  }

  cout << ans << endl;
  return 0;
}

