    }
  }
  for(int i=0;i<=N-1;i++){
    dp[i][0] = true;
  }
  for(int i=1;i<=N-1;i++){
    for(int j=0;j<=K;j++){
      if(j - b[i-1] < 0) dp[i][j] = dp[i-1][j];
      else dp[i][j] = (dp[i-1][j] || dp[i-1][j - b[i-1]]);
    }
  }
  /*
