int tabooo[MAX_N];
int memo(int pos, int val){
  if (val >= K - A[src] and val < K){
    return 1;
  }

  if (pos == N){
    return 0;
  }
  int &res = dp[pos][val];
  if (res >= 0){
    return res;
  }
  res = 0;
  res |= memo(pos + 1, val);
  if (not tabooo[pos]){
    res |= memo(pos + 1, min(K, val + A[pos]));
  }

  return res;
}


int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cin >> N >> K;

  A.resize(N);
  for (auto &val : A){
    cin >> val;
  }
  sort(A.begin(), A.end());
  int left,right;
  left = -1;
  right = N + 1;
  while (right - left > 1){
    int med = (right + left) / 2;
    if (med >= N){
      right--;
      continue;
    }else if(med < 0){
      left++;
      continue;
    }

    src = med;
    memset(dp, -1, sizeof(dp));
    tabooo[med] = true;
    int res = memo(0, 0);
    tabooo[med] = false;
    if (res > 0){//necessary
      right = med;
    }else{//unnecessary
      left = med;
      for (int i = med; i >= 0; i--){
        if (tabooo[i])break;
        tabooo[i] = true;
      }
    }
  }
  cout << (left + 1) << endl;

  return 0;
}

