using namespace std;

int IntervalSum(const vector<int> &vec, int left, int right)
{
    auto sum = vec[right];
    if (left > 0) {
        sum -= vec[left - 1];
    }
    return sum;
}

void Rucksack(vector<int> &vec, int val)
{
    for (int i = vec.size() - 1; i >= val; i -= 1) {
        vec[i] += vec[i - val];
    }
    vec[val] += 1;
}

int main()
{
    int n, k;
    cin >> n >> k;

    vector<int> sums(k + 1, 0);
    vector<int> nums;
    auto res = n;

    for (auto i = 0; i < n; i += 1) {
        int num;
        cin >> num;

        if (num >= k) {
            res -= 1;
        } else {
            nums.push_back(num);
        }
    }

    vector<vector<int>> prefixes(nums.size(), vector<int>(k, 0));
    for (size_t i = 0; i < prefixes.size(); i += 1) {
        if (i > 0) {
            copy(prefixes[i - 1].begin(), prefixes[i - 1].end(), prefixes[i].begin());
        }
        Rucksack(prefixes[i], nums[i]);
    }

    vector<vector<int>> suffixes(nums.size(), vector<int>(k, 0));
    for (int i = suffixes.size() - 1; i >= 0; i -= 1) {
        if (i + 1 < (int)suffixes.size()) {
            copy(suffixes[i + 1].begin(), suffixes[i + 1].end(), suffixes[i].begin());
        }
        Rucksack(suffixes[i], nums[i]);
    }

    for (auto &p : prefixes) {
        for (int i = 1; i < k; i += 1) {
            p[i] += p[i - 1];
        }
    }
    for (auto &s : suffixes) {
        for (int i = 1; i < k; i += 1) {
            s[i] += s[i - 1];
        }
    }

    for (size_t i = 0; i < nums.size(); i += 1) {
        auto important = false;
        if (i + 1 < nums.size() && IntervalSum(suffixes[i + 1], k - nums[i], k - 1) > 0) {
            important = true;
        }
        if (i > 0 && IntervalSum(prefixes[i - 1], k - nums[i], k - 1) > 0) {
            important = true;
        }
        if (i > 0 && i + 1 < nums.size()) {
            for (int j = 1; j < k - nums[i] && !important; j += 1) {
                if (IntervalSum(prefixes[i - 1], j, j) <= 0) {
                    continue;
                }
                if (IntervalSum(suffixes[i + 1], k - nums[i] - j, k - 1 - j) > 0) {
                    important = true;
                }
            }
        }
        res -= (important ? 1 : 0);
    }

    cout << res << "\n";
    return 0;
}

