struct UnionFind {
    // UnionFind u(n) 宣言
    // u.unionSet(x,y) 併合
    // u.findSet(x,y) -> {true, false}
    // u.root(x) xのroot. data[x]を参照。併合前はxそのもの、併合後は同一union
    vector<int> data;
    UnionFind(int size) : data(size, -1) { }
    bool unionSet(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] > data[x]) swap(x, y);
            data[y] += data[x];
            data[x] = y;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }

    void clear(int size) {
        data.clear();
        data.resize(size,-1);
    }
};



int N, K;
vector<int> a;
const int MAX_SIZE = 21;
int memo[MAX_SIZE][MAX_SIZE];


bool useless(vector<int> &b, int val){

    memo[0][b[0]] = 1;

    for(auto i = 1; i<N; i++){
        for(auto j = 0; j<=K; j++){
            memo[i][j] += memo[i-1][j];
            if (j-b[i]>=0){
                memo[i][j] += memo[i-1][j-b[i]];
            }

            if (b[i] <=K) memo[i][b[i]] = 1;
        }
    }

    bool flag = true;

    for(auto i = K-val; i<K; i++){

        if (memo[N-1][val] != 0) flag =false;

    }

    return flag;
}

int main() {
    cin >> N >> K;
    a.resize(N);

    cin >> a;

    sort(all(a));


    int left = 0;
    int right = N;
    int middle = (left + right)/2;
    while(left < right){


        for(auto i = 0; i <N; i++){
            for(auto j = 0; j<=K; j++){
                memo[i][j] =0;
            }
        }

        middle = (left + right)/2;

        vector<int> b(a);
        b.erase(find(all(b),a[middle]));


        if (useless(b,a[middle])){
            left = middle+1;
        }else{
            right = middle;
        }

    }


    cout << N-left << endl;



    return 0;
}

