	scanf("%ld %ld",&n, &k);
	long arr[n];
	for (int i=0; i<n; i++) {
		scanf("%ld",&arr[i]);
	}
	sort(arr, arr+n);
	long DP[n];
	DP[0] = arr[0];
	for (int i=1; i<n; i++) {
		DP[i] = DP[i-1] + arr[i];
	}
	int out = -1;
	for (int i=n-2; i>=0; i--) {
		if (arr[i]<k) {
			int j = i-1;
			while (j>=0 && DP[i]-DP[j] < k) {
				j--;
			}
			out = j+1;
			break;
		}
	}

	if (out>0)
		cout << out << endl;
	else cout << n << endl;
