        if(a1 < K) a.push_back(a1);
    }

    sort(all(a));

    int m = a.size();

    int ok = m, ng = -1;

    cur[0] = true;
    while(ok - ng > 0){
        int mid = (ok + ng) / 2;

        bool flg = false;
        REP(x, m) {
            if(x == mid) continue; 
            REP(y, K) {
                if(y - a[x] < 0) continue;

                nxt[y] = cur[y - a[x]];

                if(nxt[y] && y >= K - a[mid]) {
