bool deep(vector<int> a,int r){
	vector<int> b;
	int l;
	for(int i = 0;i < a.size();i++){
		if(i == r){
			l = a[r];
		}
		else{
			b.push_back(a[i]);
		}
	}
	bool bp[5000] = {};
	bp[0] = true;
	for(int i = 1;i < 5000;i++){
		bp[i] = false;
	}
	for(int i = 0;i < b.size();i++){
		for(int j = 0;j < 5000;j++){
			if(bp[j] && j+b[i] < 5000)bp[j+b[i]] = true;
		}
	}
	for(int i = k-l;i < k;i++){
		if(bp[i]) return true;
	}
	return false;
}

int main(){
	int n;
	cin >> n >> k;
	vector<int> a;
	for(int i = 0;i < n;i++){
		int j;
		cin >> j;
		a.push_back(j);
	}
	sort(a.begin(),a.end());
	for(int i = 0;i < a.size();i++){
		if(deep(a,i)){
			cout << i << endl;
			return 0;
		}
	}
	cout << a.size() << endl;
	return 0;
}

