#define MAXN 5010
LL A[MAXN],B[MAXN];
bool has[MAXN]={1},done[MAXN]={0};
int main(){
    LL ans=0,sum=0;
    DRII(r,K);
    int N=0;
    REP(i,r){RI(B[i]);sum+=B[i];
        if(B[i]<K)A[N++]=B[i];
    }
    sort(A, A+N,[=](LL a,LL b){return b<a;});
    if(sum<K){
        printf("%d\n",N);return 0;
    }
    ans=N;
    REP(i,N){
        if(done[i])continue;
        fill(has, has+K+1, false);has[0]=1;
        REP(k, N){
            bool dobreak=0;
            if(k==i)continue;
            if(A[k]>=K-A[i] && A[k]<K){
                for(int i=N-1;i>=0;--i){
                    if(A[i]+A[k]>=K)done[i]=1,--ans;
                    else break;
                }
                --ans,dobreak=1;break;
            }
            for(int j=K-A[k];j>=0;--j){
                if(has[j] && j+A[k]<MAXN){
                    has[j+A[k]]=1;
                    if(j+A[k]>=K-A[i]&&j+A[k]<K){
                        --ans,dobreak=1;break;
                    }
                }
            }
            if(dobreak)break;
        }
    }
