const u32 MAX_N = 5000;
const u32 MAX_K = 5000;
u32 N, K;
vector<u32> a;

bool check(i32 m) {
    // printf("m: %d\n", m);
    array<bool, MAX_K+1> dp;
    fill(all(dp), false);
    dp[0] = true;
    REP(i, N) {
        if(i == m) {
            continue;
        }
        RREP(j, K) {
            if(dp[j] && j + a[i] < K) {
                dp[j+a[i]] = dp[j+a[i]] || dp[j];
            }
        }
    }
    REP(j, K) {
        // printf("dp[%d]: %d, j+a[m]: %d\n", j, dp[j], j+a[m]);
        if(dp[j] && j + a[m] >= K) {
            return true;
        }
    }
    return false;

}

int main() {
    cin >> N >> K;
    a = vector<u32>(N);
    REP(i, N) {
        IN(a[i]);
    }
    sort(a.rbegin(), a.rend());
    i32 l = -1;
    i32 r = N;
    i32 m = (l + r + 1) / 2;
    while(r - l > 1) {
        if(check(m)) {
            l = m;
        } else {
            r = m;
        }
        m = (l + r + 1) / 2;
    }
    // printf("m: %d\n", m);
    cout << N - m << endl;
    return 0;
}

