		if (a[0] >= k) cout << 0 << endl;
		else cout << 1 << endl;
		return 0;
	}

	vector<vector<bool>> dp(n, vector<bool>(k,false)), dpr(n, vector<bool>(k, false));
	dp[0][0] = dp[0][a[0]] = true;
	dpr[n-1][0] = dpr[n-1][a[n-1]] = true;
	rep(i, n-1) rep(j, k) {
		if (dp[i][j]) {
			dp[i+1][j] = true;
			if (j+a[i+1] < k) dp[i+1][j+a[i+1]] = true;
		}

		if (dpr[n-i-1][j]) {
			dpr[n-i-2][j] = true;
			if (j + a[n-i-2] < k) dpr[n-i-2][j + a[n-i-2]] = true;
