bool bs(int mid, int n, int k, const vector<ll> &a) {
  vector<ll> b;
  for(int i=0;i<n;++i) {
    if(i != mid) b.push_back(a[i]);
  }
  vector<set<ll>> dp(n+1);
  dp[0].insert(0);
  for(int i=0;i<n;++i) {
    for(auto &e: dp[i]) {
      dp[i+1].insert(e);
      dp[i+1].insert(e + b[i]);
    }
  }
  auto it = lower_bound(dp[n-1].begin(), dp[n-1].end(), k - a[mid]);
  if(it != dp[n-1].end()) {
    return *it >= k;
  } else {
    return true;
  }
}
int main() {
  cin.tie(0);
  cout << fixed << setprecision(10);
  int n, k; cin >> n >> k;
  vector<ll> a(n);
  for(int i=0;i<n;++i) {
    cin >> a[i];
  }
  sort(a.begin(), a.end());
  int l = 0, r = n;
  while(r - l > 1) {
    int mid = (l + r) / 2;
    if(bs(mid, n, k, a)) {
      l = mid;
    } else {
      r = mid;
    }
  }
  cout << l + 1 << endl;
}

