        if (gb[mid].first >= K) return true;
        bitset<10101> dp;
        dp[0] = true;
        for (int k = 0; k < gb[mid].second - 1; ++k) {
            for (int j = K - 1; j >= 0; --j) {
                if (not dp[j]) continue;
                dp[min(K, j + gb[mid].first)] = true;
            }
        }
        for (int i = mid + 1; i < sz; ++i) {
            int num, quan;
            tie(num, quan) = gb[i];
            for (int k = 0; k < quan; ++k) {
                for (int j = K - 1; j >= 0; --j) {
                    if (not dp[j]) continue;
                    dp[min(K, j + num)] = true;
                }
            }
        }
        // debug(mid, dp);
        for (int i = max(0, K - gb[mid].first); i < K; ++i) if (dp[i]) return true;
        return false;
    };

    if (check(0)) return print(N);

    T ok = sz, ng = 0;
    while (abs(ok - ng) > 1) {
        T mid = (ok + ng) / 2;
        (check(mid) ? ok : ng) = mid;
    }

    int res = 0;
    for (int i = 0; i < ok; ++i) res += gb[i].second;
    print(res);

    // REP(i, sz) print(i, check(i));

}

