array<u32, MAX_K> dp;
vector<u32> a;
u32 N, K;
u32 countSubSet(int m) {
    dp.fill(0);
    dp[0] = 1;
    REP(i, N)RREP(j, K+1) {
        u32 tmp = a[i];
        if(i >= m) {
            tmp = 0;
        }
        if(tmp + j >= K) {
            dp[K] += dp[j];
        } else {
            dp[tmp+j] += dp[j];
        }
    }
    return dp[K];
}
int main() {
    IN(N);
    IN(K);
    REP(i, N) {
        u32 tmp;
        IN(tmp);
        a.PB(tmp);
    }
    sort(rall(a));
    int maxCount = countSubSet(N);
    i32 l, m, r;
    l = -1;
    r = N;
    m = (l + r) / 2;
    // DEBUG(maxCount);
    while(r - l > 1) {
        u32 c = countSubSet(m);
        // printf("l: %d, m: %d, r: %d, c: %d\n", l, m, r, c);
        if(maxCount > c) {
            l = m;
        } else {
            r = m;
        }
        m = (l + r) / 2;
    }
    u32 c = countSubSet(m);
    while(c < maxCount) {
        m++;
    }
    cout << N - m << endl;

    return 0;
}

