bool judge(ll piv)
{
  ll target = A[piv];

  REP(i, 5001)
  {
    REP(j, 5001)
    {
      dp[i][j] = 0;
    }
  }
  dp[0][0] = 1;
  ll cnt = 0;
  REP(i, n)
  {
    if (i == piv)
      continue;
    ll x = A[i];
    REP(j, 5001)
    {
      if (j - x >= 0)
      {
        dp[cnt + 1][j] = dp[cnt][j - x] | dp[cnt][j];
      }
    }
    cnt++;
  }
  bool f = false;

  for (ll i = k - target; i < k; i++)
  {
    for (ll j = 0; j < dp.size() - 1; j++)
    {
      if (i < 1)
        continue;
      if (dp[j][i] == 1)
      {
        OUT2('i', 'j');
        OUT2(i, j);
        f = true;
        return f;
      }
    }
  }
  return f;
}

