bool dfs(int i, int sum, int k, int c) {
  // n個決め終わったら今までの和sumがkより大きいかを返す。
  if (i == n) return sum >= k - a[c] && sum < k;
  if (i == c) a[i]=0;
  // a[i]を足すとき。足したあとtrueが返ってきたらtrueを返す。
  if (dfs(i+1, sum+a[i], k, c)) return true;
  // a[i]を足さないとき。上と同様。
  if (dfs(i+1, sum, k, c)) return true;
  // どっちもtrueでなかったらfalseを返す。
  return false;
}
