bool C(int m)
{
	bool flag=false;
	int dp[5050]={1};
	for(int i=0;!flag&&i<n;i++)
	{
		if(i==m)continue;
		for(int j=k-a[i]-1;!flag&&j>=0;j--)
		{
			dp[j+a[i]]|=dp[j];
			if(dp[j+a[i]]&&j+a[i]>=k-a[m])flag=true;
		}
	}
	return flag;
}
