#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)

const int N_MAX = 5000;
const int K_MAX = 5000;
const int A_I_MAX = 1000000000;

int N, K;
int a[N_MAX];

void solve() {
  sort(a, a + N, greater<int>());
  int ans = N;
  int sum = 0;
  int need = 0;
  REP(i, N) {
    sum += a[i];
    need++;
    if (sum >= K) {
      ans -= need;
      sum = a[i];
      need = 0;
    }
  }
  printf("%d\n", ans);
}

void input() {
  scanf("%d%d", &N, &K);
  REP(i, N) scanf("%d", a + i);
}

int main() {
  input();
  solve();
  return 0;
}

