      if (!tmp[a[i + 1] + j]) {
        tmp[a[i + 1] + j] = true;
        r[i].insert(a[i + 1] + j);
      }
    }
  }

  int64_t m = 0;
  bool before;

  for (int64_t i = 0; i < n; i++) {
    if (k <= a[i]) {
      break;
    }
    if (0 < i && a[i - 1] == a[i]) {
      if (before) {
        m++;
      }
      continue;
    }

    bool flag = false;
    if (l[i].size() < r[i].size()) {
      for (const auto j : l[i]) {
        const auto max = k - 1 - j;
        const auto itr = --std::upper_bound(r[i].cbegin(), r[i].cend(), max);
        if (k <= *itr + j + a[i]) {
          flag = true;
          break;
        }
      }
    } else {
      for (const auto j : r[i]) {
        const auto max = k - 1 - j;
        const auto itr = --std::upper_bound(l[i].cbegin(), l[i].cend(), max);
        if (k <= *itr + j + a[i]) {
          flag = true;
          break;
        }
      }
    }
    if (!flag) {
      m++;
      before = true;
    } else {
      before = false;
    }
  }

  std::cout << m << std::endl;
  return 0;
}

