struct BS{
  static const size_t NE=(5001+63)/64;
  unsigned long long b[NE];
  bool operator[](size_t s)const{
    return b[s/64]>>s%64&1;
  }
  void slo(const size_t s)__attribute__((noinline)){
    if(s%64==0){
      for(int i=NE-1;i>=s/64;i--){
	b[i]|=b[i-s/64];
      }
    }else{
      unsigned long long p=b[NE-1-s/64];
      for(int i=NE-1;i>=1+s/64;i--){
	//	b[i]|=b[i-s/64]<<s%64|b[i-s/64-1]>>64-s%64;
	//	b[i]|=(((unsigned __int128)b[i-s/64])<<64|b[i-s/64-1])>>64-s%64;
	unsigned long long c=b[i-s/64-1];
	b[i]|=sr(p,c,64-s%64);
	p=c;
      }
      b[s/64]|=b[0]<<s%64;
    }
  }
  unsigned long long sr(unsigned long long h,unsigned long long l,unsigned char c){
    unsigned long long r;
    asm (
	 "shrd\t%%cl, %2, %0"
	 :"=r"(r)
	 :"c"(c),"r"(h),"0"(l)
	 );
    return r;
  }
};

