template<class T>class CulSum {
	int n; vector<T> s;
public:
	CulSum() {}
	template<class U>CulSum(const vector<U>& a) { set(a); }
	template<class U>void set(const vector<U>& a) {
		n = a.size(); s.resize(n + 1);
		for (int i = 0; i < n; ++i)s[i + 1] = s[i] + static_cast<T>(a[i]);
	}
	// [l,r)
	T operator()(int l, int r) {
		l = min(max(l, 0), n); r = min(max(r, 0), n);
		return l > r ? 0 : s[r] - s[l];
	}
	// [0,r)
	T operator()(int r) {
		r = min(max(r, 0), n);
		return s[r];
	}
	const vector<T>& get_s() { return s; }
};

