int main() {
	LL n = in, k = in;
	VL a = in[n];

	vector<VB> dp(n + 1, VB(k + 3));
	dp.front()[0] = true;
	rep(i, n)rep(j, k + 3) {
		if (dp[i][j])dp[i + 1][j] = true;
		if (j >= a[i] && dp[i][j - a[i]])dp[i + 1][j] = true;
	}
	vector<VB> dp2(n + 1, VB(k + 3));
	dp2.back()[0] = true;
	rrep(i, n)rep(j, k + 3) {
		if (dp2[i + 1][j])dp2[i][j] = 1;
		if (j >= a[i] && dp2[i + 1][j - a[i]])dp2[i][j] = 1;
	}
	vector<CulSum<int>> s2(n + 1);
	rep(i, n + 1)s2[i].set(dp2[i]);

	int ans = 0;
	rep(i, n) {
		if (a[i] > k)continue;
		int l = k - a[i], r = k;
		bool flag = false;
		rep(j, k)if (dp[i][j]) { // [a_0, a_i) の和が j
			if (s2[i + 1](l - j, r - j)) {
				flag = true;
			}
		}
		ans += !flag;
	}
	out(ans);
}

