typedef long long ll;
bool ldp[5005][5005], rdp[5005][5005];
int n, k;
int a[5005];

// 二分探索判定条件 O(k^2)
bool C(int id){
    for(int i = 0; i < k; ++i){
        for(int j = 0; j < k; ++j){
            if((ldp[id][i]&rdp[id + 1][j]) && ((i+j)>=k-a[id]&&(i+j)<k)){
                return true;
            }
        }
    }
    return false;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    for(int i = 0; i < n; ++i){
        cin >> a[i];
    }

    sort(a, a + n);

    ldp[0][0] = true;
    rdp[n][0] = true;
    for(int i = 0; i < n; ++i){
        for(int j = 0; j < k; ++j){
            if(j - a[i] >= 0){
                ldp[i + 1][j] |= ldp[i][j] | ldp[i][j - a[i]];
            }
            else{
                ldp[i + 1][j] |= ldp[i][j];
            }
        }
    }
    for(int i = n - 1; i >= 0; --i){
        for(int j = 0; j < k; ++j){
            if(j - a[i] >= 0){
                rdp[i][j] |= rdp[i + 1][j] | rdp[i + 1][j - a[i]];
            }
            else{
                rdp[i][j] |= rdp[i + 1][j];
            }
        }
    }

    int lb = -1, ub = n;
    while(ub - lb > 1){     // 二分探索 O(logn)
        int mid = (lb + ub) / 2;
        if(C(mid))  ub = mid;
        else        lb = mid;
    }

    cout << ub << endl;
}

