using vb = vector<bool>;
using vvb = vector<vb>;

int solve(long long N, long long K, vector<long long> &as);
int solve_core(long long K, vector<long long> &as);
void fill_dp(long long K, const vector<long long> &as, vvb & dp);
bool is_necessary(long long a, long long K, const vb &dpf, const vb &dpb);


int main() {
    long long N, K;
    cin >> N >> K;
    vector<long long> as(N, 0);
    for (auto & a : as) cin >> a;
    cout << solve(N, K, as) << endl;
    return 0;
}

int solve(long long N, long long K, vector<long long> &as){
    if (N == 1) return (as[0] >= K) ? 0 : 1;
    long long total = accumulate(as.begin(), as.end(), 0);
    if (total < K) return N;
    vector<long long> subset;
    for (auto a : as) if (a < K) subset.push_back(a);
    return solve_core(K, subset);
}


int solve_core(long long K, vector<long long> &as){
    int N = as.size();
    vector<vector<bool>> dpf(N + 1, vector<bool>(K, false));  // dpf[n][k] as[:n] の部分和を k にできるか否か
    vector<vector<bool>> dpb(N + 1, vector<bool>(K, false));  // dpb[n][k] as[n:] の部分和を k にできるか否か
    fill_dp(K, as, dpf);
    reverse(as.begin(), as.end());
    fill_dp(K, as, dpb);
    reverse(dpb.begin(), dpb.end());
    reverse(as.begin(), as.end());
    int ans = 0;
    for (int n = 0; n != N; ++n){
        if (not is_necessary(as[n], K, dpf[n], dpb[n + 1])) ++ans;
    }
    return ans;
}

void fill_dp(long long K, const vector<long long> &as, vvb &dp){
    // dp[n][k] as[:n] を用いて 部分和を k とできれば true できなければ false
    int n = 0;
    dp[0][0] = true;
    for (const auto a : as){
        ++n;
        dp[n] = dp[n - 1]; // 値がコピーされているのか？
        for (auto k = K - 1; k >= a; --k){
            if (dp[n - 1][k - a]) dp[n][k] = true;
        }
    }
}

bool is_necessary(long long a, long long K, const vb &dpf, const vb &dpb){
    // a が必要であるかどうか判断する。
    // dpf[k] as[:n] の部分和を k にできれば true, できなければ false
    // dpb[k] as[n+1:] の部分和を k にできれば true, できなければ false
    // 尺取り法の要領で、
    // K > k1 + k2 >= K - a && dpf[k1] && dpf[k2] となる k1, k2 があれば true, なければ false を返す。
    long long k2 = K - 1;
    for (long long k1 = 0; k1 < K; ++k1){
        if (not dpf[k1]) continue;
        while (k1 + k2 >= K) --k2;
        while (k2 >= 0 and k1 + k2 >= K - a) {
            if (dpb[k2]) return true;
            --k2;
        }
    }
    return false;
}

