    for (ll i = 1; i <= n; i++) {
        cin >> a[i];
    }

    for (ll x = 1; x <= n; x++) {
        for (ll i = 0; i <= n; i++) {
            for (ll j = 0; j <= k; j++) {
                dp[i][j] = 0;
            }
        }

        dp[0][0] = 1;
        for (ll i = 1; i <= n; i++) {
            for (ll j = 0; j <= k; j++) {
                dp[i][j] = dp[i - 1][j];

                if (j >= a[i] && i != x) {
                    dp[i][j] += dp[i - 1][j - a[i]];
                }
            }
        }

        bool f = (a[x] < k);
        for (ll i = max(0ll, k - a[x]); f && i < k; i++) {
            if (dp[n][i]) f = false;
        }

        if (f) ans++;
    }

    cout << ans << endl;

    return 0;
}

