int main(void) {
    int n, k;
    cin >> n >> k;
    vector<lint> a(n);
    repeat(i, n) cin >> a[i];
    sort(a.begin(), a.end());

    auto is_no_need = [](const vector<lint> &a, int lb, int ub) {
        int n = a.size();
        // dp[x][y] = x 枚目(0-index)まで使って総和を y にできるか
        vector<vector<bool>> dp(n, vector<bool>(ub+1, false));
        dp[0][0] = dp[0][a[0]] = true;
        repeat_from(x, 1, n) {
            repeat_from_to(y, 0, ub) {
                if (y-a[x] >= 0 && dp[x-1][y-a[x]]) dp[x][y] = true;
                if (dp[x-1][y]) dp[x][y] = true;
                if (dp[x-1][y] && y + a[x] >= ub) dp[x][ub] = true;
            }
        }
        bool ret = false;
        repeat_from(i, lb, ub) {
            if (dp[n-1][i]) {
                ret = true;
                break;
            }
        }
        return !ret;
    };

    auto judge = [=](int t) {
        vector<lint> arg_a = a;
        auto pos = lower_bound(arg_a.begin(), arg_a.end(), t);
        arg_a.erase(pos);
        return is_no_need(arg_a, k-t, k);
    };

    if (n == 1) {
        if (a[0] < k) cout << 1 << endl;
        else cout << 0 << endl;
        return 0;
    }
    auto it = partition_point(a.begin(), a.end(), judge);
    cout << distance(a.begin(), it) << endl;
    return 0;

}

