    }
    else{
        dp[1][a[1]]=1;
    }
    for(int i=1;i<n;i++){
        for(int j=0;j<k;j++){
            if(dp[i-1][j]==1){
                dp[i][j]=1;
                if(j+a[i]<k && i!=x){
                    dp[i][j+a[i]]=1;
                }
            }
        }
    }
    int ans=0;
