LL n,k;
vector<LL> a;

bool solve(LL y){
    vector<vector<bool>> dp(n+1,vector<bool>(k,false));
    dp[0][0] = true;
    for(int i = 1; i < n+1; i++){
        if(i == y+1){
            for(int j = 0; j < k; j++){
                dp[i][j] = dp[i-1][j];
            }
        }else{
            for(int j = 0; j < k; j++){
                dp[i][j] = dp[i-1][j];
                if(j - a[i-1] >= 0 && dp[i-1][j-a[i-1]]){
                    dp[i][j] = true;
                }
            }
        }
    }
    LL ind = 0;
    for(int i = k-1; i >= 0; i--){
        if(dp[n][i]){
            ind = i;
            break;
        }
    }
    return (ind+a[y] >= k);
}

