	if(j != s && k >= a[j] && dp[j-1][k-a[j]]) {
	  dp[j][k] = true;
	}
      }
    }
    for(int m = K - a[s]; m < K; m++) {
      if(dp[N-1][m]) {is = true; break;}
    }
    if(is) r = s;
    else l = s;

  }
  cout << r <<endl;
}

