pii md = {1000000007, 1000000009};
pii operator + (pii a, pii b){
	a.first += b.first;
	a.second += b.second;
	if(a.first >= md.first) a.first -= md.first;
	if(a.second >= md.second) a.second -= md.second;
	return a;
}
pii operator - (pii a, pii b){
	if(b.first) b.first = md.first - b.first;
	if(b.second) b.second = md.second - b.second;
	return a + b;
}
