        sum[i] = sum[i-1] + a[i];
    }
    set<int> se;
    se.insert(0);
    ll ans = 0;
    for (int i = id; i > 0; --i) {
        auto iter = se.end();
        iter--;
        if(*iter + sum[i] < K) {
            ans = i;
            break;
        }
        for (int x: se) {
            int t = x + a[i];
            if(t < K) se.insert(t);
        }
    }

    cout << ans << "\n";
    return 0;
}

