      if(dp[i][j] > 0) dp[i+1][j] = 1;
      if(dp[i][j] > 0) dp[i+1][min(5000LL, j + as[i])] = 1;
      if(rdp[i][j] > 0) rdp[i+1][j] = 1;
      if(rdp[i][j] > 0) rdp[i+1][min(5000LL, j + as[n-1-i])] = 1;
