const int MAX_N = 5000;

int N;
ll K;

ll A[MAX_N], dp1[MAX_N][MAX_N + 1], dp2[MAX_N][MAX_N + 1];

bool isNeeded(int i);

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> K;

    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    sort(A, A + N);
    dp1[0][A[0]] = 1;
    dp1[0][0] = 1;

    for (int j = 1; j < N; j++) {
        for (int k = 0; k < K; k++) {
            if (k >= A[j]) {
                dp1[j][k] = dp1[j - 1][k] + dp1[j - 1][k - A[j]];
            } else {
                dp1[j][k] = dp1[j - 1][k];
            }
        }
    }
    dp2[N - 1][A[N - 1]] = 1;
    dp2[N - 1][0] = 1;

    for (int j = N - 2; j >= 0; j--) {
        for (int k = 0; k < K; k++) {
            if (k >= A[j]) {
                dp2[j][k] = dp2[j + 1][k] + dp2[j + 1][k - A[j]];
            } else {
                dp2[j][k] = dp2[j + 1][k];
            }
        }
    }


    int ans = 0;
    ll lmax, lmin;
    if (isNeeded(0)) {
        ans = 0;
    } else if (!isNeeded(N - 1)) {
        ans = N;
    } else {
        lmax = N - 1;
        lmin = 0;
        while (true) {
            ll lmid = (lmin + lmax) / 2;

            if (lmid == lmin || lmid == lmax) {
                ans = lmin + 1;
                break;
            }
            if (isNeeded(lmid)) {
                lmax = lmid;
            } else {
                lmin = lmid;
            }
        }
    }

    cout << ans << "\n";

    return 0;
}

bool isNeeded(int i)
{
    if (i != 0 && i != N - 1) {
        for (int s = max(0LL, K - A[i]); s < K; s++) {
            for (int t = 0; t <= s; t++) {

                if (dp1[i - 1][t] != 0 && dp2[i + 1][s - t] != 0) {
                    return true;
                }
            }
        }
        return false;
    } else if (i == 0) {
        for (int s = max(0LL, K - A[0]); s < K; s++) {
            if (dp2[1][s] != 0) {
                return true;
            }
        }
        return false;
    } else {
        for (int s = max(0LL, K - A[N - 1]); s < K; s++) {
            if (dp1[N - 2][s] != 0) {
                return true;
            }
        }
        return false;
    }
}

