    if(a[1] < K){
      cout << 1 << endl;
      return 0;
    }else{
      cout << 0 << endl;
      return 0;
    }
  }
  // binary_search
  ll left = 0, right = N;
  // (left, right]
  while(right - left > 1){
    ll mid = (left + right)/2;
    if(isneed(mid)){
      right = mid;
    }else{
      left = mid;
    }
  }
  if(right == N && !isneed(N)) cout << N << endl;
  else cout << right - 1 << endl;
}

