  for(int i=0; i < N; i++)
    cin >> A[i];
  vector<vector<bool> >dp(N,vector<bool>(K));
  int ans = 0;
  for(int i=0; i < N; i++){
    long long int ai = A[i];
    A[i] = 0;
    for(int y=0; y < K; y++){
      if(A[0]==y)
	dp[0][y] = true;
      else
        dp[0][y] = false;
    }
    for(int x=0; x < N; x++){
      dp[x][0] = true;
    }
    for(int x=1; x < N; x++){
      for(int y=1; y < K; y++){
	if(y-A[x] >= 0){
	  dp[x][y] = dp[x][y-A[x]];
	}else{
	  dp[x][y] = dp[x-1][y];
	}
      }
    }
    bool need = false;
    int s;
    if(K < ai) s = 0;
    else s = K-ai;
    for(int a=s; a < K; a++){
      if(dp[N-1][a]){
        need = true;
        break;
      }
    }
    if(need == false) ans++;
    A[i] = ai;
  }
  cout << ans << endl;
  return 0;
}

