bool solve(int n, int k, const vector<int>& a, int mid) {
    const int w = a[mid];
    vector<int> b(a);
    b[mid] = INF;

    vector<int> dp(k + 1);
    vector<int> dp_next(k + 1);

    // no card, no sum
    fill(dp.begin(), dp.end(), 0);

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= k; j++) {
            dp_next[j] = dp[j];
            if (j - b[i] > 0) {
                max(dp_next[j], b[i] + dp[j - b[i]]);
            }
        }
        dp = dp_next;
    }

    return dp[k] + w < k;
}

