        for( int j = 0; j <= k; ++j ) {
            dp[i][j] = false;

        }
    }

    for( int i = 0; i < n; ++i ) {
        if( i == 0 && i == pos ) continue;

        dp[i][0] = true;
        for( int j = 1; j < k; ++j ) {
            if( i == pos ) {
                dp[i][j] = dp[i - 1][j];
