bool Solve(int pos) {
    for( int i = 0; i < n; ++i ) {
        for( int j = 0; j <= k; ++j ) {
            dp[i][j] = false;

        }
    }

    for( int i = 0; i < n; ++i ) {
        if( i == 0 && i == pos ) continue;

        for( int j = 1; j < k; ++j ) {
            if( i == pos ) {
                dp[i][j] = dp[i - 1][j];
                continue;

            }

            if( i == 0 ) {
                if( v[i] == j ) {
                    dp[i][j] = true;

                }
            } else {
                if( v[i] == j ) {
                    dp[i][j] = true;

                } else if( v[i] < j ) {
                    dp[i][j] = dp[i - 1][j - v[i]];

                }
                if( dp[i - 1][j] ) dp[i][j] = true;
            }
        }
    }

