bool dp[MAX_N][MAX_K]; // dp[x][y] := x 枚目をみたとき、総和を y にできるか？

bool solve(int x){
	if (a[x] >= K) return false;

	memset(dp, false, sizeof(dp));
	dp[0][0] = true;
	rep (j, N){
		rep (k, K){
			if (dp[j][k]){
				dp[j+1][k] |= true;
				if (x != j && k + a[j] < K) dp[j+1][k+a[j]] |= true;
			} // end if
		} // end rep
	} // end rep

	bool need = false;
	rep(k, K){
		if (dp[N][k] && k + a[x] >= K){
			need |= true;
		} // end if
	} // end for

	return !need;
}

