	} // end rep

	sort(a, a + N);

	int ok = 0;
	int ng = N;
	while(abs(ok - ng) > 1){
		int mid = (ok + ng) / 2;
		if (solve(mid)){
			ok = mid;
		}else{
			ng = mid;
		} // end if
	} // end while

	cout << ok + 1 << endl;

	return 0;
}

