    for(j = 0; j + a[i] <= k; ++j) if(dpf[i ][j]) dpf[i + 1][j + a[i]] = true;
  }
  for(i = n; i; --i) {
    for(j = 0; j < k; ++j) dpb[i - 1][j] = dpb[i][j];
    for(j = 0; j + a[i - 1] < k; ++j) if(dpb[i][j]) dpb[i - 1][j + a[i - 1]] = true;
  }
