int main()
{
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    rep(i, n)
    {
        cin >> a[i];
    }

    vector<vector<bool>> dp1(n + 1, vector<bool>(k)), dp2(n + 1, vector<bool>(k));
    irep(i, n) rep(j, k)
    {
        if (i == 0) {
            dp1[i][j] = dp2[n - i][j] = (j == 0);
        } else {
            dp1[i][j] = dp1[i - 1][j] || (j - a[i - 1] >= 0 && dp1[i - 1][j - a[i - 1]]);
            dp2[n - i][j] = dp2[n - (i - 1)][j] || (j - a[n - i] >= 0 && dp2[n - (i - 1)][j - a[n - i]]);
        }
    }

    int result = 0;
    rep(i, n)
    {
        vector<int64_t> psum(k + 1);
