  std::vector<int32_t> a(n);
  std::cin >> a;
  std::sort(a.begin(), a.end());

  std::vector<std::set<int16_t>> l(n), r(n);

  l[0].insert(0);
  std::vector<bool> tmp(k, false);

  for (int64_t i = 1; i < n; i++) {
    l[i] = l[i - 1];
    if (k <= a[i - 1]) {
      continue;
    }
    for (const auto j : l[i - 1]) {
      if (k <= a[i - 1] + j) {
        break;
      }
      if (!tmp[a[i - 1] + j]) {
        tmp[a[i - 1] + j] = true;
        l[i].insert(a[i - 1] + j);
      }
    }
  }

  r[n - 1].insert(0);
  std::fill(tmp.begin(), tmp.end(), false);
  tmp[0] = true;

  for (int64_t i = n - 2; 0 <= i; i--) {
    r[i] = r[i + 1];
    if (k <= a[i + 1]) {
      continue;
    }
    for (const auto j : r[i + 1]) {
      if (k <= a[i + 1] + j) {
        break;
      }
      if (!tmp[a[i + 1] + j]) {
        tmp[a[i + 1] + j] = true;
        r[i].insert(a[i + 1] + j);
      }
    }
  }
  tmp.clear();
  tmp.shrink_to_fit();
  std::cout << "po" << std::endl;
  int64_t m = 0;
  bool before;

  for (int64_t i = 0; i < n; i++) {
    if (k <= a[i]) {
      break;
    }
    if (0 < i && a[i - 1] == a[i]) {
      if (before) {
        m++;
      }
      continue;
    }

    bool flag = false;
    if (l[i].size() < r[i].size()) {
      for (const auto &j : l[i]) {
        const auto max = k - 1 - j;
        const auto itr = *(--std::upper_bound(r[i].cbegin(),
          r[i].cend(), max));
        if (k <= itr + j + a[i]) {
          flag = true;
          break;
        }
      }
    } else {
      for (const auto &j : r[i]) {
        const auto max = k - 1 - j;
        const auto itr = *(--std::upper_bound(l[i].cbegin(),
          l[i].cend(), max));
        if (k <= itr + j + a[i]) {
          flag = true;
          break;
        }
      }
    }
    if (!flag) {
      m++;
      before = true;
    } else {
      before = false;
    }
  }

  std::cout << m << std::endl;
  return 0;
}

