		}
		if (!f && a[i] < k)ans++;
	}
	if (k - a[n - 1] - 1 >= 0 && dp[0][n - 2][k - 1] == dp[0][n - 2][k - a[n - 1] - 1] && a[n - 1] < k)ans++;
	else if (k - a[n - 1] - 1 < 0 && dp[0][n - 2][k - 1] == 0 && a[n - 1] < k)ans++;
