const int K = 5555;
signed main() { 
  ios::sync_with_stdio(false); cin.tie(0);
  int n, k;
  cin >> n >> k;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }
  vector<bitset<K>> dp_front(n + 2);
  vector<bitset<K>> dp_back(n + 2);
  dp_front[0][0] = 1;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < K; j++) {
      if (!dp_front[i][j]) continue;
      dp_front[i + 1][j] = 1;
      if (j + a[i] >= K) continue;
      dp_front[i + 1][j + a[i]] = 1;
    }
  }
  dp_back[n + 1][0] = 1;
  for (int i = n; i >= 1; i--) {
    for (int j = 0; j < K; j++) {
      if (!dp_back[i + 1][j]) continue;
      dp_back[i][j] = 1;
      if (j + a[i - 1] >= k) continue;
      dp_back[i][j + a[i - 1]] = 1;
    }
  }
  int ans = 0;
  for (int i = 1; i <= n; i++) {
    bitset<K> cur = dp_front[i - 1] | dp_back[i + 1];
    bool none = true;
    for (int j = 0; j < K; j++) {
      if (cur[j] && j + a[i - 1] >= k) none = false;
    }
    if (none) {
      ans++;
      continue;
    }
    bool need = false;
    for (int j = max(k - a[i - 1], 1); j < k; j++) {
      if (cur[j]) {
        need = true;
      }
    }
    if (!need) {
      ans++;
    }
  }
  cout << ans << '\n';
  return 0;
}

