	for(int i = 1; i <= n; ++i) {
		for(int j = k - 1; j >= a[i]; --j) {
			dp[j].add(dp[j - a[i]]);
		}
	}
	int fp = 0;
	for(int i = 1; i <= n; ++i) {
		if(a[i] >= k) continue;
		for(int j = a[i]; j < k; ++j) {
			dp[j].sub(dp[j - a[i]]);
		}
		fp += aa0(k - a[i]);
		for(int j = k - 1; j >= a[i]; --j) {
			dp[j].add(dp[j - a[i]]);
		}
	}
	cout << fp << endl;
	return 0;
}

