int N, K, a[5010];
bool dp[5010][5010];

// 必要ならば true
bool d(int x) {
    if(a[x] > K) return true;
    memset(dp, false, sizeof(dp));
    dp[0][0] = true;
    rep(i,0,N) repq(j,0,K) {
        dp[i+1][j] |= dp[i][j];
        if(i != x) dp[i+1][min(K, j+a[i])] |= dp[i][j];
    }
    bool ret = false;
    rep(i,max(0LL, K-a[x]),K) {
        ret |= dp[N][i];
    }
    return ret;
}

signed main() {
