bool L[5010][5001], R[5010][5001];
int N, K;

void pre(vector<int>& a){
  REP(i, N+1){
    L[i][0] = 1;
    R[i+1][0] = 1;
  }

  REP(i, N) REP(j, K){
    if(j-a[i] >= 0) L[i+1][j] |= (L[i][j] or L[i][j-a[i]]);
    else L[i+1][j] |= L[i][j];
  }

  for(int i = N+1; i >= 2; i--){
    REP(j, K){
      if(j-a[i-2] >= 0) R[i-1][j] |= (R[i][j] or R[i][j-a[i-2]]);
      else R[i-1][j] |= R[i][j];
      // if(j > 0) R[i-1][j] += R[i-1][j-1];
    }
  }
}

signed main(void){
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N >> K;
  vector<int> A(N);
  REP(i, N) cin >> A[i];
  sort(ALL(A));

  pre(A);

  int left = -1, right = N;
  while(right - left > 1){
  	int mid = (left+right) / 2;
  	bool necessary = 0;
  	for(int sum = max(0ll, K-A[mid]); sum < K; sum++){
  		REP(i, sum+1){
  			necessary |= (L[mid][i] and R[mid+2][sum-i]);
  		}
  	}
  	cerr << mid << ' ';
  	if(necessary) {
  		right = mid;
  		cerr << "necessary" << endl;
  	}else{
  		left = mid;
  		cerr << "no need" << endl;
  	}
  }
  cout << right << endl;

  return 0;
}

