  while (true) {
    if ((tgt < n-1 && flg[tgt] == -1 && flg[tgt+1] == 1) || (tgt == n-1 && flg[tgt] == -1) || (tgt == 0 && flg[tgt] == 1)) {
      break;
    }
    if (flg[tgt] != 0) {
      if (tgt == n-1 || flg[tgt+1] != 0) {
        tgt--;
        continue;
      } else {
        tgt++;
        continue;
      }
    }
    if (flg[tgt] == 0){
      bool m[k];
      for (int i = 0; i < k; ++i) {
        m[i] = false;
      }
      m[0] = true;
      for (int i = 0; i < n; ++i) {
        if (i == tgt) {
          continue;
        }
        for (int j = k-a[i]-1; j >= 0; --j) {
          if (m[j]) {
            m[j+a[i]] = true;
          }
