        }
      }
      if (ok) {
        flg[tgt] = 1;
        tgt = (bottom+tgt)/2;
        top = tgt;
      } else {
        flg[tgt] = -1;
        tgt = (top+tgt)/2;
        bottom = tgt;
      }
    }
  }
  if (flg[0] == 1) {
    cout << 0 << endl;
  } else {
    for (int i = 0; i < n-1; ++i) {
      if (flg[i] == -1 && flg[i+1] == 1) {
