bool need(int t)
{
	// cout << a[t] << endl;
	if(a[t] >= k) return true;
	for(int i = 0; i <= n; i++){
		for(int j = 0; j <= k; j++){
			sum[i][j] = 0;
		}
	}
	for(int i = 1; i <= n; i++){
		if(i != t) sum[i][min(k, a[i])]++;
	}
	for(int i = 1; i < n; i++){
		for(int j = 0; j <= k; j++){
			if(sum[i + 1][j] == 0) sum[i + 1][j] = sum[i][j];
			if(i + 1 == t) continue;
			if(sum[i][j] == 0) continue;
			sum[i + 1][(int)min((long long int)k, (long long int)j + a[i + 1])] = sum[i][j];
		}
	}
	// for(int i = 1; i <= n; i++){
	// 	for(int j = 1; j <= k; j++){
	// 		cout << sum[i][j] << " ";
	// 	}
	// 	cout << endl;
	// }
	for(int i = max(0, k - a[t]); i < k; i++){
		if(sum[n][i] > 0) return true;
	}
	return false;
}

int main()
{
	cin >> n >> k;
	for(int i = 1; i <= n; i++){
		cin >> a[i];
	}
	sort(a + 1, a + n + 1);
	if(a[0] >= k){
		cout << 0 << endl;
		return 0;
	}
	int l = 0, r = n + 1;
	while(r - l > 1){
		int mid = (r + l) / 2;
		if(need(mid)) r = mid;
		else l = mid;
	}
	cout << l << endl;
	return 0;
}

