          needs++;
          b = true;
          break;
        }
        continue;
      }

      if (i == n - 1) {
        if (dp[n - 1][nv]) {
          needs++;
          b = true;
          break;
        }
        continue;
      }

      for (int nv2 = 0; nv2 <= nv; ++nv2) {
        if (dp[i][nv2] && dp2[n - i - 1][nv - nv2]) {
          b = true;
          needs++;
          break;
        }
      }

      if (b)
        break;
    }
  }

  cout << n - needs << "\n";
  return 0;
}

