    for (int j = 0; j < k; j++) {
      if (dpr[i+1][j] == 1 and j + a < k) {
        dpr[i][j + a] = 1;
      }
    }
  }

  int ans = n;
  Conv conv(k*2);
  for (int i = 1; i <= n; i++) {
