int main(int argc, char const* argv[])
{
	int n,k;
	cin >> n >> k;
	VL a(n);
	cin >> a;
	SORT(a);
	bool dp[n+1][k];
	auto init = [&](){
		for (int i = 0; i <= n; i++) {
			for (int j = 0; j < k; j++) {
				dp[i][j] = false;
			}
		}
		dp[0][0] = true;
	};
	init();

	auto isOk = [&](LL mid){
		for (int i = 0; i <= n; i++) {
			if (mid == (i-1)) {
				continue;
			}
			for (int j = k-1; j >= 0; j--) {
				if (dp[i][j] and j + a[mid] >= k) {
					return false;
				}
			}
		}
		return true;
	};

	//上界，下界が自明なら小さくしても良い
	LL ok = -1, ng = n;
	while (ng - ok > 1) {
		LL mid = (ng + ok) / 2;
		for (int i = 1; i <= n; i++) {
			if (mid == (i-1)) {
				for (int j = 0; j < k; j++) {
					dp[i][j] = dp[i-1][j];
				}
				continue;
			}
			for (int j = 0; j < k; j++) {
				dp[i][j] = (dp[i-1][j] or dp[i][j]);
			}
			for (int j = 0; j + a[i-1] < k; j++) {
				if (dp[i-1][j]) {
					dp[i][j+a[i-1]] = true;
				}
			}
		}
		(isOk(mid) ? ok : ng) = mid;
		init();
	}
	if (ng == -1)
		cout << 0 << endl;
	else
		cout << ok+1 << endl;
	return 0;
}

