//    bitDPをやっている bitsは左からi番目までbits2は右からi番目までのやつ
    bits[0][0]=1;
    REP(i,n){
        bits[i]=bits[i-1]<<a[i];
        bits[i]|=bits[i-1];
    }
    bits2[n+1][0]=1;
    for (int i=n; i>=1; i--) {
        bits2[i]=bits2[i+1]<<a[i];
        bits2[i]|=bits2[i+1];
    }
    REP(i,n){
        vector<int> v1,v2;
        rep(j,k+1){
            if(bits[i-1][j])v1.emplace_back(j);
        }
        rep(j,k+1){
            if(bits2[i+1][j])v2.emplace_back(j);
        }
        int p=k-a[i];
        bool did=0;
        rep(j,v1.size()){
            int basho=lower_bound(ALL(v2),p-v1[j])-v2.begin();
            if (basho<v2.size()) {
                if (v2[basho]+v1[j]<k) {
                    did=1;
                    break;
                }
            }
        }

        if (!did) {
            ans++;
        }
    }
    cout<<ans<<endl;
}

