void solve() {
  sort(a, a + N, greater<int>());
  int ans = N;
  int sum = 0;
  int need = 0;
  REP(i, N) {
    sum += a[i];
    need++;
    if (sum >= K) {
      ans -= need;
      sum = a[i];
      need = 0;
    }
  }
  printf("%d\n", ans);
}

