  for (auto &val : A){
    cin >> val;
  }
  sort(A.begin(), A.end());
  int left,right;
  left = -1;
  right = N;
  while (right - left > 1){
    int med = (right + left) / 2;
    if (med >= N){
      right--;
      continue;
    }else if(med < 0){
      left++;
      continue;
    }
    src = med;
    memset(dp, -1, sizeof(dp));
    tabooo.emplace(med);

    int res = memo(0, 0);
    tabooo.erase(med);
    if (res > 0){//necessary
      right = med;
    }else{//unnecessary
      left = med;
      for (int i = 0; i <= med; i++){
        tabooo.emplace(i);
      }
    }
  }
  cout << tabooo.size() << endl;

  return 0;
}

