	for(int i = n - 1;i>-1;i--){
		if(da[i] > k) {dpp[i] = dpp[i+1];continue;}
		dpp[i] = (dpp[i + 1] << da[i])|dpp[i + 1];
		dpp[i].set(0);
	}
	int ans = 0;
	rip(i,n,0){
		if(da[i] > k) continue;
		bitset<L> now, add = dpp[i + 1];
		rip(j,L,0){
			if(dp[i].test(j)){
				now |= add;
			}
			add <<= 1;
		}
		//cout << now << endl;
		rip(j, k, k-da[i]){
			if(now.test(j)) {ans--;break;}
		}
		ans ++;
	}
	//vdeb(dp);
	//vdeb(dpp);
	cout << ans << endl;
}

