bool isNeeded(int i)
{
    if (i != 0 && i != N - 1) {
        for (int s = max(0, K - A[i]); s < K; s++) {
            for (int t = 0; t <= s; t++) {
                //cout << "s = " << s << ", t = " << t << ",dp1 = " << dp1[i - 1][t] << ", dp2 = " << dp2[i + 1][s - t] << "\n";
                if (dp1[i - 1][t] && dp2[i + 1][s - t]) {
                    return true;
                }
            }
        }
        return false;
    } else if (i == 0) {
        if (N == 1) {
            if (A[0] >= K) {
                return true;
            } else {
                return false;
            }
        }
        for (int s = max(0, K - A[0]); s < K; s++) {
            if (dp2[1][s]) {
                return true;
            }
        }
        return false;
    } else {
        for (int s = max(0, K - A[N - 1]); s < K; s++) {
            if (dp1[N - 2][s]) {
                return true;
            }
        }
        return false;
    }
}

