    int b = A[i];
    for(set<int>::iterator it = dp.begin(); it != dp.end(); it++) {
      int v = *it;
      dp2.insert(v);
      if (v+b < K-a) {
        dp2.insert(v+b);
      } else if (v+b < K) {
        return true;
      }
    }
    dp = dp2;
  }
  return false;
}

