int N, K;

int memo[5010][5010];
int isPossible(int pos, int x) {
  int& res = memo[pos][x];
  if(res < 0) {
    if (pos == N) {
      res = x == 0;
    } else {
      res = isPossible(pos+1, x);
      if(x-vs[pos] >= 0) {
        res = res || isPossible(pos+1, x-vs[pos]);
      }
    }
  }
  return res;
}

int main(void) {
  cin >> N >> K;
  REP(i, N) {
    cin >> vs[i];
  }
  sort(vs, vs + N);
  memset(memo, -1, sizeof memo);
  int res = N;
  REP(i, N) {
    if(i > 0 && vs[i] == vs[i-1]) {
      needed[i] = needed[i-1];
    } else {
      for(int x = max(K-vs[i], 0LL); x < K; ++x) {
        needed[i] = needed[i] || isPossible(i+1, x);
      }
    }
    if(needed[i]) {
      // cerr << " " << i << endl;
      --res;
    }
  }
  cout << res << endl;

  return 0;
}

