//a_nを除いたカードで数が作れるか
void jud(int n){
  bool dp[5001];
  fill(dp,dp+5001,false);
  dp[0] = true;
  for(int i=0;i<N;i++){
    if(i == n) continue;

    for(int j=K;j>=0;j--){
      if(dp[j] && j + a[i] <= K){
        dp[j + a[i]] = true;
      }
    }
  }

  for(int i=K-a[n];i<K;i++){
    if(dp[i]){
      need[n] = 1;
      return;
    }
  }

  need[n] = 0;
  return;
}

int bs(int a, int b){
  int p = (a + b) / 2;
  jud(p);

  if(a == b){
    if(a == 0 && need[0] == 1) return -1;
    else if(a == N-1 && need[N-1] == 0) return N-1;
    else if(need[a]) return a-1;
    else if(!need[a]) return a;
  }
  else {
    if(need[p]){
      return bs(a,p-1);
    } else {
      return bs(p+1,b);
    }
  }
}

