    for(int i=1;i<=N;++i){
        std::cin >> as[i];
    }

    dp[0][0] = 1;
    for(int i=1;i<=N;++i){
        for(int j=0;j<K;++j){
            dp[i][j] |= dp[i-1][j];
            if(j - as[i] >= 0){
                dp[i][j] |= dp[i-1][j-as[i]];
            }
        }
    }

