    for(int i=N;i>=1;--i){
        for(int j=0;j<K;++j){
            dp2[i][j] |= dp2[i+1][j];
            if(j - as[i] >= 0){
                dp2[i][j] |= dp2[i+1][j-as[i]];
            }
        }
    }    

    int res = 0;
