int sum_digits(int num) {    
	int rtn = 0;    
	while(num != 0) {    
		int tmp = num % 10;    
		rtn += tmp;    
		num /= 10;    
	}    
	return rtn;    
}    

// vectorのコピー    
template <class T>    
vector<T> copy_vector(vector<T> vec) {    
	vector<T> rtn;    
	rtn.reserve(vec.size());    
	copy(vec.begin(), vec.end(), back_inserter(rtn));    
	return rtn;    
}    

long gcd(long a, long b) {    
	if(b==0) return a;    
	else return gcd(b, a % b);    
}

long lcm(long a, long b) {
	long gcd_ = gcd(a, b);
	return (a * b) / gcd_;
}

vector<vector<long>> comb(long n, long r) {                                                                             
	vector<vector<long>> v(n+1, vector<long>(n+1, 0));    
	for(int i=0; i<v.size(); i++) {    
		v[i][0] = 1;    
		v[i][i] = 1;    
	}    
	for(int i=1; i<v.size(); i++) {    
		for(int j=1; j < i; j++) {    
			v[i][j] = (v[i-1][j-1] + v[i-1][j]) % DIVIDE;    
		}    
	}    
	return v;    
} 

