int N, K;

int A[MAX_N], dp[MAX_N][MAX_N + 1];

bool isNeeded(int i);

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> K;

    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }
    int ans;
    int amin, amax;
    bool needCalc = true;

    sort(A, A + N);
    if (isNeeded(0)) {
        ans = 0;
        needCalc = false;
    } else {
        amin = 0;
    }

    if (!isNeeded(N - 1)) {
        ans = N;
        needCalc = false;
    } else {
        amax = N - 1;
    }

    if (needCalc) {
        while (true) {
            int amid = (amin + amax) / 2;
            if (amid == amin || amid == amax) {
                ans = amax;
                break;
            }
            if (isNeeded(amid)) {
                amax = amid;
            } else {
                amin = amid;
            }
        }
    }

    cout << ans << "\n";

    return 0;
}

bool isNeeded(int i)
{
    int s;
    if (i != 0) {
        dp[0][A[0]] = 1;
        s = 1;
    } else {
        dp[1][A[1]] = 1;
        s = 2;
    }
    for (int j = s; j < N; j++) {
        for (int k = 0; k <= K; k++) {
            if (i == j) {
                dp[j][k] = dp[j - 1][k];
            } else {
                if (k >= A[j]) {
                    dp[j][k] = dp[j - 1][k] + dp[j - 1][k - A[j]];
                } else {
                    dp[j][k] = dp[j - 1][k];
                }
            }
        }
    }
    int ans = 0;
    for (int k = K - A[i]; k < K; k++) {
        ans += dp[N - 1][k];
    }
    memset(dp, 0, sizeof(dp));
    return ans != 0;
}

