    vector<int>a(N);
    for (int i = 0; i < N; ++i) {
        cin >> a[i];
    }
    a.push_back(0);
    sort(a.begin(), a.end());
    // K以上のカードは必要
    // K未満のカードを上から見ていって作れるK未満の最大値を更新していく
    int id = N;
    while (a[id] >= K) id--;
    if(id == 0) {
        cout << N << "\n";
        return 0;
    }
    vector<int>sum(id+1, 0);
    for (int i = 1; i <= id; ++i) {
        sum[i] = sum[i-1] + a[i];
    }
    set<int> se;
    se.insert(0);
    ll ans = 0;
    for (int i = id; i > 0; --i) {
        auto iter = se.end();
        iter--;
        if(*iter + sum[i] < K) {
            ans += i;
            break;
        }
        stack<int> st;
        for (int x: se) {
            int t = x + a[i];
            if(t < K) st.push(t);
        }
        while (! st.empty()){
