const int mod = MOD;
int n, k, arr[5005];
int Forward[5005][5005], backward[5005][5005][2], DP[5005][5005];

int fun(int ind, int rem)
{
	if (ind == n && rem == 0) return 1;
	if (ind == n) return 0;
	if (DP[ind][rem] != -1) return DP[ind][rem];

	// I go
	int res = 0;
	backward[ind][rem][1] = fun(ind+1, max(0, rem-arr[ind]));
	res += backward[ind][rem][1];
	res %= mod;

	// I dont go

	backward[ind][rem][0] = fun(ind+1, rem);
	res += backward[ind][rem][0];
	res %= mod;

	return DP[ind][rem] = res;
}
bool upper = true;
int fun2(int ind, int rem)
{
	if (rem < 0)
	{
		if (! upper) return 0;
		rem = 0;
	}
	if (ind == n && rem == 0) return 1;
	if (ind == n) return 0;
	if (DP[ind][rem] != -1) return DP[ind][rem];

	// I go
	int res = 0;
	int temp = fun2(ind+1,rem-arr[ind]);
	res += temp;
	res %= mod;

	// I dont go

	Forward[ind][rem] = fun2(ind+1, rem);
	res += Forward[ind][rem];
	res %= mod;

	return DP[ind][rem] = res;
}

inline int mul(int A, int B){return (((ll) A)*B) % mod;}
void solve()
{

	cin >> n >> k;
	rep(i,0,n) cin >> arr[i];
	memset(DP, -1, sizeof DP); memset(backward, 0, sizeof backward);


	rep(i,0,k+1)fun(0, i);

	reverse(arr, arr+n);

	memset(DP, -1, sizeof DP); memset(Forward, 0, sizeof Forward);

	fun2(0, k);
	upper = false;

	memset(DP, -1, sizeof DP);
	rep(i,0,n)rep(j,0,k)Forward[i][j] = 0;
	rep(i,0,k)fun2(0, i);

	reverse(arr, arr+n);

	int ans = 0;

	rep(i,0,n)
	{
		int num_with_me = 0, num_without_me = 0;

		rep(j,0,k+1)
		{
				num_with_me += mul( Forward[n-i-1][j], backward[i][k-j][1]);
				num_with_me %= mod;


				num_without_me += mul( Forward[n-i-1][j], backward[i][k-j][0]);
				num_without_me %= mod;

		}
		if (num_without_me == num_with_me) ans++;
	}
	cout << ans << "\n";
}
