// 二分探索判定条件
bool C(int id){
    for(int i = 0; i < k; ++i){
        for(int j = 0; j < k; ++j){
            if((ldp[id][i]&rdp[id + 1][j]) && ((i+j)>=k-a[id]&&(i+j)<k)){
                return true;
            }
        }
    }
    return false;
}

int main(){
