        cout << (a[0] < k) << endl;
        return 0;
    }

    sort(a, a + n);

    ldp[0][0] = true;
    rdp[n][0] = true;
    for(int i = 0; i < n; ++i){
        for(int j = 0; j < k; ++j){
            if(j - a[i] >= 0){
                ldp[i + 1][j] |= ldp[i][j] | ldp[i][j - a[i]];
            }
            else{
                ldp[i + 1][j] |= ldp[i][j];
            }
        }
    }
    for(int i = n - 1; i >= 0; --i){
        for(int j = 0; j < k; ++j){
            if(j - a[i] >= 0){
                rdp[i][j] |= rdp[i + 1][j] | rdp[i + 1][j - a[i]];
            }
            else{
                rdp[i][j] |= rdp[i + 1][j];
            }
        }
    }

    int lb = 0, ub = n;
    while(ub - lb > 1){
        int mid = (lb + ub) / 2;
        if(C(mid))  ub = mid;
        else        lb = mid;
    }

    cout << ub << endl;
}

