static const int MAXN = 5e3 + 10;
typedef long long LL;
LL data[MAXN];
LL sum[MAXN];
int n , k;
bitset<MAXN> dp;
bool Check(int x)
{
	if(data[x] >= k)
		return 1;
	dp.reset();
	dp[0] = 1;
	for(int i = 0 ; i < n ; ++i)
	{
		if(x == i)
			continue;
		dp |= (dp << data[i]);
	}
	for(int i = k - 1 ; i >= k - data[x] ; --i)
	{
		if(dp[i])
			return 1;
	}
	return 0;

}
int Solve()
{
	sort(data , data + n);
	int l = 0 , r = n - 1 , mx = -1;
	while(l <= r)
	{
		int mid = l + r >> 1;
		if(Check(mid))
			r = mid - 1;
		else
		{
			l = mid + 1;
			mx = max(mx , mid);
		}
	}
	return mx + 1;
}
