    scanf("%d %d", &N, &K);
    for(int i = 0; i < N; ++i) scanf("%lld", &a[i]);
    sort(a.begin(), a.begin() + N, greater<ll>());

    for(int i = 0; i < N - 1; ++i) a[i + 1] += a[i];

    int ans = 0;
    for(int i = 0; i < N; ++i){

        if((!i && a[i] >= K) || (i && a[i] - a[i - 1] >= K)){ ans = i + 1; continue; }

        ll H = (i) ? K - (a[i] - a[i - 1]) : K - a[i];

        int idx = -1;

        for(int j = N - 1; j > i; --j){
            if(H <= a[j] - a[j - 1] && a[j] - a[j - 1] < K){ idx = j; break; }
        }
        for(int j = i + 1; j < N; ++j){
            if(H <= a[j] - a[i] && a[j] - a[i] < K){ idx = max(idx, j); break; }
        }

        ans = max(ans, idx + 1);

    }
    printf("%d\n", N - ans);

    return 0;
}

