  }
  res = 0;
  res |= memo(pos + 1, val);
  if (res > 0){
    return res;
  }
  if (not tabooo[pos]){
    res |= memo(pos + 1, min(K, val + A[pos]));
    if (res > 0){
      return res;
    }
  }

  return res;
}


