class Ntt {
 public:
  using int_type = unsigned long long;
  static constexpr int_type P = 998244353;
  using mint = Modular<P>;
  using value_type = mint;
 private:
  size_t n_;
  mint r_;
  std::vector<mint> coeff_;
  std::vector<mint> icoeff_;
  size_t log_n_;
  size_t clz_n_;

 public:
  explicit Ntt(size_t size) {
    if (size == 0)
      return;
    clz_n_ = bm::clz(size-1)-1;
    log_n_ = 63 - clz_n_;
    n_ = 1ull << log_n_;
    assert((P-1)%n_ == 0);
    r_ = pow(mint{3}, (P-1)/n_);
    coeff_.resize(log_n_);
    icoeff_.resize(log_n_);
    mint iw = mint{1}/r_;
    mint w = r_;
    for (int i = log_n_-1; i >= 0; i--) {
      coeff_[i] = iw;
      iw *= iw;
      icoeff_[i] = w;
      w *= w;
    }
  };

  size_t n() const { return n_; }

  void fft_inline(std::vector<mint>& f) const {
    _fft(f);
  }

  std::vector<mint> fft(const std::vector<mint>& f) const {
    auto ff = f;
    ff.resize(n_, 0);
    _fft(ff);
    return ff;
  }

  void ifft_inline(std::vector<mint>& f) const {
    _ifft(f);
  }

  std::vector<mint> ifft(const std::vector<mint>& f) const {
    auto ff = f;
    ff.resize(n_, 0);
    _ifft(ff);
    return ff;
  }

 private:
  template <bool Forward>
  void _fft_impl(std::vector<mint>& f) const {
    // iterative bit reversal
    for (size_t i = 0, j = 1; j < n_-1; j++) {
      for (size_t k = n_ >> 1; k > (i ^= k); k >>= 1);
      if (i < j) std::swap(f[i], f[j]);
    }
    // Cooley-Tukey FFT
    for (size_t log_m = 0; log_m < log_n_; log_m++) {
      size_t m = 1ull<<log_m;
      mint w0 = Forward ? coeff_[log_m] : icoeff_[log_m];
      for (size_t chunk = 0; chunk < n_; chunk += 2*m) {
        mint w = 1;
        for (size_t i = 0; i < m; i++) {
          auto p = chunk + i;
          auto a = f[p + 0];
          auto b = f[p + m] * w;
          f[p + 0] = a + b;
          f[p + m] = a - b;
          w *= w0;
        }
      }
    }

  }

  void _fft(std::vector<mint>& f) const {
    _fft_impl<true>(f);
  }
  void _ifft(std::vector<mint>& f) const {
    _fft_impl<false>(f);
    mint div_n = mint{1}/n_;
    for (auto& x : f)
      x *= div_n;
  }

};
