        int n = a.size();
        if (lb < 0) lb = 0;
        // dp[x][y] = x 枚目(0-index)まで使って総和を y にできるか
        vector<vector<bool>> dp(n, vector<bool>(ub+1, false));
        dp[0][0] = true;
