                if (y-a[x] >= 0 && dp[x-1][y-a[x]]) dp[x][y] = true;
                if (dp[x-1][y]) dp[x][y] = true;
                if (dp[x-1][y] && y + a[x] >= ub) dp[x][ub] = true;
            }
        }
        bool ret = false;
        repeat_from(i, lb, ub) {
            if (dp[n-1][i]) {
                ret = true;
                break;
            }
        }
        return !ret;
    };

