bool f(vi & v , int & n , int & k , int t){
	vi dp(555555 , 0);
	vi mn(555555 , -1);

	dp[0] = 1;
	rep(i , n){
		if(i != t){
			rep(j , k){
				if(dp[j] && mn[j] != i){
					if(j + v[i] < k){
						dp[j + v[i]] = 1;
						if(mn[j + v[i]] == -1){
							mn[j + v[i]] = i;
						}
					}
				}
			}
		}
	}

