	for (int i = 0; i < N; i++) {
		cin >> a[i];
	}
	sort(a, a + N);

	dp[0][0] = 1;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < K; j++) {
			dp[i + 1][j] += dp[i][j];
			if (j + a[i] < K) {
				dp[i + 1][j + a[i]] += dp[i][j];
			}
		}
	}

	int ans = N;
	for (int i = 0; i < N; i++) {
		if (a[i] > K) {
			ans--;
			continue;
		}
		ll dplast[5000 + 10];
		for (int j = 0; j < K; j++)dplast[j] = dp[N][j];
		for (int j = 0; j < K; j++) {
			//dpを一回さし戻す
			if (j + a[i] < K)dplast[j + a[i]] -= dplast[j];
		}
		for (int j = K - a[i]; j <= K - 1; j++) {
			if (dplast[j] > 0) {
				ans--;
				break;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

