void swap(unsigned *num1, unsigned *num2)
{
	int swp = *num1;
	*num1 = *num2;
	*num2 = swp;
}

void sort(unsigned a[5000], unsigned n)
{
	unsigned i, p;

	for(i=0; i<n; i++){
		for(p=n-1; 0<p; p--){
			if(a[p-1] > a[p])
				swap(&a[p-1], &a[p]);
			if(p == i)
				break;
		}
	}
}

