int main(void)
{
	unsigned n, k;
	unsigned card[5000];
	unsigned sum = 0;
	unsigned ans = 0;
	unsigned i;

	//データ読み込み
	scanf("%u %u", &n, &k);
	for(i=0; i<n; i++)
		scanf("%u", &card[i]);

	/*----全集合の総和がk未満→全て不必要( END )----*/
	if(all_sum(card, n) < k){
		printf("%u\n", n);

		return 0;
	}

	//数値が大きい順にソート
	sort(card, n);

	//k以上のカードは必要
	//総和がk以上になった番数(i)までの集合→i番目以降のカードは必要
	for(i=0; (sum<k&&i<n); i++){
		if(card[i] < k)
			sum += card[i];
		else
			break;
	}
	n = i;	/* iをnに代入 */

	/*----総和がk以上になった番数(i)までの集合の総和がk未満
							→i番目以下のカードは不必要( END )----*/
	if(sum < k){
		printf("%u\n", n);

		return 0;
	}

	//不必要なカードを取り出す
	for(i=0; i<n; i++){
		if(k <= sum-card[i]){
			sum -= card[i];
			ans++;
		}
		else
			break;
	}

	/* 取り出したカードの枚数を出力( END ) */
	printf("%u\n", ans);


	return 0;
}

