struct heap_t{
	int idnum;
	int atai;
}heap[5010];

int sz=-1;

void push(int x,int y){
	//自分のノード番号
	int i;
	sz++;
	i=sz;

	while(i>0){
		//親のノード番号
		int p=(i-1)/2;
		//もう逆転していないなら抜ける
		if(heap[p].atai<=x) break;
		//親のノードの数字を下ろして、自分は上に
		heap[i]=heap[p];
		i=p;
	}
	heap[i].atai=x;
	heap[i].idnum=y;
}

int pop(){
	int ret;
	int a,b;
	int x,y;
	int i;
	//最小値
	ret=heap[0].atai;
	//根に持ってくる値
	x=heap[sz].atai;
	y=heap[sz].idnum;
	sz=sz-1;
	//根からおろしていく
	i=0;
	while(i*2+1<=sz){
		a=i*2+1;
		b=i*2+2;
		if(b<sz&&heap[b].atai<heap[a].atai) a=b;
		//もう逆転していないなら終わり
		if(heap[a].atai>=x) break;
		//子の数字を持ち上げる
		heap[i]=heap[a];
		i=a;
	}
	heap[i].atai=x;
	heap[i].idnum=y;

	return ret;
}


