	    if ((ll)d[med] >= mi) r1 = med;
	    else l1 = med;
	  }
	}
	int l2 = 0, r2 = x;
	if (ma < 0) continue;
	else {
	  while (r2 - l2 > 1) {
	    med = (r2 + l2) / 2;
	    if ((ll)d[med] <= ma) l2 = med;
	    else r2 = med;
	  }
	}

	if (l2 - r1 >= 0) {
	  ans++; break;
	}
      }
    }
  }

  printf("%d\n", n - ans);

  return 0;
}

