	int *a = (int *)malloc(sizeof(int) * N);
	int inf = N;
	for(i = 0; i < N; i++){
		scanf("%d", &a[i]);
	}
	int *inc = (int *)malloc(sizeof(int) * K);
	int *dec = (int *)malloc(sizeof(int) * K);
	for(i = 1; i < K; i++){
		inc[i] = inf;
		dec[i] = inf;
	}
	inc[0] = -1;
	dec[0] = -1;
	int sum = 0;
	for(i = 0; i < N; i++){
		sum = min(sum + a[i], K - 1);
		for(j = sum; j >= a[i]; j--){
			if(inc[j - a[i]] != inf && inc[j] == inf){
				inc[j] = i;
			}
		}
	}
	sum = 0;
	for(i = N - 1; i >= 0; i--){
		sum = min(sum + a[i], K - 1);
		for(j = sum; j >= a[i]; j--){
			if(dec[j - a[i]] != inf && dec[j] == inf){
				dec[j] = i;
			}
		}
	}
	int need = 0, k, l;
	for(i = 0; i < N; i++){
		for(k = 0, l = K - 1;;){
			while(inc[k] >= i){
				k++;
				if(k >= K){
					break;
				}
			}
			while((dec[l] <= i || dec[l] == inf) && dec[l] != -1){
				l--;
				if(l < 0){
					break;
				}
			}
			if(k >= K || l < 0 ){
				break;
			}
			if(k + l < K - a[i]){
				k++;
			}
			else if(k + l >= K){
				l--;
			}
			else{
				need++;
				break;
			}
		}
	}
	printf("%d\n", N - need);
	return 0;
}

