void Qsort(int x[], int left, int right){
	int i,j;
	int pivot;
	i=left;
	j=right;
	pivot=x[(left+right)/2];
	while(1){
		while(x[i]<pivot)
			i++;
		while(pivot<x[j])
			j--;
		if(i>=j)
			break;
		swap(x,i,j);
		i++;
		j--;
	}
	if(left<i-1)
		Qsort(x,left,i-1);
	if(j+1<right)
		Qsort(x,j+1,right);
}

void swap(int x[],int i,int j){
	int temp;
	temp=x[i];
	x[i]=x[j];
	x[j]=temp;
}

#include<stdio.h>
#include<stdlib.h>

#define F 1

//const int mod[F]={1000000009,1000000021,1000000033,1000000087};
const int mod[F]={5077};

typedef struct hashNode{
  int hash[F];
} node;

node add(node a,node b){
  node x;
  for(int i=0;i<F;i++){
    x.hash[i]=(a.hash[i]+b.hash[i])%mod[i];
  }
  return x;
}

node minus(node a,node b){
  node c;
  for(int i=0;i<F;i++){
    c.hash[i]=(a.hash[i]-b.hash[i]+mod[i])%mod[i];
  }
  return c;
}

int isZero(node a){
  for(int i=0;i<F;i++) if(a.hash[i]>0) return 0;
  return 1;
}

void run(void){
  int n,k;
  scanf("%d%d",&n,&k);
  int *a=(int *)calloc(n,sizeof(int));
  int i,j;
  for(i=0;i<n;i++) scanf("%d",a+i);
  node *dp=(node *)calloc(k,sizeof(node));
  for(i=0;i<F;i++) dp[0].hash[i]=1;
  for(i=0;i<n;i++){
    for(j=k-1;j-a[i]>=0;j--){
      dp[j]=add(dp[j],dp[j-a[i]]);
    }
  }
  node *dp2=(node *)calloc(k,sizeof(node));
  int ans=0;
  for(i=0;i<n;i++){
    if(a[i]>=k) continue;
    for(j=0;j<a[i];j++) dp2[j]=dp[j];
    for(j=a[i];j<k;j++){
      dp2[j]=minus(dp[j],dp2[j-a[i]]);
    }
    for(j=k-1;j>=k-a[i];j--) if(!isZero(dp2[j])) break;
    if(j<k-a[i]) ans++;
  }
  printf("%d\n",ans);
}

int main(void){
  run();
  return 0;
}

