int equal(int a,int b,long int *A){
    return A[a]!=A[b]?a:equal(b,b+1,A);
}

int binarySearch(int left,int right,long int *A,int key){
    int mid;
    long int mini=0;
    while(left<=right){
        mid=(left+right)/2;
        if(A[mid]==key){
            mid=equal(mid,mid+1,A);
            return mid;
        }
        else if(A[mid]>key){
            mini=A[mid];
            if(left!=mid) left=mid;
            else left+=1;
        }
        else{
            if(mid==right) return right;
            right=mid-1;
        }
    }
    return mid;
}


