#include <stdio.h>

void merge_sort(int x[], int n)
{
	static int y[5001] = {};
	if (n <= 1) return;
	merge_sort(&(x[0]), n/2);
	merge_sort(&(x[n/2]), (n+1)/2);

	int i, p, q;
	for (i = 0, p = 0, q = n/2; i < n; i++) {
		if (p >= n/2) y[i] = x[q++];
		else if (q >= n) y[i] = x[p++];
		else y[i] = (x[p] < x[q])? x[p++]: x[q++];
	}
	for (i = 0; i < n; i++) x[i] = y[i];
}

int main()
{
	int i, N, K, a[5001];
	scanf("%d %d", &N, &K);
	for (i = 0; i < N; i++) scanf("%d", &(a[i]));
	merge_sort(a, N);

	char dp[2][5001][5001] = {};
	int j, k, n, ans = 0;
	for (n = N - 1; n >= 0 && a[n] >= K; n--) ans++;
	for (i = 0, dp[0][0][0] = 1; i <= n; i++) {
		for (k = 0; k < a[i]; k++) dp[0][i+1][k] = dp[0][i][k];
		for (; k <= K; k++) dp[0][i+1][k] = dp[0][i][k] | dp[0][i][k-a[i]];
	}
	for (i = n, dp[1][n+1][0] = 1; i >= 0; i--) {
		for (k = 0; k < a[i]; k++) dp[1][i][k] = dp[1][i+1][k];
		for (; k <= K; k++) dp[1][i][k] = dp[1][i+1][k] | dp[1][i+1][k-a[i]];
	}
	for (i = 0; i <= n; i++) {
		for (j = 0, k = K - 1; j < K; j++) {
			if (dp[0][i][j] == 0) continue;
			for (; k >= 0 && (j + k >= K || dp[1][i+1][k] == 0); k--);
			if (k >= 0 && j + k >= K - a[i]) {
				ans++;
				break;
			}
		}
