int
main(int argc, const char *argv[])
{
  int n, k, a[5000];
  scanf("%d %d", &n, &k);
  for (int i = 0; i < n; i++) scanf("%d", &a[i]);

  sdp[0][0] = true;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j <= k; j++) {
      sdp[i + 1][j] = sdp[i][j];
      if (j - a[i] >= 0) sdp[i + 1][j] |= sdp[i][j - a[i]];
    }
  }

  gdp[n + 1][0] = true;
  for (int i = n - 1; i >= 0; i--) {
    for (int j = 0; j <= k; j++) {
      gdp[i + 1][j] = gdp[i + 2][j];
      if (j - a[i] >= 0) gdp[i + 1][j] |= gdp[i + 2][j - a[i]];
    }
  }

  int ans = 0;
  for (int i = 1; i <= n; i++) {
    int x = 0; ll d[5001];
    for (int j = 0; j <= k; j++) {
      if (gdp[i + 1][j]) d[x++] = (ll)j;
    }
    for (int j = 0; j <= k; j++) {
      if (sdp[i - 1][j]) {
	ll mi = (ll)k - (ll)a[i - 1] - (ll)j, ma = (ll)(k - 1 - j);
	ll l1 = -1, r1 = (ll)(x - 1), med;
	if (mi <= 0) r1 = 0;
	if (mi > d[x - 1]) continue;
	if (mi > 0) {
	  while (r1 - l1 > 1) {
	    med = (r1 + l1) / 2;
	    if (d[med] >= mi) r1 = med;
	    else l1 = med;
	  }
	}
	ll l2 = 0, r2 = (ll)x;
	if (ma < 0) continue;
	else {
	  while (r2 - l2 > 1) {
	    med = (r2 + l2) / 2;
	    if (d[med] <= ma) l2 = med;
	    else r2 = med;
	  }
	}

	if (l2 - r1 >= 0) {
	  ans++; break;
	}
      }
    }
  }

  printf("%d\n", n - ans);

  return 0;
}

