    return dp[i][j];
  int res;
  if(i == N)
    res = 0;
  else if(j < a[i])
    res = rec_dp(i+1,j);
  else if(j - a[i] == 0)
    return 1;
  else{
    t1 = dp[i+1][j] = rec_dp(i+1,j);
    t2 = dp[i+1][j-a[i]] = rec_dp(i+1,j-a[i]);
    res = t1 || t2;
  }
  return dp[i][j] = res;
}

void QuickSort(int array[],int first,int last)
{
  int tmp,i=first,j=last,std=array[i];
  while(1){
    while(array[i] < std)
      i++;
    while(array[j] > std)
      j--;
    if(i>=j)
      break;
    tmp = array[i];
    array[i] = array[j];
    array[j] = tmp;
  }
  i--;
  j++;
  if(i-first>0)
    QuickSort(array,first,i);
  if(last-j>0)
    QuickSort(array,j,last);
}

int BinalySearch(int a[],int first,int last,int tar)
{
  int mid = (first+last)/2;
  if(first +1 == last)
    return mid;
  else if(a[mid] < tar)
    return BinalySearch(a,mid,last,tar);
  else
    return BinalySearch(a,first,mid,tar);

}

