  gdp[n + 1][0] = true;
  for (int i = n - 1; i >= 0; i--) {
    for (int j = 0; j <= k; j++) {
      gdp[i + 1][j] = gdp[i + 2][j];
      if (j - a[i] >= 0) gdp[i + 1][j] |= gdp[i + 2][j - a[i]];
    }
  }

  int ans = 0;
  for (int i = 1; i <= n; i++) {
    int x = 0; int d[5001];
    for (int j = 0; j <= k; j++) {
      if (gdp[i + 1][j]) d[x++] = (ll)j;
    }
    for (int j = 0; j <= k; j++) {
      if (sdp[i - 1][j]) {
	ll mi = (ll)k - (ll)a[i - 1] - (ll)j, ma = (ll)(k - 1 - j);
	int l1 = -1, r1 = x - 1, med;
	if (mi <= 0) r1 = 0;
	if (mi > (ll)d[x - 1]) continue;
	if (mi > 0) {
	  while (r1 - l1 > 1) {
	    med = (r1 + l1) / 2;
	    if ((ll)d[med] >= mi) r1 = med;
	    else l1 = med;
	  }
	}
	int l2 = 0, r2 = x;
	if (ma < 0) continue;
	else if (ma >= d[x - 1]) l2 = x - 1;
	else {
	  while (r2 - l2 > 1) {
	    med = (r2 + l2) / 2;
	    if ((ll)d[med] <= ma) l2 = med;
	    else r2 = med;
	  }
	}

	if (l2 - r1 >= 0) {
	  ans++; break;
	}
      }
    }
  }

  printf("%d\n", n - ans);

  return 0;
}

