class Program {
    fun solve() {
        val sc = FastScanner()
        val n = sc.nextInt()
        val k = sc.nextInt()
        val a = (1..n).map { sc.nextInt() }.sorted()

        // 前 [0,i)で作れるか
        val front = Array(n) { BitSet(k + 1) }
        front[0][0] = true
        for (i in 0 until n - 1) {
            front[i + 1].or(front[i])
            for (j in 0..k) {
                if (front[i][j]) {
                    front[i + 1][Math.min(j + a[i], k)] = true
                }
            }
        }

        // 後ろ (i, n)で作れるか
        val back = Array(n) { BitSet(k + 1) }
        back[n - 1][0] = true
        for (i in n - 1 downTo 1) {
            back[i - 1].or(back[i])
            for (j in 0..k) {
                if (back[i][j]) {
                    back[i - 1][Math.min(j + a[i], k)] = true
                }
            }
        }

        // カードiが不必要 iより小さいカードも不必要

        // 必要か？
        var ok = n
        var ng = -1

        while (ok - ng > 1) {
            val med = (ok + ng) / 2
            var flag = false
            for (i in 0..k) {
                if (!front[med][i]) continue
                if (k - i - a[med] < 0 ) continue
                for (j in k - i - a[med] until k - i) {
                    if (!back[med][j]) continue
                    if (i + j < k && k <= i + j + a[med]) {
                        flag = true
                    }
                }
            }
            if (flag) {
                ok = med
            } else {
                ng = med
            }
        }

        println(ok)
    }
}


class FastScanner {
    companion object {
        val input: InputStream = System.`in`
        val buffer = ByteArray(1024) { 0 }
        fun isPrintableChar(c: Int): Boolean = c in 33..126
    }

    var ptr = 0
    var buflen = 0
    private fun hasNextByte(): Boolean {
        if (ptr < buflen) {
            return true
        } else {
            ptr = 0
            buflen = input.read(buffer)
            if (buflen <= 0) {
                return false
            }
        }
        return true
    }

    private fun readByte(): Int = if (hasNextByte()) buffer[ptr++].toInt() else -1

    private fun skipUnprintable() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr].toInt())) ptr++
    }

    fun hasNext(): Boolean {
        skipUnprintable()
        return hasNextByte()
    }

    fun next(): String {
        if (!hasNext()) throw NoSuchElementException()
        val sb = StringBuilder()
        var b = readByte()
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b)
            b = readByte()
        }
        return sb.toString()
    }

    fun nextInt(): Int {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0
        var b = readByte()
        // '-' = 45
        val minus = b == 45
        if (minus) {
            b = readByte()
        }

        // '0' = 48 '9' = 57
        if (b !in 48..57) {
            throw NumberFormatException()
        }

        while (true) {
            if (b in 48..57) {
                n *= 10
                n += b - 48
            } else if (b == -1 || !isPrintableChar(b)) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun nextLong(): Long {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0L
        var b = readByte()
        // '-' = 45
        val minus = b == 45
        if (minus) {
            b = readByte()
        }

        // '0' = 48 '9' = 57
        if (b !in 48..57) {
            throw NumberFormatException()
        }

        while (true) {
            if (b in 48..57) {
                n *= 10
                n += b - 48
            } else if (b == -1 || !isPrintableChar(b)) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun nextDouble(): Double = next().toDouble()
}

