    val arr = readLine()!!.split(" ").map { it.toInt() }
    val front = Array(n+1){TreeSet<Int>()}
    val back = Array(n+1){TreeSet<Int>()}

    front[0].add(0)
    back[0].add(0)

    for(i in 1..n) {
        val prev = front[i-1]
        val v = arr[i - 1]
        for(d in prev) {
            front[i].add(d)
            if(d + v < k)
                front[i].add(d + v)
        }
        if(v < k)
            front[i].add(v)
    }

    for(i in 1..n) {
        val prev = back[i-1]
        val v = arr[n - i]
        for(d in prev) {
            back[i].add(d)
            if(d + v < k)
                back[i].add(d + v)
        }
        if(v < k)
            back[i].add(v)
    }

    var ans = 0
    for(i in 0 until n) {
        if(arr[i] >= k)
            continue
        val upper = k - arr[i]
        val f = front[i]
        val b = back[n - 1 - i]
        var hasFind = false

        for(d in f) {
            if(d >= upper) {
                hasFind = true
                break
            }
            val higher = b.higher(upper - d - 1) ?: continue
            if(higher + d < k) {
