//            dp[next][j] = min(dp[next][j], dp[cur][j-v] + 1)
//            dp[next][j] =  dp[next][j] or dp[cur][j-v]
            dp[next][j] += dp[cur][j-v]
            if(dp[next][j] >= inf) {
                dp[next][j] = inf
            }
        }
        cur = (cur + 1) % 2
        next = (next + 1) % 2
    }

