class Program {
    fun solve() {
        val sc = FastScanner()
        val n = sc.nextInt()
        val k = sc.nextInt()
        val a = (1..n).map { sc.nextInt() }

        // a[i]が必要になる条件
        // a[i]を含む良い集合の総和 - a[i] < kになる良い集合が存在する

        // [0,i)で作れる値 (i,n)で作れる値を持っておく [
        // 前 f 後ろ b
        // f + b < k <= f + b + a[i]
        // k - f - a[i] <= b < k - f
        //

        val f = Array(n) { Array(k + 1) { false } }
        f[0][0] = true
        for (i in 0 until n - 1) {
            for (j in 0..k) {
                if (f[i][j]) {
                    f[i + 1][j] = true
                    f[i + 1][Math.min(k, j + a[i])] = true
                }
            }
        }



        val b = Array(n) { SegmentTree({ l, r -> l + r }, 0) }
        b[n - 1][0] = 1

        for (i in n - 1 downTo 1) {
            for (j in 0..k) {
                if (b[i][j] == 1) {
                    b[i - 1][j] = 1
                    b[i - 1][Math.min(k, j + a[i])] = 1
                }
            }
        }

        var ans = n

        for (i in 0 until n) {
            var flag = false
            for (j in 0 until k) {
                if (f[i][j] && b[i].query(k - j - a[i], k - j) > 0) {
                    flag = true
                    break
                }
            }
            if (flag) ans--
        }

        println(ans)
    }
}

class SegmentTree<T>(private val op: (T, T) -> T, private val id: T) {
    companion object {
        const val size = 1 shl 13
    }

    @Suppress("UNCHECKED_CAST")
    private val array = Array<Any?>(size * 2) { id } as Array<T>

    operator fun get(i: Int) = array[i + size]
    operator fun set(i: Int, n: T) = update(i, n)

    fun update(i: Int, n: T) {
        var index = i + size
        array[index] = n
        while (index > 1) {
            index /= 2
            array[index] = op(array[index * 2], array[index * 2 + 1])
        }
    }

    private fun query(left: Int, right: Int, k: Int, l: Int, r: Int): T {
        if (left <= l && r <= right) {
            return array[k]
        }

        if (r <= left || right <= l) {
            return id
        }

        return op(query(left, right, k * 2, l, (l + r) / 2), query(left, right, k * 2 + 1, (l + r) / 2, r))
    }

    fun query(left: Int, right: Int) = query(left, right, 1, 0, size)
}


