val pw = PrintWriter(System.out)
val MOD: Long = (1e+9 + 7).toLong()

fun main(args: Array<String>) {
	val (n, k) = readListOfInt()
	val aArr = readListOfInt().sorted()

	var l = 0
	var r = n

	while(l < r) {
		val removed = (l+r) / 2
		val dp = Array(n+1) { Array(k+1) { false } }
		dp[0][0] = true
		for(i in 0 until n) {
			val a = aArr[i]
			// スコアj
			for(j in 0 .. k) {
				// 使ってない場合
				dp[i+1][j] = dp[i+1][j] || dp[i][j]
				// 使った場合
				if(i != removed) {
					dp[i+1][Math.min(k, j+a)] = dp[i+1][Math.min(k, j+a)] || dp[i][j]
				}
			}
		}
		val isNeeded = dp[n].slice(Math.max(0, k-aArr[removed]) until k).any { it }
		if(!isNeeded) {
			l = removed + 1
		} else {
			r = removed
		}
	}
	println(l)

	pw.flush()
}

