class Program {
    fun solve() {
        val sc = MyScanner()
        val (n, k) = sc.intList()
        val a = sc.intList().filter { it < k }.sorted()

        // k以上 必要
        // iが必要 -> i以上も必要
        // i以外で良くない集合、iを足すと良い集合になる
        // できるなら必要
        val front = Array(a.size + 1) { Array(k) { false } }
        front[0][0] = true
        for (i in a.indices) {
            for (j in 0 until k) {
                if (front[i][j]) {
                    if (j + a[i] < k) {
                        front[i + 1][j + a[i]] = true
                    }
                    front[i + 1][j] = true
                }
            }
        }

        val back = Array(a.size + 1) { Array(k) { false } }
        back[a.size][0] = true
        for (i in a.size downTo 1) {
            for (j in 0 until k) {
                if (back[i][j]) {
                    if (j + a[i - 1] < k) {
                        back[i - 1][j + a[i - 1]] = true
                    }
                    back[i - 1][j] = true
                }
            }
        }

        var ok = a.size
        var ng = -1
        while (ok - ng > 1) {
            val mid = (ok + ng) / 2
            val f = mutableListOf<Int>()
            val b = mutableListOf<Int>()
            for (i in 0 until k) {
                if (front[mid][i]) f.add(i)
                if (back[mid + 1][i]) b.add(i)
            }
            var flag = false
            for (i in f.indices) {
                var ok2 = 0
                var ng2 = b.size
                while (ng2 - ok2 > 1) {
                    val mid2 = (ok2 + ng2) / 2
                    if (f[i] + b[mid2] < k) ok2 = mid2
                    else ng2 = mid2
                }
                if (f[i] + b[ok2] + a[mid] >= k) {
                    flag = true
                    break
                }
            }

            if (flag) ok = mid
            else ng = mid
        }

        println(ok)
    }
}

