class Program {
    fun solve() {
        val sc = FastScanner()
        val n = sc.nextInt()
        val k = sc.nextInt()
        val a = (1..n).map { sc.nextInt() }

        // a[i]が必要になる条件
        // a[i]を含む良い集合の総和 - a[i] < kになる良い集合が存在する

        // [0,i)で作れる値 (i,n)で作れる値を持っておく [
        // 前 f 後ろ b
        // f + b < k <= f + b + a[i]
        // k - f - a[i] <= b < k - f
        //

        val f = Array(n) { Array(k + 1) { false } }
        f[0][0] = true
        for (i in 0 until n - 1) {
            for (j in 0..k) {
                if (f[i][j]) {
                    f[i + 1][j] = true
                    f[i + 1][Math.min(k, j + a[i])] = true
                }
            }
        }



        val b = Array(n) { SegmentTree({ l, r -> l + r }, 0) }
        b[n - 1][0] = 1

        for (i in n - 1 downTo 1) {
            for (j in 0..k) {
                if (b[i][j] == 1) {
                    b[i - 1][j] = 1
                    b[i - 1][Math.min(k, j + a[i])] = 1
                }
            }
        }

        var ans = n

        for (i in 0 until n) {
            var flag = false
            for (j in 0 until k) {
                if (f[i][j] && b[i].query(k - j - a[i], k - j) > 0) {
                    flag = true
                    break
                }
            }
            if (flag) ans--
        }

        println(ans)
    }
}

class SegmentTree<T>(private val op: (T, T) -> T, private val id: T) {
    companion object {
        const val size = 1 shl 14
    }

    @Suppress("UNCHECKED_CAST")
    private val array = Array<Any?>(size * 2) { id } as Array<T>

    operator fun get(i: Int) = array[i + size]
    operator fun set(i: Int, n: T) = update(i, n)

    fun update(i: Int, n: T) {
        var index = i + size
        array[index] = n
        while (index > 1) {
            index /= 2
            array[index] = op(array[index * 2], array[index * 2 + 1])
        }
    }

    private fun query(left: Int, right: Int, k: Int, l: Int, r: Int): T {
        if (left <= l && r <= right) {
            return array[k]
        }

        if (r <= left || right <= l) {
            return id
        }

        return op(query(left, right, k * 2, l, (l + r) / 2), query(left, right, k * 2 + 1, (l + r) / 2, r))
    }

    fun query(left: Int, right: Int) = query(left, right, 1, 0, size)
}


class FastScanner {
    companion object {
        val input: InputStream = System.`in`
        val buffer = ByteArray(1024) { 0 }
        fun isPrintableChar(c: Int): Boolean = c in 33..126
    }

    var ptr = 0
    var buflen = 0
    private fun hasNextByte(): Boolean {
        if (ptr < buflen) {
            return true
        } else {
            ptr = 0
            buflen = input.read(buffer)
            if (buflen <= 0) {
                return false
            }
        }
        return true
    }

    private fun readByte(): Int = if (hasNextByte()) buffer[ptr++].toInt() else -1

    private fun skipUnprintable() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr].toInt())) ptr++
    }

    fun hasNext(): Boolean {
        skipUnprintable()
        return hasNextByte()
    }

    fun next(): String {
        if (!hasNext()) throw NoSuchElementException()
        val sb = StringBuilder()
        var b = readByte()
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b)
            b = readByte()
        }
        return sb.toString()
    }

    fun nextInt(): Int {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0
        var b = readByte()
        // '-' = 45
        val minus = b == 45
        if (minus) {
            b = readByte()
        }

        // '0' = 48 '9' = 57
        if (b !in 48..57) {
            throw NumberFormatException()
        }

        while (true) {
            if (b in 48..57) {
                n *= 10
                n += b - 48
            } else if (b == -1 || !isPrintableChar(b)) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun nextLong(): Long {
        if (!hasNext()) throw NoSuchElementException()
        var n = 0L
        var b = readByte()
        // '-' = 45
        val minus = b == 45
        if (minus) {
            b = readByte()
        }

        // '0' = 48 '9' = 57
        if (b !in 48..57) {
            throw NumberFormatException()
        }

        while (true) {
            if (b in 48..57) {
                n *= 10
                n += b - 48
            } else if (b == -1 || !isPrintableChar(b)) {
                return if (minus) -n else n
            } else {
                throw NumberFormatException()
            }
            b = readByte()
        }
    }

    fun nextDouble(): Double = next().toDouble()
}

fun main() {
    val (n,k) = readLine()!!.split(" ").map { it.toInt() }
    val arr = readLine()!!.split(" ").map { it.toInt() }.sorted()

    fun isNecessary(idx:Int): Boolean {
        if(arr[idx] >= k)
            return true
        val dp = Array(2){BooleanArray(k+1){false} }
        var cur = 0
        var next = 1
        dp[cur][0] = true
        dp[next][0] = true

        for(i in arr.indices) {
            if(i == idx) continue
            val v = arr[i]
            for(j in 1..k) {
                dp[next][j] = dp[cur][j]
            }
            for(j in 1..k) {
                if(j - v < 0) continue
                dp[next][j] =  dp[next][j] or dp[cur][j-v]
                if(j >= k - arr[idx] && j <= k - 1 && dp[next][j])
                    return true
            }
            cur = (cur + 1) % 2
            next = (next + 1) % 2
        }
        return false
    }
    var ans = 0
    var l = 0
    var r = n - 1
    while(l <= r) {
        val mid = (l + r) / 2
        if(isNecessary(mid)) {
            r = mid - 1
            ans = mid
        } else {
            l = mid + 1
        }
    }
    print(ans)
    // 2 3 4 10 10 25
    // 0 1 2 3 4 5
}

