class Program {
    fun solve() {
        val sc = FastScanner()
        val n = sc.nextInt()
        val k = sc.nextInt()
        val a = (1..n).map { sc.nextInt() }.sorted()

        // 前 [0,i)で作れるか
        val front = Array(n) { BitSet(k + 1) }
        front[0][0] = true
        for (i in 0 until n - 1) {
            front[i + 1].or(front[i])
            for (j in 0..k) {
                if (front[i][j]) {
                    front[i + 1][Math.min(j + a[i], k)] = true
                }
            }
        }

        // 後ろ (i, n)で作れるか
        val back = Array(n) { BitSet(k + 1) }
        back[n - 1][0] = true
        for (i in n - 1 downTo 1) {
            back[i - 1].or(back[i])
            for (j in 0..k) {
                if (back[i][j]) {
                    back[i - 1][Math.min(j + a[i], k)] = true
                }
            }
        }

        // カードiが不必要 iより小さいカードも不必要

        // 必要か？
        var ok = n
        var ng = -1

        while (ok - ng > 1) {
            val med = (ok + ng) / 2
            var flag = false
            for (i in 0..k) {
                if (!front[med][i]) continue
                if (k - i - a[med] < 0 || k - i - a[med] >= k - i) continue
                for (j in k - i - a[med] until k - i) {
                    if (!back[med][j]) continue
                    if (i + j < k && k <= i + j + a[med]) {
                        flag = true
                    }
                }
            }
            if (flag) {
                ok = med
            } else {
                ng = med
            }
        }

        println(ok)
    }
}


