fun main(args: Array<String>) {
    val (N, K) = readLine()!!.split(" ").map{it.toInt()}
    val a = readLine()!!.split(" ").map{it.toInt()}

    fun func(a: List<Int>): Array<TreeSet<Int>> {
        val dp = Array(N + 1) { TreeSet<Int>() }

        dp[0].add(0)

        for (i in a.indices) {
            dp[i + 1].addAll(dp[i])

            for (t in dp[i]) {
                if (t + a[i] >= K) {
                    continue
                }

                dp[i + 1].add(t + a[i])
            }
        }

        return dp
    }

    val dp = func(a)
    val rdp = func(a.reversed())

    var cnt = 0

    for (i in a.indices) {
        if (a[i] >= K) {
            cnt++
            continue
        }

        val t1 = dp[i]
        val t2 = rdp[N - i - 1]

        var r = false

        for (l in t1) {
            val e = t2.lower(K - l) ?: continue

            if (l + e >= K - a[i]) {
                r = true
            }
        }

        if (r) {
            cnt++
        }
    }

    println(N - cnt)
}

