            return true
        val dp = Array(2){BooleanArray(k+1){false} }
        var cur = 0
        var next = 1
        dp[cur][0] = true
        dp[next][0] = true

        for(i in arr.indices) {
            if(i == idx) continue
            val v = arr[i]
            for(j in 1..k) {
                dp[next][j] = dp[cur][j]
            }
            for(j in 1..k) {
                if(j - v < 0) continue
                dp[next][j] =  dp[next][j] or dp[cur][j-v]
                if(j >= k - arr[idx] && j <= k - 1 && dp[next][j])
                    return true
            }
            cur = (cur + 1) % 2
            next = (next + 1) % 2
        }
        return false
    }
    var ans = 0
    for(i in 0 until n) {
        if(isNecessary(i))
            continue
        ++ans
    }
