								dp[j][k] = dp[j-1][k];
							}
						}
					}
				}

				boolean ok = false;
				for (int j = Math.max(0, K-a[i]); j < K; j++) {
					ok = ok || dp[N-1][j];
				}
				if (ok) ans++;

