class Main {

    public static void main(String[] args) {
        new Main().compute();
    }

    void compute() {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        int[] a = new int[N];
        for (int i = 0; i < N; i++) {
            a[i] = sc.nextInt();
        }
        Arrays.sort(a);
        int lb = -1, ub = N;
        if (ub - lb == 2) {
            ub--;
        }
        while (ub - lb > 1) {
            int mid = (lb + ub) / 2;
            List<Integer> aList = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                if (i != mid) {
                    aList.add(a[i]);
                }
            }
            boolean[][] dp = new boolean[N - 1][K];
            dp[0][0] = true;
            if (aList.get(0) <= K) {
                dp[0][aList.get(0)] = true;
            }
            for (int i = 1; i < N - 1; i++) {
                for (int j = 0; j < K; j++) {
                    dp[i][j] = dp[i - 1][j];
                    if (aList.get(i) <= j) {
                        dp[i][j] |= dp[i - 1][j - aList.get(i)];
                    }
                }
            }

            int tmp = lb;
            lb = mid;
            for (int i = Math.max(0, K - a[mid]); i < K; i++) {
                if (dp[N - 2][i]) {
                    ub = mid;
                    lb = tmp;
                    break;
                }
            }
        }
        System.out.println(ub);
    }
}

import java.io.PrintWriter;
import java.util.Scanner;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main{
	static int n, k;
	static int[] a;

	public static void main(String[] args){
		//入力
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		k = sc.nextInt();
		a = new int[n];
		for(int i = 0; i < n; i++){
			a[i] = sc.nextInt();
		}
		sc.close();

		//処理
		Arrays.sort(a);
		int ret = binarySearch();
		int ans = 0;
		if(ret >= 0){
			ans = Math.min(n, ret + 1);
		}

		//出力
		PrintWriter out = new PrintWriter(System.out);
		out.println(ans);
		out.flush();
	}

	private static int binarySearch(){
		int ng = n; //条件を満たさない
		int ok = -1;  //条件を満たす

		while(Math.abs(ok - ng) > 1){
			int mid = (ok+ng) / 2;
			if(isOK(mid)) ok = mid;
			else ng = mid;
		}

		return ok;
	}

	static int[][] dp = new int[5010][5010];

	private static boolean isOK(int notuse){
		int kp = k - a[notuse];
		if(kp < 0) return false;

		for(int[] t : dp) Arrays.fill(t, -1);
		dp[0][0] = 1;
		List<Integer> b = new ArrayList<>();
		for(int i = 0; i < n; i++){
			if(i != notuse && a[i] < k) b.add(a[i]);
		}
		int m = b.size();

		for(int i = 0; i < m; i++){
			for(int j = 0; j < k; j++){
				if(dp[i][j] == 1){
					dp[i+1][j] = 1;
					if(j + b.get(i) < k) dp[i+1][j+b.get(i)] = 1;
				}
			}
		}

		boolean f = true;
		for(int i = kp; i < k; i++){
			if(dp[m][i] == 1) f = false;
		}

		return f;
	}
}

