        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = fsc.nextInt();
        }
        int[][] backsum = new int[n + 1][k + 1];
        backsum[n][1] = 1;
        for (int i = n - 1; i >= 0; i--) for (int j = 1; j <= k; j++) {
            if (backsum[i + 1][j] > 0) {
                backsum[i][j] = 1;
                if (j + a[i] <= k) {
                    backsum[i][j + a[i]] = 1;
                }
            }
        }
        for (int i = 0; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                backsum[i][j] += backsum[i][j - 1];
            }
        }
        int need = 0;
        int[] front = new int[k];
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                front[0] = 1;
            } else {
                for (int j = k - 1; j >= 0; j--) {
                    if (j - a[i - 1] >= 0) {
                        front[j] += front[j - a[i - 1]];
                    }
                }
            }
            for (int j = 0; j < k; j++) {
                if (front[j] > 0 && backsum[i + 1][k - j] - backsum[i + 1][max(0, k - a[i] - j)] > 0) {
