					if(rdp[i][j]>0)rdp[i+1][j+a[n-1-i]]=1;
				}
			}	
		}

		//累積和にする
		for(int i=0;i<n+1;i++) {
			for(int j=5000;j>=1;j--) {
				rdp[i][j-1] += rdp[i][j];
			}
		}

		int ans = n;
		boolean dp[][] = new boolean[2][5001];
		dp[0][0] = true;
		for(int i=0;i<n;i++) {
			for(int j=0;j<5001;j++) {
				dp[(i+1)&1][j] |= dp[i&1][j];
				if(j+a[i]>5000) {
					dp[(i+1)&1][5000]|=dp[i&1][j];
				}
				else {
					dp[(i+1)&1][j+a[i]]|=dp[i&1][j];
				}
			}	
			for(int j=0;j<=k;j++) {
