class Main {

    public static void main(String[] args) {
        new Main().compute();
    }

    void compute() {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        int[] a = new int[N];
        for (int i = 0; i < N; i++) {
            a[i] = sc.nextInt();
        }
        int[][] dp = new int[N + 1][K];
        for (int i = 0; i <= N; i++) {
            Arrays.fill(dp[i], -1);
        }
        dp[0][0] = 0;
        dp[0][a[0]] = 1;
        for (int i = 1; i <= N; i++) {
            for (int j = 0; j < K; j++) {
                try {
                    if (dp[i - 1][j - a[i]] != -1) {
                        dp[i][j] = dp[i - 1][j - a[i]] | 1 << i;
                    }
                } catch (Exception e) {
                }
            }
            for (int j = 0; j < K; j++) {
                if (dp[i - 1][j] != -1) {
                    if (dp[i][j] != -1) {
                        dp[i][j] &= dp[i - 1][j];
                    } else {
                        dp[i][j] = dp[i - 1][j];
                    }
                }
            }
        }
        int ans = 0;
        for (int i = 0; i < N; i++) {
            for (int j = Math.max(0, K - a[i]); j < K; j++) {
                if (dp[N][j] != -1 && dp[N][j] >> i % 2 == 0) {
                    ans++;
                    break;
                }
            }
        }
        System.out.println(N - ans);
    }
}

