import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    private static boolean debug = false;
    private static boolean elapsed = true;

    private static PrintWriter _out = new PrintWriter(System.out);
    private static PrintWriter _err = new PrintWriter(System.err);

    private int N;
    private int K;
    private int[] a;

    private void solve(Scanner sc) {
        N = sc.nextInt();
        K = sc.nextInt();
        a = new int[N];
        long sum = 0;
        for (int i = 0; i < N; ++i) {
            a[i] = sc.nextInt();
            sum += a[i];
        }

        if (sum < K) {
            _out.println(N);
            return;
        }

        Arrays.sort(a);

        long ans = 0;
        int left = 0;
        int right = N;
        while (left < right) {
            int c = (left + right) / 2;
            boolean flg = false;
            if (a[c] < K) {
                int[][] dp = new int[N][K];
                dp[0][0] = 1;
                for (int i = 1; i < N; ++i) {
                    for (int j = 0; j < K; ++j) {
                        if (i != c && a[i] <= j) {
                            dp[i][j] = dp[i - 1][j] | dp[i - 1][j - a[i]];
                        } else {
                            dp[i][j] = dp[i - 1][j];
                        }
                    }
                }
                for (int i = K - a[c]; i < K; ++i) {
                    if (dp[N - 1][i] == 1) {
                        flg = true;
                        break;
                    }
                }
            }
            if (flg) {
                right = c;
            } else {
                ans = c + 1;
                left = c + 1;
            }
        }

        _out.println(ans);
    }
    private static BigInteger C(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        for (long i = r; i > 1; --i) {
            res = res.divide(BigInteger.valueOf(i));
        }
        return res;
    }
    private static BigInteger P(long n, long r) {
        BigInteger res = BigInteger.ONE;
        for (long i = n; i > n - r; --i) {
            res = res.multiply(BigInteger.valueOf(i));
        }
        return res;
    }
    /*
     * 10^10 > Integer.MAX_VALUE = 2147483647 > 10^9
     * 10^19 > Long.MAX_VALUE = 9223372036854775807L > 10^18
     */
    public static void main(String[] args) {
        long S = System.currentTimeMillis();

        Scanner sc = new Scanner(System.in);
        new Main().solve(sc);
        _out.flush();

        long G = System.currentTimeMillis();
        if (elapsed) {
            _err.println((G - S) + "ms");
        }
        _err.flush();
    }
}

import java.io.PrintWriter;
import java.util.Scanner;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main{
	static int n, k;
	static int[] a;

	public static void main(String[] args){
		//入力
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		k = sc.nextInt();
		a = new int[n];
		for(int i = 0; i < n; i++){
			a[i] = sc.nextInt();
		}
		sc.close();

		//処理
		Arrays.sort(a);
		int ret = binarySearch();
		int ans = 0;
		if(ret >= 0){
			ans = Math.min(n, ret + 1);
		}

		//出力
		PrintWriter out = new PrintWriter(System.out);
		out.println(ans);
		out.flush();
	}

	private static int binarySearch(){
		int ng = n; //条件を満たさない
		int ok = -1;  //条件を満たす

		while(Math.abs(ok - ng) > 1){
			int mid = (ok+ng) / 2;
			if(isOK(mid)) ok = mid;
			else ng = mid;
		}

		return ok;
	}

	static int[][] dp = new int[5010][5010];

	private static boolean isOK(int notuse){
		if(notuse >= n) return false;
		if(notuse < 0) return true;
		int kp = k - a[notuse];
		if(kp < 0) return false;
		for(int[] t : dp) Arrays.fill(t, -1);
		dp[0][0] = 1;
		List<Integer> b = new ArrayList<>();
		for(int i = 0; i < n; i++){
			if(i != notuse && a[i] < k) b.add(a[i]);
		}
		int m = b.size();

		for(int i = 0; i < m; i++){
			for(int j = 0; j < k; j++){
				if(dp[i][j] == 1){
					dp[i+1][j] = 1;
					if(j + b.get(i) < k) dp[i+1][j+b.get(i)] = 1;
				}
			}
		}

		boolean f = true;
		for(int i = kp; i < k; i++){
			if(dp[m][i] == 1) f = false;
		}

		return f;
	}
}

