      boolean[][] dp = new boolean[N][K + 1];
      dp[0][0] = true;
      if(i != 0) dp[0][a[0]] = true;
      for(int j = 1; j < N; j++) {
        for(int k = 0; k < K + 1; k++) {
          if(i == j) {
            dp[j][k] = dp[j - 1][k];
          } else {
            if(k >= a[j]) {
              dp[j][k] = dp[j - 1][k] || dp[j - 1][k - a[j]];
            } else {
              dp[j][k] = dp[j - 1][k];
            }
          }
        }
      }
      boolean flg = false;
      for(int j = K - a[i]; j < K; j++) {
        flg = flg || dp[N - 1][j];
      }
      if(flg) ans++;
    }
