	static class TaskX {

		int n, k;
		int[] a;
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			n = in.nextInt();
			k = in.nextInt();
			a = in.nextIntArray(n);
			Arrays.sort(a);

			int l = 0, r = n;
			while (r - l > 1) {
				int m = (l+r)/2;

				if (check(m)) {
					r = m;
				} else {
					l = m;
				}
			}
			out.println(r);
		}

		boolean check(int m) {
			boolean[][] dp = new boolean[n+1][k+1];
			dp[0][0] = true;

			for (int i = 0; i < n; i++) {
				for (int j = 0; j < k+1; j++) {
					if (i == m) {
						dp[i+1][j] |= dp[i][j];
						continue;
					}

					if (j - a[i] >= 0) {
						dp[i+1][j] |= dp[i][j-a[i]];
					}
					dp[i+1][j] |= dp[i][j];
				}
			}

			boolean ret = false;
			for (int i = Math.max(0, k-a[m]); i < k; i++) {
				ret |= dp[n][i];
			}
			return ret;
		}
	}


