        bset[n-1].add(a[n-1]);
        for(int i=n-2;i>=0;i--){
            for(int ok:bset[i+1]){
                bset[i].add(ok);
                if(ok+a[i]<k) bset[i].add(ok+a[i]);
            }
        }
        int ans=n;
        Out:for(int i=0;i<n;i++){
            if(i==0){
                if(Objects.nonNull(bset[1].higher(k-a[i]-1))){
                    ans--;
                }
            }
            else if(i==n-1){
                if(Objects.nonNull(fset[n-2].lower(k-a[i]-1))){
                    ans--;
                }
            }
            else{
                for(int ok: fset[i-1]){
                    Integer h=bset[i+1].lower(k-a[i]-ok-1);
                    if(Objects.nonNull(h)){
                        if(ok+h<k){
                            ans--;
                            continue Out;
                        }
                    }
                    else{
                        break;
                    }
                }
            }
        }
        System.out.println(ans);
    }
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

import java.util.Scanner;
import java.util.Arrays;

public class Main{
  static int n, k;
  static int[] a;

  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    n = sc.nextInt();
    k = sc.nextInt();
    a = new int[n];
    for(int i = 0; i < n; i++){
      a[i] = sc.nextInt();
    }

    int count = 0;
    for(int i = 0; i < n; i++){
      if(a[i] >= k){
        ++count;
      }
    }

    int[] b = new int[n - count];
    int m = 0;
    for(int i = 0; i < n; i++){
      if(a[i] < k){
        b[m++] = a[i];
      }
    }

    int ans = 0;
    for(int i = 0; i < m; i++){
      if(!check(i, b)){
        ++ans;
      }
    }

    System.out.println(ans);
  }

  private static boolean check(int index, int[] b){
    int[] c = new int[b.length - 1];
    int m = 0;
    for(int i = 0; i < b.length; i++){
      if(i != index){
        c[m++] = b[i];
      }
    }

    boolean[][] dp = new boolean[m + 1][400 * 400 + 1];
    dp[0][0] = true;
    for(int i = 1; i <= m; i++){
      for(int j = 0; j < dp[i].length; j++){
        if(j - c[i - 1] >= 0){
          dp[i][j] = dp[i - 1][j] || dp[i - 1][j - c[i - 1]];
        }
        else{
          dp[i][j] = dp[i - 1][j];
        }
      }
    }

    for(int s = k - b[index]; s < k; s++){
      if(dp[m][s]){
        return true;
      }
    }

    return false;
  }
}

import java.util.Scanner;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        Scanner stdin = new Scanner(System.in);
        int n = stdin.nextInt();
        int k = stdin.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = stdin.nextInt();
        }

        int lo = -1;
        int hi = n;
        while (Math.abs(hi - lo) > 1) {
            int mi = (lo + hi) / 2;
            if (ok(n, k, a, mi)) {
                hi = mi;
            } else {
                lo = mi;
            }
        }
        System.out.println(hi);
    }

    private static boolean ok(int n, int k, int[] a, int x) {
        int[][] dp = new int[n + 1][k];
        dp[0][0] = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < k; j++) {
                dp[i + 1][j] += dp[i][j];
                if (i != x && j + a[i] < k) {
                    dp[i + 1][j + a[i]] += dp[i][j];
                }
            }
        }

        return IntStream.range(Math.max(0, k - a[x]), k).anyMatch(i -> dp[n][i] > 0);
    }
}

