/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();
            int[] a = in.nextIntArray(n);

            Arrays.sort(a);
            int high = n;
            int low = -1;
            while (high - low > 1) {
                int mid = (high + low) / 2;
                if (isNeed(a, k, mid)) {
                    high = mid;
                } else {
                    low = mid;
                }
            }

            out.println(high);
        }

        boolean isNeed(int[] a, int k, int idx) {
            int n = a.length;
            boolean[] can = new boolean[k];
            can[0] = true;
            for (int i = 0; i < n; i++) {
                if (i == idx) continue;
                for (int j = k - 1; j >= 0; j--) {
                    if (j - a[i] >= 0 && can[j - a[i]]) {
                        can[j] = true;
                    }
                }
            }

            for (int i = k - a[idx]; i < k; i++) {
                if (can[i]) return true;
            }
            return false;
        }

    }

    static class InputReader {
        private BufferedReader in;
        private StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public int[] nextIntArray(int n) {
            int[] res = new int[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextInt();
            }
            return res;
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner stdin = new Scanner(System.in);
        int n = stdin.nextInt();
        int k = stdin.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = stdin.nextInt();
        }

        Arrays.sort(a);

        int lo = -1;
        int hi = n;
        while (Math.abs(hi - lo) > 1) {
            int mi = (lo + hi) / 2;
            if (ok(n, k, a, mi)) {
                hi = mi;
            } else {
                lo = mi;
            }
        }
        System.out.println(hi);
    }

    private static boolean ok(int n, int k, int[] a, int x) {
        List<Map<Integer, Integer>> dp = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            dp.add(new HashMap<>());
        }
        dp.get(0).put(0, 0);

        for (int i = 0; i < n; i++) {
            Map<Integer, Integer> pre = dp.get(i);
            Map<Integer, Integer> nxt = dp.get(i + 1);
            nxt.putAll(pre);
            if (i == x) {
                continue;
            }
            for (int j : pre.keySet()) {
                if (j + a[i] < k) {
                    int v = nxt.getOrDefault(j + a[i], 0) + pre.get(j);
                    nxt.put(j + a[i], v);
                }
            }
        }

        return dp.get(n).keySet().stream().anyMatch(i -> k - a[x] <= i && i < k);
    }
}

