import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		new Main().solve();
	}

	int n,k;
	int[]a;

	void solve(){
		Scanner sc=new Scanner(System.in);
		n=sc.nextInt();
		k=sc.nextInt();
		a=new int[n];
		for(int i=0;i<n;i++){
			a[i]=sc.nextInt();
		}
		Arrays.sort(a);

		//二分探索
		int max=n;
		int min=-1;
		int med=0;
		LOOP:while(max-min>1){
			med=(max+min)/2;

			if(a[med]>k){
				max=med;
				continue;
			}
			int idx=0;

			//dp[j][sum]:=j枚目までで和sumを作れるか
			boolean[][]dp=new boolean[n][k];
			for(int j=0;j<n;j++){
				dp[j][0]=true;
			}

			for(int j=1;j<n;j++){
				if(idx==med)idx++;	//i枚目は使わないので

				for(int sum=0;sum<k;sum++){
					if(dp[j-1][sum]){
						dp[j][sum]=true;
						int temp=sum+a[idx];
						if(temp<k)dp[j][temp]=true;
					}
				}
				idx++;
			}

			for(int sum=k-a[med];sum<k;sum++){
				if(dp[n-1][sum]){
					max=med;
					continue LOOP;
				}
			}
			min=med;
		}
		System.out.println(max);
	}
}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int K = sc.nextInt();
    int[] a = new int[N];
    for(int i = 0; i < N; i++) {
      a[i] = sc.nextInt();
    }

    // dp1[i][j]はカード0～iで総和をjに出来るかを表す
    int[][] dp1 = new int[N][K];
    dp1[0][0] = 1;
    if(a[0] < K) dp1[0][a[0]] = 1;
    for(int i = 1; i < N; i++) {
      for(int j = 0; j < K; j++) {
        if(a[i] <= j) {
          if((dp1[i - 1][j] == 1) || (dp1[i - 1][j - a[i]] == 1)) dp1[i][j] = 1;
        } else {
          dp1[i][j] = dp1[i - 1][j];
        }
      }
    }

    // dp2[i][j]はカードi～N-1までで総和0～jの内、何個達成出来るかを表す
    int[][] dp2 = new int[N][K];
    for(int j = 0; j < K; j++) {
      if(a[N - 1] < K) {
        if(j < a[N - 1]) {
          dp2[N - 1][j] = 1;
        } else {
          dp2[N - 1][j] = 2;
        }
      } else {
        dp2[N - 1][j] = 1;
      }
    } 

    int nec = 0;
    for(int i = 0; i < N; i++) {
      boolean flg = false;
      if(a[i] >= K) {
        flg = true;
      } else {
        if(i == 0) {
          if((dp2[1][K - 1] - dp2[1][K - a[i] - 1]) > 0) flg = true;
        } else if(i == N - 1) {
          for(int j = K - a[i]; j < K; j++) {
            if(dp1[i - 1][j] == 1) {
              flg = true;
              break;
            }
          }
        } else {
          for(int j = 0; j < K; j++) {
            if(K - a[i] - j - 1 >= 0) {
              if((dp1[i - 1][j] == 1) && (dp2[i + 1][K - j - 1] > dp2[i + 1][K - a[i] - j - 1])) {
                flg = true;
                break;
              }
            } else {
              if((dp1[i - 1][j] == 1) && (dp2[i + 1][K - j - 1] > 0)) {
                flg = true;
                break;
              }
            }
          }
        }
      }
      if(flg) nec++;
    }
    System.out.println(N - nec);
  }
}

