/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        DNoNeed solver = new DNoNeed();
        solver.solve(1, in, out);
        out.close();
    }

    static class DNoNeed {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int k = in.readInt();
            int[] a = in.readIntArray(n);

            Arrays.sort(a);
            int high = n;
            int low = -1;
            while (high - low > 1) {
                int mid = (high + low) / 2;
                boolean[] dp = new boolean[k];
                dp[0] = true;
                for (int i = 0; i < n; i++) {
                    if (i == mid) continue;
                    for (int j = k - 1; j >= 0; j--) {
                        if (j - a[i] >= 0) {
                            dp[j] |= dp[j - a[i]];
                        }
                    }
                }
                boolean need = false;
                if (a[mid] <= k) {
                    for (int i = k - a[mid]; i < k; i++) {
                        need |= dp[i];
                    }
                }
                if (need) {
                    high = mid;
                } else {
                    low = mid;
                }
            }
            out.printLine(high);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int[] readIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = readInt();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(int i) {
            writer.println(i);
        }

    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		try (Scanner sc = new Scanner(System.in)) {
			int N = sc.nextInt();
			int K = sc.nextInt();
			List<Integer> alist = new ArrayList<Integer>();
			int sum = 0;
			int ignore = 0;
			int ignoreCnt = 0;

			for (int i = 0; i < N; i++) {
				int read = sc.nextInt();
				if (read < K) {
					alist.add(read);
				} else {
					// 単独でKを超えるものは除外
					ignore = ignore + read;
					ignoreCnt++;
				}
				sum = sum + read;
			}

			// 全値の合計がKより低い場合はすべて不要
			if (sum < K) {
				System.out.println(N);
				return;
			}

			int result = 0;
			Collections.sort(alist);
			Collections.reverse(alist);

			for (int i = 0; i < N - ignoreCnt; i++) {
				int tmp = alist.get(i);
				for (int j = i + 1; j < N - ignoreCnt - i; j++) {
					tmp = tmp + alist.get(j);
					if (tmp >= K) {
						result = result + (N - ignoreCnt - (i + 1) - j);
						break;
					}
				}
			}
			System.out.println(result);

		}
	}
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説どおりに作成したソースコード<br/>
 * https://atcoder.jp/contests/abc056/submissions/4757789 にも参照
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			int k = scanner.nextInt();
			int[] a = new int[n];
			IntStream.range(0, n).forEach(i -> a[i] = scanner.nextInt());
			if (1 == n) {
				System.out.println((k > a[0]) ? 1 : 0);
				return;
			}
			Arrays.sort(a);

			int ng = 0, ok = n + 1;
			while (ok - ng > 1) {
				int mid = (ok + ng) / 2;
				if (isNeeded(mid, n, k, a)) {
					ok = mid;
				} else {
					ng = mid;
				}
			}
			System.out.println(ng);
		}
	}

	/**
	 * @param now
	 * @param n
	 * @param k
	 * @param a
	 * @return now番目のカードが必要かどうか
	 */
	private static boolean isNeeded(int now, final int n, final int k, final int[] a) {
		boolean[][] dp = new boolean[n + 1][k + 1];
		IntStream.range(0, n + 1).forEach(i -> Arrays.fill(dp[i], false));
		dp[0][0] = true;
		IntStream.rangeClosed(1, n).forEach(i -> IntStream.rangeClosed(0, k).forEach(j -> {
			if (i == now) {
				// ぬくカードの場合
				dp[i][j] = dp[i - 1][j];
			} else {
				if (dp[i - 1][j]) {
					dp[i][j] = true;
					if (j + a[i - 1] <= k) {
						dp[i][j + a[i - 1]] = true;
					}
				}
			}
		}));
		for (int i = k - 1; i >= Math.max(k - a[now - 1], 0); i--) {
			if (dp[n][i]) {
				return true;
			}
		}
		return false;
	}
}

import java.io.*;
