            lb++;
        }
        while (ub - lb > 1) {
            int mid = (lb + ub) / 2;
            List<Integer> aList = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                if (i != mid) {
                    aList.add(a[i]);
                }
            }
            boolean[][] dp = new boolean[N - 1][K];
            dp[0][0] = true;
            if (aList.get(0) <= K) {
                dp[0][aList.get(0)] = true;
            }
            for (int i = 1; i < N - 1; i++) {
                for (int j = 0; j < K; j++) {
                    dp[i][j] = dp[i - 1][j];
                    if (aList.get(i) <= j) {
                        dp[i][j] |= dp[i - 1][j - aList.get(i)];
                    }
                }
            }

            int tmp = lb;
            lb = mid;
            for (int i = Math.max(0, K - a[mid]); i < K; i++) {
                if (dp[N - 2][i]) {
                    ub = mid;
                    lb = tmp;
                    break;
                }
            }
        }
        System.out.println(ub);
    }
}

