public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int K = sc.nextInt();
    int[] a = new int[N];
    for(int i = 0; i < N; i++) {
      a[i] = sc.nextInt();
    }
    // dp1[i][j]は左からi個までで和をjに出来るかどうかを表す。
    boolean[][] dp1 = new boolean[N + 1][K + 1];
    dp1[0][0] = true;
    for(int i = 1; i < N + 1; i++) {
      for(int j = 0; j < K + 1; j++) {
        if(a[i - 1] <= j) {
          dp1[i][j] = dp1[i - 1][j] || dp1[i - 1][j - a[i - 1]];
        } else {
          dp1[i][j] = dp1[i - 1][j];
        }
      }
    }
    // dp2[i][j]は右からi個までで和を0～jの内何個作れるかを表す。
    int[][] dp2 = new int[N + 1][K + 1];
    dp2[0][0] = 1;
    for(int i = 1; i < N + 1; i++) {
      dp2[i][0] = 1;
      for(int j = 1; j < K + 1; j++) {
        int count = 0;
        if(a[N - i] <= j) {
          if(a[N - i] == j) {
            if(dp2[i - 1][j] > dp2[i - 1][j - 1] || dp2[i - 1][j - a[N - i]] > 0) count++;
          } else {
            if(dp2[i - 1][j] > dp2[i - 1][j - 1] || dp2[i - 1][j - a[N - i]] > dp2[i - 1][j - a[N - i] - 1]) count++;
          }
        } else {
          if(dp2[i - 1][j] > dp2[i - 1][j - 1]) count++;
        }
        dp2[i][j] = dp2[i][j - 1] + count;
      }
    }
    int ans = 0;
    for(int i = 0; i < N; i++) {
      int count = 0;
      for(int j = 0; j < K; j++) {
        if(K - a[i] - j - 1 >= 0) {
          if(dp1[i][j] && (dp2[N - 1 - i][K - j - 1] > dp2[N - 1 - i][K - a[i] - j - 1])) {
            count++;
            break;
          }
        } else {
          if(dp1[i][j] && (dp2[N - 1 - i][K - j - 1] > 0)) {
            count++;
            break;
          }
        }
      }
      if(count > 0) ans++;
    }
    System.out.println(N - ans);
  }
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    int N = scanner.nextInt();
    int K = scanner.nextInt();
    int[] a = new int[N + 1];
    for (int i = 1; i <= N; i++) a[i] = scanner.nextInt();

    boolean[][] dp1 = new boolean[N + 1][K + 1];
    for (int i = 0; i <= N; i++) dp1[i][0] = true;
    for (int i = 1; i <= N; i++) {
      for (int j = 1; j <= K; j++) {
        dp1[i][j] = dp1[i - 1][j] || (j >= a[i] && dp1[i - 1][j - a[i]]);
      }
    }

    boolean[][] dp2 = new boolean[N + 1][K + 1];
    for (int i = 0; i <= N; i++) dp2[i][0] = true;
    for (int i = N - 1; i >= 0; i--) {
      for (int j = 1; j <= K; j++) {
        dp2[i][j] = dp2[i + 1][j] || (j >= a[i + 1] && dp2[i + 1][j - a[i + 1]]);
      }
    }

    int count = 0;
    loop:
    for (int i = 1; i <= N; i++) {
      int rc = 0;
      for (int j = 0; j <= K; j++) if (dp2[i][j]) rc++;
      int[] right = new int[rc];
      int idx = 0;
      for (int j = 0; j <= K; j++) if (dp2[i][j]) right[idx++] = j;

      int min = Math.max(0, K - a[i]);
      for (int j = 0; j <= K; j++) {
        if (dp1[i - 1][j]) {
          int r = findLowerBound(right, Math.max(0, min - j));
          if (r >= 0 && j + r < K) {
            count++;
            continue loop;
          }
        }
      }
    }
    System.out.println(N - count);
  }

  private static int findLowerBound(int[] list, int min) {
    int left = -1;
    int right = list.length;
    while (right - left > 1) {
      int mid = (left + right) / 2;
      if (list[mid] >= min) {
        right = mid;
      } else {
        left = mid;
      }
    }
    return right == list.length ? - 1 : list[right];
  }
}

