public class Main {
	static final long MOD=1000000007;//998244353;
	static long ans;
	public static void main(String[] args) {
		PrintWriter out = new PrintWriter(System.out);
		InputReader sc=new InputReader(System.in);
		int N=sc.nextInt();
		int K=sc.nextInt();
		int[] A=sc.nextIntArray(N);
		boolean[][] dp1=new boolean[N+1][5001];
		boolean[][] dp2=new boolean[N+1][5001];
		dp1[0][0]=true;
		dp2[N][0]=true;
		int ans=N;
		for (int i = 1; i <= N; i++) {
			for (int j = 0; j <= 5000; j++) {
				dp1[i][j]=dp1[i-1][j];
				if (j-A[i-1]>=0) {
					dp1[i][j]|=dp1[i-1][j-A[i-1]];
				}
			}
		}
		for (int i = N-1; i >= 0; i--) {
			for (int j = 0; j <= 5000; j++) {
				dp2[i][j]=dp2[i+1][j];
				if (j-A[i]>=0) {
					dp2[i][j]|=dp2[i+1][j-A[i]];
				}
			}
		}
		int[][] bool=new int[N+1][5001];
		for (int i = 0; i <= N; i++) {
			for (int j = 0; j <= 5000; j++) {
				if (dp2[i][j]) {
					bool[i][j]=1;
				}
				if (j>=1) {
					bool[i][j]+=bool[i][j-1];	
				}
			}
		}
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < K; j++) {
				boolean flag=false;
				if (Math.max(0, K-A[i])-j-1<0) {
					if (bool[i+1][K-1-j]>=1) {
						flag=true;
					}
				}else {
					if (bool[i+1][K-1-j]-bool[i+1][Math.max(0, K-A[i])-j-1]>=1) {
						flag=true;
					}
				}
				if (dp1[i][j]&&flag) {
					ans--;
					break;
				}
			}
		}
		System.out.println(ans);
 	}
	static class InputReader { 
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;
		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}
	}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int K = sc.nextInt();
    int[] a = new int[N];
    for(int i = 0; i < N; i++) {
      a[i] = sc.nextInt();
    }
    Arrays.sort(a);
    int l = 0;
    int r = N;
    int ans = -1;
    while(l < r) {
      int med = (l + r) / 2;
      boolean[][] dp = new boolean[N][K + 1];
      dp[0][0] = true;
      if(med != 0 && a[0] < K + 1) dp[0][a[0]] = true;
      for(int j = 1; j < N; j++) {
        for(int k = 0; k < K + 1; k++) {
          if(med == j) {
            dp[j][k] = dp[j - 1][k];
          } else {
            if(k >= a[j]) {
              dp[j][k] = dp[j - 1][k] || dp[j - 1][k - a[j]];
            } else {
              dp[j][k] = dp[j - 1][k];
            }
          }
        }
      }
      boolean flg = false;
      for(int j = Math.max(0, K - a[med]); j < K; j++) {
        flg = flg || dp[N - 1][j];
      }
      if(flg) {
        r = med;
      } else {
        l = med + 1;
        ans = med;
      }
    }
    System.out.println(ans + 1);
  }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

    private static Scanner scan = new Scanner(System.in);
    private static int N;
    private static int K;
    private static int[] a;

    public static void main(String[] args) {
	N = Integer.parseInt(scan.next());
	K = Integer.parseInt(scan.next());

	a = new int[N];
	for (int i = 0; i < N; i++) {
	    a[i] = Integer.parseInt(scan.next());
	}
	Arrays.sort(a);

	int needless = binarySearch(0, N);
	System.out.println(needless);
	scan.close();
    }

    private static int binarySearch(int from, int to) {
	if(from == to) return from;

	int index = (from+to)/2;
	return isNeeded(index) ? binarySearch(from, index) : binarySearch(index+1, to);
    }

    private static boolean isNeeded(int target) {

	int k = K - a[target];
	if(k < 0) {
	    return true;
	}

	int index = 0;

	boolean[][] dp = new boolean[N][K];
	for (int x = 0; x < N; x++) {
	    dp[x][0] = true;
	}

	for (int x = 1; x < N; x++) {
	    if(index == target) index++;

	    for (int y = 0; y < K; y++) {
		if(dp[x-1][y]) {
		    dp[x][y] = true;
		    int tmp = y + a[index];
		    if(tmp < K) dp[x][tmp] = true;
		}
	    }
	    index++;
	}

	for (int y = k; y < K; y++) {
	    if(dp[N-1][y]) {
		return true;
	    }
	}

	return false;
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    int N = scanner.nextInt();
    int K = scanner.nextInt();
    int[] a = new int[N + 1];
    for (int i = 1; i <= N; i++) a[i] = scanner.nextInt();
    Arrays.sort(a);

    boolean[][] dp1 = new boolean[N + 1][K + 1];
    for (int i = 0; i <= N; i++) dp1[i][0] = true;
    for (int i = 1; i <= N; i++) {
      for (int j = 1; j <= K; j++) {
        dp1[i][j] = dp1[i - 1][j] || (j >= a[i] && dp1[i - 1][j - a[i]]);
      }
    }

    boolean[][] dp2 = new boolean[N + 1][K + 1];
    for (int i = 0; i <= N; i++) dp2[i][0] = true;
    for (int i = N - 1; i >= 0; i--) {
      for (int j = 1; j <= K; j++) {
        dp2[i][j] = dp2[i + 1][j] || (j >= a[i + 1] && dp2[i + 1][j - a[i + 1]]);
      }
    }

    int count = 0;
    for (int i = 1; i <= N; i++) {
      int min = Math.max(0, K - a[i]);
      for (int k = min; k < K; k++) {
        if (dp1[i - 1][k] || dp2[i][k]) {
          count++;
          break;
        }
      }
    }
    System.out.println(N - count);
  }
}

