                sum += a[j];
                if (sum >= k) {
                    while (sum - a[s] >= k) {
                        sum -= a[s++];
                        if (s == i) {
                            s++;
                        }
                    }

                    if (sum - a[i] < k) {
                        isNeed = true;
                        break;
                    }
                }
            }

            if (!isNeed) {
                ans++;
            }
        }

        System.out.println(ans);
    }

