		}
		for(int j = 0; j + a[i] < k; j ++) {
			dp2[i + 1][j + a[i]] |= dp2[i][j];
		}
	}
	int max2[][] = new int[num + 1][k];
	fill(max2, 0);
	for(int i = 0; i <= num; i ++) {
		for(int j = 1; j < k; j ++) {
			max2[i][j] = max2[i][j - 1];
			if(dp2[i][j]) max2[i][j] = j;
		}
	}
	reverse(a);
	reverse(dp2);
	reverse(max2);

	long ans = 0;
	for(int i = 0; i < num; i ++) {
		boolean b = a[i] >= k;
		for(int j = 0; j < k; j ++) {
			b |= max1[i][j] + max2[i + 1][k - j - 1] >= k - a[i];
		}
		if(!b) ans ++;
	}
