public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int k = sc.nextInt();
    long[] a = new long[n];
    for(int i = 0; i < n; i++) {
      a[i] = sc.nextLong();
    }
    Arrays.sort(a);
    int ans = 0;
    int left = 0;
    int right = n;
    while(left < right) {
      int med = (left + right) / 2;
      boolean[][] dp = new boolean[n][k]; 
      if(med != 0) {
        dp[0][0] = true;
        if(a[0] < k) dp[0][(int)a[0]] = true;
      } else {
        dp[0][0] = true;
        if(n > 1) {
          dp[1][0] = true;
          if(a[1] < k) dp[1][(int)a[1]] = true;
        }
      }
      for(int i = 1; i < n; i++) {
        dp[i][0] = true;
        for(int j = 1; j < k; j++) {
          dp[i][j] = dp[i - 1][j];
          if((i != med) && (j >= a[i])) dp[i][j] = (dp[i][j] || dp[i - 1][(int)(j - a[i])]);
        }
      }
      int p = 0;
      for(int j = (int)Math.max(0, k - a[med]); j < k; j++) {
        if(dp[n - 1][j]) p++;
      }
      if(p == 0) {
        left = med + 1;
      } else {
        ans = med;
        right = med;
      }
    }
    System.out.println(n - ans);
  }
}

import java.util.Scanner;
import java.util.TreeSet;

public class Main{
  static int n, k;
  static int[] a;

  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    n = sc.nextInt();
    k = sc.nextInt();
    a = new int[n];
    for(int i = 0; i < n; i++){
      a[i] = sc.nextInt();
    }

    int count = 0;
    for(int i = 0; i < n; i++){
      if(a[i] >= k){
        ++count;
      }
    }

    int[] b = new int[n - count];
    int m = 0;
    for(int i = 0; i < n; i++){
      if(a[i] < k){
        b[m++] = a[i];
      }
    }

    TreeSet< Integer > set = new TreeSet< >();
    for(int i = 0; i < m; i++){
      set.add(b[i]);
    }

    int ans = 0;
    for(int i = 0; i < m; i++){
      set.remove(b[i]);
      if(!check(i, b, set)){
        ++ans;
      }
      set.add(b[i]);
    }

    System.out.println(ans);
  }

  private static boolean check(int index, int[] b, TreeSet< Integer > set){
    int m = set.size();
    if(set.higher(k - b[index] - 1) != null){
      return true;
    }

    for(int i = 0; i < b.length; i++){
      if(i != index){
        set.remove(b[i]);
        Integer lb = set.lower(k - b[i] + 1);
        if(lb != null){
          if(b[i] + lb >= k - b[index] &&
              b[i] + lb < k){
            set.add(b[i]);
            return true;
          }
        }
        set.add(b[i]);
      }
    }

    return false;
  }
}

