import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[] a = new int[n];
        boolean[] need = new boolean[n];
        for(int i=0; i<n; i++){
            a[i] = sc.nextInt();
        }
        sc.close();

        int amin = Arrays.stream(a).min().getAsInt();
        if(amin > k){
            System.out.println(n);
            return;
        }

        for(int i=0; i<n; i++){
            if(a[i] + amin >= k && a[i] != amin){
                need[i] = true;
            }
        }

        int[][] dpl = new int[n][k];
        int[][] dpr = new int[n][k];
        dpl[0][0] = 1;
        dpr[n-1][0] = 1;
        if(a[0] < k) dpl[0][a[0]] = 1;
        if(a[n-1] < k) dpr[n-1][a[n-1]] = 1;
        for(int i=1; i<n; i++){
            dpl[i][0] = 1;
            for(int j=0; j<k-a[i]; j++){
                if(dpl[i-1][j] == 1) dpl[i][j+a[i]] = 1;
            }

            dpr[n-i-1][0] = 1;
            for(int j=0; j<k-a[n-i-1]; j++){
                if(dpr[n-i][j] == 1) dpr[n-i-1][j+a[n-i-1]] = 1;
            }

            for(int j=0; j<k; j++){
                if(dpl[i-1][j] == 1) dpl[i][j] = 1;
                if(dpr[n-i][j] == 1) dpr[n-i-1][j] = 1;    
            }
        }

        for(int i=0; i<n; i++){
            for(int j=1; j<k; j++){
                dpl[i][j] = dpl[i][j-1] + dpl[i][j];
                dpr[i][j] = dpr[i][j-1] + dpr[i][j];
            }
        }

        for(int i=1; i<n-1; i++){
            if(need[i]) continue;
            if(dpr[i+1][k-1] - dpr[i+1][Math.max(0, k-1-a[i])] >= 1) need[i] = true;
            if(dpl[i-1][k-1] - dpl[i-1][Math.max(0, k-1-a[i])] >= 1) need[i] = true;
            for(int j=1; j<k; j++){
                if(dpl[i-1][j]-dpl[i-1][j-1]>=1){
                    if(dpr[i+1][Math.max(0, k-1-j)] - dpr[i+1][Math.max(0, k-1-j-a[i])] >= 1) need[i] = true;
                }
            }
        }
        if(!need[0]){
            if(dpr[1][k-1] - dpr[1][Math.max(0, k-1-a[0])] >= 1) need[0] = true;
        }
        if(!need[n-1]){
            if(dpl[n-2][k-1] - dpl[n-2][Math.max(0, k-1-a[n-1])] >= 1) need[n-1] = true;
        }

        int ans = 0;
        for(int i=0; i<n; i++) if(!need[i]) ans++;
        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static PrintWriter out;
    public static FastScanner in;

    private void solve(){
        int n = in.nextInt();
        long k = in.nextLong();

        List<Long> list = new ArrayList<>();
        for(int i=0;i<n;i++){
            long v = in.nextLong();
            if(v < k) list.add(v);
        }

        Collections.sort(list,Collections.reverseOrder());
        n = list.size();
        int start = 0,ans = n;
        long v = 0L;
        while (true){
            if(start == n){
                out.print(ans);
                return;
            }

            v+= list.get(start);
            int x;
            for(x = start+1;x<n;x++){
                if(v+list.get(x) < k){
                    v+=list.get(x);
                }else {
                    break;
                }
            }
            start = x-1;
            if(start+1 == n){
                out.print(ans);
                return;
            }

            if(v + list.get(n-1) >= k){
                out.print(0);
                return;
            }
            int idx = -1;
            for(int i= n-1;i>start;i--){
                if(v+list.get(i) >= k){
                    idx = i;
                    break;
                }
            }

            if(idx == -1){
                out.print(ans);
                return;
            }
            //out.println(v + " " + start + " " + idx);
            ans-=(idx-start+1);
            start = idx+1;
        }
    }

    private void runIO() {
        in = new FastScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out));
        solve();
        out.close();
    }
    private static class FastScanner {
        BufferedReader bufferedReader;
        StringTokenizer stringTokenizer;

        private FastScanner() {
            bufferedReader = new BufferedReader(new InputStreamReader(System.in));
        }

        private String next() {
            if (stringTokenizer == null || !stringTokenizer.hasMoreElements()) {
                try {
                    stringTokenizer = new StringTokenizer(bufferedReader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return stringTokenizer.nextToken();
        }

        private int nextInt() {
            return Integer.parseInt(next());
        }

        private long nextLong() {
            return Long.parseLong(next());
        }

        private String nextLine() {
            String ret = "";
            try {
                ret = bufferedReader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return ret;
        }
    }

    public static void main(String[] args) {
        new Main().runIO();
    }
