	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int N = in.nextInt(); int K =in.nextInt();
			int[] a = in.nextIntArray(N);
			Arrays.sort(a);

			int ans = 0;

			for (int i = 0; i < N; i++) {

				boolean[][] dp = new boolean[N][K+1];

				dp[0][0] = true;
				if(i != 0 && a[0] < K + 1) dp[0][a[0]] = true;

				for (int j = 1; j < N; j++) {
					if (i == j) continue;
					for (int k = 0; k <= K; k++) {
						if (k-a[j] >= 0) {
							dp[j][k] = dp[j-1][k] | dp[j-1][k-a[j]];
						} else {
							dp[j][k] = dp[j-1][k];
						}
					}
				}

				boolean ok = false;
				for (int j = Math.max(0, K-a[i]); j < K; j++) {
					ok |= dp[N-1][j];
				}
				if (ok) ans++;

			}

			out.println(N-ans);



		}
	}

