        int[] a = new int[N];
        for (int i = 0; i < N; i++) {
            a[i] = sc.nextInt();
        }
        int[][] dp = new int[N + 1][K];
        for (int i = 0; i <= N; i++) {
            Arrays.fill(dp[i], -1);
        }
        dp[0][0] = 0;
        if (a[0] <= K) {
            dp[0][a[0]] = 1;
        }
        for (int i = 1; i <= N; i++) {
            for (int j = 0; j < K; j++) {
