class Solver {
  final int n, k;
  final int[] as;

  Solver(int n, int k, int[] as) {
    this.n = n;
    this.k = k;
    this.as = as;
  }

  public int solve() {
    int[] count = new int[k];
    for (int a : as) {
      if (a >= k) {
        continue;
      }
      count[a]++;
    }

    int requiredMin = 0;
    int requiredMax = k - 1;
    while (requiredMax - requiredMin >= 2) {
      int requiredMid = (requiredMax + requiredMin) / 2;
      count[requiredMid]--;
      boolean[] dptable = new boolean[k];
      dptable[0] = true;
      for (int i = 1; i < k; i++) {
        for (int j = 0; j < count[i]; j++) {
          for (int v = k - 1; v >= i; v--) {
            dptable[v] |= dptable[v - i];
          }
        }
      }
      count[requiredMid]++;
      boolean required = false;
      for (int i = k - requiredMid; i < k; i++) {
        required |= dptable[i];
      }
      if (required) {
        requiredMax = requiredMid;
      } else {
        requiredMin = requiredMid;
      }
    }
    int threshold = requiredMax;
    int sum = 0;
    for (int i = 1; i < threshold; i++) {
      sum += count[i];
    }
    return sum;
  }
}

