        public void solve() {
        	int N = ni();
        	int K = ni();
        	int[] A = ndi(N);
        	Arrays.sort(A);
        	boolean[][] dp_1 = new boolean[N+1][K+1];
        	boolean[][] dp_2 = new boolean[N+1][K+1];
        	dp_1[0][0] = true;
    		for (int j = 0; j < N; j++) {
    			for (int j2 = 0; j2 <= K; j2++) {
//        			prn(" i = " + i + " j = " + j + " j2 = " + j2 + " A[" + j + "] = " + A[j]);
//        			prn("  dp_1[" + j + "][" + j2 + "] = " + dp_1[j][j2]);
        			if(j2 - A[j] >= 0) {
        				dp_1[j+1][j2] |= (dp_1[j][j2] | dp_1[j][j2-A[j]]); 
//	        			prn("  dp_1[" + j + "][" + (j2-A[j]) + "] = " + dp_1[j+1][j2-A[j]]);
        			} else {
        				dp_1[j+1][j2] |= dp_1[j][j2];
        			}
//        			prn("  -->  dp_1[" + (j+1) + "][" + j2 + "] = " + dp_1[j+1][j2]);
    			}
    		}
        	dp_2[N][0] = true;
    		for (int j = N; j > 0; j--) {
    			for (int j2 = 0; j2 <= K; j2++) {
//        			prn(" i = " + i + " j = " + j + " j2 = " + j2 + " A[" + j + "] = " + A[j]);
//        			prn("  dp_2[" + j + "][" + j2 + "] = " + dp_2[j][j2]);
        			if(j2 - A[j-1] >= 0) {
        				dp_2[j-1][j2] |= (dp_2[j][j2] | dp_2[j][j2-A[j-1]]); 
//	        			prn("  dp_2[" + j + "][" + (j2-A[j]) + "] = " + dp_2[j+1][j2-A[j]]);
        			} else {
        				dp_2[j-1][j2] |= dp_2[j][j2];
        			}
//        			prn("  -->  dp_2[" + (j+1) + "][" + j2 + "] = " + dp_2[j+1][j2]);
    			}
    		}
        	int cnt = 0;		// 必要な数を数える
    		for (int i = 1; i <= N; i++) {
				LOOP:
    			for (int j = Math.max(K - A[i-1], 0); j < K; j++) {
    				for (int j2 = 0; j2 < j; j2++) {
//        				prn("" + A[i-1] + " -->  dp_1[" + (i-1) + "][" + (j-j2) + "] = " + dp_1[i-1][j-j2]
//        						+ "   dp_2[" + i + "][" + j2 + "] = " + dp_2[i][j2]);
//        				prn("     -->  dp_1[" + (i-1) + "][" + (j2) + "] = " + dp_1[i-1][j2]
//        						+ "   dp_2[" + i + "][" + (j-j2) + "] = " + dp_2[i][j-j2]);
//        				prn("------------------------------------------------------------------");
    					if((dp_1[i-1][j-j2] && dp_2[i][j2]) || (dp_1[i-1][j2] && dp_2[i][j-j2])) {
    						cnt++;
    						break LOOP;
    					}
					}
    			}
			}
        	prn(N - cnt);
        }

