        public void solve() {
        	int N = ni();
        	int K = ni();
        	int[] A = ndi(N);
        	Arrays.sort(A);
        	boolean[][] dp = new boolean[N+5][K+5];
        	int cnt = 0;		// 必要な数を数える
        	for (int i = 0; i < N; i++) {
        		for (int x = 0; x <= N; x++) {
        			Arrays.fill(dp[x], false);
				}
            	dp[0][0] = true;
        		for (int j = 0; j < N; j++) {
        			for (int j2 = 0; j2 <= K; j2++) {
//        				prn(" i = " + i + " j = " + j + " j2 = " + j2 + " A[" + j + "] = " + A[j]);
//        				prn("  dp[" + j + "][" + j2 + "] = " + dp[j][j2]);
	        			if(i != j && j2 - A[j] >= 0) {
	        				dp[j+1][j2] |= (dp[j][j2] | dp[j][j2-A[j]]); 
//	        				prn("  dp[" + j + "][" + (j2-A[j]) + "] = " + dp[j+1][j2-A[j]]);
	        			} else {
	        				dp[j+1][j2] |= dp[j][j2];
	        			}
//        				prn("  -->  dp[" + (j+1) + "][" + j2 + "] = " + dp[j+1][j2]);
        			}
        		}
    			for (int j2 = Math.max(K - A[i], 0); j2 < K; j2++) {
//    				prn("" + A[i] + " -->  dp[" + N + "][" + j2 + "] = " + dp[N][j2]);
//    				prn("------------------------------------------------------------------");
    				if(dp[N][j2]) {
    					cnt++;
    					break;
    				}
    			}
			}
        	prn(N - cnt);
        }

