            for (int j = 0; j < n; j++) {
                for (int l = 0; l <= k; l++) {
                    if (dp[j][l]) {
                        dp[j+1][l] = true;
                        if (i != j && l+a[j] <= k) {
                            dp[j+1][l+a[j]] = true;
                            if (l+a[j] >= k-a[i] && l+a[j] < k) f = true;
                        }
                    }
                }
            }

            if (!f) count++;
        }

        System.out.println(count);
    }
}

