import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static boolean exist(int a[], int t, int k) {
		if(a[t] > k)return true;
		int tmp = min_k(a, t, k);
		if(tmp < k && tmp + a[t] >= k)return true;
		else return false;
	}

	public static int min_k(int a[], int t, int k) {
		int ans = 0;
		for(int i = 0; i < a.length; ++i) {
			if(i != t) {
				ans += a[i];
				if(ans + a[t] >= k && ans < k)break;
			}
		}

		return ans;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n, k, a[], sum = 0, ans = 0;

		n = sc.nextInt();
		k = sc.nextInt();
		a = new int[n];
		for(int i = 0; i < n; ++i) {
			a[i] = sc.nextInt();
			sum += a[i];
		}
		sc.close();

		Arrays.sort(a);

		if(sum >= k) {
			for(int i = 0; i < n; ++i) {
				if(!exist(a, i, k))++ans;
			}		
		}
		else ans = n;
		System.out.println(ans);
	}

}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int K = sc.nextInt();
    int[] a = new int[N];
    for(int i = 0; i < N; i++) {
      a[i] = sc.nextInt();
    }
    Arrays.sort(a);
    int ans = -1;
    int left = 0;
    int right = N;
    while(left < right) {
      int med = (left + right) / 2;
      if(a[med] < K) {
        // dp[i][j]はカードiまででカードmedを使わずに総和をjと出来るかを表す
        boolean[][] dp = new boolean[N][K];
        dp[0][0] = true;
        if(med != 0) dp[0][a[0]] = true;
        for(int i = 1; i < N; i++) {
          dp[i][0] = true;
          for(int j = 1; j < K; j++) {
            if(med != i) {
              if(a[i] <= j) {
                dp[i][j] = (dp[i - 1][j] == 1) || (dp[i - 1][j - a[i]] == 1);
              } else {
                dp[i][j] = dp[i - 1][j];
              }
            } else {
              dp[i][j] = dp[i - 1][j];
            }
          }
        }
        boolean flg = false;
        for(int j = K - a[med]; j < K; j++) {
          if(dp[N - 1][j]) flg = true;
        }
        if(flg) {
          right = med;
        } else {
          ans = med;
          right = med + 1;
        }
      } else {
        right = med;
      }
    }
    ans++;
    System.out.println(ans);
  }
}

import java.util.Scanner;

class Main {

	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);
		//1行目の入力
		int N = sc.nextInt();
		int K = sc.nextInt();
		//2行目以降の入力
		int[] C = new int[N];
		for(int i=0; i<N; i++){
			C[i]  = sc.nextInt();
		}

		//前からi枚目までを使った時に総和をjにできるか
		boolean[][] dp1 = new boolean[N+1][K+1];
		dp1[0][0] = true;
		for(int j=1; j<=K; j++){
			dp1[0][j] = false;
		}
		for(int i=1; i<=N; i++){
			dp1[i][0] = true;
		}
		for(int i=1; i<=N; i++){
			for(int j=1; j<=K; j++){
				if(dp1[i-1][j]==true){dp1[i][j]=true;}
				if(j-C[i-1]>=0){
					if(dp1[i-1][j-C[i-1]]==true){dp1[i][j]=true;}
				}
				else{dp1[i][j]=false;}
			}
		}

		//後ろからi枚目までを使った時に総和をjにできるか
		boolean[][] dp2 = new boolean[N+1][K+1];
		dp2[0][0] = true;
		for(int j=1; j<=K; j++){
			dp2[0][j] = false;
		}
		for(int i=1; i<=N; i++){
			dp2[i][0] = true;
		}
		for(int i=1; i<=N; i++){
			for(int j=1; j<=K; j++){
				if(dp2[i-1][j]==true){dp2[i][j]=true;}
				if(j-C[N-i]>=0){
					if(dp2[i-1][j-C[N-i]]==true){dp2[i][j]=true;}
				}
				else{dp2[i][j]=false;}
			}
		}

		//「カードiを含んだ総和がK-C[i-1]以上K未満のものをつくれるiの個数」を数える
		int count = 0;
		for(int i=1; i<=N; i++){
			outside: for(int j=K-C[i-1]; j<K; j++){
				for(int l=0; l<=j; l++){
					if(dp1[i-1][l]==true && dp2[N-i][j-l] == true){
						count++;
						break outside;
					}
				}
			}
		}
		System.out.println(N-count);

	}

}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		new Main().solve();
	}

	int n,k;
	int[]a;

	void solve(){
		Scanner sc=new Scanner(System.in);
		n=sc.nextInt();
		k=sc.nextInt();
		a=new int[n];
		for(int i=0;i<n;i++){
			a[i]=sc.nextInt();
		}
		Arrays.sort(a);

		//二分探索
		int max=n;
		int min=0;
		int i=0;
		LOOP:while(min<max){
			i=(max+min)/2;

			if(a[i]>k){
				max=i;
				continue;
			}
			int idx=0;

			//dp[j][sum]:=j枚目までで和sumを作れるか
			boolean[][]dp=new boolean[n][k];
			for(int j=0;j<n;j++){
				dp[j][0]=true;
			}

			for(int j=1;j<n;j++){
				if(idx==i)idx++;	//i枚目は使わないので

				for(int sum=0;sum<k;sum++){
					if(dp[j-1][sum]){
						dp[j][sum]=true;
						int temp=sum+a[idx];
						if(temp<k)dp[j][temp]=true;
					}
				}
				idx++;
			}

			for(int sum=k-a[i];sum<k;sum++){
				if(dp[n-1][sum]){
					max=i;
					continue LOOP;
				}
			}
			min=i+1;
		}
		System.out.println(i+1);
	}
}

