		int N = sc.ni();
		int K = sc.ni();
		int[] nums = new int[N];
		for (int i = 0; i < N; i++)
			nums[i] = Math.min(sc.ni(),K);
		long[] dp = new long[2*K];
		dp[0] = 1L;
		for (int i = 0; i < N; i++) {
			for (int k = 2*K-1; k >= 0; k--) {
				if (k-nums[i] >= 0) {
					dp[k] += dp[k-nums[i]];
					dp[k] %= MOD;
				}
			}
		}
		long[][] withoutI = new long[N][2*K];
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < nums[i]; j++)
				withoutI[i][j] = dp[j];
			for (int j = nums[i]; j < 2*K; j++)
				withoutI[i][j] = (dp[j]-withoutI[i][j-nums[i]]+MOD)%MOD;
		}

		int ans = N;
		for (int i = 0; i < N; i++) {
			for (int j = K-1; j >= K-nums[i]; j--) {
				if (withoutI[i][j] != 0) {
					ans--;
					break;
				}
			}
		}
