public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[] a = new int[n];
        boolean[] need = new boolean[n];
        for(int i=0; i<n; i++){
            a[i] = sc.nextInt();
        }
        sc.close();

        int amin = Arrays.stream(a).min().getAsInt();
        if(amin > k){
            System.out.println(n);
            return;
        }else if(amin == k){
            int ans = 0;
            for(int i=0; i<n; i++){
                if(a[i] == amin) ans--;
            }
            System.out.println(ans);
            return;
        }

        for(int i=0; i<n; i++){
            if(a[i] + amin >= k && a[i] != amin){
                need[i] = true;
            }
        }

        int[][] dpl = new int[n][k];
        int[][] dpr = new int[n][k];
        dpl[0][0] = 1;
        dpr[n-1][0] = 1;
        if(a[0] < k) dpl[0][a[0]] = 1;
        if(a[n-1] < k) dpr[n-1][a[n-1]] = 1;
        for(int i=1; i<n; i++){
            dpl[i][0] = 1;
            for(int j=0; j<k-a[i]; j++){
                if(dpl[i-1][j] == 1) dpl[i][j+a[i]] = 1;
            }

            dpr[n-i-1][0] = 1;
            for(int j=0; j<k-a[n-i-1]; j++){
                if(dpr[n-i][j] == 1) dpr[n-i-1][j+a[n-i-1]] = 1;
            }

            for(int j=0; j<k; j++){
                if(dpl[i-1][j] == 1) dpl[i][j] = 1;
                if(dpr[n-i][j] == 1) dpr[n-i-1][j] = 1;    
            }
        }

        for(int i=0; i<n; i++){
            for(int j=1; j<k; j++){
                dpl[i][j] = dpl[i][j-1] + dpl[i][j];
                dpr[i][j] = dpr[i][j-1] + dpr[i][j];
            }
        }

