					dp[i+1][5000]+=dp[i][j];
				}
				else {
					dp[i+1][j+a[i]]+=dp[i][j];
				}
			}	
		}

		rdp[0][0] = 1;
		for(int i=0;i<n;i++) {
			for(int j=0;j<5001;j++) {
				rdp[i+1][j] += dp[i][j];
				if(j+a[n-1-i]>5000) {
					rdp[i+1][5000]+=rdp[i][j];
				}
				else {
					rdp[i+1][j+a[n-1-i]]+=rdp[i][j];
				}
			}	
		}

		long sum[][] = new long[n][5001];
		long rsum[][] = new long[n][5001];

		for(int i=0;i<n;i++) {
			sum[i][5000] = dp[i][5000];
			for(int j=5000;j>=1;j--) {
				sum[i][j-1] = sum[i][j] + dp[i][j-1];
			}
		}

		for(int i=0;i<n;i++) {
			rsum[i][5000] = rdp[i][5000];
