        if(a[0] < k) dpl[0][a[0]] = 1;
        if(a[n-1] < k) dpr[n-1][a[n-1]] = 1;
        for(int i=1; i<n; i++){
            dpl[i][0] = 1;
            for(int j=0; j<k-a[i]; j++){
                if(dpl[i-1][j] == 1) dpl[i][j+a[i]] = 1;
            }

            dpr[n-i-1][0] = 1;
            for(int j=0; j<k-a[n-i-1]; j++){
                if(dpr[n-i][j] == 1) dpr[n-i-1][j+a[n-i-1]] = 1;
            }

            for(int j=0; j<k; j++){
                if(dpl[i-1][j] == 1) dpl[i][j] = 1;
                if(dpr[n-i][j] == 1) dpr[n-i-1][j] = 1;    
            }
        }

        for(int i=0; i<n; i++){
            for(int j=1; j<k; j++){
                dpl[i][j] = dpl[i][j-1] + dpl[i][j];
                dpr[i][j] = dpr[i][j-1] + dpr[i][j];
            }
        }

        for(int i=1; i<n-1; i++){
            if(need[i]) continue;
            if(dpr[i+1][Math.max(0, k-1)] - dpr[i+1][Math.max(0, k-1-a[i])] >= 1) need[i] = true;
            for(int j=1; j<k; j++){
                if(dpl[i-1][j]-dpl[i-1][j-1]>=1){
                    if(dpr[i+1][Math.max(0, k-1-j)] - dpr[i+1][Math.max(0, k-1-j-a[i])] >= 1) need[i] = true;
                }
            }
        }
        if(!need[0]){
            if(dpr[1][k-1] - dpr[1][Math.max(0, k-1-a[0])] >= 1) need[0] = true;
        }
        if(!need[n-1]){
            if(dpl[n-2][k-1] - dpl[n-2][Math.max(0, k-1-a[n-1])] >= 1) need[n-1] = true;
        }

        int ans = 0;
        for(int i=0; i<n; i++) if(!need[i]) ans++;
        System.out.println(ans);
    }
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説通りに作成したソースコード
 * 
 * https://atcoder.jp/contests/abc056/submissions/4757789 と https://atcoder.jp/contests/abc056/submissions/3511073 にも参照
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt(), k = scanner.nextInt();
			int[] a = IntStream.range(0, n).map(i -> scanner.nextInt()).toArray();
			if (1 == n) {
				System.out.println((k > a[0]) ? 1 : 0);
				return;
			}
			Arrays.sort(a);

			int ng = 0, ok = n + 1;
			while (ok - ng > 1) {
				int mid = (ok + ng) / 2;
				if (isNeeded(mid, n, k, a)) {
					ok = mid;
				} else {
					ng = mid;
				}
			}
			System.out.println(ng);
		}
	}

	/**
	 * @param now
	 * @param n
	 * @param k
	 * @param a
	 * @return now番目のカードが必要かどうか
	 */
	private static boolean isNeeded(int now, final int n, final int k, final int[] a) {
		boolean[][] dp = new boolean[n + 1][k + 1];
		IntStream.range(0, n + 1).forEach(i -> Arrays.fill(dp[i], false));
		dp[0][0] = true;
		IntStream.rangeClosed(1, n).forEach(i -> IntStream.rangeClosed(0, k).forEach(j -> {
			if (i == now) {
				// ぬくカードの場合
				dp[i][j] = dp[i - 1][j];
			} else {
				if (dp[i - 1][j]) {
					dp[i][j] = true;
					if (j + a[i - 1] <= k) {
						dp[i][j + a[i - 1]] = true;
					}
				}
			}
		}));
		for (int i = k - 1; i >= Math.max(k - a[now - 1], 0); i--) {
			if (dp[n][i]) {
				return true;
			}
		}
		return false;
	}
}

