    //
    // 必要ならtrue [K - v , K)が作れるなら必要
    public static boolean solve(long v)
    {
        BitSet[] dp = new BitSet[N + 1];
        for (int i = 0; i < N + 1; i++)
        {
            dp[i] = new BitSet();
        }
        dp[0].set(0);
        for (int i = 0; i < N; i++)
        {
            for (int j = 0; j < K; j++)
            {
                if (!bitGet(dp[i], j)) continue;
                dp[i + 1].set(j);
                if (i == v) continue;
                dp[i + 1].set(j + A[i]);
            }
        }
        for (int k = K - A[(int) v]; k < K; k++)
        {
            if (bitGet(dp[N], k)) return true;
        }
        return false;
    }

    //条件を満たす最大値、あるいは最小値を求める
    static long binarysearch(long ok, long ng)
    {
        //int ok = 0; //解が存在する
        //int ng = N; //解が存在しない
        while (Math.abs(ok - ng) > 1)
        {
            long mid;
            if (ok < 0 && ng > 0 || ok > 0 && ng < 0) mid = (ok + ng) / 2;
            else mid = ok + (ng - ok) / 2;

            if (solve(mid))
            {
                ok = mid;
            }
            else
            {
                ng = mid;
            }
        }
        return ok;
    }

