import static java.util.Arrays.sort;




public class Main {
    public static void main(String[] args) {
        FastScanner fsc = new FastScanner();
        int n = fsc.nextInt();
        int k = fsc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = min(k, fsc.nextInt());
        }
        sort(a);
        TreeSet<Integer>[] back = new TreeSet[n + 1];
        back[n] = new TreeSet<>();
        back[n].add(0);
        for (int i = n - 1; i >= 0; i--) {
            back[i] = new TreeSet<>();
            for (int e : back[i + 1]) {
                back[i].add(e);
                if (e + a[i] < k) {
                    back[i].add(e + a[i]);
                }
            }
        }
        TreeSet<Integer> front = new TreeSet<>();
        front.add(0);
        int need = 0;
        for (int i = 0; i < n; i++) {
            int s = front.first();
            int t = front.last();
            int b = back[i + 1].lower(k - s);
            if (b >= k - a[i] - t) {
                need++;
            }
            TreeSet<Integer> fc = new TreeSet<>(front);
            for (int e : fc) {
                if (e + a[i] < k) {
                    front.add(e + a[i]);
                }
            }
        }
        System.out.println(n - need);
    }
}


class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

