import java.io.*;
import java.util.*;

class Solver {
  final int n, k;
  final int[] as;

  Solver(int n, int k, int[] as) {
    this.n = n;
    this.k = k;
    this.as = as;
  }

  public int solve() {
    int[] count = new int[k];
    Set<Integer> aSet = new HashSet<>();
    for (int a : as) {
      if (a >= k) {
        continue;
      }
      count[a]++;
      aSet.add(a);
    }
    List<Integer> uniqueAList = new ArrayList<>();
    uniqueAList.addAll(aSet);
    Collections.sort(uniqueAList);

    int requiredMinIndex = -1;
    int requiredMaxIndex = uniqueAList.size();
    while (requiredMaxIndex - requiredMinIndex >= 2) {
      int requiredMidIndex = (requiredMaxIndex + requiredMinIndex) / 2;
      int requiredMid = uniqueAList.get(requiredMidIndex);
      count[requiredMid]--;
      boolean[] dptable = new boolean[k];
      dptable[0] = true;
      for (int i = 1; i < k; i++) {
        for (int j = 0; j < count[i]; j++) {
          for (int v = k - 1; v >= i; v--) {
            dptable[v] |= dptable[v - i];
          }
        }
      }
      count[requiredMid]++;
      boolean required = false;
      for (int i = k - requiredMid; i < k; i++) {
        required |= dptable[i];
      }
      if (required) {
        requiredMaxIndex = requiredMidIndex;
      } else {
        requiredMinIndex = requiredMidIndex;
      }
    }

    int threshold;
    if (requiredMaxIndex >= uniqueAList.size()) {
      threshold = k;
    } else {
      threshold = uniqueAList.get(requiredMaxIndex);
    }

    int sum = 0;
    for (int i = 1; i < threshold; i++) {
      sum += count[i];
    }
    return sum;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int k = reader.nextInt();
    int[] as = reader.nextIntArray(n);
