public class Main {
    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int k = sc.nextInt();
        int[] a = new int[n];
        for (int i=0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            boolean[][] dp = new boolean[n+1][k+1];
            dp[0][0] = true;
            boolean f = false;

            for (int j = 0; j < n; j++) {
                if (f) break;
                for (int l = 0; l <= k; l++) {
                    if (dp[j][l]) {
                        dp[j+1][l] = true;
                        if (i != j && l+a[j] <= k) {
                            dp[j+1][l+a[j]] = true;
                            if (l+a[j] >= k-a[i] && l+a[j] < k) f = true; break;
                        }
                    }
                }
            }

            if (!f) count++;
        }

        System.out.println(count);
    }
}

