    //ふひつようならtrue [k-a[v] k) がないならtrue
    public static boolean solve(int mid)
    {
        if (mid == -1) return true;
        boolean[][] dp = new boolean[N + 1][K];
        dp[0][0] = true;
        for (int i = 0; i < N; i++)
        {
            for (int k = 0; k < K; k++)
            {
                if (i == mid)
                {
                    dp[i + 1][k] |= dp[i][k];
                }
                else
                {
                    dp[i + 1][k] |= dp[i][k];
                    if (k - A[i] >= 0)
                    {
                        dp[i + 1][k] |= dp[i][k - A[i]];
                    }
                }
            }
        }
        for (int i = upper0(K - A[mid]); i < K; i++)
        {
            if (dp[N][i]) return false;
        }
        return true;
    }

    //条件を満たす最大値、あるいは最小値を求める
    static long binarysearch(long ok, long ng)
    {
        //int ok = 0; //解が存在する
        //int ng = N; //解が存在しない
        while (Math.abs(ok - ng) > 1)
        {
            long mid;
            if (ok < 0 && ng > 0 || ok > 0 && ng < 0) mid = (ok + ng) / 2;
            else mid = ok + (ng - ok) / 2;

            if (solve((int) mid))
            {
                ok = mid;
            }
            else
            {
                ng = mid;
            }
        }
        return ok;
    }

