    }

    public void run() {
        Main main = new Main();
        try {
            in = new ContestScanner();
            out = new Writer();
            main.solve();
            out.close();
            in.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    void solve() throws IOException {
        n = in.nextInt();
        k = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }
        Arrays.sort(a);
        int left = 0;
        int right = n - 1;
        int ans = -1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (check(a, mid)) {
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        System.out.println(ans + 1);
    }

    int k, n;
    boolean check(int[] a, int x) {
        if(a[x] >= k) return false;
        boolean[] dp = new boolean[k * 2 + 1];
        dp[a[x]] = true;
        for (int i = 0; i < n; i++) {
            if(i == x) continue;
            if(a[i] >= k) break;
            for (int j = dp.length - 1 - a[i]; j >= 0; j--) {
                if(!dp[j]) continue;
                dp[j + a[i]] = true;
            }
        }
        for (int i = k; i < k + a[x]; i++) {
            if(dp[i]) return false;
        }
        return true;
    }
}

