	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int N = in.nextInt(); int K =in.nextInt();
			int[] a = new int[N];
			for (int i = 0; i < N; i++) {
				a[i] = in.nextInt();
			}
			Arrays.sort(a);

			int ans = 0;

			for (int i = 0; i < N; i++) {

				boolean[][] dp = new boolean[N+1][K+1];

				dp[0][0] = true;

				for (int j = 0; j < N; j++) {
					for (int k = 0; k <= K; k++) {

						// jがi番目と同じ場合は選ばない
						if (i == j) {
							dp[j+1][k] |= dp[j][k];
						} else {
							// DPの遷移条件
							if (k-a[j] >= 0) {
								dp[j+1][k] |= dp[j][k-a[j]];
							} else {
								dp[j+1][k] |= dp[j][k];
							}
						}

					}
				}

				boolean ok = false;
				for (int j = Math.max(0, K-a[i]); j < K; j++) {
					ok |= dp[N][j];
				}
				if (ok) ans++;

			}

			out.println(N-ans);



		}
	}

