        // -----------------------------------------
        public void solve() {
        	int N = ni();
        	int K = ni();
        	long[] A = ndl(N);
        	Arrays.sort(A);
        	long sum = 0, sv = K, cnt = 0;
        	for (int i = N-1; i >= 0; i--) {
