        	}
        	// キーのカウントを取得する（なければ　０　を返す）
        	public Long getCount(int key) {
        		Long val = map.get(key);
        		if(val == null)		return 0L;
        		else 				return val;
        	}
        	public Set<Integer> getKey() {
        		return map.keySet();
        	}
