import java.util.*;
import java.io.*;

class Main{
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int N=fsc.nextInt(), k=fsc.nextInt();
        ArrayList<Integer> in=new ArrayList<>();
        for(int i=0;i<N;i++){
            long ai=fsc.nextLong();
            if(ai<k) in.add((int) ai);
        }
        fsc.close();
        int[] a=new int[in.size()];
        int n=a.length;
        if(n==0){
            System.out.println(0);
            return;
        }
        else if(n==1){
            System.out.println(1);
            return;
        }
        for(int i=0;i<n;i++){
            a[i]=in.get(i);
        }
        TreeSet<Integer>[] fset=new TreeSet[n];
        for(int i=0;i<n;i++){
            fset[i]=new TreeSet<>();
        }
        fset[0].add(0);
        fset[0].add(a[0]);
        for(int i=1;i<n;i++){
            for(int ok:fset[i-1]){
                fset[i].add(ok);
                if(ok+a[i]<k) fset[i].add(ok+a[i]);
            }
        }
        TreeSet<Integer>[] bset=new TreeSet[n];
        for(int i=0;i<n;i++){
            bset[i]=new TreeSet<>();
        }
        bset[n-1].add(0);
        bset[n-1].add(a[n-1]);
        for(int i=n-2;i>=0;i--){
            for(int ok:bset[i+1]){
                bset[i].add(ok);
                if(ok+a[i]<k) bset[i].add(ok+a[i]);
            }
        }
        int ans=n;
        Out:for(int i=0;i<n;i++){
            if(i==0){
                if(Objects.nonNull(bset[1].higher(k-a[i]-1))){
                    ans--;
                }
            }
            else if(i==n-1){
                if(Objects.nonNull(fset[n-2].higher(k-a[i]-1))){
                    ans--;
                }
            }
            else{
                for(int ok: fset[i-1]){
                    Integer h=bset[i+1].higher(k-a[i]-ok-1);
                    if(Objects.nonNull(h)){
                        if(ok+h<k){
                            ans--;
                            continue Out;
                        }
                    }
                }
            }
        }
        System.out.println(ans);
    }
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

