public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Aoki" : "Takahashi"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var K = cr.Int;
        var arr = cr.Repeat(N).Int.Where(n => n < K).ToArray().Sort(ComparerReverse<int>());
        N = arr.Length;
        var hissu = new HashSet<int>();
        var dp = new HashSet<int>[K];
        dp[0] = new HashSet<int>();
        for (int i = 0; i < arr.Length; i++)
        {
            for (int j = dp.Length - arr[i]; j < dp.Length; j++)
                if (dp[j] != null)
                    hissu.UnionWith(dp[j].Append(arr[i]));
            for (int j = dp.Length - arr[i] - 1; j >= 0; j--)
                if (dp[j] != null)
                {
                    if (dp[j + arr[i]] == null)
                        dp[j + arr[i]] = new HashSet<int>(dp[j].Append(arr[i]));
                    else
                        dp[j + arr[i]].UnionWith(dp[j].Append(arr[i]));
                }
        }

        return N - arr.Count(hissu.Contains);
    }
}

