class Simple {
    private int N, K;
    private int[] a;
    void Solve() {
        //input
        N = io.Int;
        K = io.Int;
        a = new int[N];
        for(int i = 0; i < N; ++i) a[i] = io.Int;
        //cal
        Func <int, bool> check = (n) => {
            if(a[n] > K) return true;
            var dp = new bool[K];
            dp[0] = true;
            for(int i = 0; i < N; ++i) {
                if(i == n) continue;
                for(int j = K - 1; j >= 0; --j) 
                    if(dp[j] && j + a[i] < K)
                        dp[j + a[i]] = true;
            }
            for(int i = K - a[n]; i < K; ++i) 
                if(dp[i]) return true;
            return false;
        };
        Array.Sort(a);
        var ans = search(a, -1, N, check);
        //ret
        Console.WriteLine(ans);
    }
    int search(int[] arr, int ng, int ok, Func <int, bool> f) {
        while(Math.Abs(ok - ng) > 1) {
            var mid = (ok + ng) / 2;
            if(f(mid)) ok = mid;
            else ng = mid;
        }
        return ok;
    }
    SimpleIO io = new SimpleIO();
