	public class Program
	{
		static void Main(string[] args)
		{
			var nk = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
			int n = nk[0];
			int k = nk[1];
			int[] a = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
			Array.Sort(a);

			long allNum = Calc(a, n, k);
			if (allNum == 0) {
				Console.WriteLine(n);
				return;
			}

			int ok = -1;
			int ng = n;
			while (ng - ok > 1) {
				int mid = (ng + ok) / 2;
				int temp = a[mid];
				a[mid] = 0;
				long num = Calc(a, n, k);
				if (num == allNum) {
					ok = mid;
				} else {
					ng = mid;
				}

				a[mid] = temp;
			}

			int ans = ok + 1;
			Console.WriteLine(ans);
		}

		static long Calc(int[] a, int n, int k)
		{
			var dp = new long[k + 1];
			for (int i = 0; i < n; i++) {
				var dst = new long[k + 1];
				for (int j = 0; j <= k; j++) {
					if (dp[j] == 0) {
						continue;
					}

					dst[j] += dp[j];
					dst[Math.Min(k, j + a[i])] += dp[j];
				}

				dst[Math.Min(k, a[i])] += 1;

				dp = dst;
			}

			return dp[k];
		}
	}
}

