public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int K = GetInt();
		int[] a = GetInts(N);

		Array.Sort(a);
		Array.Reverse(a);

		int ok = -1;
		int ng = N;
		while(Abs(ok - ng) > 1)
		{
			int mid = (ok + ng) / 2;
			if(need(N, K, a, mid))
				ok = mid;
			else
				ng = mid;
		}
		WriteLine(N - ok - 1);
	}

	private bool need(int N, int K, int[] a, int pos)
	{
		bool[,] dp = new bool[N, K];
		dp[0, 0] = true;
		int offset = 0;
		int prevMax = 0;
		int max = 0;
		for(int i = 0; i < N - 1; i++)
		{
			if(i == pos)
				offset++;

			max = prevMax;
			for(int j = 0; j <= prevMax; j++)
			{
				if(!dp[i, j])
					continue;

				dp[i + 1, j] = true;
				if(j + a[i + offset] < K)
				{
					dp[i + 1, j + a[i + offset]] = true;
					max = Max(max, j + a[i + offset]);
				}
			}
			prevMax = max;
		}

		int cnt = 0;
		for(int i = K - 1; i >= 0; i--)
		{
			if(dp[N - 1, i])
			{
				cnt = i;
				break;
			}
		}
		return (cnt + a[pos] >= K);
	}
}

