	public class Program
	{
		static void Main(string[] args)
		{
			var nk = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
			int n = nk[0];
			int k = nk[1];
			int[] a = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();

			long allNum = 0;
			{
				var dp = new long[n + 1, k + 1];
				for (int i = 0; i < n; i++) {
					for (int j = 0; j <= k; j++) {
						if (dp[i, j] == 0) {
							continue;
						}

						dp[i + 1, j] += dp[i, j];
						int target = Math.Min(k, j + a[i]);
						dp[i + 1, target] += dp[i, j];
					}

					dp[i + 1, Math.Min(k, a[i])] += 1;
				}

				allNum = dp[n, k];
			}

			if (allNum == 0) {
				Console.WriteLine(n);
				return;
			}

			int ans = 0;
			for (int r = 0; r < n; r++) {
				int temp = a[r];
				a[r] = 0;

				var dp = new long[n + 1, k + 1];
				for (int i = 0; i < n; i++) {
					for (int j = 0; j <= k; j++) {
						if (dp[i, j] == 0) {
							continue;
						}

						dp[i + 1, j] += dp[i, j];
						int target = Math.Min(k, j + a[i]);
						dp[i + 1, target] += dp[i, j];
					}

					dp[i + 1, Math.Min(k, a[i])] += 1;
				}

				long num = dp[n, k];
				if (allNum == num) {
					++ans;
				}

				a[r] = temp;
			}

			Console.WriteLine(ans);
		}
	}
}

