    // After seeing editorial
    class Program
    {
        static void Main(string[] args)
        {
            string[] bufs = Console.ReadLine().Split(' ');
            int N = Int32.Parse(bufs[0]);
            int K = Int32.Parse(bufs[1]);
            int[] a = new int[N];
            bool[,] reach = new bool[N,K];

            string buf = String.Empty;
            char ch = '\0';
            int idx = 0;
            while (idx < N - 1)
            {
                ch = (char)Console.Read();
                if (ch == ' ' || ch == '\n')
                {
                    a[idx] = Int32.Parse(buf);
                    buf = String.Empty;
                    idx++;
                }
                else
                {
                    buf += ch;
                }
            }

            buf = Console.ReadLine();
            a[idx] = Int32.Parse(buf);

            int res = N;
            bool loop = false;

            for (int i = 0; i < N; i++)
            {
                loop = true;
                for (int j = 0; j < N; j++)
                {
                    reach[j, 0] = true;
                    for (int k = 1; k < K; k++)
                    {
                        reach[j, k] = false;
                    }
                }

                int line = K - a[i];

                for (int j = 0; j < N - 1 && loop; j++)
                {
                    int c = (j < i) ? j : j + 1;
                    for (int k = 0; k < K; k++)
                    {
                        if (reach[j, k])
                        {
                            if (line <= k)
                            {
                                loop = false;
                                res--;
                                break;
                            }
                            reach[j + 1, k] = true;

                            if (k + a[c] < K)
                            {
                                reach[j + 1, k + a[c]] = true;
                            }
                        }
                    }
                }
            }            

            Console.WriteLine(res);
        }
    }
