        static int NeedNum(int K, int[] vals)
        {
            int sum = 0;
            int hit = -1;
            for (int i = 0; i < vals.Length; i++)
            {
                sum += vals[i];
                if (sum >= K && (i + 1 >= vals.Length || hit == vals[i + 1]))
                {
                    return (i + 1) + NeedNum(K, vals.Skip(i + 1).ToArray());
                }
            }
            return 0;
        }
