            var left = new long[N + 1, K + 1];//0:0,1:a1,2:(a1,a2),･･･,N:(a1,a2,･･･,aN)
            var right = new long[N + 1, K + 1];//0:0,1:aN,2:(aN-1,aN),･･･N:(a1,a2,･･･aN)
            left[0, 0] = 1;
            right[0, 0] = 1;
            for (var i = 1; i <= N; ++i)
            {
                for (var j = 0; j <= K; ++j)
                {
                    if (left[i - 1, j] == 1)
                    {
                        left[i, j] = 1;
                        if (j + ai[i - 1] <= K)
                            left[i, j + ai[i - 1]] = 1;
                    }
                    if (right[i - 1, j] == 1)
                    {
                        right[i, j] = 1;
                        if (j + ai[N - i] <= K)
                            right[i, j + ai[N - i]] = 1;
                    }
                }
            }
            //aiを使わないとき、～ai)から[ai+1～が満たせばよい数値を作る
            var imos = new long[N + 1, K + 2];
            for (var i = 0; i < N; ++i)
            {
                for (var j = 0; j <= K; ++j)
                {
                    if (left[i, j] == 1)
                    {
                        imos[i, Max(0,K - ai[i] - j)] += 1;
                        imos[i, Max(0, K - j)] -= 1;
                    }
                }
                for (var j = 1; j <= K; ++j)
                    imos[i, j] += imos[i, j - 1];
            }
            var cnt = 0L;
            for (var i = 0; i < N; ++i)
            {
                var used = false;
                for (var j = 0; j <= K; ++j)
                {
                    //a_iを使わないとき、ai+1～aNでimosが1の値を作ることができれば必要なカード
                    //imos[i,]:a_iを使わない場合
                    //right[N-1-i,]:aN～ai+1を使う
                    if (0 < imos[i, j] && 0 < right[N - 1 - i, j])
                        used = true;
                }
                if (!used)
                    ++cnt;
            }
            WriteLine(cnt);
        }

        static long Mod = (long)1e9 + 7;
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        static public (T1 a, T2 b) Slice<T1, T2>()
        {
            var t = ReadLine().Split();
            return (
            (T1)Convert.ChangeType(t[0], typeof(T1)),
            (T2)Convert.ChangeType(t[1], typeof(T2)));
        }
        static public (T a, T b) Slice2<T>()
        {
            var t = ReadLine().Split();
            return (
            (T)Convert.ChangeType(t[0], typeof(T)),
            (T)Convert.ChangeType(t[1], typeof(T)));
        }
        static public (T a, T b, T c) Slice3<T>()
        {
            var t = ReadLine().Split();
            return (
            (T)Convert.ChangeType(t[0], typeof(T)),
            (T)Convert.ChangeType(t[1], typeof(T)),
            (T)Convert.ChangeType(t[2], typeof(T)));
        }
    }
