namespace Kujikatsu004.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/abc056/tasks/arc070_b
    /// </summary>
    public class QuestionG : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var (n, k) = inputStream.ReadValue<int, int>();
            var a = inputStream.ReadIntArray();

            var counts = new Modular[n + 1, n + 1, k + 1].SetAll((i, j, k) => new Modular(0));
            for (int i = 0; i <= n; i++)
            {
                counts[i, 0, 0] = new Modular(1);
            }

            for (int ignored = 0; ignored <= n; ignored++)
            {
                for (int item = 0; item < n; item++)
                {
                    for (int sum = 0; sum <= k; sum++)
                    {
                        counts[ignored, item + 1, sum] += counts[ignored, item, sum];
                        if (item != ignored - 1)
                        {
                            counts[ignored, item + 1, Math.Min(sum + a[item], k)] += counts[ignored, item, sum];
                        }
                    }
                }
            }

            var count = 0;
            for (int ignored = 1; ignored <= n; ignored++)
            {
                if (counts[0, n, k] / new Modular(2) == counts[ignored, n, k])
                {
                    count++;
                }
            }

            yield return count;
        }
    }
}


namespace Kujikatsu004
{
    class Program
    {
        static void Main(string[] args)
        {
            IAtCoderQuestion question = new QuestionG();
            var answers = question.Solve(Console.In);

            var writer = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(writer);
            foreach (var answer in answers)
            {
                Console.WriteLine(answer);
            }
            Console.Out.Flush();
        }
    }
}

