                bool need = false;
                if (array[x] >= nk[1]) need = true;
                else
                {
                    var dp = new bool[nk[1]];
                    dp[0] = true;
                    for (int i = 0; i < nk[0]; i++)
                    {
                        if (x == i) continue;

                        var nextDp = new bool[nk[1]];
                        for (int j = 0; j < nk[1]; j++)
                        {
                            if (!dp[j]) continue;

                            nextDp[j] = true;

                            if (j + array[i] >= nk[1]) continue;

                            if (j + array[i] >= nk[1] - array[x])
