namespace ABC056D
{
    // After seeing editorial
    class Program
    {
        static void Main(string[] args)
        {
            string[] bufs = Console.ReadLine().Split(' ');
            int N = Int32.Parse(bufs[0]);
            int K = Int32.Parse(bufs[1]);
            int[] a = new int[N];
            bool[,] reach = new bool[N,K];

            bufs = Console.ReadLine().Split(' ');
            for (int i = 0; i < N; i++)
            {
                a[i] = Int32.Parse(bufs[i]);
            }

            int res = N;
            int broken = 0;
            bool loop = false;

            for (int i = 0; i < N; i++)
            {
                if (broken >= a[i]) { continue; }

                for (int j = 0; j < N; j++)
                {
                    reach[j, 0] = true;
                    for (int k = 1; k < K; k++)
                    {
                        reach[j, k] = false;
                    }
                }

                int line = K - a[i];
                loop = line > 0;

                for (int j = 0; j < N - 1 && loop; j++)
                {
                    int c = (j < i) ? j : j + 1;
                    for (int k = 0; k < K; k++)
                    {
                        if (reach[j, k])
                        {
                            if (line <= k)
                            {
                                loop = false;
                                break;
                            }
                            reach[j + 1, k] = true;

                            if (k + a[c] < K)
                            {
                                reach[j + 1, k + a[c]] = true;
                            }
                            else
                            {
                                // continue;
                            }
                        }
                    }

                }

                for (int k = line; k < K; k++)
                {
                    if (!loop || reach[N - 1, k])
                    {
                        res--;
                        break;
                    }
                    else if (k == K - 1 && broken < a[i])
                    {
                        broken = a[i];
                    }
                }

            }
            Console.WriteLine(res);
        }
    }
}

