            public int calu(int[] input1, int[] input2){
                Array.Sort(input2);
                Array.Reverse(input2);
                long a = 0;
                for (int i = 0; i < input2.Length; i++)
                {   if (input2[i] <= input1[1])
                    {
                        a += input2[i];
                        if (input1[1] <= a)
                        {
                            return input2.Length - (i + 1);
                        }
                    }
                }
                return input2.Length;
            }
        }
    }

