class Prog
{
    public Prog() { }
    public static int Main()
    {
        new Prog().calc();
        return 0;
    }

    Scanner cin;
    const long MaxK = 5000;

    public void calc()
    {
        cin = new Scanner();
        long N = cin.nextLong();
        long K = cin.nextLong();
        long[] a = new long[N];

        for (long i = 0; i < N; i++)
            a[i] = cin.nextLong();

        Array.Sort(a);

        long maxpos = a.Length;
        for(long i = 0;i<N;i++)
        {
            if(a[i] >= K)
            {
                maxpos = i;
                break;
            }
        }

        long ans = 0;

        for (long k = 0; k < maxpos; k++)
        {
            // dp[N] := Nを作れたら1
            long[] dp = new long[MaxK + 1];
            dp[0]++;
            for (int i = 0; i < maxpos; i++)
            {
                for (long n = MaxK; n >= 0; n--)
                {
                    if (i != k && n - a[i] >= 0 && dp[n - a[i]] > 0) dp[n]++;
                }
            }

            bool ok = false;
            for(long n = K-a[k];n<= K-1;n++)
            {
                if (dp[n] > 0)
                {
                    ok = true;
                    break;
                }
            }

            ans += ok ? 0 : 1;
        }
        Console.WriteLine(ans);
        Console.Read();


    }
}


