class Simple {
    private int N, K;
    private int[] a;
    void Solve() {
        //input
        N = io.Int;
        K = io.Int;
        a = new int[N];
        for(int i = 0; i < N; ++i) a[i] = io.Int;
        //cal
        Func <int, bool> check = (n) => {
            if(a[n] > K) return true;
            var dp = new bool[K];
            dp[0] = true;
            for(int i = 0; i < N; ++i) {
                if(i == n) continue;
                for(int j = K - 1; j >= 0; --j) 
                    if(dp[j] && j + a[i] < K)
                        dp[j + a[i]] = true;
            }
            for(int i = K - a[n]; i < K; ++i) 
                if(dp[i]) return true;
            return false;
        };
        Array.Sort(a);
        var ans = search(a, -1, N, check);
        //ret
        Console.WriteLine(ans);
    }
    int search(int[] arr, int ng, int ok, Func <int, bool> f) {
        while(Math.Abs(ok - ng) > 1) {
            var mid = (ok + ng) / 2;
            if(f(mid)) ok = mid;
            else ng = mid;
        }
        return ok;
    }
    SimpleIO io = new SimpleIO();
    public static void Main(string[] args) => new Simple().Stream();
    private void Stream() {
        //var exStdIn = new System.IO.StreamReader("stdin.txt");
        //System.Console.SetIn(exStdIn);
        Solve();
        io.Flush();
    }
}
class SimpleIO {
    string[] _nextBuffer;
    int _bufferCnt;
    char[] cs = new char[] {' ', '"', ','};
    StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) {AutoFlush = false};
    public SimpleIO() {
        _nextBuffer = new string[0];
        _bufferCnt = 0;
        Console.SetOut(sw);
    }
    public string Next() {
        if(_bufferCnt < _nextBuffer.Length) return _nextBuffer[_bufferCnt++];
        var st = Console.ReadLine();
        while(st == "") st = Console.ReadLine();
        if(st != null) _nextBuffer = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        else st = "";
        _bufferCnt = 0;
        return _nextBuffer[_bufferCnt++];
    }
    public string String => Next();
    public char Char => char.Parse(String);
    public int Int => int.Parse(String);
    public long Long => long.Parse(String);
    public double Double => double.Parse(String);
    public void Flush() { Console.Out.Flush(); }
}
