namespace Kujikatsu004.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/abc056/tasks/arc070_b
    /// </summary>
    public class QuestionG : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var (n, k) = inputStream.ReadValue<int, int>();
            var a = inputStream.ReadIntArray();
            const int mod = 1_000_000_007;

            var counts = new long[n + 1, n + 1, k + 1].SetAll((i, j, k) => 0);
            for (int i = 0; i <= n; i++)
            {
                counts[i, 0, 0] = 1;
            }

            for (int ignored = 0; ignored <= n; ignored++)
            {
                for (int item = 0; item < n; item++)
                {
                    for (int sum = 0; sum <= k; sum++)
                    {
                        counts[ignored, item + 1, sum] += counts[ignored, item, sum];

                        if (counts[ignored, item + 1, sum] >= mod)
                        {
                            counts[ignored, item + 1, sum] -= mod;
                        }

                        if (item != ignored - 1)
                        {
                            var index = Math.Min(sum + a[item], k);
                            counts[ignored, item + 1, index] += counts[ignored, item, sum];
                            if (counts[ignored, item + 1, index] >= mod)
                            {
                                counts[ignored, item + 1, index] -= mod;
                            }
                        }
                    }
                }
            }

            var count = 0;
            for (int ignored = 1; ignored <= n; ignored++)
            {
                if (counts[0, n, k] == (counts[ignored, n, k] * 2) % mod)
                {
                    count++;
                }
            }

            yield return count;
        }
    }
}


