using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace AtCoder
{
	class Program
	{
		static void Main(string[] args)
		{
			var firstLine = Console.ReadLine().Split(' ').Select(value => int.Parse(value)).ToList();
			var n = firstLine[0];
			var k = firstLine[1];
			var numbers = Console.ReadLine().Split(' ').Select(value => long.Parse(value)).ToList();
			numbers.Sort();

			var needList = new List<bool>();

			for(int i = 0; i < n; i++)
			{
				needList.Add(false);
			}


			for(int i = 0; i < n; i++)
			{
				if(numbers[i] >= k)
				{
					break;
				}

				long sum = 0;

				for(int j = i; j < n; j++)
				{
					sum += numbers[j];

					if(sum >= k)
					{
						if(sum - numbers[i] < k)
						{
							needList[i] = true;
						}
						break;
					}
				}
			}

			for(int i = n - 1; i >= 0; i--)
			{
				if(needList[i])
				{
					break;
				}

				if(numbers[i] >= k)
				{
					needList[i] = true;
				}

				long sum = 0;

				for (int j = i; j >= 0; j--)
				{
					sum += numbers[j];

					if (sum >= k)
					{
						if (sum - numbers[i] < k)
						{
							needList[i] = true;
						}
						break;
					}
				}
			}

			Console.WriteLine(needList.Count(value => !value));
        }
	}
}

