namespace Kujikatsu004.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/abc056/tasks/arc070_b
    /// </summary>
    public class QuestionG : AtCoderQuestionBase
    {
        const int mod = 1_000_000_007;

        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            var (n, k) = inputStream.ReadValue<int, int>();
            var a = inputStream.ReadIntArray();
            Array.Sort(a);

            var normalCount = GetCounts(n, k, -1, a);

            var count = SearchExtensions.BoundaryBinarySearch(ignored => normalCount == (GetCounts(n, k, ignored, a) * 2) % mod, -1, n) + 1;

            yield return count;
        }

        int GetCounts(int n, int k, int ignored, int[] a)
        {
            var counts = new int[n + 1, k + 1];
            counts[0, 0] = 1;

            for (int item = 0; item < n; item++)
            {
                for (int sum = 0; sum <= k; sum++)
                {
                    counts[item + 1, sum] += counts[item, sum];

                    if (counts[item + 1, sum] >= mod)
                    {
                        counts[item + 1, sum] -= mod;
                    }

                    if (item != ignored)
                    {
                        var index = Math.Min(sum + a[item], k);
                        counts[item + 1, index] += counts[item, sum];
                        if (counts[item + 1, index] >= mod)
                        {
                            counts[item + 1, index] -= mod;
                        }
                    }
                }
            }
            return counts[n, k];
        }
    }
}


