        private bool IsNeededSub(int target, int idx, long subTotal) {
            if(subTotal >= this.TargetNum) {
                return false;
            }
            if(subTotal + this.Items[target] >= this.TargetNum) {
                return true;
            }
            if(idx >= this.Items.Length) {
                return false;
            } 
            if(this.Items[idx]>=this.TargetNum) {
                return false;
            }
            if(!dic.ContainsKey(target)) {
                dic.Add(target, new Dictionary<int, Dictionary<long, bool>>());
            }
            if(!dic[target].ContainsKey(idx)) {
                dic[target].Add(idx, new Dictionary<long, bool>());
            }
            if(dic[target][idx].ContainsKey(subTotal)) {
                return dic[target][idx][subTotal];
            }
            bool ans = this.IsNeededSub(target,idx+1, subTotal);
            if(target != idx && (!ans)) {
                ans = this.IsNeededSub(target,idx+1, subTotal+this.Items[idx]);
            }
            dic[target][idx][subTotal] = ans;
