	public void Solve()
	{
		int N = GetInt();
		int K = GetInt();
		int[] a = GetInts(N);

		Array.Sort(a);
		Array.Reverse(a);

		bool[,] dp = new bool[N, K];
		int ok = -1;
		int ng = N;
		while(Abs(ok - ng) > 1)
		{
			int mid = (ok + ng) / 2;
			if(need(dp, N, K, a, mid))
				ok = mid;
			else
				ng = mid;
		}
		WriteLine(N - ok - 1);
	}

	private bool need(bool[,] dp, int N, int K, int[] a, int pos)
	{
		for(int i = 0; i < N; i++)
		{
			for(int j = 0; j < K; j++)
				dp[i, j] = false;
		}
		dp[0, 0] = true;

		int offset = 0;
		for(int i = 0; i < N - 1; i++)
		{
			if(i == pos)
				offset++;

			for(int j = 0; j < K; j++)
			{
				if(dp[i, j])
					dp[i + 1, j] = true;

				if(j + a[i + offset] < K && dp[i, j])
					dp[i + 1, j + a[i + offset]] = true;
			}
		}

		int max = 0;
		for(int i = K - 1; i >= 0; i--)
		{
			if(dp[N - 1, i])
			{
				max = i;
				break;
			}
		}
		return (max + a[pos] >= K);
	}
}

