	{
		static void Main(string[] args)
		{
			var nk = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
			int n = nk[0];
			int k = nk[1];
			long[] a = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();

			Func<long> calc = () => {
				var dp = new long[n + 1, k + 1];
				for (int i = 0; i < n; i++) {
					for (int j = 0; j <= k; j++) {
						if (dp[i, j] == 0) {
							continue;
						}

						dp[i + 1, j] += dp[i, j];
						dp[i + 1, Math.Min(k, j + a[i])] += dp[i, j];
					}

					dp[i + 1, Math.Min(k, a[i])] += 1;
				}

				return dp[n, k];
			};

			long allNum = calc();
			if (allNum == 0) {
				Console.WriteLine(n);
				return;
			}

			int ans = 0;
			for (int r = 0; r < n; r++) {
				long temp = a[r];
				a[r] = 0;

				long num = calc();
				if (allNum == num) {
					++ans;
				}

				a[r] = temp;
			}

			Console.WriteLine(ans);
		}
	}
