    int n, k;
    long[] xs;

    void Read()
    {
        var line = ReadLine(int.Parse);
        n = line[0];
        k = line[1];
        xs = ReadLine(long.Parse);
    }

    int Solve()
    {
        Array.Sort(xs);

        var count = 0;

        for (var j = 0; j < xs.Length; j++)
        {
            var sum = xs[j];

            for (var i = 0; i < xs.Length; i++)
            {
                if (i == j) continue;
                if (sum >= k) break;
                sum += xs[i];
            }

            if (sum < k || sum - xs[j] >= k)
            {
                count++;
            }
        }

        return count;
    }

