class Solver
{
    public void Solve(Scanner sc)
    {
        int N, K;
        sc.Make(out N, out K);
        var A = sc.ArrInt.Where(v=>v<K).ToArray();
        Array.Sort(A);
        int r = A.Length, l = -1;
        while (r - l > 1)
        {
            var m = (r + l) >> 1;
            var dp = new bool[K + 1];
            var newdp = new bool[K + 1];
            dp[0] = true;
            for (int i = 0; i < A.Length; i++)
            {
                if (i == m) continue;
                for (int j = 0; j < K+1; j++)
                {
                    newdp[j] = dp[j];
                    if (j - A[i] >= 0) newdp[j] |= dp[j - A[i]];
                }
                swap(ref dp, ref newdp);
            }
            var ok = true;
            for (int j = K - 1; j >= K - A[m]; j--)
                ok &= !dp[j];
            if (ok) l = m;
            else r = m;
        }
        WriteLine(l+1);
    }
}

