using System;
class Program
{
    static IO io = new IO();

    static void Main(string[] args)
    {
        io.ReadSplit();
        int N = io.Int();
        int K = io.Int();
        io.ReadSplit();
        int[] a = io.Int(N);
        Array.Sort(a);

        int[] aLessThanK = RemoveItemMorethanK(a, K);
        Array.Reverse(aLessThanK);

        int NecessaryCount;
        if (Sum(aLessThanK) >= K)
        {
            NecessaryCount = aLessThanK.Length - CountNecessary(aLessThanK, K);
        }
        else
        {
            NecessaryCount = aLessThanK.Length;
        }
        io.Write(NecessaryCount.ToString());

    }
    static int Sum(int[] a)
    {
        int sum = 0;
        for (int i = 0; i < a.Length; ++i)
        {
            sum += a[i];
        }
        return sum;
    }
    static int[] RemoveItemMorethanK(int[] a, int K)
    {
        for (int i = 0; i < a.Length; ++i)
        {
            if (a[i] >= K)
            {
                int[] aa = new int[i];
                Array.Copy(a, aa, i);
                return aa;
            }
        }
        return a;
    }
    static int[] RemoveItemFromArray(int[] a, int index)
    {
        int[] aa = new int[a.Length - 1];
        for (int i = 0; i < index - 1; ++i)
        {
            aa[i] = a[i];
        }
        for (int i = index + 1; i < a.Length; ++i)
        {
            aa[i - 1] = a[i];
        }
        return aa;
    }
    static int CountNecessary(int[] a, int K)
    {
        int count = 0;
        for (int i = 0; i < a.Length; ++i)
        {
            int[] aa = RemoveItemFromArray(a, i);
            if (IsNecessary(aa, 0, 0, K - a[i]))
            {
                count += 1;
            }
        }
        return count;
    }
    static bool IsNecessary(int[] a, int i, int sum, int K)
    {
        if (i >= a.Length) { return true; }
        if (sum + a[i] > K) { return false; }
        if (!IsNecessary(a, i + 1, sum + a[i], K)) { return false; }
        if (!IsNecessary(a, i + 1, sum, K)) { return false; }
        return true;
    }
}

