			{
				var dp = new long[n + 1, k + 1];
				for (int i = 0; i < n; i++) {
					for (int j = 0; j <= k; j++) {
						if (dp[i, j] == 0) {
							continue;
						}

						dp[i + 1, j] += dp[i, j];
						long target = Math.Min(k, j + a[i]);
						dp[i + 1, target] += dp[i, j];
					}

					dp[i + 1, Math.Min(k, a[i])] += 1;
				}

				allNum = dp[n, k];
			}

			int ans = 0;
			for (int r = 0; r < n; r++) {
				long temp = a[r];
				a[r] = 0;

				var dp = new long[n + 1, k + 1];
