public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int K = GetInt();
		int[] a = GetInts(N);

		Array.Sort(a);
		Array.Reverse(a);
		int ok = -1;
		int ng = N;
		while(Abs(ok - ng) > 1)
		{
			int mid = (ok + ng) / 2;
			if(need(N, K, a, mid))
				ok = mid;
			else
				ng = mid;
		}
		WriteLine(N - ok - 1);
	}

	private bool need(int N, int K, int[] a, int pos)
	{
		var b = new List<int>();
		for(int i = 0; i < N; i++)
		{
			if(i != pos)
				b.Add(a[i]);
		}

		bool[,] dp = new bool[N, K];
		dp[0, 0] = true;
		for(int i = 0; i < N - 1; i++)
		{
			for(int j = 0; j < K; j++)
			{
				if(dp[i, j])
					dp[i + 1, j] = true;

				if(j + b[i] < K && dp[i, j])
					dp[i + 1, j + b[i]] = true;
			}
		}

		int max = 0;
		for(int i = K - 1; i >= 0; i--)
		{
			if(dp[N - 1, i])
			{
				max = i;
				break;
			}
		}
		return (max + a[pos] >= K);
	}
}

