	}
	sort.Ints(a)

	// binary_search
	dp := make([][]bool, N+1)
	for i := range dp {
		dp[i] = make([]bool, K+1)
	}
	left, right := 0, N+1
	for left+1 < right {
		index := (left + right) / 2
		for i := range dp {
			for j := range dp[i] {
				dp[i][j] = false
			}
		}
		dp[0][0] = true
		// i文字目までで，値jを作れるか動的計画法で調査
		for i := 1; i < N+1; i++ {
