package main

import (
	"fmt"
)

var N, K int
var arr []int

func max(a, b int) int {
	if a < b {
		return b
	}
	return a
}

func main() {
	fmt.Scan(&N, &K)
	arr = make([]int, N+1)

	for i := 1; i <= N; i++ {
		fmt.Scan(&arr[i])
	}

	dp := make([][][]bool, N)
	for i := range dp {
		dp[i] = make([][]bool, N+1)
		for j := range dp[i] {
			dp[i][j] = make([]bool, K+1)
			dp[i][j][0] = true
		}
	}

	count := 0
	for i := 0; i < N; i++ {
		for num := 1; num <= N; num++ {
			if i+1 == num {
				dp[i][num] = dp[i][num-1]
			} else {
				card := arr[num]
				for j := range dp[i][num] {
					if j-card >= 0 {
						dp[i][num][j] = dp[i][num][j] || dp[i][num-1][j-card]
					}
					dp[i][num][j] = dp[i][num][j] || dp[i][num-1][j]
				}
			}
		}

		var found bool
		for n := max(0, K-arr[i+1]); n < K; n++ {
			if dp[i][N][n] {
				found = true
			}
		}
		if found {
			count++
		}
	}

	// for i := range dp {
	// 	fmt.Println(dp[i][N])
	// }

	fmt.Println(N - count)
}

