func readLine(sc *bufio.Scanner) string {
	sc.Scan()
	return sc.Text()
}

func readInt(sc *bufio.Scanner) (res int) {
	res, _ =strconv.Atoi(readLine(sc))
	return
}

func readInts(sc *bufio.Scanner, n int) []int {
	ns := strings.Split(readLine(sc), " ")
	res := make([]int, n)

	for i, n := range ns {
		res[i], _ = strconv.Atoi(n)
	}
	return res
}

func readInt64s(sc *bufio.Scanner, n int) []int64 {
	ns := strings.Split(readLine(sc), " ")
	res := make([]int64, n)

	for i, n := range ns {
		res[i], _ = strconv.ParseInt(n, 10, 64)
	}
	return res
}

func readMatrix(sc *bufio.Scanner, rows, cols int) [][]int {
	res := make([][]int, rows)
	for i := 0; i < rows; i ++ {
		res[i] = readInts(sc, cols)
	}
	return res
}

func main() {
	sc := bufio.NewScanner(os.Stdin)

	xs := readInts(sc, 2)
	n := xs[0]
	k := xs[1]

	as := readInts(sc, k)
	sort.Ints(as)

	res := -1
	least := 0
	for _, a := range as {
		least += a
		if least >= k {
			res = least
			break
		}
	}

	if res < 0 {
		fmt.Println(n)
	} else {
		count := 0
		for _, a := range as {
			if least - a >= k {
				count += 1
			}
		}
		fmt.Println(count)
	}
}

