	buf := make([]byte, 0, 10e6)

	rdr := bufio.NewReaderSize(os.Stdin, 10e6)
	for {
		l, p, e := rdr.ReadLine()
		if e != nil {
			panic(e)
		}
		buf = append(buf, l...)
		if !p {
			break
		}
	}
	return string(buf)
}

