	"sort"
	"strconv"
)

const pi = math.Pi

var mod int = pow(10, 9) + 7
var Umod uint64 = 1000000007
var ans, cnt int

func main() {
	reader.Split(bufio.ScanWords)
	N, _ := strconv.Atoi(read())
	K, _ := strconv.Atoi(read())
	a_f, a_r := make([]int, N+1), make([]int, N)
	for i := 1; i < N+1; i++ {
		t, _ := strconv.Atoi(read())
		a_f[i] = t
		a_r[i-1] = t
	}
	sort.Ints(a_f)
	sort.Sort(sort.Reverse(sort.IntSlice(a_r)))
	a_r = append(a_r[0:1], a_r[0:]...)
	a_r[0] = 0

	dp_f := make([][]bool, N+1)
	dp_r := make([][]bool, N+1)
	for i := 0; i < N+1; i++ {
		dp_f[i] = make([]bool, K+1)
		dp_r[i] = make([]bool, K+1)
	}
	dp_f[0][0] = true
	dp_r[0][0] = true
	// i文字目までで，値jを作れるか動的計画法で調査
	for i := 1; i < N+1; i++ {
		for j := 0; j < K+1; j++ {
			if 0 <= j-a_f[i] {
				dp_f[i][j] = dp_f[i][j] || dp_f[i-1][j-a_f[i]]
			}
			dp_f[i][j] = dp_f[i][j] || dp_f[i-1][j]
		}
	}
	// N-i文字目までで，値jを作れるか動的計画法で調査
	for i := 1; i < N+1; i++ {
		for j := 0; j < K+1; j++ {
			if 0 <= j-a_r[i] {
				dp_r[i][j] = dp_r[i][j] || dp_r[i-1][j-a_r[i]]
			}
			dp_r[i][j] = dp_r[i][j] || dp_r[i-1][j]
		}
	}
	// dpテーブルの累積和
	for i := 1; i < N+1; i++ {
		dp_ans := make([]bool, K+1)
		//fmt.Println(a_f[i], a_r[N-i+1], a_f[i-1], a_r[N-i])
		for j := 0; j < K+1; j++ {
			dp_ans[j] = dp_f[i-1][j] || dp_r[N-i][j]
		}
		// K-a[i] <= X < Kが存在するか調査
		for j := max(0, K-a_f[i]); j < K; j++ {
			if dp_ans[j] {
				break
			}
			if j == K-1 {
				cnt++
			}
		}
	}
	fmt.Println(cnt)
}

