func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	k := getNextInt64(scanner)
	aa := make(i64, n)
	ss := make([]int64, n+1)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt64(scanner)
		ss[i+1] = ss[i] + aa[i]
	}
	sort.Sort(aa)
	for i := 0; i < n; i++ {
		ss[i+1] = ss[i] + aa[i]
	}

	ans := 0
	for i := 0; i < n; i++ {
		l := 1
		r := n + 1
		for l < r {
			m := (l + r) >> 1
			if m > i {
				if ss[m] > k {
					r = m
					continue
				}
				l = m + 1
				continue
			}
			if ss[m]+aa[i] > k {
				r = m
				continue
			}
			l = m + 1
		}

		if r == n+1 {
			ans++
			continue
		}
		if r > i {
			if ss[r]-aa[i] >= k {
				ans++
			}
			continue
		}
		if ss[r] >= k {
			ans++
		}

	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

