	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	k := getNextInt64(scanner)
	aa := make([]int64, n)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt64(scanner)
	}

	ans := 0
	imml := IntMapMap{}
	immr := IntMapMap{}
	imml.increment(0, aa[0])
	immr.increment(n-1, aa[n-1])
	for i := 1; i < n; i++ {
		imml.increment(i, aa[i])
		for a := range imml[i-1] {
			imml.increment(i, a)
			imml.increment(i, a+aa[i])
		}
		immr.increment(n-i-1, aa[n-i-1])
		for a := range immr[n-i] {
			immr.increment(n-i-1, a)
			immr.increment(n-i-1, a+aa[n-i-1])
		}
	}

	for i := 0; i < n; i++ {
		needed := false
		for ii := k - aa[i]; ii < k; ii++ {
			if i == 0 && immr.get(1, ii) > 0 {
				needed = true
				break
			}
			if i == n-1 && imml.get(n-2, ii) > 0 {
				needed = true
				break
			}
			found := false
			for iii := int64(0); iii <= ii; iii++ {
				if imml.get(i-1, iii) > 0 && immr.get(i+1, ii-iii) > 0 {
					found = true
					break
				}
			}
			if found {
				needed = true
				break
			}
		}
		if needed == false {
			ans++
		}
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

