    for j := K-1; j >= K-v; j-- {
      need = need || memo[N-1][j]
    }
    if !need {
      cnt += 1
    }
  }

  if cnt == 0 {
    fmt.Println(N)
  } else {
    fmt.Println(cnt)
  }
}

