var dp, dpr [5001][5001]int

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)
	k := getNextInt(scanner)
	aa := make([]int, n)

	dp[0][0] = 1
	dpr[n][0] = 1

	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
		for ii := k; ii >= 0; ii-- {
			dp[i+1][ii] = dp[i][ii]

			if ii-aa[i] < 0 {
				continue
			}
			if dp[i][ii-aa[i]] > 0 {
				dp[i+1][ii]++
			}
		}
	}
	for i := n - 1; i > 0; i-- {
		for ii := k; ii >= 0; ii-- {
			dpr[i][ii] = dpr[i+1][ii]

			if ii-aa[i] < 0 {
				continue
			}
			if dpr[i+1][ii-aa[i]] > 0 {
				dpr[i][ii]++
			}
		}
	}

	for i := 1; i < n+1; i++ {
		for ii := 0; ii < k; ii++ {
			dpr[i][ii+1] += dpr[i][ii]
		}
	}

	ans := 0

	for i := 0; i < n; i++ {
		if needed(i, n, k, aa) == false {
			ans++
		}
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

func needed(ai, n, k int, aa []int) bool {
	for i := 0; i < k; i++ {
		if dp[ai][i] == 0 {
			continue
		}
		if i+aa[ai] >= k {
			return true
		}
		minr := k - aa[ai] - i - 1
		maxr := k - i - 1
		if minr < 0 {
			continue
		}
		if maxr < 0 {
			continue
		}
		if dpr[ai+1][maxr]-dpr[ai+1][minr] > 0 {
			return true
		}
	}
	return false
}

