func dp(idx int, value int, min int, memo [][]bool, arr []int) bool{
  if min <= value && value < len(memo[0]) {
    return true
  }
  if idx > len(arr)-1 || value >= len(memo[0]) || memo[idx][value] {
    return false
  }
  memo[idx][value] = true
  return dp(idx+1, value, min, memo, arr) || dp(idx+1, value+arr[idx], min, memo, arr)
}


