var N, K int
var arr []int

func max(a, b int) int {
	if a < b {
		return b
	}
	return a
}

func main() {
	fmt.Scan(&N, &K)
	arr = make([]int, N+1)

	for i := 1; i <= N; i++ {
		fmt.Scan(&arr[i])
	}
	sort.Ints(arr)

	left := 0
	right := N + 1
	dp := make([][]bool, N+1)
	for left+1 < right {
		for j := range dp {
			dp[j] = make([]bool, K+1)
		}
		dp[0][0] = true

		i := (left + right) / 2
		for num := 1; num <= N; num++ {
			if i == num {
				dp[num] = dp[num-1]
			} else {
				card := arr[num]
				for j := range dp[num] {
					if j-card >= 0 {
						dp[num][j] = dp[num][j] || dp[num-1][j-card]
					}
					dp[num][j] = dp[num][j] || dp[num-1][j]
				}
			}
		}

		var found bool
		for n := max(0, K-arr[i]); n < K; n++ {
			if dp[N][n] {
				found = true
			}
		}

		if found {
			right = i
		} else {
			left = i
		}
	}

	fmt.Println(left)
}

