var sc = bufio.NewScanner(os.Stdin)

func nextLine() string {
  sc.Scan()
  return sc.Text()
}


func main()  {
  fst := nextLine()
  fstArray := strings.Split(fst, " ")
  N, _ := strconv.Atoi(fstArray[0])
  K, _ := strconv.Atoi(fstArray[1])

  line := nextLine()
  s := strings.Split(line, " ")
  n := []int{}
  for _, v := range s{
    i, _ := strconv.Atoi(v)
    n = append(n, i)
  }
  cnt := 0
  sort.Ints(n)
  for i, v := range n {
    memo := make([][]bool, N)
    for j:= 0; j < N; j++{
      memo[j] = make([]bool, K)
    }
    for j:= 0; j < N; j++ {
      memo[j][0] = true
    }
    for j, w := range n {
      if j == 0 {
        continue
      }

      for k := 0; k < K; k++ {
        if (i != j && k-w >= 0 && memo[j-1][k-w]) || memo[j-1][k] {
          memo[j][k] = true
        }
      }
    }
    need := false
    for j := K-1; j >= K-v; j-- {
      need = need || memo[N-1][j]
    }
    if !need {
      cnt += 1
    }
  }

  if cnt == 0 {
    fmt.Println(N)
  } else {
    fmt.Println(cnt)
  }
}

