func needed(ai, n, k int, aa []int) bool {
	if ai > 0 {
		for ii := k; ii >= 0; ii-- {
			if ii-aa[ai-1] < 0 {
				continue
			}
			if dp[ii-aa[ai-1]] > 0 {
				dp[ii]++
			}
		}
		for ii := 0; ii <= k; ii++ {
			if ii+aa[ai] > k {
				continue
			}
			if dpr[ii] == 0 {
				continue
			}
			if dpr[ii+aa[ai]] > 0 {
				dpr[ii+aa[ai]]--
			}
		}
	}

	var sr [5001]int
	sr[0] = dpr[0]
	for ii := 1; ii < k; ii++ {
		sr[ii] = sr[ii-1] + dpr[ii]
	}

	for i := 0; i < k; i++ {
		if dp[i] == 0 {
			continue
		}
		if i+aa[ai] >= k {
			return true
		}
		minr := k - aa[ai] - i - 1
		maxr := k - i - 1
		if minr < 0 {
			continue
		}
		if maxr < 0 {
			continue
		}
		if sr[maxr]-sr[minr] > 0 {
			return true
		}
	}
	return false
}

