func needed(i, n int, k int64, aa []int64, imml, immr IntMapMap) bool {
	var sl, sr [5001]int
	var l int64

	for a := range imml[i-1] {
		sl[a]++
	}
	for a := range immr[i+1] {
		sr[a]++
	}
	for ii := 1; ii < 5001; ii++ {
		sr[ii] += sr[ii-1]
	}

	// (l+r) < k && (l+r)+aa[i] >= k

	for l = 0; l < k; l++ {
		if sl[l] == 0 {
			continue
		}
		if l+aa[i] >= k {
			return true
		}
		minr := k - l - aa[i] - 1
		maxr := k - l - 1
		if minr < 0 {
			continue
		}
		if maxr < 0 {
			continue
		}
		if (sr[maxr] - sr[minr]) > 0 {
			return true
		}
	}
	return false
}

