void readV(T...)(ref T t){auto r=rdsp;foreach(ref v;t)pick(r,v);}
void readA(T)(size_t n,ref T[]t){t=new T[](n);auto r=rdsp;foreach(ref v;t)pick(r,v);}

void main()
{
  int n, k; readV(n, k);
  int[] a; readA(n, a);

  a = a.filter!(ai => ai < k).array;
  a.sort();
  n = a.length.to!int;

  auto calc(R)(R b, int ai)
  {
    auto dp = new bool[][](n, k);
    dp[0][0] = true;

    foreach (i, bi; b.enumerate)
      foreach (j; 0..k) {
        dp[i+1][j] = dp[i][j];
        if (j >= bi) dp[i+1][j] |= dp[i][j-bi];
      }

    return dp[n-1][k-ai..k].any;
  }

  auto bs = iota(0, n).map!(i => calc(chain(a.take(i), a.drop(i+1)), a[i])).assumeSorted;
  writeln(bs.lowerBound(true).length);
}

