void main() {
    int N, K;
    scan(N, K);
    auto a = readln.split.to!(int[]);

    auto dpf = new bool[][](N + 1, K);
    dpf[0][0] = true;
    foreach (i ; 1 .. N + 1) {
        foreach (x ; 0 .. K) {
            dpf[i][x] = dpf[i - 1][x];
            if (x - a[i - 1] >= 0) {
                dpf[i][x] |= dpf[i - 1][x - a[i - 1]];
            }
        }
    }

    auto dpb = new bool[][](N + 1, K);
    dpb[N][0] = true;
    foreach_reverse (i ; 0 .. N) {
        foreach (x ; 0 .. K) {
            dpb[i][x] = dpb[i + 1][x];
            if (x - a[i] >= 0) {
                dpb[i][x] |= dpb[i + 1][x - a[i]];
            }
        }
    }

    int ans;

    foreach (i ; 0 .. N) {
        bool need;

        for (int x = 0, y = K - 1; x < K; x++) {
            if (!dpf[i][x]) continue;
            while (y >= K - x || !dpb[i + 1][y]) y--;
            if (x + y >= K - a[i]) {
                need = true;
                break;
            }
        }

        if (!need) {
            ans++;
        }
    }

    writeln(ans);
}






