    bool check(int k) {
        if (a[k] >= K) return true;
        auto dp = new bool[][](N + 1, K + 1);
        dp[0][0] = 1;
        foreach (i ; 1 .. N + 1) {
            foreach (j ; 0 .. K + 1) {
                dp[i][j] = dp[i - 1][j];
                if (i - 1 == k) continue;
                if (j - a[i - 1] >= 0) {
                    dp[i][j] |= dp[i - 1][j - a[i - 1]];
                }
            }
        }

        foreach (i ; max(0, K - a[k]) .. K) {
            if (dp[N][i]) {
                return true;
            }
        }

        return false;
    }

    int ng = -1, ok = N;
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;
        (check(mid) ? ok : ng) = mid;
    }
    auto ans = ok;
    writeln(ans);
}






