void main()
{
    auto N = scanElem;
    auto K = scanElem;
    auto list = scanArray.sort().array;

    auto dp = Grid!bool(N+1, K);
    bool calc(long n)
    {
        dp.clear();
        dp[0, 0] = true;

        if(K<=list[n])return true;

        foreach(i;0..N)
        {
            foreach(k;0..K)
            {
                dp[i + 1, k] |= dp[i, k];
                if(i==n)continue;
                if(k+list[i]>=K)continue;
                dp[i + 1, k + list[i]] |= dp[i, k];
            }
        }
        foreach(i;K-list[n]..K)
        {
            if(dp[N, i])return true;
        }
        return false;
    }

    long l = 0, r = N;
    while(l!=r)
    {
        auto n = l+(r-l)/2;
        if(calc(n)){
            r = n;
        }else{
            l = n;
        }
        if(r-l==1){
            if(calc(l)){
                r = l;
            }else{
                l = r;
            }
        }
    }
    (l).writeln();
}

struct CombTable(long MOD)
{
    long[] fac;
    long[] finv;
    long[] inv;
    this(long n)
    {
        fac = uninitializedArray(n);
        finv = uninitializedArray(n);
        inv = uninitializedArray(n);
        fac[0] = fac[1] = 1;
        finv[0] = finv[1] = 1;
        inv[1] = 1;
        foreach(i;2..n){
            fac[i] = fac[i - 1] * i % MOD;
            inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
            finv[i] = finv[i - 1] * inv[i] % MOD;
        }
    }

    long comb(int n, int k)
    {
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
        return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
    }
}


