struct Factor
{
    long n;
    long c;
}

//素因数分解
Factor[] factors(long n) pure
{
    Factor[] res;
    for (long i = 2; i ^^ 2 <= n; i++)
    {
        if (n % i != 0)
            continue;

        long c;
        while (n % i == 0)
        {
            n = n / i;
            c++;
        }
        res ~= Factor(i, c);
    }
    if (n != 1)
        res ~= Factor(n, 1);

    return res;
}
//約数をすべて列挙
long[] divisors(long n) pure
{
    long[] list;
    void func(Factor[] fs, long n)
    {
        if(fs.empty){
            list ~= n;
            return;
        }

        foreach(c; 0..fs[0].c+1)
        {
            func(fs[1..$], n * (fs[0].n ^^ c));
        }
    }

    func(factors(n), 1);
    sort(list);
    return list;
}
//nまでの素数のリスト
long[] primes(long n) pure
{
    if(n<2)return [];

    auto table = new long[cast(size_t)n+1];

    long[] res;
    for(size_t i = 2;i<=n;i++)
    {
        if(table[i]==-1) continue;
        for(size_t a = i;a<table.length;a+=i)
        {
            table[a] = -1;
        }
        res ~= i;
    }
    return res;
}
//素数判定
bool isPrime(long n) pure
{
    if (n <= 1)
        return false;
    if (n == 2)
        return true;
    if (n % 2 == 0)
        return false;
    for (long i = 3; i ^^ 2 <= n; i += 2)
        if (n % i == 0)
            return false;
    return true;
}

import std.stdio, std.array, std.string, std.conv, std.algorithm;
import std.typecons, std.range, std.random, std.math, std.container;
import std.numeric, std.bigint, core.bitop, core.stdc.stdio;


void main() {
    auto S = readln.split.map!(to!int);
    auto K = S[1];
    auto A = readln.split.map!(to!int).filter!(a => a < K).array;
    A.sort();
    auto N = A.length.to!int;

    if (N == 1) {
        writeln(A[0] >= K ? 1 : 0);
        return;
    }


    auto dp1 = new int[][](N);
    dp1[0] = [0, A[0]];
    foreach (i; 1..N) {
        foreach (j; dp1[i-1]) {
            dp1[i] ~= j;
            dp1[i] ~= A[i] + j;
        }
        dp1[i].sort();
        dp1[i] = dp1[i].uniq().filter!(a => a < K).array;
    }

    auto dp2 = new int[][](N);
    dp2[N-1] = [0, A[N-1]];
    foreach (i; iota(N-2, -1, -1)) {
        foreach (j; dp2[i+1]) {
            dp2[i] ~= j;
            dp2[i] ~= A[i] + j;
        }
        dp2[i].sort();
        dp2[i] = dp2[i].uniq().filter!(a => a < K).array;
    }


    int ans = 0;

    foreach (i; 0..N) {
        bool required = false;

        if (i == 0) {
            foreach (j; dp2[1]) {
                if (j >= K-A[i] && j < K) {
                    required = true;
                    break;
                }
            }
        }

        else if (i == N-1) {
            foreach (j; dp2[N-2]) {
                if (j >= K-A[i] && j < K) {
                    required = true;
                    break;
                }
            }
        }

        else {
            int n = dp1[i-1].length.to!int;
            int m = dp2[i+1].length.to!int;
            int p1 = 0;
            int p2 = m-1;
            while (p1 < n && p2 >= 0) {
                int s = dp1[i-1][p1] + dp2[i+1][p2];
                if (s > K) p2 -= 1;
                else if (s < K - A[i]) p1 += 1;
                else {required = true; break;}
            }
        }

        if (!required) ans += 1;
    }


    ans.writeln;
}

