void main()
{
    GC.disable;
    auto N = scanElem;
    auto K = scanElem;
    auto list = scanArray.sort().array;

    auto dp = Grid!bool(N+1, K);
    bool calc(long n)
    {
        if(K<=list[n])return true;

        debug(Local) immutable before = MonoTime.currTime;
        dp.clear();
        dp[0, 0] = true;

        foreach(i;0..N)
        {
            foreach(k;0..K)
            {
                dp[i + 1, k] |= dp[i, k];
                if(i==n)continue;
                if(k+list[i]>=K)continue;
                dp[i + 1, k + list[i]] |= dp[i, k];
            }
        }
        debug(Local) immutable after = MonoTime.currTime;
        debug(Local) println(after-before);
        foreach(i;K-list[n]..K)
        {
            if(dp[N, i])return true;
        }
        return false;
    }

    long l = -1, r = N;
    while(r-l>1)
    {
