struct Factor
{
    long n;
    long c;
}

//素因数分解
Factor[] factors(long n) pure
{
    Factor[] res;
    for (long i = 2; i ^^ 2 <= n; i++)
    {
        if (n % i != 0)
            continue;

        long c;
        while (n % i == 0)
        {
            n = n / i;
            c++;
        }
        res ~= Factor(i, c);
    }
    if (n != 1)
        res ~= Factor(n, 1);

    return res;
}
//約数をすべて列挙
long[] divisors(long n) pure
{
    long[] list;
    void func(Factor[] fs, long n)
    {
        if(fs.empty){
            list ~= n;
            return;
        }

        foreach(c; 0..fs[0].c+1)
        {
            func(fs[1..$], n * (fs[0].n ^^ c));
        }
    }

    func(factors(n), 1);
    sort(list);
    return list;
}
//nまでの素数のリスト
long[] primes(long n) pure
{
    if(n<2)return [];

    auto table = new long[cast(size_t)n+1];

    long[] res;
    for(size_t i = 2;i<=n;i++)
    {
        if(table[i]==-1) continue;
        for(size_t a = i;a<table.length;a+=i)
        {
            table[a] = -1;
        }
        res ~= i;
    }
    return res;
}
//素数判定
bool isPrime(long n) pure
{
    if (n <= 1)
        return false;
    if (n == 2)
        return true;
    if (n % 2 == 0)
        return false;
    for (long i = 3; i ^^ 2 <= n; i += 2)
        if (n % i == 0)
            return false;
    return true;
}

import std.algorithm, std.conv, std.range, std.stdio, std.string;
import std.bitmanip;  // BitArray

void main()
{
  auto rd = readln.split.to!(int[]), n = rd[0], k = rd[1];
  auto a = readln.split.to!(int[]);

  auto dp1 = new BitArray[](n+1), dp2 = new BitArray[](n+1);
  dp1[0].length = dp2[0].length = k;
  dp1[0][0] = dp2[0][0] = true;
  foreach (i; 0..n) {
    dp1[i+1] = dp1[i].dup;
    dp1[i+1].lshift(a[i]);
    dp1[i+1] |= dp1[i];

    dp2[i+1] = dp2[i].dup;
    dp2[i+1].lshift(a[$-i-1]);
    dp2[i+1] |= dp2[i];
  }

  auto check(int ai, BitArray dpi1, BitArray dpi2)
  {
    if (ai >= k) return true;
    auto mi = k-ai, cs = new int[](k);

    cs[0] = dpi2[0];
    foreach (j; 1..k) cs[j] = cs[j-1] + dpi2[j];

    foreach (j; 0..k) {
      auto mj = max(0, mi-j), c = cs[k-j-1] - cs[mj] + dpi2[mj];
      if (dpi1[j] & (c > 0)) return true;
    }

    return false;
  }

  auto ans = 0;
  foreach (i; 0..n) {
    auto dpi1 = dp1[i], dpi2 = dp2[n-i-1];
    ans += check(a[i], dpi1, dpi2);
  }

  writeln(n-ans);
}

auto lshift(ref BitArray ba, size_t n)
{
  if (n % 64 == 0) {
    if (n > 0) {
      ba <<= 1;
      ba <<= n-1;
    }
  } else {
    ba <<= n;
  }
}

