T scanElem(T = long)()
{
    import core.stdc.stdlib;
    scanBuf.reserve(200);

    int c = ' ';
    while (isWhite(c) && c != -1)
    {
        c = getchar;
    }
    long end;
    while (!isWhite(c) && c != -1)
    {
        if(scanBuf.length<=end){
            scanBuf.length = end * 2 + 10;
        }
        scanBuf[end] = cast(char) c;
        end++;
        c = getchar;
    }
    return scanBuf[0..end].to!T;
}

