struct Stack(Elem){

    private Elem[] array;
    private size_t endIdx;

    void insertBack(Elem e)
    {
        if(endIdx==array.length){
            array.length = array.length*2+10;
        }
        array[endIdx++] = e;
    }

    void popBack()
    {
        assert(endIdx!=0);
        endIdx--;
    }

    ref Elem back()
    {
        assert(endIdx!=0);
        return array[endIdx-1];
    }

    size_t count() const 
    {
        return endIdx; 
    }
}

