def DP(N,K,A,i):
    Ac=A.copy()
    a_check=Ac.pop(i)
    if a_check>=K:
        return True
    dp=[0]*(K-a_check+1)
    dp[0]=1
    for a in Ac:
        dpc=dp.copy()
        for k in range(K-a_check+1):
            if dpc[k]==0:continue
            else:
                if k+a<K-a_check:
                    dp[k+a]=1
                elif K-a_check<=k+a<K:
                    return True
    return False

def bisect(N,K,A,check,maxFalse,minTrue):
    idx=N*check[0]//check[1]
    if DP(N,K,A,idx)==True:
        if maxFalse==idx-1:
            return maxFalse
        return bisect(N,K,A,(check[0]*2-1,check[1]*2),maxFalse,min(minTrue,idx))
    else:
        if minTrue==idx+1:
            return idx
        return bisect(N,K,A,(check[0]*2+1,check[1]*2),max(maxFalse,idx),minTrue)

