def can_delete(idx, A, K):

    dp = [False] * (K + 1)
    dp[0] = True
    for i in range(len(A)):
        if i == idx:
            continue

        for j in range(len(dp) - 1, -1, -1):
            if dp[j] and j + A[i] < len(dp):
                dp[j + A[i]] = True

    ok = True
    for i in range(K):
        if dp[i] and i + A[idx] >= K:
            ok = False
    return ok


