def findminsum(lst,K,N):
    inf=10**16
    dp=[[(inf if lst[0]<s and j==0 else lst[0]) for j in range(N)] for s in range(K+1)]
    for s in range(K+1):
        for j in range(N):
            if s>lst[j] and j>0:
                dp[s][j]=min(dp[s-lst[j]][j-1]+lst[j], dp[s][j-1])
            elif s<=lst[j] and j>0:
                dp[s][j]=min(lst[j],dp[s][j-1])
    # print(lst)
    # print(dp[0][:])
    # print(dp[1][:])
    # print(dp[K][:])
    return dp[K][N-1]

