def no_need(N: int, K: int, A: list) -> int:
    count = 0
    for i in range(N):
        # s[i] を要素の和が i 以上の部分集合の個数とする。
        s = [0] * (K + 1)
        s[0] = 1

        for a in A[:i] + A[i+1:]:
            for k in range(K, -1, -1):
                s[min(K, a + k)] += s[k]

        s[0] = 0
        for k in range(K, 0, -1):
            s[k-1] += s[k]

        count += 1 if s[K - A[i]] - s[K] == 0 else 0

    return count


