def slv(N, K, A):
    @lru_cache(maxsize=None)
    def f(w):
        if K - A[w] <= 0:
            return True
        dp = [0] * (K)

        for i, a in enumerate(A):
            if i == w:
                continue
            tdp = dp[:]
            for j in range(K):
                if dp[j] and j + a < K:
                    tdp[j+a] = 1
            if a < K:
                tdp[a] = 1
            dp = tdp

        print(w, dp, dp[K-A[w]:])
        if sum(dp[K-A[w]:]) > 0:
            return True

        return False

    A.sort()
    l = 0
    r = N-1
    while r-l > 1:
        c = (l+r)//2
        if f(c):
            r = c
        else:
            l = c

    if f(l):
        return l
    return r + 1 if not f(r) else l + 1


