            tdp = dp[:]
            for j in range(K):
                if dp[j] and j + a < K:
                    tdp[j+a] = True
            if a < K:
                tdp[a] = True
            dp = tdp

        for b in dp[K-A[w]:]:
            if b:
                return True

        return False

