def partial_solution(N, K, A):
    # O(K * N**2)解法
    #     「aが不必要」
    #     ＝「aを含む良い集合の数字の和は K+a 以上」
    #     ＝「a以外の数字の組み合わせで K-a ～ K-1 は作れない」
    if N == 1:
        return 0
    cnt = 0
    for i in range(N):
        # dp[n][k]: n番目（1-indexed）までの数字の和でkを作れるか否か
        dp = [[0 for _ in range(K + 1)] for _ in range(N + 1)]
        dp[0][0] = 1
        for j in range(N):
            a = A[j]
            if j == i:
                for k in range(K + 1):
                    # i番目（0-indexed）のAは使わない
                    dp[j + 1][k] = dp[j][k]
            else:
                for k in range(K + 1):
                    v = dp[j][k]
                    if k >= a:
                        v = max(v, dp[j][k - a])
                    dp[j + 1][k] = v
        lb, ub = max(0, K - A[i]), K - 1
        if sum(dp[N][lb:(ub + 1)]) == 0:
            cnt += 1
    return cnt


def solution(N, K, A):
    # O(K * N)解法
    #     partial_solutionの改良。
    #    「a以外の数字の組み合わせで作れる数字」を考えるため、両方向からdpテーブルを作る。
    if N == 1:
        return 0
    # dp1[i][k]: i番目（0-indexed）以前の数字の和でkを作れるか否か
    # dp2[j][k]: j番目（0-indexed）以降の数字の和でkを作れるか否か
    # iについてのfor loopで
    #     dp[j][k] = dp1[j][k] (j < i)
    #              = dp2[j][k] (j >= i)
    # となるように更新していく
    dp = [[0 for _ in range(K + 1)] for _ in range(N)]  # 最初はdp2で初期化
    dp[N - 1][0] = 1
    dp[N - 1][min(A[N - 1], K)] = 1
    for j in range(N - 2, -1, -1):
        a = A[j]
        for k in range(K + 1):
            v = dp[j + 1][k]
            if k >= a:
                v = max(v, dp[j + 1][k - a])
            dp[j][k] = v
    # 「A[i] 以外の数字の組で K-A[i] ～ K-1 は作れない」ものの数を数える
    cnt = 0
    for i in range(N):
        # 次の式を満たす(x, y)が存在しなければA[i]は不必要：
        #     K - A[i] <= x + y <= K - 1
        #         x: ～i-1の要素, y: i+1～の要素
        a = A[i]
        if i == 0:
            if max(dp[1][max(0, K - a):K]) == 0:
                cnt += 1
            # dp1の反映
            for k in range(K + 1):
                dp[0][k] = 0
            dp[0][0] = 1
            dp[0][min(K, a)] = 1
        elif i == N - 1:
            if max(dp[N - 2][max(0, K - a):K]) == 0:
                cnt += 1
        else:
            # dp2の累積和
            for k in range(1, K + 1):
                dp[i + 1][k] += dp[i + 1][k - 1]
            unnecessary = True
            for x in range(K + 1):
                if dp[i - 1][x] == 0:
                    continue
                # K - A[i] - x <= y <= K - 1 - x なるyの存在をチェック
                if 0 < K - a - x:
                    # dp[i + 1]はdp2の累積和になってる
                    if dp[i + 1][K - 1 - x] - dp[i + 1][K - a - x - 1] > 0:
                        unnecessary = False
                        break
                elif K - a - x <= 0 <= K - 1 - x:
                    if dp[i + 1][K - 1 - x] > 0:
                        unnecessary = False
                        break
            if unnecessary:
                cnt += 1
            # dp1の反映
            for k in range(K + 1):
                v = dp[i - 1][k]
                if k >= a:
                    v = max(v, dp[i - 1][k - a])
                dp[i][k] = v
    return cnt


def check():
    import random
    random.seed(0)
    for N in range(1, 102, 10):
        for K in range(1, 102, 10):
            A = random.choices(range(1, 200+1), k=N)
