def no_need(N: int, K: int, A: list) -> int:
    A.sort()

    def need(i: int)->bool:
        dp = [[False] * (K) for _ in range(N)]
        dp[0][0] = True

        for n, a in enumerate(A[:i] + A[i+1:]):
            for k in range(K):
                dp[n + 1][k] = dp[n][k] or (a <= k and dp[n][k - a])

        return any(dp[N - 1][max(K - A[i], 0):])

    l, r = -1, N
    while l + 1 < r:
        m = (l + r) // 2
        if need(m):
            r = m
        else:
            l = m

    return l+1


