def read_ints():
    return list(map(int, input().strip().split(' ')))


def solve():
    """
    maximum modulo k
    dp[i] = True if there exists i
    """
    _, K = read_ints()
    A = [a for a in read_ints() if a < K]
    N = len(A)
    dp = [
        [False for _ in range(K)] for _ in range(N+1)
    ]
    for i, a in enumerate(A):
        for k in range(K):
            if k-a >= 0:
                dp[i+1][k] = dp[i+1][k] or dp[i][k-a]
        dp[i+1][a] = True
    max_k = -1
    for i, d in enumerate(dp[N]):
        if d:
            max_k = i
    if max_k == -1:
        return 0
    count = 0
    for a in A:
        if max_k-2*a >= 0:
            count += 1
    return count



