class cumsum:
    def __init__(self, A):
        self.n = len(A)
        self.data = [0]*self.n
        for i in range(self.n):
            self.data[i] = self.data[i-1]+A[i]
    def query(self, l, r):
        if self.n<=l:
            return 0
        if r<0:
            return 0
        if l<0:
            x = 0
        else:
            x = self.data[l]
        if r>=self.n:
            y = self.data[-1]
        else:
            y = self.data[r]
        return y-x

