from collections import defaultdict


def can_discard(p, K, a_list):
    dp = [0] * K
    dp[0] = 1
    for i in range(len(a_list)):
        if i == p:
            continue

        for j in range(len(dp) - 1, -1, -1):
            if dp[j] == 0:
                continue
            if j + a_list[i] < len(dp):
                dp[j + a_list[i]] = 1

    x = a_list[p]
    for i in range(len(dp)):
        if dp[i] != 0 and i < K <= i + x:
            return False
    return True


