    for u in itertools.chain(a[:x],a[x+1:]):
        h=dp[:]
        for i in range(u,k):
            h[i]=h[i]|dp[i-u]
        dp=h
    cnt=0
    for i in range(k-a[x],k):
        cnt+=dp[i]
    if cnt==0:
        return True
    else:
        return False

