def DP(i, K, memo = {}):
    if i == 0 and K == 0:
        return 0
    elif i == 0:
        return Inf
    elif K <= A[i-1]:
        return 1
    try:
        return memo[(i, K)]
    except KeyError:
        if K - A[i-1] >= 0:
            ret = min(DP(i-1, K, memo), DP(i-1, K-A[i-1], memo) + 1)
        else:
            ret = DP(i-1, K, memo)
        memo[(i, K)] = ret
        return ret

