def solve(n, k, a, ai):
	dp = [[False for _ in range(k+1)] for _ in range(n)]
	dp[0][0] = True
	if a[0] > k:
		dp[0][k] = True
	else:
		dp[0][a[0]] = True
	for i in range(1, n-1):
		for j in range(k-1):
			if not dp[i-1][j]:
				continue
			dp[i][j] = True
			if j + a[i] > k:
				dp[i][k] = True
			else:
				dp[i][j+a[i]] = True
	return not any(map(lambda j: dp[n-2][j], range(k-ai, k)))


