def no_need(N: int, K: int, A: list) -> int:
    A.sort()

    def need(i: int)->bool:
        dp = [[False] * (K) for _ in range(N)]
        dp[0][0] = True

        card_num = 0
        for n, a in enumerate(A):
            if n == i:
                continue
            for k in range(K):
                dp[card_num + 1][k] = \
                    dp[card_num][k] or (a <= k and dp[card_num][k - a])
            card_num += 1

        return any(dp[N - 1][max(K - A[i], 0):])

