def partial_solution(N, K, A):
    # O(K * N**2)解法
    # 「aが不必要」＝「aを含む良い集合の数字の和は K+a 以上」
    #              ＝「a以外の数字の組み合わせで K-a ～ K-1 は作れない」
    cnt = 0
    for i in range(N):
        # dp[n][k]: n番目（1-indexed）までの数字の和でkを作れるか否か
        dp = [[0 for _ in range(K + 1)] for _ in range(N + 1)]
        dp[0][0] = 1
        for j in range(N):
            a = A[j]
            if j == i:
                for k in range(K + 1):
                    # i番目（0-indexed）のAは使わない
                    dp[j + 1][k] = dp[j][k]
            else:
                for k in range(K + 1):
                    v = dp[j][k]
                    if k >= a:
                        v = max(v, dp[j][k - a])
                    dp[j + 1][k] = v
        lb, ub = max(0, K - A[i]), K - 1
        if sum(dp[N][lb:(ub + 1)]) == 0:
            cnt += 1
    return cnt


