import sys

def biser(lst,func):
    n=len(lst)
    nh=n//2
    r=n
    while r>1:
        if func(lst[nh]):
            r=n-nh
            nh=nh+(n-nh)//2
        else:
            r=nh
            n=nh
            nh=nh//2
    if not func(lst[nh]):
        return -1
    else:
        return lst[nh]

