def partial_solution(N, K, A):
    # O(K * N**2)解法
    #     「aが不必要」
    #     ＝「aを含む良い集合の数字の和は K+a 以上」
    #     ＝「a以外の数字の組み合わせで K-a ～ K-1 は作れない」
    if N == 1:
        return 0
    cnt = 0
    for i in range(N):
        # dp[n][k]: n番目（1-indexed）までの数字の和でkを作れるか否か
        dp = [[0 for _ in range(K + 1)] for _ in range(N + 1)]
        dp[0][0] = 1
        for j in range(N):
            a = A[j]
            if j == i:
                for k in range(K + 1):
                    # i番目（0-indexed）のAは使わない
                    dp[j + 1][k] = dp[j][k]
            else:
                for k in range(K + 1):
                    v = dp[j][k]
                    if k >= a:
                        v = max(v, dp[j][k - a])
                    dp[j + 1][k] = v
        lb, ub = max(0, K - A[i]), K - 1
        if sum(dp[N][lb:(ub + 1)]) == 0:
            cnt += 1
    return cnt


def solution(N, K, A):
    # O(K * N)解法
    #     partial_solutionの改良。
    #    「a以外の数字の組み合わせで作れる数字」を考えるため、両方向からdpテーブルを作る。
    if N == 1:
        return 0
    # dp1[i][k]: i番目（0-indexed）以前の数字の和でkを作れるか否か
    # dp2[j][k]: j番目（0-indexed）以降の数字の和でkを作れるか否か
    dp1 = [[0 for _ in range(K + 1)] for _ in range(N)]
    dp2 = [[0 for _ in range(K + 1)] for _ in range(N)]
    dp1[0][0] = 1
    dp1[0][min(A[0], K)] = 1
    dp2[N - 1][0] = 1
    dp2[N - 1][min(A[N - 1], K)] = 1
    for i in range(1, N):
        j = N - 1 - i
        a1, a2 = A[i], A[j]
        for k in range(K + 1):
            v1, v2 = dp1[i - 1][k], dp2[j + 1][k]
            if k >= a1:
                v1 = max(v1, dp1[i - 1][k - a1])
            if k >= a2:
                v2 = max(v2, dp2[j + 1][k - a2])
            dp1[i][k] = v1
            dp2[j][k] = v2
    # 「A[i] 以外の数字の組で K-A[i] ～ K-1 は作れない」ものの数を数える
    cnt = 0
    cumsum_dp2 = [0] * (K + 1)
    for i in range(N):
        # 次の式を満たす(x, y)が存在しなければA[i]は不必要：
        #     K - A[i] <= x + y <= K - 1
        #         x: ～i-1の要素, y: i+1～の要素
        a = A[i]
        if i == 0:
            if max(dp2[1][max(0, K - a):K]) == 0:
                cnt += 1
        elif i == N - 1:
            if max(dp1[N - 2][max(0, K - a):K]) == 0:
                cnt += 1
        else:
            cumsum_dp2[0] = dp2[i + 1][0]  # dp2の累積和
            for k in range(1, K + 1):
                cumsum_dp2[k] = cumsum_dp2[k - 1] + dp2[i + 1][k]
            unnecessary = True
            for x in range(K + 1):
                if dp1[i - 1][x] == 0:
                    continue
                # K - A[i] - x <= y <= K - 1 - x なるyの存在をチェック
                if 0 < K - a - x:
                    if cumsum_dp2[K - 1 - x] - cumsum_dp2[K - a - x - 1] > 0:
                        unnecessary = False
                        break
                elif K - a - x <= 0 <= K - 1 - x:
                    if cumsum_dp2[K - 1 - x] > 0:
                        unnecessary = False
                        break
            if unnecessary:
                cnt += 1
    return cnt


