def solve(N, K, Ai):
    sum_a = sum(Ai)
    if sum_a < K:
        return N

    Ai = sorted(Ai)

    def search():
        x, y = N + 1, K + 1
        MEMO = [[None for _ in range(y)] for _ in range(x)]

        def recur(i, total, target_card, range_head):
            if range_head <= total < K:
                if not MEMO[i][total] is None:
                    return

            if range_head <= total < K:
                MEMO[i][total] = True
                return

            if not i < N:
                return

            if i == target_card:
                recur(i + 1, total, target_card, range_head)
            else:
                if total < range_head:
                    # 選ぶ
                    recur(i + 1, total + Ai[i], target_card, range_head)

                    # 選ばない
                    recur(i + 1, total, target_card, range_head)

        count = 0
        for target_card in range(N):
            range_head = K - Ai[target_card]
            if range_head <= 0:
                MEMO[i][0] = True
            else:
                recur(0, 0, target_card, range_head)

            for i in range(N):
                if 0 < MEMO[i].count(True):
                    count += 1
                    break

        return count

    res = search()
    return res


