fn main() {
    let nk: Vec<u64> = util::gets();
    let k = nk[1];

    let a: Vec<u64> = {
        let mut v = util::gets();
        v.sort();
        v
    };

    println!("{}", search(0, a.len(), &a, k));
}

fn search(low: usize, high: usize, a: &Vec<u64>, k: u64) -> usize {
    if low == high {
        return low;
    }

    let mid = (low + high) / 2;

    if !check(a[mid], k, a) {
        search(mid + 1, high, a, k)
    } else {
        search(low, mid, a, k)
    }
}

fn check(a: u64, k: u64, aa: &Vec<u64>) -> bool {
    if a >= k {
        return true;
    }

    let mut skipped = false;
    let mut dp = HashSet::new();
    dp.insert(a);

    for &x in aa {
        if !skipped && x == a {
            skipped = true;
            continue;
        }

        let v: Vec<_> = dp.iter().cloned().collect();

        for &y in &v {
            let s = x + y;
            if s >= k && s < k + a {
                return true;
            } else if s < k {
                dp.insert(s);
            }
        }
    }

    return false;
}

