fn is_needed(ns: &[i64], i: usize,  k: i64) -> bool {
    let lb = k - ns[i];
    if lb < 0 {
        return true;
    }

    let mut dp = vec![vec![0; (k+1) as usize]; ns.len() + 1];
    dp[0][0] = 1;

    for j in 0..ns.len() {
        for k2 in 0..k+1 {
            if i == j {
                dp[j+1][k2 as usize] += dp[j][k2 as usize];
                continue;
            }

            dp[j+1][k2 as usize] += dp[j][k2 as usize];
            if k2 + ns[j] > k {
                continue;
            }
            dp[j+1][(k2 + ns[j]) as usize] += dp[j][k2 as usize];
        }
    }

    for k2 in lb..k {
        if dp[ns.len()][k2 as usize] != 0 {
            return true;
        }
    }

    false
}


fn solve(mut ns: Vec<i64>, k: i64) -> i64 {
    ns.sort();

    if is_needed(&ns, 0 as usize, k) {
        return 0;
    }

    let mut lb = 0;
    let mut ub = ns.len() as i64;
    while ub - lb > 1 {
        let med = (lb + ub) / 2;
        if is_needed(&ns, med as usize, k) {
            ub = med;
        } else {
            lb = med;
        }
    }
    lb + 1
}


fn main() {
    input! {
        n: usize,
        k: i64,
        ns: [i64; n]
    }
     println!("{}", solve(ns, k));
}

