fn doit(a: &Vec<usize>, k: usize) -> Vec<Vec<i32>> {
    let n = a.len();
    let mut dp = dvec!(0; n+1, k+10);
    dp[0][0] = 1;
    for i in 1..n+1 {
        for j in 0..k+10 {
            dp[i][j] = dp[i-1][j];
        }
        let add = a[i-1];
        for j in 0..k+10 {
            if j >= add {
                dp[i][j] = max(dp[i][j], dp[i-1][j-add]);
            }
        }
    }
    dp
}

fn main() {
    input! {
        n: usize, k: usize,
        mut a: [usize; n]
    };

    let mut noneed = 0;

    let mut left = doit(&a, k); // table of 0-1
    a.reverse();
    let mut right = doit(&a, k);
    a.reverse();

    for i in 0..n+1 {
        for j in (1..k+10).rev() {
            right[i][j] = right[i][j-1];
        }
        right[i][0] = 0;
        for j in 1..k+10 {
            right[i][j] += right[i][j-1];
        }
    }

    for i in 0..n {
        if a[i] >= k {
            continue;
        }

        // do we have subset of cards without i which sum is k-a[i] to k-1?
        // left[i] and right[n-i-1]
        let mut isneed = false;
        for l in 0..k {
            // right: k-a[i]-l to k-1-l

            let f = ifv!(k >= a[i]+l, k-a[i]-l, 0);
            let t = k-l;
            isneed |= left[i][l] >= 1 && right[n-i-1][t] - right[n-i-1][f] >= 1;
        }
        if !isneed {
            noneed += 1;
        }
    }
    println!("{}", noneed);
}

use proconio::input;

fn is_ok(n: usize, k: usize, a: &Vec<usize>, i_s: usize) -> bool {
    let a_s = a[i_s];
    let mut dp = vec![vec![false; k]; n];
    dp[0][0] = true;
    for i in 0..n {
        if i == i_s {
            continue;
        }
        let a_i = a[i];
        let i = if i > i_s { i - 1 } else { i };
        for j in 0..k {
            dp[i + 1][j] |= dp[i][j];
            if j + a_i < k {
                dp[i + 1][j + a_i] |= dp[i][j];
            }
        }
    }
    !dp[n - 1][k.saturating_sub(a_s)..k].iter().any(|&b_i| b_i)
}

fn main() {
    input! {
        n: usize,
        k: usize,
        mut a: [usize; n],
    };
    a.sort();
    let mut l = 0;
    let mut r = n;
    while r - l > 1 {
        let m = l + (r - l) / 2;
        if is_ok(n, k, &a, m) {
            l = m;
        } else {
            r = m;
        }
    }
    let ans = l + 1;
    println!("{}", ans);
}

