fn is_needed(a: &Vec<usize>, mid: usize, k: usize) -> bool {
    if a[mid] >= k {
        return true;
    }

    let mut ok = vec![false; k + 1];
    ok[0] = true;

    for i in 0..a.len() {
        if i == mid {
            continue;
        }
        for j in (0..k).rev() {
            if j + a[i] > k {
                continue;
            }
            if ok[j] {
                ok[j + a[i]] = true;
            }
        }
    }

    for i in 0..k {
        if ok[i] && i + a[mid] >= k {
            return true;
        }
    }
    return false;
}

