fn search(low: usize, high: usize, a: &Vec<usize>, k: usize) -> usize {
    if low == high {
        return low;
    }

    let mid = (low + high) / 2;

    if !check(a[mid], k, a) {
        search(mid + 1, high, a, k)
    } else {
        search(low, mid, a, k)
    }
}

fn check(a: usize, k: usize, aa: &Vec<usize>) -> bool {
    if a >= k {
        return true;
    }

    let mut skipped = false;
    let mut dp = vec![false; k];
    dp[a] = true;

    for &x in aa {
        if !skipped && x == a {
            skipped = true;
            continue;
        }

        for i in 0..k as usize {
            let i = k - i - 1;
            if dp[i] {
                let s = i + x;
                if s >= k && s < k + a {
                    return true;
                } else if s < k {
                    dp[s] = true;
                }
            }
        }
    }

    return false;
}

