#[derive(Copy, Clone, Eq, PartialEq)]
struct edge22{from:usize, to:usize, cost:i64, ind:usize}
impl Ord for edge22 {
    fn cmp(&self, other: &edge22) -> Ordering {
        other.cost.cmp(&self.cost)
    }
}

impl PartialOrd for edge22 {
    fn partial_cmp(&self, other: &edge22) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
fn kruskal2(es:&mut Vec<edge22>, n:usize) -> Vec<usize>{
    es.sort();
    es.reverse();
    let mut uf =  UnionFind::init(n);
    let mut res = Vec::new();
    for i in 0..es.len(){
        let e = es[i];
        if uf.same(e.from, e.to) == false{
            uf.unite(e.from, e.to);
            res.push(e.ind);

        }

    }
    res
}
fn main(){
    input!{
        n:usize,
        k:usize,
        a:[usize;n],
    }
    let mut a = a.clone();
    a.sort();
    let mut b = a.clone();
    b.reverse();
    let mut dp = vec![vec![-1;k+1];n+1];
    let mut dp2 = dp.clone();
    dp[0][0] = 0;
    for i in 0..n{
        for j in 0..k+1{
            if dp[i][j] != -1{
                if j+a[i]<=k{
                    dp[i+1][j+a[i]] = 0;
                }
                if j<=k{
                    dp[i+1][j] = 0;
                }
            }

        }
    }
    dp2[0][0] = 0;
    for i in 0..n{
        for j in 0..k+1{
            if dp2[i][j] != -1{
                if j+b[i]<=k{
                    dp2[i+1][j+b[i]] = 0;
                }
                if j<=k{
                    dp2[i+1][j] = 0;
                }
            }

        }
    }
    let mut res = 0;
    for i in 0..n{
        let mut flag = false;
        if a[i]>=k{
            res += 1;
            continue;
        }
        let mut tmp = vec![0;k+1];
        for j in 1..k{
            if dp2[n-i-1][j] == 0{
                tmp[j] = 1;
            }
        }
        for j in 1..k+1{
            tmp[j] +=tmp[j-1];
        }

        for j in 0..k{
            if dp[i][j] == 0 && j+a[i]>=k{
                flag = true;
                break;
