fn main() {
    input! {
        n: usize,
        x: usize,
        mut a: [usize; n],
    }
    a.sort();
    let a = a.into_iter().enumerate().collect::<Vec<(usize, usize)>>();
    let result = a.upper_bound_by(|&(k, ak)| {
        let mut dp = vec![vec![false; x + 1]; n + 1];
        for i in 0..=n {
            dp[i][0] = true;
        }
        for i in 0..n {
            if i == k {
                for j in 0..=x {
                    dp[i + 1][j] = dp[i][j];
                }
            } else {
                let ai = a[i].1;
                for j in 0..min(x + 1, ai) {
                    dp[i + 1][j] = dp[i][j];
                }
                for j in ai..=x {
                    dp[i + 1][j] = dp[i][j] || dp[i][j - ai];
                }
            }
        }
        if (x - ak..x).any(|j| dp[n][j]) {
            Ordering::Greater
        } else {
            Ordering::Less
        }
    });
    println!("{}", result);
}

