    dp[0][0] = true;
    for i in 0..n {
        if i == i_s {
            continue;
        }
        let a_i = a[i] as usize;
        let i = if i > i_s { i - 1 } else { i };
        for j in 0..k as usize {
            dp[i + 1][j] |= dp[i][j];
            if j + a_i < k as usize {
                dp[i + 1][j + a_i] |= dp[i][j];
            }
        }
    }
    for j in std::cmp::max(k - a_s, 0) as usize..k as usize {
        if dp[n - 1][j] {
            return false;
        }
    }
    true
}

fn main() {
    input! {
        n: usize,
        k: i64,
        mut a: [i64; n],
    };
    a.sort();
    let mut l = 0;
    let mut r = n;
    while r - l > 1 {
        let m = l + (r - l) / 2;
        if is_ok(n, k, &a, m) {
            l = m;
        } else {
            r = m;
        }
    }
    let ans = l + 1;
    println!("{}", ans);
}

use std::io::Read;

const INF: i64 = 1e16 as i64;

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();
    let n = iter.next().unwrap().parse().unwrap();
    let k = iter.next().unwrap().parse().unwrap();
    let a: Vec<usize> = (0..n)
        .map(|_| iter.next().unwrap().parse().unwrap())
        .collect();

    let mut dp_f: Vec<Vec<bool>> = vec![vec![false; k]; n];
    let mut dp_b: Vec<Vec<bool>> = vec![vec![false; k]; n];

    dp_f[0][0] = true;

    for i in 0..(n - 1) {
        for j in 0..k {
            if !dp_f[i][j] {
                continue;
            }

            dp_f[i + 1][j] = true;
            if j + a[i] < k {
                dp_f[i + 1][j + a[i]] = true;
            }
        }
    }

    dp_b[n - 1][0] = true;
    for _i in 0..(n - 1) {
        let i = n - 1 - _i;
        for j in 0..k {
            if !dp_b[i][j] {
                continue;
            }

            dp_b[i - 1][j] = true;
            if j + a[i] < k {
                dp_b[i - 1][j + a[i]] = true;
            }
        }
    }

    let mut res = 0;
    let mut dp_b_sum = vec![0; k + 1];
    for i in 0..n {
        if a[i] > k {
            continue;
        }

        let mut ok = false;
        for j in 0..k {
            dp_b_sum[j + 1] = dp_b[i][j] as i32 + dp_b_sum[j];
        }

        for j in 0..k {
            let min = if k - a[i] < j { 0 } else { k - a[i] - j };
            let max = k - j;

            if dp_f[i][j] && dp_b_sum[max] - dp_b_sum[min] > 0 {
                ok = true;
            }
        }
        if !ok {
            res += 1;
        }
    }
    println!("{}", res);
}

