fn solve(aa: &[u32], k: u32, memo: &mut [Vec<Option<bool>>]) -> bool {
    memo[k as usize][aa.len()].unwrap_or_else(|| {
        let ans = k == 0 || aa.split_first().map_or(false, |(&a, tl)|
            solve(tl, k, memo) ||
            k.checked_sub(a).map_or(false, |sub| solve(tl, sub, memo))
        );
        memo[k as usize][aa.len()] = Some(ans);
        ans
    })
}

fn main() {
    read!(n = usize, k = u32);
    read!(mut aa = Vec<u32>);
    aa.sort();
    let ans = (0..n).bsearch_right_min(|&i| {
        k.checked_sub(aa[i]).map_or(true, |min| {
            let mut excluded = aa.clone();
            excluded.remove(i);
            let mut memo = vec![vec![None; n]; k as usize];
            (min..k).any(|x| solve(&excluded, x, &mut memo))
        })
    }).unwrap_or(n);
    println!("{}", ans);
}

#[allow(unused_macros)]
macro_rules! scan {
    () => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().to_string()
        }
    };
    (;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().split_whitespace().map(|s| s.to_string()).collect::<Vec<String>>()
        }
    };
    (;;$n:expr) => {
        {
            (0..$n).map(|_| scan!()).collect::<Vec<_>>()
        }
    };
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
    ($t:ty;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };
}

fn main() {
    let (n, k) = scan!(usize, i64);
    let mut vs = scan!(i64;;);
    vs.sort_by_key(|v| -v);

    let mut sum = 0;
    let mut ans = 0;
    if vs.iter().filter(|&&v| v < k).sum::<i64>() >= k {
        for v in vs.iter().filter(|&&v| v < k) {
            sum += *v;
            if sum < k {
                ans += 1;
            }
        }
        ans += 1;
        println!("{}", n - (ans + vs.iter().filter(|&&v| v >= k).count()));
