#[derive(Copy, Clone, Eq, PartialEq)]
struct edge22{from:usize, to:usize, cost:i64, ind:usize}
impl Ord for edge22 {
    fn cmp(&self, other: &edge22) -> Ordering {
        other.cost.cmp(&self.cost)
    }
}

impl PartialOrd for edge22 {
    fn partial_cmp(&self, other: &edge22) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
fn kruskal2(es:&mut Vec<edge22>, n:usize) -> Vec<usize>{
    es.sort();
    es.reverse();
    let mut uf =  UnionFind::init(n);
    let mut res = Vec::new();
    for i in 0..es.len(){
        let e = es[i];
        if uf.same(e.from, e.to) == false{
            uf.unite(e.from, e.to);
            res.push(e.ind);

        }

    }
    res
}
