fn is_ok(n: usize, k: i64, a: &Vec<i64>, i_s: usize) -> bool {
    let a_s = a[i_s];
    let mut dp = vec![vec![false; k as usize]; n];
    dp[0][0] = true;
    for i in 0..n {
        if i == i_s {
            continue;
        }
        let a_i = a[i] as usize;
        let i = if i > i_s { i - 1 } else { i };
        for j in 0..k as usize {
            dp[i + 1][j] |= dp[i][j];
            if j + a_i < k as usize {
                dp[i + 1][j + a_i] |= dp[i][j];
            }
        }
    }
    if k - a_s < 0 {
        return false;
    }
    for j in (k - a_s) as usize..k as usize {
        if dp[n - 1][j] {
            return false;
        }
    }
    true
}

