    es.sort();
    es.reverse();
    let mut uf =  UnionFind::init(n);
    let mut res = Vec::new();
    for i in 0..es.len(){
        let e = es[i];
        if uf.same(e.from, e.to) == false{
            uf.unite(e.from, e.to);
            res.push(e.ind);

        }

    }
    res
