fn f(vs: &[i64], i: usize, k: i64) -> bool {
    let mut dp = vec![vec![false; k as usize]; vs.len()];
    dp[0][0] = true;

    let mut j = 0;
    for (n, &v) in vs.iter().enumerate() {
        if n == i {
            continue;
        }
        for l in 0..dp[j].len() {
            if v as usize <= l {
                dp[j + 1][l] = dp[j][l] || dp[j][l - v as usize]
            } else {
                dp[j + 1][l] |= dp[j][l]
            }
        }
        j += 1;
    }

    for (j, &b) in dp[vs.len() - 1].iter().enumerate() {
        if k - vs[i] <= j as i64 && b {
            return true;
        }
    }
    false
}

