fn nessesary(vs: &[usize], k: usize, skip: usize) -> bool {
    let n = vs.len();

    let mut dp = vec![vec![false; k]; n];
    dp[0][0] = true;
    for (i, &v) in vs
        .iter()
        .enumerate()
        .filter(|&(i, _)| i != skip)
        .map(|(_, v)| v)
        .enumerate()
    {
        for j in 0..dp[i].len() {
            if j >= v {
                dp[i + 1][j] |= dp[i][j - v];
            }
            dp[i + 1][j] |= dp[i][j]
        }
    }

    dp[n - 1]
        .iter()
        .enumerate()
        .any(|(i, &v)| vs[skip] >= k || (k - vs[skip] <= i && i < k && v))
}

fn main() {
    let (_, k) = scan!(usize, usize);
    let mut vs = scan!(usize;;);
    vs.sort();

    let (mut left, mut right) = (0, vs.len() + 1);
    while left + 1 < right {
        let mid = (left + right) / 2;
        if nessesary(&vs, k, mid - 1) {
            right = mid;
        } else {
            left = mid;
        }
    }

    println!("{}", left);
}

