use std::io::Read;

fn trans(a: usize, dp: &mut [bool]) {
    for i in (a..dp.len()).rev() {
        dp[i] |= dp[i - a];
    }
}

fn calc(a: &[usize], dp: &Vec<bool>) -> usize {
    if a.len() == 1 {
        return if dp.iter().rposition(|b| *b).unwrap() + a[0] >= dp.len() {
            0
        } else {
            1
        };
    }
    let n = a.len();
    let m = n / 2;
    let mut next = dp.clone();
    for &a in &a[..m] {
        trans(a, &mut next);
    }
    let ans = calc(&a[m..], &next);
    let mut next = dp.clone();
    for &a in &a[m..] {
        trans(a, &mut next);
    }
    ans + calc(&a[..m], &next)
}

