    let mut dp1 = vec![vec![false; k]; n + 1];
    let mut dp2 = vec![vec![false; k]; n + 1];
    dp1[0][0] = true;
    for i in 0..n {
        for j in 0..k {
            dp1[i + 1][j] = dp1[i][j] | if j >= a[i] { dp1[i][j - a[i]] } else { false };
        }
    }
    dp2[n][0] = true;
    for i in (0..n).rev() {
        for j in 0..k {
            dp2[i][j] = dp2[i + 1][j]
                | if j >= a[i] {
                    dp2[i + 1][j - a[i]]
                } else {
                    false
                };
        }
    }
    for i in 0..n {
        let rv = acc(&dp2[i + 1]);
        for j in 0..k {
            if dp1[i][j] {
                let x = if k >= a[i] + j { k - a[i] - j } else { 0 };
                if rv[k - j] != rv[x] {
                    ans -= 1;
                    break;
                }
            }
        }
    }
    println!("{}", ans);
}

