    for ignore in 0..n {
        let mut dp = vec![vec![false; k]; n + 1];
        dp[0][0] = true;
        for i in 0..n {
            for j in 0..k {
                if i == ignore {
                    dp[i + 1][j] = dp[i][j];
                    continue;
                }

                dp[i + 1][j] |= dp[i][j];
                let a = av[i];
                if j + a >= k {
                    continue;
                }
                dp[i + 1][j + a] |= dp[i][j];
            }
        }
        let a = av[ignore];
        let l = (k as isize - a as isize).max(0) as usize;
        let is_required = (l..k).any(|i| dp[n][i]);
        if !is_required {
            res += 1;
        }
    }
    println!("{}", res);
